const server = http.createServer(async (req, res) => {
  const url = new URL(req.url || "/", `http://${req.headers.host || "localhost"}`);

  try {
    if (req.method === "OPTIONS") {
      sendText(res, 204, "");
      return;
    }

    if (req.method === "GET" && url.pathname === "/") {
      redirect(res, "/admin");
      return;
    }

    if (req.method === "GET" && url.pathname === "/health") {
      const config = getEffectiveConfig();
      const stats = getRuntimeStats();
      sendJson(res, 200, {
        ok: true,
        service: "feishu-fund-assistant",
        release: getRuntimeRelease(),
        configured: getConfigStatus(config),
        skills: listSkills(false).length,
        counters: {
          conversations: stats.counters.conversations,
          imagesReceived: stats.counters.imagesReceived,
          answersSent: stats.counters.answersSent,
          errors: stats.counters.errors
        }
      });
      return;
    }

    if (req.method === "GET" && url.pathname === "/admin") {
      await serveStaticFile(res, path.join(PUBLIC_DIR, "admin.html"));
      return;
    }

    if (req.method === "GET" && url.pathname.startsWith("/public/")) {
      const relativePath = decodeURIComponent(url.pathname.replace(/^\/public\//, ""));
      await serveStaticFile(res, path.join(PUBLIC_DIR, relativePath));
      return;
    }

    if (url.pathname.startsWith("/api/")) {
      if (!isAdminAuthorized(req, url)) {
        sendJson(res, 401, { ok: false, error: "需要管理令牌" });
        return;
      }
      await handleApiRequest(req, res, url);
      return;
    }

    if (req.method === "POST" && url.pathname === "/feishu/events") {
      await handleFeishuEventRequest(req, res);
      return;
    }

    sendJson(res, 404, { ok: false, error: "not_found" });
  } catch (error) {
    console.error("[request-error]", error);
    sendJson(res, 500, { ok: false, error: error.message });
  }
});

if (process.env.FUNDAGENT_SKIP_SERVER_START !== "1") {
  server.listen(PORT, HOST, () => {
    console.log(`Feishu Fund Manager listening on http://${HOST}:${PORT}`);
    console.log(`Admin UI: http://127.0.0.1:${PORT}/admin`);
    startPortfolioScheduler();
  });
}

let eventLoopLagExpectedAt = Date.now() + 5000;
if (process.env.FUNDAGENT_SKIP_SERVER_START !== "1") {
  setInterval(() => {
    const now = Date.now();
    const lagMs = now - eventLoopLagExpectedAt;
    if (lagMs > Number(process.env.EVENT_LOOP_LAG_WARN_MS || 3000)) {
      console.warn(`[event-loop-lag] ${lagMs}ms`);
    }
    eventLoopLagExpectedAt = now + 5000;
  }, 5000).unref?.();

  for (const signal of ["SIGINT", "SIGTERM"]) {
    process.once(signal, () => {
      try {
        flushPortfolioDbSync();
      } finally {
        process.exit(0);
      }
    });
  }
}

async function handleApiRequest(req, res, url) {
  if (req.method === "GET" && url.pathname === "/api/config") {
    sendJson(res, 200, getPublicConfig());
    return;
  }

  if (req.method === "POST" && url.pathname === "/api/config") {
    const patch = await readJsonBody(req);
    const saved = saveConfigPatch(patch);
    tenantAccessTokenCache = null;
    sendJson(res, 200, { ok: true, config: getPublicConfig(saved) });
    return;
  }

  if (req.method === "POST" && url.pathname === "/api/test/model") {
    const result = await testModelConnection();
    sendJson(res, 200, result);
    return;
  }

  if (req.method === "POST" && url.pathname === "/api/test/feishu") {
    const result = await testFeishuConnection();
    sendJson(res, 200, result);
    return;
  }

  if (req.method === "GET" && url.pathname === "/api/skills") {
    sendJson(res, 200, { ok: true, count: listSkills(true).length, skills: listSkills(true) });
    return;
  }

  if (req.method === "GET" && url.pathname === "/api/stats") {
    sendJson(res, 200, { ok: true, stats: getRuntimeStats() });
    return;
  }

  if (req.method === "GET" && url.pathname === "/api/deployment") {
    const force = url.searchParams.get("force") === "1";
    const deployment = await getDeploymentFreshness({ force });
    sendJson(res, 200, { ok: true, deployment });
    return;
  }

  if (req.method === "GET" && url.pathname === "/api/portfolio") {
    const startedAt = Date.now();
    const forceFull = url.searchParams.get("full") === "1";
    const lightweight = !forceFull && (portfolioRunInFlight || url.searchParams.get("light") === "1" || url.searchParams.get("summary") === "1");
    const portfolio = getPortfolioPublicState(undefined, { lightweight });
    const elapsedMs = Date.now() - startedAt;
    if (elapsedMs > 1000) {
      console.warn(`[portfolio-api-slow] /api/portfolio${lightweight ? "?light=1" : ""} ${elapsedMs}ms`);
    }
    sendJson(res, 200, { ok: true, portfolio });
    return;
  }

  if (req.method === "POST" && url.pathname === "/api/portfolio/run") {
    const body = await readJsonBody(req);
    const portfolioState = getPortfolioPublicState();
    if (portfolioState.scheduler?.inFlight) {
      sendJson(res, 409, { ok: false, error: "虚拟组合任务正在运行，请先等待完成或手动结束。", portfolio: portfolioState });
      return;
    }
    runPortfolioTask(body.type || "decision", { manual: true }).catch((error) => {
      console.error("[portfolio-run-error]", error);
    });
    sendJson(res, 202, { ok: true, accepted: true, portfolio: getPortfolioPublicState() });
    return;
  }

  if (req.method === "POST" && url.pathname === "/api/portfolio/cancel") {
    const result = cancelPortfolioTask();
    sendJson(res, 200, { ok: true, portfolio: result });
    return;
  }

  if (req.method === "POST" && url.pathname === "/api/portfolio/reset") {
    const body = await readJsonBody(req);
    const result = resetPortfolioAccount(body.initialCapital, { clearHistory: body.clearHistory !== false });
    sendJson(res, 200, { ok: true, portfolio: result });
    return;
  }

  if (req.method === "POST" && url.pathname === "/api/portfolio/prune") {
    const result = prunePortfolioDatabase();
    sendJson(res, 200, { ok: true, portfolio: result });
    return;
  }

  if (req.method === "POST" && url.pathname === "/api/user-portfolios/holding") {
    const body = await readJsonBody(req);
    const result = updateUserPortfolioHoldingFromAdmin(body);
    sendJson(res, 200, { ok: true, portfolio: result });
    return;
  }

  sendJson(res, 404, { ok: false, error: "api_not_found" });
}

async function handleFeishuEventRequest(req, res) {
  const config = getEffectiveConfig();
  const rawBody = await readRequestBody(req);

  if (config.feishuEncryptKey) {
    maybeVerifyFeishuSignature(req.headers, rawBody, config.feishuEncryptKey);
  }

  const payload = decodeFeishuPayload(rawBody, config);
  verifyFeishuToken(payload, config);

  const challenge = getChallenge(payload);
  if (challenge) {
    sendJson(res, 200, { challenge });
    return;
  }

  const eventId = payload?.header?.event_id || payload?.uuid || "";
  if (eventId && wasSeenRecently(eventId)) {
    updateStats({ counters: { duplicateEvents: 1 } });
    sendJson(res, 200, { code: 0, msg: "duplicate ignored" });
    return;
  }

  sendJson(res, 200, { code: 0, msg: "ok" });

  if (isMessageReceiveEvent(payload)) {
    updateStats({
      counters: { messageEvents: 1 },
      last: { lastMessageEventAt: new Date().toISOString() }
    });
    setImmediate(() => {
      handleMessageEvent(payload).catch((error) => {
        console.error("[message-event-error]", error);
        recordError(error);
      });
    });
  }
}

async function handleMessageEvent(payload) {
  const message = payload?.event?.message;
  if (!message?.message_id) {
    return;
  }

  capturePortfolioPushTarget(payload);

  let parsedContent = {};
  try {
    parsedContent = message.content ? JSON.parse(message.content) : {};
  } catch {
    parsedContent = {};
  }

  const imageKeys = extractImageKeys(parsedContent);
  const userText = extractUserText(message.message_type, parsedContent);
  const mergeKey = getFeishuImageTextMergeKey(payload);
  const pendingPortfolioImport = mergeKey ? takePendingUserPortfolioImportForImage(mergeKey, imageKeys, userText) : null;
  if (pendingPortfolioImport) {
    await processFeishuFundMessage({
      message,
      imageKeys,
      imageEntries: buildMessageImageEntries(message.message_id, imageKeys),
      userText: [pendingPortfolioImport.userText, userText].filter(Boolean).join("\n"),
      messageType: message.message_type,
      parsedContent,
      mergedFromPendingImages: true
    });
    return;
  }

  if (shouldBufferUserPortfolioImportText({ imageKeys, userText })) {
    bufferPendingUserPortfolioImportRequest({ key: mergeKey, message, userText });
    await replyToMessage(
      message.message_id,
      `已准备为用户「${extractUserPortfolioId(userText) || "未命名用户"}」建立持仓关注。请继续发送持仓截图，我会把截图里的基金保存到该用户的持仓列表。`,
      { kind: "progress" }
    );
    return;
  }

  const pendingImageMessage = mergeKey ? takePendingImageMessageForText(mergeKey, userText) : null;

  if (pendingImageMessage) {
    const currentImageEntries = buildMessageImageEntries(message.message_id, imageKeys);
    await processFeishuFundMessage({
      message,
      imageKeys: [
        ...pendingImageMessage.imageEntries.map((entry) => entry.imageKey),
        ...currentImageEntries.map((entry) => entry.imageKey)
      ],
      imageEntries: [...pendingImageMessage.imageEntries, ...currentImageEntries],
      userText,
      messageType: message.message_type,
      parsedContent,
      mergedFromPendingImages: true
    });
    return;
  }

  if (shouldBufferImageOnlyMessage({ imageKeys, userText })) {
    bufferPendingImageMessage({ key: mergeKey, message, parsedContent, imageKeys });
    return;
  }

  if (!imageKeys.length && !userText) {
    await replyToMessage(
      message.message_id,
      "请发送基金截图、基金代码/名称，或直接问“按最近题材推荐几个基金”。我会先判断工作流，再选择单基分析、基金推荐或基金问答。",
      { kind: "noContent" }
    );
    updateStats({ counters: { noContentMessages: 1 } });
    return;
  }

  await processFeishuFundMessage({
    message,
    imageKeys,
    imageEntries: buildMessageImageEntries(message.message_id, imageKeys),
    userText,
    messageType: message.message_type,
    parsedContent
  });
}

function buildMessageImageEntries(messageId, imageKeys = []) {
  return (imageKeys || [])
    .map((imageKey) => ({
      messageId,
      imageKey: String(imageKey || "").trim()
    }))
    .filter((entry) => entry.messageId && entry.imageKey);
}

function getFeishuImageTextMergeKey(payload) {
  const message = payload?.event?.message || {};
  const senderId = payload?.event?.sender?.sender_id || {};
  const chatId = message.chat_id || payload?.event?.chat_id || "";
  const sender = senderId.open_id || senderId.union_id || senderId.user_id || senderId.email || "";
  if (!chatId || !sender) return "";
  return `${chatId}:${sender}`;
}

function shouldBufferImageOnlyMessage({ imageKeys = [], userText = "" }) {
  return FEISHU_IMAGE_TEXT_MERGE_WINDOW_MS > 0 && imageKeys.length > 0 && !String(userText || "").trim();
}

function shouldBufferUserPortfolioImportText({ imageKeys = [], userText = "" }) {
  return USER_PORTFOLIO_IMPORT_IMAGE_WAIT_MS > 0
    && !imageKeys.length
    && isUserPortfolioImportRequest(userText);
}

function takePendingUserPortfolioImportForImage(key, imageKeys = [], userText = "") {
  if (!key || !imageKeys.length) return null;
  const pending = pendingUserPortfolioImportRequests.get(key);
  if (!pending) return null;
  if (pending.timer) clearTimeout(pending.timer);
  pendingUserPortfolioImportRequests.delete(key);
  updateStats({ counters: { mergedUserPortfolioImportImages: 1 } });
  return {
    ...pending,
    userText: [pending.userText, userText].filter(Boolean).join("\n")
  };
}

function bufferPendingUserPortfolioImportRequest({ key, message, userText }) {
  const mergeKey = key || `message:${message.message_id}`;
  const previous = pendingUserPortfolioImportRequests.get(mergeKey);
  if (previous?.timer) clearTimeout(previous.timer);
  const timer = setTimeout(() => {
    pendingUserPortfolioImportRequests.delete(mergeKey);
  }, Math.max(0, USER_PORTFOLIO_IMPORT_IMAGE_WAIT_MS));
  timer.unref?.();
  pendingUserPortfolioImportRequests.set(mergeKey, {
    messageId: message.message_id,
    userText,
    userId: extractUserPortfolioId(userText),
    createdAt: new Date().toISOString(),
    timer
  });
  updateStats({ counters: { pendingUserPortfolioImports: 1 } });
}

function takePendingImageMessageForText(key, userText) {
  if (!key || !String(userText || "").trim()) return null;
  const pending = pendingImageMessages.get(key);
  if (!pending) return null;
  if (pending.timer) clearTimeout(pending.timer);
  pendingImageMessages.delete(key);
  updateStats({ counters: { mergedImageTextMessages: 1 } });
  return pending;
}

function bufferPendingImageMessage({ key, message, parsedContent, imageKeys = [] }) {
  const mergeKey = key || `message:${message.message_id}`;
  const previous = pendingImageMessages.get(mergeKey);
  if (previous?.timer) clearTimeout(previous.timer);

  const imageEntries = [
    ...(previous?.imageEntries || []),
    ...buildMessageImageEntries(message.message_id, imageKeys)
  ];

  const timer = setTimeout(() => {
    const pending = pendingImageMessages.get(mergeKey);
    if (!pending) return;
    pendingImageMessages.delete(mergeKey);
    processFeishuFundMessage({
      message: pending.message,
      imageKeys: pending.imageEntries.map((entry) => entry.imageKey),
      imageEntries: pending.imageEntries,
      userText: "",
      messageType: pending.message?.message_type || "image",
      parsedContent: pending.parsedContent,
      bufferedImageOnly: true
    }).catch((error) => {
      console.error("[buffered-image-message-error]", error);
      recordError(error);
    });
  }, Math.max(0, FEISHU_IMAGE_TEXT_MERGE_WINDOW_MS));

  pendingImageMessages.set(mergeKey, {
    message,
    parsedContent,
    imageEntries,
    createdAt: previous?.createdAt || Date.now(),
    timer
  });
  updateStats({ counters: { bufferedImageMessages: 1 } });
}

async function processFeishuFundMessage({
  message,
  imageKeys = [],
  imageEntries = buildMessageImageEntries(message?.message_id, imageKeys),
  userText = "",
  messageType = message?.message_type || "",
  parsedContent = {},
  mergedFromPendingImages = false,
  bufferedImageOnly = false
}) {
  const normalizedImageEntries = imageEntries?.length
    ? imageEntries
    : buildMessageImageEntries(message?.message_id, imageKeys);
  const imageCount = normalizedImageEntries.length;

  updateStats({
    counters: {
      conversations: 1,
      imagesReceived: imageCount,
      textMessages: userText ? 1 : 0
    },
    last: {
      lastConversationAt: new Date().toISOString(),
      lastMessageType: messageType || "unknown",
      lastImageTextMerge: mergedFromPendingImages ? "merged" : bufferedImageOnly ? "image_only_timeout" : "direct"
    }
  });

  try {
    const intent = await classifyMessageIntent({
      imageKeys: normalizedImageEntries.map((entry) => entry.imageKey),
      userText,
      messageType
    });
    const isHeldSellPlan = intent.mode === "screenshot_held_position_sell_plan" || intent.mode === "held_position_sell_plan";
    recordWorkflowIntent(intent);

    if (intent.workflow === "conversation") {
      await handleConversationWorkflow({ message, userText, intent });
      return;
    }

    if (intent.workflow === "portfolio_status") {
      await handlePortfolioStatusWorkflow({ message, userText, intent });
      return;
    }

    if (intent.workflow === "fund_recommendation") {
      await handleFundRecommendationWorkflow({ message, userText, intent });
      return;
    }

    if (intent.workflow === "fund_qa") {
      await handleFundQaWorkflow({ message, userText, intent });
      return;
    }

    if (intent.workflow === "user_portfolio_import") {
      await handleUserPortfolioImportWorkflow({
        message,
        userText,
        intent,
        imageEntries: normalizedImageEntries,
        messageType
      });
      return;
    }

    await replyToMessage(message.message_id, buildProgressMessage(imageCount, userText), {
      kind: "progress"
    }).catch((error) => {
      console.error("[progress-reply-error]", error);
      recordError(error, { replyFailures: 1 });
    });

    await replyToMessage(
      message.message_id,
      imageCount
        ? "进度：正在识别截图中的基金代码和关键字段。"
        : "进度：正在识别文字中的基金名称、代码和关键字段。",
      {
        kind: "progress"
      }
    ).catch((error) => {
      console.error("[progress-reply-error]", error);
      recordError(error, { replyFailures: 1 });
    });

    const images = [];
    for (const entry of normalizedImageEntries) {
      images.push(await downloadMessageImage(entry.messageId, entry.imageKey));
    }

    const extracted = await extractFundFactsWithModel({ images, userText, messageType, intent });
    const fundCodes = mergeFundCodes(extractFundCodes(userText), extracted.fundCodes);

    await replyToMessage(
      message.message_id,
      fundCodes.length
        ? `进度：已识别到基金代码 ${fundCodes.join("、")}，正在联网补全基金资料。`
        : "进度：截图中未稳定识别到基金代码，将先按可见信息分析。",
      { kind: "progress" }
    ).catch((error) => {
      console.error("[progress-reply-error]", error);
      recordError(error, { replyFailures: 1 });
    });

    const enrichments = await enrichFunds(fundCodes, { limit: getFundAnalysisEnrichmentLimit() });

    await replyToMessage(
      message.message_id,
      "进度：分析师分析中。产品、业绩指标、持仓风格、市场主题、情绪新闻 5 个角度正在整理证据。",
      { kind: "progress" }
    ).catch((error) => {
      console.error("[progress-reply-error]", error);
      recordError(error, { replyFailures: 1 });
    });

    const analystReview = await buildAnalystReviewWithModel({
      images,
      userText,
      messageType,
      extracted,
      enrichments,
      intent
    });

    await replyToMessage(
      message.message_id,
      "进度：委员会投票中。正在汇总牛方、熊方、风险经理的倾向，并判断是买入、分批买入、观察还是回避。",
      { kind: "progress" }
    ).catch((error) => {
      console.error("[progress-reply-error]", error);
      recordError(error, { replyFailures: 1 });
    });

    const committeeVote = await buildCommitteeVoteWithModel({
      userText,
      messageType,
      extracted,
      enrichments,
      analystReview,
      intent
    });

    await replyToMessage(
      message.message_id,
      isHeldSellPlan
        ? "进度：主席验收中。正在把投票结果压缩成飞书卡片，并生成持有/减仓/卖出计划。"
        : "进度：主席验收中。正在把投票结果压缩成飞书卡片，并生成 1 万元执行方案。",
      { kind: "progress" }
    ).catch((error) => {
      console.error("[progress-reply-error]", error);
      recordError(error, { replyFailures: 1 });
    });

    const analysis = await analyzeFundWithModel({
      userText,
      messageType,
      extracted,
      enrichments,
      analystReview,
      committeeVote,
      intent
    });
    const screeningChartProfiles = selectFundReportProfilesForAnswer(
      selectFundScreeningWatchlistProfiles(enrichments, analysis, userText),
      analysis,
      {
        minCount: Math.min(getFundReportChartMinCount(), countEligibleFundReportProfiles(enrichments)),
        limit: getFundReportChartLimit()
      }
    );
    persistAnswerWatchlistCandidates({
      userText,
      answerText: analysis,
      chartProfiles: screeningChartProfiles,
      source: "fund_screening_answer"
    });
    const reportImages = await buildFundReportCardImages(screeningChartProfiles, getEffectiveConfig()).catch((error) => {
      console.error("[fund-report-trend-image-error]", error);
      recordError(error, { fundReportTrendImageFailures: 1 });
      return [];
    });
    await replyToMessage(
      message.message_id,
      [buildCompletionPrefix(images.length, userText), appendFundReportChartReadingGuide(analysis, screeningChartProfiles)].filter(Boolean).join("\n\n"),
      { kind: "answer", images: reportImages }
    );
  } catch (error) {
    console.error("[analysis-error]", error);
    recordError(error);
    await replyToMessage(
      message.message_id,
      [
        "这次没有完成基金分析。",
        `原因：${error.message}`,
        "可以稍后重试，或直接发送基金名称/代码、近 1/3/5 年收益、最大回撤、费率、基金经理任期等关键数据。"
      ].join("\n"),
      { kind: "error" }
    );
  }
}

async function handleUserPortfolioImportWorkflow({ message, userText, intent, imageEntries = [], messageType }) {
  const userId = extractUserPortfolioId(userText) || "default";
  if (!imageEntries.length) {
    await replyToMessage(
      message.message_id,
      `已识别为用户持仓导入。请继续发送用户「${userId}」的持仓截图，我会识别基金代码、名称和截图里的持有状态。`,
      { kind: "progress" }
    );
    return;
  }

  await replyToMessage(
    message.message_id,
    `进度：正在识别用户「${userId}」的持仓截图，识别到的基金会保存到用户持仓关注列表。`,
    { kind: "progress" }
  ).catch((error) => {
    console.error("[progress-reply-error]", error);
    recordError(error, { replyFailures: 1 });
  });

  const images = [];
  for (const entry of imageEntries) {
    images.push(await downloadMessageImage(entry.messageId, entry.imageKey));
  }

  const extracted = await extractFundFactsWithModel({ images, userText, messageType, intent });
  const fundCodes = mergeFundCodes(
    extractFundCodes(userText),
    extracted.fundCodes,
    (extracted.screenshotHoldings || []).map((item) => item.code)
  );
  const enrichments = fundCodes.length ? await enrichFunds(fundCodes, { limit: getFundAnalysisEnrichmentLimit() }) : [];
  const result = upsertUserPortfolioFromExtractedHoldings({
    userId,
    displayName: extractUserPortfolioDisplayName(userText) || userId,
    userText,
    extracted,
    enrichments,
    source: "feishu_screenshot_import"
  });

  await replyToMessage(
    message.message_id,
    buildUserPortfolioImportReply(result, { imageCount: images.length, userText }),
    { kind: "answer" }
  );
}

