function compactPortfolioReviewProfile(profile = {}) {
  const oneYear = profile.riskMetrics?.periods?.["1y"] || {};
  const topHoldings = (profile.holdings?.equityTopHoldings || profile.topHoldings || profile.topStocks || []).slice(0, 10).map((item) => {
    if (typeof item === "string") return item;
    return [item.code, item.name, item.netValuePct ? `${item.netValuePct}%` : ""].filter(Boolean).join(" ");
  });
  return {
    code: profile.code || "",
    name: profile.name || "",
    navDate: profile.snapshotDate || "",
    unitNav: profile.unitNav || "",
    estimatedNav: profile.estimatedNav || "",
    estimatedChangePct: profile.estimatedChangePct || "",
    estimateTime: profile.estimateTime || "",
    realtimeEvidence: formatPortfolioRealtimeEvidence(profile),
    holdingRealtimePulse: compactFundHoldingRealtimePulse(profile.holdingRealtimePulse),
    trendProfile: compactPortfolioTrendProfile(profile.trendProfile),
    actionability: compactPortfolioActionabilityProfile(profile.actionability),
    oneYearRisk: oneYear.ok ? pickRiskPeriod(oneYear) : null,
    returns: profile.returns || {},
    shareClass: profile.shareClass || "",
    feeModel: profile.shareClassFeeModel || null,
    feeImpact: profile.fees?.feeImpact || null,
    feeDecisionRule: profile.fees?.feeDecisionRule || "",
    scale: profile.scale || null,
    topHoldings,
    sources: (profile.sources || []).slice(0, 4)
  };
}

function compactPortfolioTrendProfile(trend = null) {
  if (!trend || typeof trend !== "object") return null;
  return {
    ok: Boolean(trend.ok),
    note: trend.note || "",
    latestDate: trend.latestDate || "",
    trendLabel: trend.trendLabel || "",
    entryBias: trend.entryBias || "",
    return5dPct: finiteMetricNumber(trend.return5dPct),
    return10dPct: finiteMetricNumber(trend.return10dPct),
    return20dPct: finiteMetricNumber(trend.return20dPct),
    return60dPct: finiteMetricNumber(trend.return60dPct),
    return120dPct: finiteMetricNumber(trend.return120dPct),
    drawdownFromRecentHighPct: finiteMetricNumber(trend.drawdownFromRecentHighPct),
    drawdownFrom120HighPct: finiteMetricNumber(trend.drawdownFrom120HighPct),
    lowPositionPct120: finiteMetricNumber(trend.lowPositionPct120),
    lowPositionPct250: finiteMetricNumber(trend.lowPositionPct250),
    pullbackSetup: trend.pullbackSetup ? {
      signal: trend.pullbackSetup.signal || "",
      score: finiteMetricNumber(trend.pullbackSetup.score),
      reason: String(trend.pullbackSetup.reason || "").slice(0, 240)
    } : null
  };
}

function compactPortfolioActionabilityProfile(actionability = null) {
  if (!actionability || typeof actionability !== "object") return null;
  const holdingsOutlook = actionability.holdingsOutlook || null;
  return {
    score: finiteMetricNumber(actionability.score),
    fitLabel: normalizePortfolioActionabilityText(actionability.fitLabelText || formatFitLabel(actionability.fitLabel) || actionability.fitLabel || ""),
    fitLabelText: normalizePortfolioActionabilityText(actionability.fitLabelText || formatFitLabel(actionability.fitLabel) || ""),
    action: actionability.action || "",
    actionText: normalizePortfolioActionabilityText(actionability.actionText || formatActionabilityAction(actionability.action)),
    allocationBand: normalizePortfolioActionabilityText(actionability.allocationBand || ""),
    confidence: formatActionabilityConfidence(actionability.confidence),
    decisiveEvidence: normalizePortfolioActionabilityList(actionability.decisiveEvidence, 5),
    decisionBlocker: normalizePortfolioActionabilityList(actionability.decisionBlocker, 5),
    holdingsOutlook: holdingsOutlook ? {
      label: normalizePortfolioActionabilityText(holdingsOutlook.label || ""),
      evidence: normalizePortfolioActionabilityText(holdingsOutlook.evidence || "").slice(0, 320),
      risks: normalizePortfolioActionabilityList(holdingsOutlook.risks, 4),
      positives: normalizePortfolioActionabilityList(holdingsOutlook.positives, 4),
      concentration: holdingsOutlook.concentration || null,
      realtimePulse: compactFundHoldingRealtimePulse(holdingsOutlook.realtimePulse),
      disclosureDate: holdingsOutlook.disclosureDate || "",
      topHoldings: (holdingsOutlook.topHoldings || []).slice(0, 10)
    } : null
  };
}

function normalizePortfolioActionabilityList(value, limit = 5) {
  return normalizeStringArray(value)
    .slice(0, limit)
    .map(normalizePortfolioActionabilityText)
    .filter(Boolean);
}

function normalizePortfolioActionabilityText(value) {
  return normalizePortfolioUserFacingText(String(value || ""))
    .replace(/\bhigh\b/gi, "较高")
    .replace(/\bmedium\b/gi, "中等")
    .replace(/\blow\b/gi, "偏低")
    .replace(/\bwatch\s*\/\s*test(?:\s+only)?\b/gi, "观察/小额试探")
    .replace(/\btest\s+only\b/gi, "仅小额试探")
    .trim();
}

function formatActionabilityConfidence(value) {
  const text = normalizePortfolioActionabilityText(value);
  const labels = {
    high: "较高",
    medium: "中等",
    low: "偏低"
  };
  return labels[String(value || "").trim().toLowerCase()] || text;
}

function buildFallbackPortfolioValuationRaw({ accountBefore, accountAfter, positionUpdates, lifecycle = {}, profiles = [] }) {
  const changes = [...positionUpdates].sort((a, b) => Math.abs(Number(b.dayPnl || 0)) - Math.abs(Number(a.dayPnl || 0)));
  const biggest = changes[0];
  const dayPnl = round(Number(accountAfter?.dayPnl || 0), 2);
  const summary = dayPnl > 0
    ? `今日组合估值上升 ${formatSignedNumber(dayPnl)} 元。`
    : dayPnl < 0
      ? `今日组合估值回落 ${formatSignedNumber(dayPnl)} 元。`
      : "今日组合估值基本持平。";
  const reasonParts = [
    biggest ? `主要变动来自 ${biggest.code} ${biggest.name || ""}，单项 ${formatSignedNumber(biggest.dayPnl)} 元。` : "当前没有明显持仓估值变动。",
    `总资产 ${accountAfter?.totalAsset ?? 0} 元，仓位 ${accountAfter?.positionWeightPct ?? 0}%。`,
    lifecycle.orderUpdates?.length ? `有 ${lifecycle.orderUpdates.length} 笔订单状态更新。` : "",
    lifecycle.transactions?.length ? `有 ${lifecycle.transactions.length} 笔确认成交。` : ""
  ].filter(Boolean);
  const nextWatch = changes.slice(0, 3).map((item) =>
    `${item.code} ${item.name || ""}：关注净值 ${item.latestNav || "缺失"} 后续是否延续，当前单日影响 ${formatSignedNumber(item.dayPnl)} 元。`
  );
  if (!nextWatch.length) nextWatch.push("明日继续观察持仓净值更新和未完成订单确认状态。");
  const learningNotes = [
    accountAfter?.positionWeightPct > 80 ? "仓位偏高，下一轮决策应优先评估加仓必要性。" : "",
    accountAfter?.cash > 0 ? "保留现金可提高下一轮调仓机动性。" : "",
    "本次为模型空返回后的规则兜底复盘，应在下一轮正常模型复盘中复核。"
  ].filter(Boolean);

  return JSON.stringify({
    summary,
    reason: reasonParts.join(" "),
    nextWatch,
    learningNotes,
    sources: collectPortfolioSources(null, profiles).slice(0, 8)
  });
}

