function normalizePortfolioInvestedCostReturnText(text, account = {}) {
  const body = String(text || "");
  if (!body) return body;
  const investedCost = resolvePortfolioInvestedCostBasis(account);
  const investedPct = Number(account.cumulativePnlPct);
  const pctText = Number.isFinite(investedPct) ? `${formatSignedNumber(investedPct)}%` : "实际投入成本口径";
  const costText = Number.isFinite(investedCost) && investedCost > 0
    ? `按实际投入成本${round(investedCost, 2)}元计${pctText}`
    : `按实际投入成本口径计${pctText}`;
  return body
    .replace(/(?:不能|不要|严禁)把(?:初始本金|初始资金|本金)(?:作为|当作|当成)?收益率分母/g, "必须把实际投入成本作为收益率分母")
    .replace(/按(?:初始本金|初始资金|本金)(?:口径|计算|收益率)?(?:为|计|约|是)?\s*[+-]?\d+(?:\.\d+)?%/g, costText)
    .replace(/(?:相对|较)(?:初始本金|初始资金|本金)\s*[+-]?\d+(?:\.\d+)?%/g, costText)
    .replace(/(?:初始本金|初始资金|本金)(?:作为|当作|当成)?收益率分母/g, "实际投入成本作为收益率分母")
    .replace(/初始资金口径|初始本金口径|本金口径/g, "实际投入成本口径");
}

function normalizePortfolioUserFacingText(text, account = {}) {
  const investedCostText = normalizePortfolioInvestedCostReturnText(String(text || ""), account);
  return formatReadablePortfolioUserFacingText(normalizeUserFacingFundAnswer(investedCostText)).trim();
}

const PORTFOLIO_USER_FACING_SECTION_PATTERN = /^(?:虚拟基金经理日报|直接结论|本次重点|今日手法|市场判断|投委会意见|经理判断|今日操作|申购\/赎回申请|已确认成交|自选基金池|当前资产|回撤预算|风险控制|回溯学习点|数据来源|下一步|持仓复盘|买入准备|备选观察|决策边界|执行方案|风控检查|学习点)\s*[：:]?/;

function formatReadablePortfolioUserFacingText(text = "") {
  const lines = String(text || "")
    .split(/\r?\n/)
    .flatMap((line) => splitReadablePortfolioUserFacingLine(line))
    .map((line) => line.trimEnd());
  const output = [];
  for (const line of lines) {
    const rawLine = String(line || "").trimEnd();
    const trimmed = rawLine.trim();
    if (!trimmed) {
      if (output.length && output[output.length - 1] !== "") output.push("");
      continue;
    }
    const isSection = PORTFOLIO_USER_FACING_SECTION_PATTERN.test(trimmed);
    const previous = output[output.length - 1];
    if (isSection && output.length && previous !== "") {
      output.push("");
    }
    output.push(/^ {2,}\S/.test(rawLine) ? rawLine : trimmed);
  }
  return output.join("\n").replace(/\n{3,}/g, "\n\n").trim();
}

function splitReadablePortfolioUserFacingLine(line = "") {
  const actionLines = splitOverlongPortfolioActionLine(line);
  if (actionLines.length > 1) return actionLines;
  return splitOverlongPortfolioNarrativeLine(line);
}

function splitOverlongPortfolioActionLine(line = "") {
  const text = String(line || "");
  if (text.length < 100 || !/^(?:[-*•]\s*)?(?:买入|卖出|观察|持有|回避|申购|赎回)\s+\d{6}\b/.test(text.trim())) {
    return [text];
  }
  const parts = text.split(/(?<=[。；])\s*/).map((item) => item.trim()).filter(Boolean);
  if (parts.length <= 1) return [text];
  const first = parts[0];
  return [first, ...parts.slice(1).map((part) => `  ${part}`)];
}

function splitOverlongPortfolioNarrativeLine(line = "") {
  const text = String(line || "");
  const trimmed = text.trim();
  if (text.length < 70 || !/^(?:市场判断|投委会意见|经理判断|风险控制|回溯学习点|客户行动牌|主力题材作战图|今日手法|本次重点|下一步)[：:]/.test(trimmed)) {
    return [text];
  }
  const parts = text.split(/(?<=[。；])\s*/).map((item) => item.trim()).filter(Boolean);
  if (parts.length <= 1) return [text];
  return [parts[0], ...parts.slice(1).map((part) => `  ${part}`)];
}

function normalizePortfolioUserFacingArray(value, limit = 8, account = {}) {
  return normalizeStringArray(value)
    .slice(0, limit)
    .map((item) => normalizePortfolioUserFacingText(item, account))
    .filter(Boolean);
}

