function buildFallbackPortfolioWeeklyRaw({ account = {}, weeklyContext = {}, watchlist = [], lifecycle = {}, error = null }) {
  const compactContext = compactPortfolioWeeklyContext(weeklyContext);
  const equity = compactContext.equity || [];
  const firstEquity = equity[0] || {};
  const lastEquity = equity[equity.length - 1] || {};
  const assetChange = Number.isFinite(Number(firstEquity.totalAsset)) && Number.isFinite(Number(lastEquity.totalAsset))
    ? round(Number(lastEquity.totalAsset) - Number(firstEquity.totalAsset), 2)
    : null;
  const positions = account.positions || [];
  const weakPositions = [...positions]
    .sort((a, b) => Number(a.unrealizedPnlPct || 0) - Number(b.unrealizedPnlPct || 0))
    .slice(0, 3);
  const givebackPositions = positions
    .filter((item) => Number(item.profitGivebackPct || 0) >= Math.abs(finiteNumberOr(process.env.PORTFOLIO_PROFIT_GIVEBACK_PCT, 4)))
    .slice(0, 3);
  const readyWatchlist = normalizePortfolioWatchlist(watchlist).filter((item) => item.status === "ready").slice(0, 4);
  const waitingWatchlist = normalizePortfolioWatchlist(watchlist).filter((item) => item.status === "waiting_pullback").slice(0, 4);
  const failedRuns = compactContext.failedRuns || [];
  const modelError = String(error?.message || "").slice(0, 240);

  return JSON.stringify({
    summary: [
      "本周周报使用规则兜底生成",
      Number.isFinite(assetChange) ? `总资产变化${formatSignedNumber(assetChange)}元` : "",
      `当前仓位${account.positionWeightPct ?? 0}%`,
      `按实际投入成本收益率${formatFallbackPct(account.cumulativePnlPct ?? 0)}`
    ].filter(Boolean).join("，") + "。",
    pnlAttribution: [
      Number.isFinite(assetChange)
        ? `本周账面资产从${firstEquity.totalAsset}元变为${lastEquity.totalAsset}元，变化${formatSignedNumber(assetChange)}元。`
        : `当前总资产${account.totalAsset ?? 0}元，累计盈亏${formatSignedNumber(account.cumulativePnl || 0)}元。`,
      `当前持仓市值${account.investedValue ?? 0}元，当前持仓成本${account.investedCost ?? 0}元，实际投入基准${account.investedCostBasis ?? account.investedCost ?? 0}元，收益率按投入基准为${formatFallbackPct(account.cumulativePnlPct ?? 0)}。`,
      weakPositions.length
        ? `拖累项优先复核：${weakPositions.map((item) => `${item.code} ${item.name || ""} ${formatFallbackPct(item.unrealizedPnlPct)}`).join("；")}。`
        : "本周缺少足够持仓盈亏拆分，下一轮估值后继续归因。"
    ],
    operationReview: [
      `本周运行${compactContext.runs.length}次任务、订单${compactContext.orders.length}张、流水${compactContext.transactions.length}笔。`,
      lifecycle.orderUpdates?.length ? `本轮订单生命周期更新${lifecycle.orderUpdates.length}条。` : "本轮没有新增订单生命周期变化。",
      failedRuns.length ? `存在失败任务：${failedRuns.map((run) => `${run.type} ${run.error || run.summary}`).join("；")}。` : "没有检测到周内失败任务。"
    ],
    disciplineReview: [
      `账户回撤${formatFallbackPct(account.drawdownFromPeakPct || 0)}，风控等级${account.riskBudget?.label || account.riskBudget?.level || "未知"}。`,
      givebackPositions.length
        ? `浮盈回吐需要盯紧：${givebackPositions.map((item) => `${item.code} ${item.name || ""} 已回吐${item.profitGivebackPct}pct`).join("；")}。`
        : "当前未出现需要规则兜底强制列出的浮盈回吐持仓。",
      "下周仍坚持分批、低位、不过热和费用/份额复核，不用周报直接下单。"
    ],
    mistakes: [
      modelError ? `模型周报生成异常，已用规则兜底：${modelError}` : "",
      failedRuns.length ? "本周存在运行失败，客户侧会感到经理连续性不足，需要优先修复任务可靠性。" : "",
      "规则兜底报告信息密度低于正常模型周报，下周正常任务需重新复盘。"
    ].filter(Boolean),
    nextWeekPlan: [
      "先复核失败的决策/周报任务，确保经理有连续输出，而不是只留下进度文案。",
      "持仓优先看回撤、浮盈回吐和同题材暴露，科技/通信/芯片方向不因短线新闻追涨。",
      readyWatchlist.length
        ? `接近买点候选只做盘前再确认：${readyWatchlist.map((item) => `${item.code} ${item.name || ""}`).join("；")}。`
        : "暂无可直接升级的接近买点候选，继续等待回调完成和启动前夜证据。",
      waitingWatchlist.length
        ? `等待回调候选继续盯触发条件：${waitingWatchlist.map((item) => `${item.code} ${item.name || ""}`).join("；")}。`
        : "没有足够等待回调候选时，优先补低位召回而不是硬凑推荐。"
    ],
    watchlist: buildPortfolioWatchlistStatusLines(watchlist, { limitPerStatus: 3 }).slice(0, 8),
    watchlistUpdates: [],
    riskNotes: [
      `现金${account.cash ?? 0}元、仓位${account.positionWeightPct ?? 0}%，不能因为现金多就放松买入纪律。`,
      `账户较峰值回撤${formatFallbackPct(account.drawdownFromPeakPct || 0)}，若扩大到预算线，下一轮决策应优先减风险。`,
      "周报兜底不生成交易订单，具体申购/赎回仍需每日决策用最新净值复核。"
    ],
    sources: ["portfolio_weekly_deterministic_fallback", "portfolio_ledger", "portfolio_watchlist"]
  });
}

function isRecoverablePortfolioWeeklyModelError(error) {
  return isEmptyModelResponse(error) || isModelContextWindowError(error) || isTransientModelTransportError(error);
}

function normalizePortfolioTeam(value) {
  const defaults = ["市场分析师", "题材分析师", "基金研究员", "组合经理", "风控经理", "主席"];
  const input = Array.isArray(value) ? value : [];
  const byAgent = new Map(input.map((item) => [String(item?.agent || "").trim(), item]));
  return defaults.map((agent) => {
    const item = byAgent.get(agent) || {};
    return {
      agent,
      stance: String(item.stance || "中").trim(),
      reason: normalizePortfolioUserFacingText(item.reason || "暂无明确意见。"),
      dataBasis: normalizePortfolioUserFacingArray(item.dataBasis, 5)
    };
  });
}

function normalizePortfolioActions(value) {
  const input = Array.isArray(value) ? value : [];
  return input
    .map((item) => {
      const action = String(item?.action || "WATCH").trim().toUpperCase();
      const normalizedAction = ["BUY", "SELL", "HOLD", "WATCH"].includes(action) ? action : "WATCH";
      const code = String(item?.code || "").match(/^\d{6}$/)?.[0] || "";
      return {
        action: normalizedAction,
        code,
        name: String(item?.name || "").trim(),
        amount: Math.max(0, round(Number(item?.amount || 0), 2) || 0),
        targetWeightPct: round(Number(item?.targetWeightPct || 0), 2) || 0,
        reason: normalizePortfolioUserFacingText(item?.reason || ""),
        dataBasis: normalizePortfolioUserFacingArray(item?.dataBasis, 8),
        rankingBasis: normalizePortfolioUserFacingText(item?.rankingBasis || ""),
        rotationCheck: normalizePortfolioUserFacingText(item?.rotationCheck || ""),
        positionCheck: normalizePortfolioUserFacingText(item?.positionCheck || ""),
        chaseRisk: normalizePortfolioUserFacingText(item?.chaseRisk || ""),
        feeCheck: normalizePortfolioUserFacingText(item?.feeCheck || ""),
        riskControl: normalizePortfolioUserFacingText(item?.riskControl || "")
      };
    })
    .filter((item) => item.action === "HOLD" || item.action === "WATCH" || item.code)
    .slice(0, 10);
}

function buildPortfolioExposureSummary(positions = []) {
  const activePositions = (positions || []).filter((position) => Number(position?.currentValue || 0) > 0);
  const themeMap = new Map();
  const holdingMap = new Map();
  let totalPositionWeightPct = 0;
  for (const position of activePositions) {
    const positionWeightPct = finiteMetricNumber(position.weightPct) || 0;
    totalPositionWeightPct += positionWeightPct;
    const fundLabel = `${position.code || ""} ${position.name || ""}`.trim();
    const holdings = collectPortfolioPositionHoldingItems(position);
    const tags = new Set(collectPortfolioPositionThemeTags(position));
    for (const tag of tags) {
      const current = themeMap.get(tag) || { theme: tag, positionWeightPct: 0, funds: [] };
      current.positionWeightPct += positionWeightPct;
      current.funds = mergeStringLists(current.funds, [fundLabel].filter(Boolean)).slice(0, 8);
      themeMap.set(tag, current);
    }
    for (const holding of holdings) {
      const key = holding.code || holding.name;
      if (!key) continue;
      const current = holdingMap.get(key) || {
        code: holding.code || "",
        name: holding.name || "",
        fundCount: 0,
        fundEnvelopePct: 0,
        estimatedAccountPct: 0,
        funds: []
      };
      current.fundCount += 1;
      current.fundEnvelopePct += positionWeightPct;
      if (Number.isFinite(holding.pct)) {
        current.estimatedAccountPct += positionWeightPct * holding.pct / 100;
      }
      current.funds = mergeStringLists(
        current.funds,
        [`${fundLabel}${Number.isFinite(holding.pct) ? ` ${round(holding.pct, 2)}%` : ""}`.trim()]
      ).slice(0, 8);
      holdingMap.set(key, current);
    }
  }

  const themeClusters = [...themeMap.values()]
    .map((item) => ({
      theme: item.theme,
      positionWeightPct: round(item.positionWeightPct, 2),
      fundCount: item.funds.length,
      funds: item.funds
    }))
    .filter((item) => item.positionWeightPct > 0)
    .sort((a, b) => Number(b.positionWeightPct || 0) - Number(a.positionWeightPct || 0))
    .slice(0, 8);

  const overlappingHoldings = [...holdingMap.values()]
    .map((item) => ({
      code: item.code,
      name: item.name,
      fundCount: item.fundCount,
      fundEnvelopePct: round(item.fundEnvelopePct, 2),
      estimatedAccountPct: round(item.estimatedAccountPct, 2),
      funds: item.funds
    }))
    .filter((item) => item.fundCount >= 2)
    .sort((a, b) =>
      Number(b.fundCount || 0) - Number(a.fundCount || 0)
      || Number(b.estimatedAccountPct || 0) - Number(a.estimatedAccountPct || 0)
    )
    .slice(0, 10);

  const largestPosition = [...activePositions]
    .sort((a, b) => Number(b.weightPct || 0) - Number(a.weightPct || 0))[0] || null;
  const riskNotes = buildPortfolioExposureRiskNotes({ themeClusters, overlappingHoldings, totalPositionWeightPct });
  return {
    totalPositionWeightPct: round(totalPositionWeightPct, 2),
    riskLevel: riskNotes.some((item) => /过度集中|重复持有/.test(item)) ? "high" : riskNotes.length ? "warning" : "normal",
    largestPosition: largestPosition ? {
      code: largestPosition.code || "",
      name: largestPosition.name || "",
      weightPct: round(Number(largestPosition.weightPct || 0), 2)
    } : null,
    themeClusters,
    overlappingHoldings,
    riskNotes
  };
}

function collectPortfolioPositionHoldingItems(position = {}) {
  const snapshot = position.fundSnapshot || {};
  const source = Array.isArray(snapshot.topHoldings) && snapshot.topHoldings.length
    ? snapshot.topHoldings
    : snapshot.holdings?.equityTopHoldings?.length
      ? snapshot.holdings.equityTopHoldings
      : snapshot.holdings?.bondTopHoldings?.length
        ? snapshot.holdings.bondTopHoldings
        : snapshot.actionability?.holdingsOutlook?.topHoldings || [];
  return normalizeHoldingItems(source).slice(0, 10);
}

function buildPortfolioExposureRiskNotes({ themeClusters = [], overlappingHoldings = [], totalPositionWeightPct = 0 } = {}) {
  const notes = [];
  const topTheme = themeClusters[0];
  if (topTheme && Number(topTheme.positionWeightPct) >= 25) {
    notes.push(`同题材暴露过度集中：${topTheme.theme}相关基金约${formatFallbackPlainPct(topTheme.positionWeightPct)}，新增同线买入应暂停或等回撤。`);
  } else if (topTheme && Number(topTheme.positionWeightPct) >= 18) {
    notes.push(`同题材暴露偏高：${topTheme.theme}相关基金约${formatFallbackPlainPct(topTheme.positionWeightPct)}，加仓前需证明低位轮动而非追涨。`);
  }
  const repeated = overlappingHoldings.find((item) => Number(item.fundCount) >= 3) || overlappingHoldings[0];
  if (repeated) {
    const holdingName = [repeated.code, repeated.name].filter(Boolean).join(" ") || "同一底层持仓";
    const severity = Number(repeated.fundCount) >= 3 ? "重复持有明显" : "存在重复持有";
    notes.push(`${severity}：${holdingName} 出现在${repeated.fundCount}只持仓基金前十大中，穿透估算约${formatFallbackPlainPct(repeated.estimatedAccountPct)}。`);
  }
  if (Number(totalPositionWeightPct) >= 70) {
    notes.push(`组合仓位${formatFallbackPlainPct(totalPositionWeightPct)}偏高，新增买入必须受账户回撤预算约束。`);
  }
  return notes.slice(0, 4);
}

function collectPortfolioPositionThemeTags(position = {}) {
  const holdings = collectPortfolioPositionHoldingItems(position);
  const explicitTags = normalizeStringArray(position.fundSnapshot?.actionability?.holdingsOutlook?.holdingTags);
  return [...new Set([
    ...explicitTags,
    ...holdings.flatMap((holding) => inferHoldingThemeTags(`${holding.code || ""} ${holding.name || ""}`)),
    ...inferHoldingThemeTags(`${position.name || ""} ${position.fundSnapshot?.name || ""}`)
  ].filter(Boolean))];
}

function formatPortfolioExposureSummaryLines(summary = {}) {
  const lines = [];
  const topTheme = summary.themeClusters?.[0];
  if (topTheme) {
    lines.push(`同题材暴露：${topTheme.theme}约${formatFallbackPlainPct(topTheme.positionWeightPct)}，涉及 ${topTheme.fundCount} 只基金。`);
  }
  if (summary.overlappingHoldings?.length) {
    const repeated = summary.overlappingHoldings[0];
    lines.push(`底层重叠：${[repeated.code, repeated.name].filter(Boolean).join(" ") || "重复持仓"} 出现在 ${repeated.fundCount} 只基金前十大中，穿透估算约${formatFallbackPlainPct(repeated.estimatedAccountPct)}。`);
  }
  lines.push(...normalizeStringArray(summary.riskNotes).slice(0, 3));
  return lines;
}

function getActivePortfolioWatchlist(db) {
  db.watchlist = normalizePortfolioWatchlist(db.watchlist);
  return db.watchlist.filter((item) => item.status !== "removed").slice(0, 60);
}

function normalizePortfolioWatchlist(value) {
  const input = Array.isArray(value) ? value : [];
  const byCode = new Map();
  for (const item of input) {
    const normalized = normalizePortfolioWatchItem(item);
    if (!normalized) continue;
    const existing = byCode.get(normalized.code);
    if (!existing || Date.parse(normalized.updatedAt || "") >= Date.parse(existing.updatedAt || "")) {
      byCode.set(normalized.code, normalized);
    }
  }
  return sortPortfolioWatchlist(consolidatePortfolioWatchlistAlternatives([...byCode.values()]));
}

function sortPortfolioWatchlist(items = []) {
  return [...items].sort((a, b) => {
    if (a.status === "removed" && b.status !== "removed") return 1;
    if (a.status !== "removed" && b.status === "removed") return -1;
    return Number(a.priority || 3) - Number(b.priority || 3)
      || String(b.updatedAt || "").localeCompare(String(a.updatedAt || ""));
  });
}

function normalizePortfolioWatchItem(item = {}, defaults = {}) {
  const now = defaults.now || new Date().toISOString();
  const code = String(item?.code || defaults.code || "").match(/^\d{6}$/)?.[0] || "";
  if (!code) return null;
  const status = normalizePortfolioWatchStatus(item.status || defaults.status || "watch");
  return {
    code,
    name: String(item.name || defaults.name || "").trim(),
    shareClass: String(item.shareClass || defaults.shareClass || "").trim().toUpperCase(),
    type: String(item.type || defaults.type || "").trim(),
    status,
    priority: normalizePortfolioWatchPriority(item.priority ?? defaults.priority ?? 3),
    candidateRole: String(item.candidateRole || defaults.candidateRole || "").trim(),
    reason: String(item.reason || defaults.reason || "").trim().slice(0, 1200),
    setupEvidence: normalizeStringArray(item.setupEvidence || defaults.setupEvidence).slice(0, 8),
    buyTriggers: normalizeStringArray(item.buyTriggers || defaults.buyTriggers).slice(0, 8),
    riskNotes: normalizeStringArray(item.riskNotes || defaults.riskNotes).slice(0, 8),
    feeNotes: normalizeStringArray(item.feeNotes || defaults.feeNotes).slice(0, 8),
    positionPlan: String(item.positionPlan || defaults.positionPlan || "").trim().slice(0, 600),
    reviewDate: String(item.reviewDate || defaults.reviewDate || "").trim().slice(0, 80),
    dataBasis: normalizeStringArray(item.dataBasis || defaults.dataBasis).slice(0, 8),
    source: String(item.source || defaults.source || "").trim().slice(0, 120),
    sourceRunId: String(item.sourceRunId || defaults.sourceRunId || "").trim().slice(0, 80),
    alternativeShareClasses: normalizePortfolioWatchAlternatives(item.alternativeShareClasses || defaults.alternativeShareClasses).slice(0, 8),
    sameExposureAlternatives: normalizePortfolioWatchAlternatives(item.sameExposureAlternatives || defaults.sameExposureAlternatives).slice(0, 8),
    lastSnapshot: item.lastSnapshot || defaults.lastSnapshot || null,
    addedAt: String(item.addedAt || defaults.addedAt || now),
    updatedAt: String(item.updatedAt || defaults.updatedAt || now)
  };
}

function normalizePortfolioWatchAlternatives(value) {
  const input = Array.isArray(value) ? value : [];
  const byCode = new Map();
  for (const item of input) {
    const code = String(item?.code || "").match(/^\d{6}$/)?.[0] || "";
    if (!code || byCode.has(code)) continue;
    byCode.set(code, {
      code,
      name: String(item.name || "").trim(),
      shareClass: String(item.shareClass || "").trim().toUpperCase(),
      type: String(item.type || "").trim(),
      status: item.status ? normalizePortfolioWatchStatus(item.status) : "",
      statusText: item.statusText || (item.status ? formatPortfolioWatchStatus(item.status) : ""),
      priority: item.priority === undefined || item.priority === null || item.priority === "" ? null : normalizePortfolioWatchPriority(item.priority),
      reason: String(item.reason || "").trim().slice(0, 260),
      shareClassFeeModel: item.shareClassFeeModel && typeof item.shareClassFeeModel === "object" ? {
        type: String(item.shareClassFeeModel.type || "").trim(),
        label: String(item.shareClassFeeModel.label || "").trim().slice(0, 120),
        selectionRule: String(item.shareClassFeeModel.selectionRule || "").trim().slice(0, 220)
      } : null,
      feeImpact: item.feeImpact && typeof item.feeImpact === "object" ? {
        oneYearCostPer10000: finiteMetricNumber(item.feeImpact.oneYearCostPer10000),
        twoYearCostPer10000: finiteMetricNumber(item.feeImpact.twoYearCostPer10000),
        feeDragLevel: String(item.feeImpact.feeDragLevel || "").trim(),
        holdingPeriodFit: String(item.feeImpact.holdingPeriodFit || "").trim()
      } : null,
      feeNotes: normalizeStringArray(item.feeNotes).slice(0, 3),
      riskNotes: normalizeStringArray(item.riskNotes).slice(0, 3),
      source: String(item.source || "").trim().slice(0, 120),
      updatedAt: String(item.updatedAt || "").trim()
    });
  }
  return [...byCode.values()];
}

function consolidatePortfolioWatchlistAlternatives(items = []) {
  const active = (items || []).filter((item) => item?.status !== "removed");
  const removed = (items || []).filter((item) => item?.status === "removed");
  const byProduct = consolidatePortfolioWatchlistByKey(active, getPortfolioWatchProductKey, "alternativeShareClasses", "watchlist_product_consolidation");
  const byExposure = consolidatePortfolioWatchlistByKey(byProduct, getPortfolioWatchExposureKey, "sameExposureAlternatives", "watchlist_exposure_consolidation");
  return [...byExposure, ...removed];
}

function consolidatePortfolioWatchlistByKey(items = [], keyFn, field, sourceLabel) {
  const groups = new Map();
  const passthrough = [];
  for (const item of items || []) {
    const key = keyFn(item);
    if (!key) {
      passthrough.push(item);
      continue;
    }
    if (!groups.has(key)) groups.set(key, []);
    groups.get(key).push(item);
  }

  const consolidated = [];
  for (const group of groups.values()) {
    if (group.length <= 1) {
      consolidated.push(group[0]);
      continue;
    }
    const sorted = [...group].sort(comparePortfolioWatchPrimaryCandidate);
    const primary = sorted[0];
    const alternatives = sorted.slice(1).map(buildPortfolioWatchAlternative);
    consolidated.push({
      ...primary,
      [field]: mergePortfolioWatchAlternatives(primary[field], alternatives),
      dataBasis: mergeStringLists(primary.dataBasis, [`来源：${sourceLabel}`]),
      riskNotes: mergeStringLists(
        primary.riskNotes,
        field === "alternativeShareClasses"
          ? ["同一基金不同份额已归并为替代份额，主列表只保留最可操作的一只。"]
          : ["同一指数/同主题暴露已归并为同类替代，避免重复占用自选池名额。"]
      )
    });
  }
  return [...passthrough, ...consolidated];
}

function comparePortfolioWatchPrimaryCandidate(a = {}, b = {}) {
  return portfolioWatchStatusRank(a.status) - portfolioWatchStatusRank(b.status)
    || Number(a.priority || 3) - Number(b.priority || 3)
    || portfolioWatchShareClassRank(a.shareClass) - portfolioWatchShareClassRank(b.shareClass)
    || String(b.updatedAt || "").localeCompare(String(a.updatedAt || ""));
}

function portfolioWatchStatusRank(status) {
  const ranks = {
    in_position: 0,
    ready: 1,
    waiting_pullback: 2,
    watch: 3,
    blocked: 5,
    removed: 9
  };
  return ranks[status] ?? 4;
}

function portfolioWatchShareClassRank(shareClass) {
  const ranks = { C: 0, E: 1, I: 1, A: 2, B: 3, D: 3 };
  return ranks[String(shareClass || "").toUpperCase()] ?? 4;
}

function buildPortfolioWatchAlternative(item = {}) {
  return {
    code: item.code || "",
    name: item.name || "",
    shareClass: item.shareClass || "",
    type: item.type || "",
    status: item.status || "",
    statusText: formatPortfolioWatchStatus(item.status),
    priority: item.priority || null,
    reason: item.reason || "",
    feeNotes: item.feeNotes || [],
    riskNotes: item.riskNotes || [],
    source: item.source || "",
    updatedAt: item.updatedAt || ""
  };
}

function mergePortfolioWatchAlternatives(...groups) {
  return normalizePortfolioWatchAlternatives(groups.flat()).slice(0, 8);
}

function getPortfolioWatchProductKey(item = {}) {
  return getCandidateProductKey(item);
}

function getPortfolioWatchExposureKey(item = {}) {
  return getCandidateExposureKey(item);
}

function normalizePortfolioWatchStatus(value) {
  const raw = String(value || "watch").trim().toLowerCase();
  const aliases = {
    buy: "ready",
    buyable: "ready",
    ready_to_buy: "ready",
    staged_buy: "ready",
    wait: "waiting_pullback",
    waiting: "waiting_pullback",
    wait_pullback: "waiting_pullback",
    hold_observe: "watch",
    avoid: "blocked",
    avoid_now: "blocked",
    reject: "blocked",
    remove: "removed",
    deleted: "removed",
    bought: "in_position",
    holding: "in_position"
  };
  const status = aliases[raw] || raw;
  return ["ready", "waiting_pullback", "watch", "blocked", "in_position", "removed"].includes(status)
    ? status
    : "watch";
}

function normalizePortfolioWatchPriority(value) {
  const numeric = Number(value);
  if (!Number.isFinite(numeric)) return 3;
  return Math.max(1, Math.min(5, Math.round(numeric)));
}

function normalizePortfolioWatchlistUpdates(value) {
  const input = Array.isArray(value) ? value : [];
  return input
    .map((item) => {
      const code = String(item?.code || "").match(/^\d{6}$/)?.[0] || "";
      if (!code) return null;
      return {
        operation: normalizePortfolioWatchOperation(item.operation || item.updateAction || item.action || "UPSERT"),
        code,
        name: String(item.name || "").trim(),
        shareClass: String(item.shareClass || "").trim().toUpperCase(),
        type: normalizePortfolioUserFacingText(item.type || ""),
        status: item.status ? normalizePortfolioWatchStatus(item.status) : "",
        priority: item.priority === undefined || item.priority === null || item.priority === ""
          ? null
          : normalizePortfolioWatchPriority(item.priority),
        candidateRole: normalizePortfolioUserFacingText(item.candidateRole || ""),
        reason: normalizePortfolioUserFacingText(item.reason || ""),
        setupEvidence: normalizePortfolioUserFacingArray(item.setupEvidence, 8),
        buyTriggers: normalizePortfolioUserFacingArray(item.buyTriggers, 8),
        riskNotes: normalizePortfolioUserFacingArray(item.riskNotes, 8),
        feeNotes: normalizePortfolioUserFacingArray(item.feeNotes, 8),
        positionPlan: normalizePortfolioUserFacingText(item.positionPlan || ""),
        reviewDate: String(item.reviewDate || "").trim(),
        dataBasis: normalizePortfolioUserFacingArray(item.dataBasis, 8),
        alternativeShareClasses: normalizePortfolioWatchAlternatives(item.alternativeShareClasses).slice(0, 8),
        sameExposureAlternatives: normalizePortfolioWatchAlternatives(item.sameExposureAlternatives).slice(0, 8),
        source: String(item.source || "").trim()
      };
    })
    .filter(Boolean)
    .slice(0, 20);
}

function normalizePortfolioWatchOperation(value) {
  const text = String(value || "UPSERT").trim().toUpperCase();
  if (["REMOVE", "DELETE", "DROP"].includes(text)) return "REMOVE";
  return "UPSERT";
}

function buildPortfolioWatchlistUpdatesFromActions(actions = []) {
  return (actions || [])
    .filter((action) => action?.code && ["BUY", "WATCH", "HOLD", "SELL"].includes(action.action))
    .map((action) => {
      const status = inferPortfolioWatchStatusFromAction(action);
      return {
        operation: "UPSERT",
        code: action.code,
        name: action.name || "",
        status,
        priority: status === "ready" ? 1 : status === "waiting_pullback" ? 2 : status === "blocked" ? 5 : 3,
        candidateRole: action.action === "BUY"
          ? "已触发买入候选"
          : action.action === "WATCH"
            ? "自选观察候选"
            : action.action === "SELL"
              ? "卖出后复查候选"
              : "持仓复查候选",
        reason: action.reason || "",
        setupEvidence: [action.rotationCheck, action.positionCheck].filter(Boolean),
        buyTriggers: action.action === "WATCH" ? [action.riskControl].filter(Boolean) : [],
        riskNotes: [action.chaseRisk, action.riskControl].filter(Boolean),
        feeNotes: [action.feeCheck].filter(Boolean),
        positionPlan: action.targetWeightPct
          ? `触发后目标仓位约 ${action.targetWeightPct}%。`
          : action.amount
            ? `触发后先观察 ${action.amount} 元级别试探。`
            : "",
        dataBasis: action.dataBasis || [],
        source: "portfolio_action"
      };
    });
}

async function fetchPortfolioWatchlistSeedCandidates(marketSnapshot, watchlist = [], options = {}) {
  if (String(process.env.PORTFOLIO_WATCHLIST_SEED_ENABLED ?? "true") === "false") {
    return [];
  }
  const activeWatchlist = getActivePortfolioWatchlist({ watchlist });
  const targetSize = Math.max(0, finiteNumberOr(process.env.PORTFOLIO_WATCHLIST_TARGET_SIZE, 10));
  const deficit = targetSize - activeWatchlist.filter((item) => !["blocked", "removed"].includes(item.status)).length;
  const forceRedeploymentScan = shouldForcePortfolioRedeploymentSeedScan(options.account, activeWatchlist, options.profiles || []);
  const blockedFollowThroughCandidates = findPortfolioBacktestBlockedFollowThroughCandidates({
    watchlist: activeWatchlist,
    totalAsset: options.account?.totalAsset || 0
  });
  const dataBlockedCandidates = findPortfolioBacktestDataBlockedCandidates(activeWatchlist);
  const forceBlockedReplacementScan = shouldForcePortfolioBlockedFollowThroughSeedScan(options.account, activeWatchlist);
  const forceDataBlockedScan = shouldForcePortfolioDataBlockedSeedScan(options.account, activeWatchlist);
  const forceThemeOpportunityScan = shouldForcePortfolioThemeOpportunitySeedScan(marketSnapshot, activeWatchlist);
  if (deficit <= 0 && !forceRedeploymentScan && !forceBlockedReplacementScan && !forceDataBlockedScan && !forceThemeOpportunityScan) return [];

  const userText = buildPortfolioWatchlistSeedSearchText([
    ...blockedFollowThroughCandidates,
    ...dataBlockedCandidates
  ], marketSnapshot);
  const themeRadar = Array.isArray(marketSnapshot?.themeRadar) ? marketSnapshot.themeRadar : [];
  const themeCarrierSeedCandidates = buildPortfolioThemeOpportunitySeedCandidates(marketSnapshot);
  const candidates = await fetchPullbackSetupCandidates(userText, marketSnapshot, themeRadar);
  return selectPortfolioWatchlistSeedCandidates(mergeCandidateFunds(themeCarrierSeedCandidates, candidates), activeWatchlist, themeRadar, {
    marketSnapshot,
    limit: forceRedeploymentScan || forceBlockedReplacementScan || forceDataBlockedScan || forceThemeOpportunityScan
      ? finiteNumberOr(process.env.PORTFOLIO_REDEPLOYMENT_SEED_LIMIT, 8)
      : Math.min(deficit, finiteNumberOr(process.env.PORTFOLIO_WATCHLIST_SEED_LIMIT, 6))
  });
}

function shouldForcePortfolioRedeploymentSeedScan(account = {}, watchlist = [], profiles = []) {
  const plan = buildPortfolioRedeploymentPlan(account, watchlist, profiles);
  if (!plan.pressureActive) return false;
  return !plan.candidates.some((item) => ["verified_buy", "starter_buy", "theme_micro_starter"].includes(item.redeploymentAction));
}

function shouldForcePortfolioBlockedFollowThroughSeedScan(account = {}, watchlist = []) {
  const totalAsset = Number(account.totalAsset || 0);
  const cash = Number(account.cash || 0);
  const cashPct = totalAsset > 0 ? cash / totalAsset * 100 : null;
  if (!Number.isFinite(cashPct) || cashPct < 55 || account.riskBudget?.blockNewBuys) return false;
  return findPortfolioBacktestBlockedFollowThroughCandidates({
    watchlist,
    totalAsset
  }).length > 0;
}

function shouldForcePortfolioDataBlockedSeedScan(account = {}, watchlist = []) {
  const totalAsset = Number(account.totalAsset || 0);
  const cash = Number(account.cash || 0);
  const cashPct = totalAsset > 0 ? cash / totalAsset * 100 : null;
  if (!Number.isFinite(cashPct) || cashPct < 55 || account.riskBudget?.blockNewBuys) return false;
  return findPortfolioBacktestDataBlockedCandidates(watchlist).length > 0;
}

function shouldForcePortfolioThemeOpportunitySeedScan(marketSnapshot = null, watchlist = []) {
  const keywordGroups = buildPortfolioThemeOpportunityKeywordGroups(marketSnapshot);
  if (!keywordGroups.length) return false;
  return keywordGroups.some((group) =>
    !hasPortfolioThemeRepresentativeCoverageForGroup(watchlist, group)
  );
}

function buildPortfolioWatchlistSeedSearchText(seedContextCandidates = [], marketSnapshot = null) {
  const keywords = inferPortfolioBlockedFollowThroughSearchKeywords(seedContextCandidates);
  const themeKeywords = inferPortfolioThemeOpportunitySearchKeywords(marketSnapshot);
  return [
    "回调完成",
    "低位",
    "准备启动",
    "主力进场",
    "题材预热",
    "新闻催化",
    "前十大持仓",
    "龙头承载",
    "同主题替代",
    "代表基金",
    "基金",
    ...themeKeywords,
    ...keywords
  ].join(" ");
}

function inferPortfolioThemeOpportunitySearchKeywords(marketSnapshot = null) {
  return [...new Set(buildPortfolioThemeOpportunityKeywordGroups(marketSnapshot)
    .flatMap((group) => group.keywords))]
    .slice(0, 12);
}

function buildPortfolioThemeOpportunityKeywordGroups(marketSnapshot = null) {
  const leaderItems = filterPortfolioDefaultThemeOpportunityItems(
    collectPortfolioThemeOpportunityLeaderboardItems(marketSnapshot)
      .filter((item) => ["mainCapital", "preheat", "lowRotation"].includes(item.laneKey))
  )
    .slice(0, 6);
  if (!leaderItems.length) return [];
  const radar = Array.isArray(marketSnapshot?.themeRadar) ? marketSnapshot.themeRadar : [];
  const radarById = new Map(radar.map((theme) => [String(theme.id || theme.name || ""), theme]));
  return leaderItems.map((item) => {
    const theme = radarById.get(String(item.id || "")) || radar.find((candidate) => candidate.name === item.name) || {};
    const keywords = collectThemeOpportunitySearchKeywords(theme, {
      extra: [item.name, item.whyMove, item.newsLogic, item.catalyst, ...(item.carrierSearchKeywords || [])]
    });
    return {
      id: item.id || theme.id || "",
      laneKey: item.laneKey,
      title: item.title || formatPortfolioThemeOpportunityLaneTitle(theme),
      name: item.name || theme.name || "",
      keywords,
      anchors: collectThemeOpportunityAnchorKeywords(theme, {
        extra: [item.name, ...(item.carrierAnchors || [])]
      }),
      whyMove: item.whyMove || item.newsLogic || theme.newsLogic || theme.primaryCatalyst || "",
      newsLogic: item.newsLogic || theme.newsLogic || "",
      catalyst: item.catalyst || theme.catalystProfile?.summary || theme.primaryCatalyst || "",
      catalystFreshness: item.catalystFreshness || theme.catalystProfile?.freshnessLabel || "",
      latestNewsTime: theme.catalystProfile?.latestNewsTime || "",
      capitalProof: item.capitalProof || formatThemeMainForceCapitalProof(theme),
      playbookAction: item.playbookAction || ""
    };
  }).filter((group) => group.keywords.length);
}

function buildPortfolioThemeOpportunitySeedCandidates(marketSnapshot = null) {
  const themeRadar = Array.isArray(marketSnapshot?.themeRadar) ? marketSnapshot.themeRadar : [];
  if (!themeRadar.length) return [];
  const leaderItems = filterPortfolioDefaultThemeOpportunityItems(
    collectPortfolioThemeOpportunityLeaderboardItems(marketSnapshot)
      .filter((item) => ["mainCapital", "preheat", "lowRotation"].includes(item.laneKey))
  );
  if (!leaderItems.length) return [];
  const laneByThemeKey = new Map();
  for (const item of leaderItems) {
    for (const key of [item.id, item.name].map((value) => normalizeIntentText(value)).filter(Boolean)) {
      if (!laneByThemeKey.has(key)) laneByThemeKey.set(key, item);
    }
  }
  const seeds = [];
  for (const theme of themeRadar) {
    const themeKeys = [theme.id, theme.name].map((value) => normalizeIntentText(value)).filter(Boolean);
    const lane = themeKeys.map((key) => laneByThemeKey.get(key)).find(Boolean);
    if (!lane || !isPortfolioThemeOpportunitySeedTheme(theme)) continue;
    const funds = Array.isArray(theme.evidence?.funds) ? theme.evidence.funds : [];
    const keywords = collectThemeOpportunitySearchKeywords(theme, {
      extra: [theme.name, lane.whyMove, theme.newsLogic, theme.primaryCatalyst, lane.title, ...(lane.carrierSearchKeywords || [])]
    }).slice(0, 10);
    const carrierAnchors = collectThemeOpportunityAnchorKeywords(theme, {
      extra: [theme.name, ...(lane.carrierAnchors || [])]
    }).slice(0, 8);
    const compactTheme = compactMatchedThemeSignal(theme);
    for (const fund of funds.slice(0, 5)) {
      const code = String(fund.code || "").match(/^\d{6}$/)?.[0] || "";
      if (!code) continue;
      seeds.push({
        ...fund,
        code,
        name: fund.name || "",
        shareClass: fund.shareClass || inferFundShareClass(fund.name || ""),
        type: fund.type || "",
        keywords: [...new Set([...(fund.keywords || []), ...keywords, ...carrierAnchors, "题材榜单代表基金"].filter(Boolean))],
        matchedThemes: [compactTheme],
        themeOpportunityRequirement: "require_current_theme_playbook",
        candidateRole: `${lane.title || "主力/预热题材"}代表基金`,
        setupDiscoverySource: `theme_leaderboard_carrier_seed:${lane.laneKey || lane.id || "theme"}`,
        themeEvidence: formatCandidateThemeEvidence({ matchedThemes: [compactTheme] }),
        dataBasis: [
          `题材榜单：${lane.title || "主力/预热题材"}`,
          lane.playbookAction ? `作战动作：${lane.playbookAction}` : "",
          lane.whyMove ? `为什么动：${lane.whyMove}` : "",
          lane.capitalProof ? `主力证据：${lane.capitalProof}` : "",
          theme.newsLogic ? `题材逻辑：${theme.newsLogic}` : "",
          theme.catalystProfile?.summary ? `催化性质：${theme.catalystProfile.summary}` : "",
          theme.primaryCatalyst ? `新闻线索：${theme.primaryCatalyst}` : "",
          carrierAnchors.length ? `承载锚点：${carrierAnchors.join("/")}` : ""
        ].filter(Boolean),
        source: fund.source || "market_theme_leaderboard"
      });
    }
  }
  return mergeCandidateFunds(seeds);
}

function filterPortfolioDefaultThemeOpportunityItems(items = []) {
  const list = (items || []).filter(Boolean);
  const hasNonPrecious = list.some((item) => !isPreciousPortfolioThemeOpportunityItem(item));
  return hasNonPrecious ? list.filter((item) => !isPreciousPortfolioThemeOpportunityItem(item)) : list;
}

function isPreciousPortfolioThemeOpportunityItem(item = {}) {
  return item.id === "precious_metals" || /黄金|贵金属|白银|金价|沪金|沪银|COMEX/i.test(`${item.name || ""} ${item.reason || ""} ${item.newsLogic || ""}`);
}

function isPortfolioThemeOpportunitySeedTheme(theme = {}) {
  if (!theme || typeof theme !== "object") return false;
  if (hasThemeCapitalRetreatRisk(theme) || isStaleThemeCatchdownRiskTheme(theme)) return false;
  if (theme.positionSignal === "high_chase_risk" || theme.stage === "crowded" || Number(theme.crowdingScore) >= 55) return false;
  const capitalFlowConflict = hasConflictingThemeCapitalOutflow(theme);
  const mainOrPreheat = !capitalFlowConflict && hasTraceableFreshThemeCatalystContext(theme) && hasThemeLeaderOrPreheatSignal(theme);
  const lowRotation = hasUsableThemeLowRotationSupport(theme);
  return Boolean(mainOrPreheat || (lowRotation && (hasTraceableFreshThemeCatalystContext(theme) || Number(theme.capitalFollowScore) >= 45)));
}

function getPortfolioThemeCoverageAnchors(group = {}) {
  const anchors = normalizeStringArray(group.anchors).filter(Boolean);
  return anchors.length ? anchors : normalizeStringArray(group.keywords);
}

function collectThemeOpportunitySearchKeywords(theme = {}, options = {}) {
  const boards = Array.isArray(theme.evidence?.boards) ? theme.evidence.boards : [];
  const catalystKeywords = collectThemeCatalystSearchKeywords(theme, options);
  const values = [
    theme.name,
    ...catalystKeywords,
    ...(Array.isArray(theme.fundKeywords) ? theme.fundKeywords : []),
    ...(Array.isArray(theme.keywords) ? theme.keywords : []),
    ...(Array.isArray(theme.themeKeywords) ? theme.themeKeywords : []),
    ...(Array.isArray(theme.newsKeywords) ? theme.newsKeywords : []),
    ...(Array.isArray(theme.boardNames) ? theme.boardNames : []),
    ...(Array.isArray(theme.leaderStocks) ? theme.leaderStocks : []),
    ...boards.flatMap((board) => [board.name, board.leadStock]),
    ...(Array.isArray(options.extra) ? options.extra : [])
  ];
  return [...new Set(values
    .flatMap((value) => String(value || "").split(/[，,、/；;+\s]+/))
    .map((value) => value.trim())
    .filter(isThemeOpportunitySearchKeywordUseful))].slice(0, 18);
}

function collectThemeCatalystSearchKeywords(theme = {}, options = {}) {
  const newsItems = Array.isArray(theme.evidence?.news) ? theme.evidence.news : [];
  const texts = [
    theme.newsLogic,
    theme.primaryCatalyst,
    theme.catalystProfile?.summary,
    ...(Array.isArray(options.extra) ? options.extra : []),
    ...newsItems.slice(0, 5).map((item) => `${item.title || ""} ${item.mediaName || ""}`)
  ].map((item) => String(item || "").trim()).filter(Boolean);
  const extracted = new Set();
  for (const text of texts) {
    for (const term of extractEmergingNewsTopicTerms({ title: text })) {
      extracted.add(term);
    }
    const normalized = normalizeIntentText(text);
    for (const group of THEME_NEWS_KEYWORD_EXPANSIONS) {
      const needles = (group.needles || []).map(normalizeIntentText).filter(Boolean);
      if (needles.some((needle) => needle && normalized.includes(needle))) {
        for (const alias of collectMatchedThemeNewsAliases(group, normalized)) extracted.add(alias);
      }
    }
  }
  return [...new Set(expandThemeNewsKeywords([...extracted], { name: theme.name || "", preciseOnly: true }))]
    .filter(isThemeOpportunitySearchKeywordUseful)
    .slice(0, 10);
}

function collectMatchedThemeNewsAliases(group = {}, normalizedText = "") {
  const aliases = (group.aliases || []).filter(Boolean);
  const matchedAliases = aliases.filter((alias) => {
    const value = normalizeIntentText(alias);
    return value && normalizedText.includes(value);
  });
  if (matchedAliases.length) return matchedAliases.slice(0, 5);
  const matchedNeedles = (group.needles || []).filter((needle) => {
    const value = normalizeIntentText(needle);
    return value && normalizedText.includes(value);
  });
  const needleAliases = matchedNeedles
    .map((needle) => aliases.find((alias) => normalizeIntentText(alias).includes(normalizeIntentText(needle))))
    .filter(Boolean);
  return (needleAliases.length ? needleAliases : aliases.slice(0, 1)).slice(0, 5);
}

function collectThemeOpportunityAnchorKeywords(theme = {}, options = {}) {
  const boards = Array.isArray(theme.evidence?.boards) ? theme.evidence.boards : [];
  const catalystKeywords = collectThemeCatalystSearchKeywords(theme, options);
  const values = [
    ...catalystKeywords,
    ...(Array.isArray(theme.boardNames) ? theme.boardNames : []),
    ...(Array.isArray(theme.leaderStocks) ? theme.leaderStocks : []),
    ...boards.flatMap((board) => [board.name, board.leadStock]),
    ...(Array.isArray(theme.newsKeywords) ? theme.newsKeywords : []),
    theme.name,
    ...(Array.isArray(options.extra) ? options.extra : [])
  ];
  const anchors = [...new Set(values
    .flatMap((value) => String(value || "").split(/[，,、/；;+\s]+/))
    .map((value) => value.trim())
    .filter(isThemeOpportunityAnchorKeywordUseful))];
  const specificAnchors = anchors.filter((anchor) => !isBroadThemeOpportunityCoverageAnchor(anchor));
  return (specificAnchors.length ? specificAnchors : anchors).slice(0, 10);
}

function isThemeOpportunitySearchKeywordUseful(value = "") {
  const text = String(value || "").trim();
  if (text.length < 2 || text.length > 18) return false;
  if (/^(基金|代表基金|主题|板块|概念|行业|方向|逻辑|催化|新闻|预热|主力|资金|低位|轮动|回调|机会|测试)$/.test(text)) return false;
  if (/^(news|dynamic|theme|main|preheat|low|capital)[_-]/i.test(text)) return false;
  if (/^\d+(?:\.\d+)?%?$/.test(text)) return false;
  return true;
}

function isThemeOpportunityAnchorKeywordUseful(value = "") {
  const text = String(value || "").trim();
  if (!isThemeOpportunitySearchKeywordUseful(text)) return false;
  const normalized = normalizeIntentText(text);
  if (GENERIC_THEME_NEWS_MATCH_TERMS?.has?.(normalized)) return false;
  if (/^(科技|电子|通信|汽车|新能源|高端制造|军工|医药|医疗|资源|材料|设备|行业|概念)$/.test(text)) return false;
  return true;
}

function isBroadThemeOpportunityCoverageAnchor(value = "") {
  const text = normalizeIntentText(value);
  if (!text) return true;
  return [
    "科技",
    "电子",
    "通信",
    "汽车",
    "新能源",
    "高端制造",
    "智能制造",
    "军工",
    "医药",
    "医疗",
    "资源",
    "材料",
    "设备",
    "人工智能",
    "数字经济"
  ].some((item) => text === normalizeIntentText(item));
}

function inferPortfolioBlockedFollowThroughSearchKeywords(candidates = []) {
  const text = normalizeIntentText((candidates || []).slice(0, 6).map((item) => [
    item.name,
    item.reason,
    item.blockingReason,
    item.blocker,
    item.evidence,
    ...(item.setupEvidence || []),
    ...(item.riskNotes || []),
    ...(item.readinessGaps || [])
  ].filter(Boolean).join(" ")).join(" "));
  const groups = [
    { needles: ["信息传媒", "传媒", "游戏", "影视"], keywords: ["传媒", "游戏"] },
    { needles: ["全球价值", "全球", "海外", "qdii"], keywords: ["QDII", "全球", "海外"] },
    { needles: ["新能源车", "新能源", "锂电", "电池"], keywords: ["新能源", "新能源车", "锂电池"] },
    { needles: ["香港", "港股", "恒生"], keywords: ["港股", "恒生"] },
    { needles: ["深圳", "特区", "小盘"], keywords: ["中证1000", "中证2000"] },
    { needles: ["医药", "医疗", "创新药"], keywords: ["医药", "医疗"] },
    { needles: ["半导体", "芯片"], keywords: ["半导体", "芯片"] },
    { needles: ["人工智能", "ai", "算力", "通信"], keywords: ["人工智能", "算力", "通信"] }
  ];
  const keywords = [];
  for (const group of groups) {
    if (group.needles.some((needle) => text.includes(normalizeIntentText(needle)))) {
      keywords.push(...group.keywords);
    }
  }
  return [...new Set(keywords)].slice(0, 8);
}

function selectPortfolioWatchlistSeedCandidates(candidates = [], watchlist = [], themeRadar = [], options = {}) {
  const activeCodes = new Set(normalizePortfolioWatchlist(watchlist)
    .filter((item) => item.status !== "removed")
    .map((item) => item.code));
  const minScore = finiteNumberOr(options.minScore ?? process.env.PORTFOLIO_WATCHLIST_SEED_MIN_SCORE, 52);
  const limit = Math.max(0, finiteNumberOr(options.limit ?? process.env.PORTFOLIO_WATCHLIST_SEED_LIMIT, 6));
  if (!limit) return [];
  const marketContext = options.marketSnapshot || themeRadar;
  const currentThemeRadar = Array.isArray(marketContext?.themeRadar)
    ? marketContext.themeRadar
    : Array.isArray(themeRadar)
      ? themeRadar
      : [];

  const scored = (candidates || [])
    .filter((candidate) => candidate?.code && !activeCodes.has(candidate.code))
    .map((candidate) => {
      const currentThemeCandidate = refreshPortfolioCandidateThemesWithMarketRadar(candidate, marketContext);
      const matchedThemes = currentThemeCandidate.matchedThemes?.length ? currentThemeCandidate.matchedThemes : matchCandidateThemes(candidate, currentThemeRadar);
      const enriched = { ...candidate, ...currentThemeCandidate, matchedThemes };
      return {
        ...enriched,
        portfolioWatchlistSeedScore: round(scorePullbackSetupSeedCandidate(enriched, marketContext, "回调完成 低位 准备启动 基金"), 1)
      };
    })
    .filter((candidate) =>
      Number(candidate.portfolioWatchlistSeedScore || 0) >= minScore
      && !isPortfolioWatchlistChaseSeed(candidate)
    )
    .sort((a, b) => {
      const scoreDiff = Number(b.portfolioWatchlistSeedScore || 0) - Number(a.portfolioWatchlistSeedScore || 0);
      if (scoreDiff) return scoreDiff;
      return Number(isLowBaseLaunchWatchSeed(b)) - Number(isLowBaseLaunchWatchSeed(a));
    });

  return selectDiversifiedDeepDiveCandidates(scored, limit, { diversifyExposure: true });
}

function finiteNumberOr(value, fallback) {
  const numeric = Number(value);
  return Number.isFinite(numeric) ? numeric : fallback;
}

function isPortfolioWatchlistChaseSeed(candidate = {}) {
  const oneWeek = toNumber(candidate.oneWeekPct);
  const oneMonth = toNumber(candidate.oneMonthPct);
  const threeMonth = toNumber(candidate.threeMonthPct);
  const sixMonth = toNumber(candidate.sixMonthPct);
  if (Number.isFinite(oneWeek) && oneWeek > 7) return true;
  if (Number.isFinite(oneMonth) && oneMonth > 12) return true;
  if (Number.isFinite(threeMonth) && threeMonth > 25) return true;
  if (Number.isFinite(sixMonth) && sixMonth > 45) return true;
  return (candidate.matchedThemes || []).some((theme) =>
    theme.positionSignal === "high_chase_risk" || theme.stage === "crowded"
    || isStaleThemeCatchdownRiskTheme(theme)
  );
}

function isLowBaseLaunchWatchSeed(candidate = {}) {
  const text = [
    candidate.name || "",
    candidate.type || "",
    candidate.candidateRole || "",
    candidate.reason || "",
    candidate.positionPlan || "",
    candidate.setupDiscoverySource || "",
    candidate.source || "",
    ...(candidate.discoverySources || []),
    ...(candidate.keywords || []),
    ...(candidate.setupEvidence || []),
    ...(candidate.dataBasis || [])
  ].join(" ");
  return /低位启动前夜候选|low_base_turn_scan/.test(text);
}

function formatPortfolioWatchSeedKind(candidate = {}, profile = null) {
  if (profile && hasPortfolioThemeMicroStarterSetup(profile)) {
    return hasThemeLowBaseMicroStarterTrendSetup(profile.trendProfile || {})
      ? "低位主力预热候选"
      : "主线启动验证候选";
  }
  if (isLowBaseLaunchWatchSeed(candidate)) return "低位启动前夜候选";
  if (hasPortfolioPlaybookOpportunitySeedContext(candidate)) return "主力预热代表基金候选";
  const text = `${candidate.name || ""} ${(candidate.keywords || []).join(" ")} ${candidate.setupDiscoverySource || ""}`;
  if (/theme_leaderboard_carrier_seed|题材榜单代表基金/.test(text)) return "主力预热代表基金候选";
  if (/近1周低位转强候选|weekly_reversal_scan/.test(text)) return "近1周低位转强候选";
  return "低位回调召回候选";
}

function hasPortfolioPlaybookOpportunitySeedContext(candidate = {}) {
  const text = [
    candidate.name,
    candidate.type,
    candidate.candidateRole,
    candidate.setupDiscoverySource,
    candidate.source,
    candidate.marketThemeRefresh?.source,
    candidate.seed?.marketThemeRefresh?.source,
    ...(candidate.keywords || []),
    ...(candidate.setupEvidence || []),
    ...(candidate.dataBasis || []),
    ...(candidate.seed?.dataBasis || [])
  ].filter(Boolean).join(" ");
  return /theme_leaderboard_carrier_seed|题材榜单代表基金|theme_main_force_playbook_opportunity|作战图机会|主力作战图/.test(text)
    || collectPortfolioManagerPlaybookOpportunityMatches(candidate).length > 0;
}

function formatPortfolioSeedPlaybookOpportunityEvidence(candidate = {}) {
  const match = collectPortfolioManagerPlaybookOpportunityMatches(candidate)[0];
  if (!match) return "";
  const matchedTerms = normalizeStringArray(match.matchedTerms).slice(0, 3).join("/");
  return [
    "作战图机会",
    match.name || "",
    match.laneTitle || "",
    match.capitalProof || "",
    matchedTerms ? `承载锚点：${matchedTerms}` : ""
  ].filter(Boolean).join("，");
}

function formatPortfolioWatchSeedCandidateRole(status, seedKind) {
  if (status === "blocked") return "追涨风险拦截候选";
  if (seedKind === "主线启动验证候选") {
    return status === "ready" ? "主线启动微型验证备选" : "主线启动观察备选";
  }
  if (seedKind === "低位主力预热候选") {
    return status === "ready" ? "低位主力预热微型试探备选" : "低位主力预热观察备选";
  }
  if (seedKind === "主力预热代表基金候选") {
    return status === "ready" ? "主力预热代表基金微型复核备选" : "主力预热代表基金观察备选";
  }
  if (status === "ready") {
    return seedKind === "低位启动前夜候选" ? "净值验证低位启动前夜备选" : "净值验证低位启动备选";
  }
  return seedKind === "低位启动前夜候选" ? "低位启动前夜观察备选" : "回调观察备选";
}

function buildPortfolioWatchlistUpdatesFromSeedCandidates(candidates = [], options = {}) {
  const profiles = Array.isArray(options) ? options : options.profiles || [];
  const profileByCode = new Map((profiles || []).filter(Boolean).map((profile) => [profile.code, profile]));
  return (candidates || []).map((candidate) => {
    const profile = profileByCode.get(candidate.code) || null;
    const shareClass = profile?.fees?.shareClass || profile?.shareClass || candidate.shareClass || inferFundShareClass(candidate.name || "");
    const feeModel = profile?.fees?.shareClassFeeModel || profile?.shareClassFeeModel || candidate.shareClassFeeModel || inferShareClassFeeModel(shareClass, {
      sourceRatePct: candidate.sourceRatePct || "",
      currentRatePct: candidate.currentRatePct || "",
      salesServiceFeePct: ""
    });
    const seedScore = Number(candidate.portfolioWatchlistSeedScore || scorePullbackSetupSeedCandidate(candidate, candidate.matchedThemes || [], "回调完成 低位 准备启动 基金"));
    const status = inferPortfolioWatchStatusFromSeedCandidate(candidate, seedScore, profile);
    const themeEvidence = formatPortfolioSeedThemeEvidence(candidate);
    const returnEvidence = formatPortfolioSeedReturnEvidence(candidate);
    const verifiedTrendEvidence = formatPortfolioSeedVerifiedTrendEvidence(profile);
    const statusReason = formatPortfolioSeedStatusReason(status, profile);
    const oneYearFeeCost = toNumber(profile?.fees?.feeImpact?.oneYearCostPer10000);
    const seedKind = formatPortfolioWatchSeedKind(candidate, profile);
    const playbookEvidence = formatPortfolioSeedPlaybookOpportunityEvidence(candidate);
    return {
      operation: "UPSERT",
      code: candidate.code,
      name: profile?.name || candidate.name || "",
      shareClass,
      type: candidate.type || profile?.type || "",
      status,
      priority: scorePortfolioWatchSeedPriority(seedScore, status, seedKind),
      candidateRole: formatPortfolioWatchSeedCandidateRole(status, seedKind),
      reason: [
        `系统低位回调召回评分 ${round(seedScore, 1)}。`,
        `召回定位：${seedKind}。`,
        statusReason,
        playbookEvidence,
        returnEvidence || "短期收益结构待复核。",
        verifiedTrendEvidence,
        themeEvidence || "题材轮动信号待复核。"
      ].filter(Boolean).join(" "),
      setupEvidence: [
        `召回定位：${seedKind}`,
        playbookEvidence,
        verifiedTrendEvidence,
        returnEvidence,
        themeEvidence,
        ...(candidate.keywords || []).slice(0, 3).map((keyword) => `召回标签：${keyword}`)
      ].filter(Boolean),
      buyTriggers: [
        seedKind === "主线启动验证候选" || seedKind === "主力预热代表基金候选"
          ? "主力资金和新闻催化继续成立，代表持仓不冲高回落，才允许0.5%-1.2%微型验证。"
          : "后续5日/10日继续温和转强，且近20日涨幅不超过10%。",
        seedKind === "主线启动验证候选" || seedKind === "主力预热代表基金候选"
          ? "题材不进入拥挤/追涨状态，基金前十大仍能承载龙头或指数标的。"
          : "主题不进入拥挤状态，120日低位或距高点回撤证据得到净值下钻确认。",
        "费用和份额类别适合计划持有期后，再小仓位分批。"
      ],
      riskNotes: [
        profile?.trendProfile?.ok
          ? "候选已做净值下钻，但仍需在下一次盘前观察复核是否继续低位转强。"
          : "候选来自公开排行和搜索召回，缺少可用净值下钻时不能标记为可买。",
        status === "blocked" ? "净值下钻显示偏热、等待回撤或缺少低位证据，已拦截为非买入候选。" : "",
        "如果近1周或近1月涨幅突然扩大，降级为等待回调，避免追涨。"
      ].filter(Boolean),
      feeNotes: [
        feeModel?.label || "份额类别和费率待基金详情页复核。",
        Number.isFinite(oneYearFeeCost)
          ? `估算持有1年每万元费用约 ${round(oneYearFeeCost, 0)} 元。`
          : ""
      ].filter(Boolean),
      positionPlan: status === "ready"
        ? seedKind === "主线启动验证候选" || seedKind === "主力预热代表基金候选"
          ? "只按主线启动微型验证处理，单笔0.5%-1.2%，若新闻或主力退潮立即撤回。"
          : "触发后先作为卫星仓小额分批，不直接重仓。"
        : status === "blocked"
          ? "暂不买入；只有重新回到低位、回撤完成并消化追涨风险后才复核。"
          : seedKind === "低位启动前夜候选"
            ? "先放入启动前夜观察池；只等净值下钻确认回调完成、低位和早期转强后小额分批。"
            : "先放入观察池，等待回调完成和走势确认。",
      reviewDate: "下一次盘前观察或每日决策复核",
      dataBasis: [
        candidate.setupDiscoverySource ? `召回来源：${candidate.setupDiscoverySource}` : "",
        playbookEvidence,
        ...(Array.isArray(candidate.dataBasis) ? candidate.dataBasis.slice(0, 4) : []),
        candidate.source || "",
        profile?.sources?.[0] ? `净值下钻来源：${profile.sources[0]}` : "",
        returnEvidence
      ].filter(Boolean),
      source: "deterministic_pullback_recall"
    };
  });
}

function buildPortfolioWatchlistUpdatesFromAnswerProfiles(profiles = [], options = {}) {
  const input = Array.isArray(profiles) ? profiles : [profiles].filter(Boolean);
  const userText = String(options.userText || "").trim();
  const answerText = String(options.answerText || "").trim();
  const source = String(options.source || "fund_answer_watchlist").trim() || "fund_answer_watchlist";
  const seen = new Set();
  return input
    .map((profile) => {
      const code = String(profile?.code || profile?.seed?.code || "").match(/^\d{6}$/)?.[0] || "";
      if (!code || seen.has(code)) return null;
      seen.add(code);
      const context = extractAnswerWatchlistProfileContext(answerText, profile);
      const role = inferAnswerWatchlistRole(profile, context);
      const hardRiskWarnings = getAnswerWatchlistHardRiskWarnings(profile);
      const rejectedByAnswer = isAnswerWatchlistRejectedContext(context);
      const rejectedByHardRisk = hardRiskWarnings.length > 0;
      const rejected = rejectedByAnswer || rejectedByHardRisk;
      const catchdownRejected = rejected && isAnswerWatchlistCatchdownRisk(profile, context, hardRiskWarnings);
      const status = rejected ? "blocked" : inferPortfolioWatchStatusFromAnswerProfile(profile, role);
      const trendEvidence = formatPortfolioSeedVerifiedTrendEvidence(profile);
      const shareClass = profile?.fees?.shareClass || profile?.shareClass || profile?.seed?.shareClass || inferFundShareClass(profile?.name || profile?.seed?.name || "");
      const feeModel = profile?.fees?.shareClassFeeModel || profile?.shareClassFeeModel || profile?.seed?.shareClassFeeModel || inferShareClassFeeModel(shareClass, profile?.fees || {});
      const oneYearFeeCost = toNumber(profile?.fees?.feeImpact?.oneYearCostPer10000);
      const answerRole = rejected ? "暂不买入/排除" : role === "backup" ? "备选观察" : "买入参考";
      const originLabel = formatAnswerWatchlistSourceLabel(source);
      const statusReason = rejectedByAnswer
        ? catchdownRejected
          ? "回答中明确写了接盘/退潮/主力撤离或旧题材风险，系统写入0元观察，不能当成低位启动。"
          : "回答中明确写了暂不买入、回避、排除、接盘/退潮/主力撤离或旧题材风险，系统写入暂不买入而不是可买。"
        : rejectedByHardRisk
          ? catchdownRejected
            ? `结构化下钻已识别接盘/退潮/主力撤离风险，系统写入0元观察，不能当成低位启动：${hardRiskWarnings.slice(0, 2).join("；")}。`
            : `结构化下钻已识别接盘/退潮/主力撤离或题材支撑缺口，系统写入暂不买入而不是可买：${hardRiskWarnings.slice(0, 2).join("；")}。`
        : formatAnswerWatchlistStatusReason(status, role, profile);
      const gapEvidence = formatAnswerWatchlistGapEvidence(profile, {
        status,
        role,
        userText,
        context
      });
      return {
        operation: "UPSERT",
        code,
        name: profile.name || profile.seed?.name || "",
        shareClass,
        type: profile.type || profile.seed?.type || "",
        status,
        priority: scoreAnswerWatchPriority(status, role),
        candidateRole: rejectedByAnswer
          || rejectedByHardRisk
          ? `${originLabel}${catchdownRejected ? "接盘风险排除候选" : "排除候选"}`
          : role === "backup" ? `${originLabel}备选观察候选` : `${originLabel}主推荐候选`,
        reason: [
          `${originLabel}沉淀：本次回答将其列为${answerRole}。`,
          statusReason,
          gapEvidence,
          trendEvidence,
          userText ? `用户原始需求：${userText.slice(0, 80)}` : ""
        ].filter(Boolean).join(" "),
        setupEvidence: [
          `回答角色：${answerRole}`,
          gapEvidence,
          trendEvidence,
          profile.actionability?.action ? `自评动作：${formatActionabilityAction(profile.actionability.action)}${profile.actionability.allocationBand ? ` ${profile.actionability.allocationBand}` : ""}` : "",
          Number.isFinite(Number(profile.trendProfile?.lowPositionPct120)) ? `120日位置${round(Number(profile.trendProfile.lowPositionPct120), 1)}%` : ""
        ].filter(Boolean),
        buyTriggers: buildAnswerWatchBuyTriggers(status, role, profile, { catchdownRejected }),
        riskNotes: [...(catchdownRejected ? ["这不是低位启动，是旧题材/主力撤离后的表面回调；没有资金回流和新鲜催化前不能试探买入。"] : []), ...hardRiskWarnings.slice(0, 3), ...buildAnswerWatchRiskNotes(status, profile, { catchdownRejected }), gapEvidence].filter(Boolean),
        feeNotes: [
          feeModel?.label || "份额类别和费率待基金详情页复核。",
          Number.isFinite(oneYearFeeCost) ? `估算持有1年每万元费用约 ${round(oneYearFeeCost, 0)} 元。` : ""
        ].filter(Boolean),
        positionPlan: formatAnswerWatchPositionPlan(status, role, profile, { catchdownRejected }),
        reviewDate: "下一次盘前观察或用户复问时复查",
        dataBasis: [
          `来源：${source}`,
          `来自本次回答的${answerRole}候选`,
          profile.sources?.[0] ? `资料源：${profile.sources[0]}` : ""
        ].filter(Boolean),
        source
      };
    })
    .filter(Boolean);
}

function selectFundScreeningWatchlistProfiles(profiles = [], answerText = "", userText = "") {
  if (String(process.env.PORTFOLIO_SCREENING_WATCHLIST_ENABLED ?? "true") === "false") return [];
  const input = Array.isArray(profiles) ? profiles : [profiles].filter(Boolean);
  if (!input.length) return [];
  const actionSeeking = isActionSeekingFundQuestion(userText)
    || isPullbackSetupRequest(userText)
    || /(买入|分批|持有|观察|备选|等待|回避|不买|换基|加仓|减仓|止盈|止损)/.test(String(answerText || ""));
  if (!actionSeeking) return [];
  return input
    .filter((profile) => profile?.code && profile.trendProfile?.ok)
    .map((profile) => {
      const context = extractAnswerWatchlistProfileContext(answerText, profile);
      return {
        ...profile,
        reportChartRole: inferAnswerWatchlistRole(profile, context) === "backup" ? "备选观察图" : "买入参考图"
      };
    });
}

function extractAnswerWatchlistProfileContext(answerText = "", profile = {}) {
  const body = String(answerText || "");
  if (!body.trim()) return "";
  const code = profile?.code || profile?.seed?.code || "";
  const name = profile?.name || profile?.seed?.name || "";
  const codeIndex = code ? body.indexOf(code) : -1;
  const nameIndex = name ? body.indexOf(name) : -1;
  const indexes = [codeIndex, nameIndex].filter((index) => index >= 0).sort((a, b) => a - b);
  if (!indexes.length) return "";
  return extractFundChartContext(body, code, name, indexes[0]);
}

function inferAnswerWatchlistRole(profile = {}, context = "") {
  if (profile.reportChartRole === "备选观察图") return "backup";
  const text = String(context || "");
  if (/(备选|观察|只观察|等待|等回撤|等回调|回踩|可关注|接近可买)/.test(text)) return "backup";
  return "buy_reference";
}

function isAnswerWatchlistRejectedContext(context = "") {
  const text = String(context || "");
  if (!text.trim()) return false;
  return /(回避|剔除|排除|不推荐|不作为主推荐|不是主推|暂不买|暂不加仓|不买|追涨|偏热|过热|不符合|风险偏高|接盘|退潮|主力(?:资金)?撤离|资金撤离|旧题材|旧新闻|旧催化|回调(?:不是|不作为|不能当|不能作为)买点|不能把回调当(?:成)?买点)/.test(text);
}

function isAnswerWatchlistCatchdownRisk(profile = {}, context = "", warnings = []) {
  const text = [
    context,
    ...(Array.isArray(warnings) ? warnings : []),
    profile?.reason,
    profile?.trendSummary,
    profile?.actionability?.decisionBlocker,
    profile?.actionability?.blocker,
    ...(Array.isArray(profile?.riskNotes) ? profile.riskNotes : []),
    ...(Array.isArray(profile?.readinessGaps) ? profile.readinessGaps : [])
  ].filter(Boolean).join(" ");
  return hasStaleThemeCatchdownRisk(profile)
    || hasThemeRetreatRisk(profile)
    || hasHoldingRealtimeCatchdownRisk(profile)
    || isTextualCatchdownRiskSegment(text)
    || /接盘|退潮|主力(?:资金)?撤离|资金撤离|旧题材|旧催化|旧新闻|历史热点|表面回调/.test(text);
}

function getAnswerWatchlistHardRiskWarnings(profile = {}) {
  if (!profile || typeof profile !== "object") return [];
  const actionability = profile.actionability || {};
  const warningGroups = [
    [getHoldingRealtimeCatchdownWarning(profile)],
    getThemeMainForcePlaybookRiskWarnings(profile),
    getStalePortfolioThemeRefreshWarnings(profile),
    getStaleThemeCatchdownWarnings(profile),
    getCandidateThemeRetreatWarnings(profile),
    getTextualCatchdownWarnings(profile),
    getUnrefreshedMarketThemeWarnings(profile),
    [getPortfolioActionableThemeSupportGap(profile)],
    normalizeStringArray(actionability.decisionBlocker).filter(isAnswerWatchlistHardRiskText),
    normalizeStringArray(actionability.blocker).filter(isAnswerWatchlistHardRiskText)
  ];
  const seen = new Set();
  return warningGroups
    .flat()
    .map((item) => String(item || "").trim())
    .filter((item) => {
      if (!item || seen.has(item)) return false;
      seen.add(item);
      return true;
    })
    .slice(0, 6);
}

function isAnswerWatchlistHardRiskText(value = "") {
  return /(接盘|退潮|主力(?:资金)?撤离|资金撤离|旧雷达|旧题材|旧新闻|旧催化|当前题材雷达.*未确认|未被当前题材雷达确认|底层持仓|前十大持仓.*走弱|回调(?:不是|不作为|不能当|不能作为)买点|泛题材热度不能覆盖底层退潮|缺少主力进场|缺少当前题材雷达|题材支撑缺口)/.test(String(value || ""));
}

function formatAnswerWatchlistSourceLabel(source = "") {
  if (source === "fund_screening_answer") return "具体基金分析";
  if (source === "fund_recommendation_answer") return "基金推荐回答";
  if (source === "fund_qa_answer") return "基金问答";
  return "用户问答";
}

function buildPortfolioWatchlistRecheckUpdates(watchlist = [], options = {}) {
  const profiles = Array.isArray(options) ? options : options.profiles || [];
  const profileByCode = new Map((profiles || []).filter(Boolean).map((profile) => [profile.code, profile]));
  return normalizePortfolioWatchlist(watchlist)
    .filter((item) => ["ready", "waiting_pullback"].includes(item.status))
    .map((item) => {
      const freshProfile = profileByCode.get(item.code) || null;
      const profile = freshProfile || item.lastSnapshot || null;
      if (!profile) return null;
      const score = item.status === "ready" ? 72 : 64;
      const inferredStatus = inferPortfolioWatchStatusFromSeedCandidate(item, score, profile);
      const freshness = evaluatePortfolioWatchlistFreshness({ ...item, status: inferredStatus }, profile, {
        ignoreReviewAge: Boolean(freshProfile)
      });
      let status = inferredStatus === "ready" && !freshness.ok ? "waiting_pullback" : inferredStatus;
      const readiness = evaluatePortfolioWatchReadiness({ ...item, status }, profile);
      const readinessGuard = buildPortfolioReadyStatusReadinessGuard(status, readiness);
      if (readinessGuard) status = readinessGuard.status;
      const trendEvidence = formatPortfolioSeedVerifiedTrendEvidence(profile);
      const freshnessNotes = freshness.issues.map((issue) => `系统时效复核：${issue}`);
      const readinessNotes = readinessGuard ? [readinessGuard.reason] : [];
      return {
        operation: "UPSERT",
        code: item.code,
        name: item.name || profile?.name || "",
        shareClass: item.shareClass || profile?.fees?.shareClass || profile?.shareClass || "",
        type: item.type || profile?.type || "",
        status,
        priority: status === "ready" ? Math.min(Number(item.priority || 2), 2) : status === "blocked" ? 5 : Math.max(Number(item.priority || 3), 3),
        candidateRole: item.candidateRole || (status === "ready" ? "每日复核接近可买候选" : "每日复核等待回调候选"),
        reason: [
          `系统每日复核自选池：${formatPortfolioWatchStatus(item.status)} -> ${formatPortfolioWatchStatus(status)}。`,
          formatPortfolioSeedStatusReason(status, profile),
          ...freshnessNotes,
          ...readinessNotes,
          trendEvidence,
          item.reason || ""
        ].filter(Boolean).join(" "),
        setupEvidence: mergeStringLists(item.setupEvidence, [trendEvidence]),
        buyTriggers: mergeStringLists(item.buyTriggers, buildAnswerWatchBuyTriggers(status, item.status === "waiting_pullback" ? "backup" : "buy_reference", profile)),
        riskNotes: mergeStringLists(item.riskNotes, buildAnswerWatchRiskNotes(status, profile), freshnessNotes, readinessNotes),
        feeNotes: item.feeNotes || [],
        positionPlan: item.positionPlan || formatAnswerWatchPositionPlan(status, item.status === "waiting_pullback" ? "backup" : "buy_reference", profile),
        reviewDate: freshness.ok ? "本次每日决策已复核，下一次盘前继续确认" : "需重新下钻刷新净值后再评估买入",
        dataBasis: mergeStringLists(item.dataBasis, [
          "来源：decision_watchlist_recheck",
          "来源：watchlist_freshness_guard",
          readinessGuard ? "来源：watchlist_readiness_guard" : "",
          trendEvidence
        ]),
        source: "decision_watchlist_recheck"
      };
    })
    .filter(Boolean);
}

function buildPortfolioDecisionReadinessQueue(watchlist = [], profiles = []) {
  const profileByCode = new Map((profiles || []).filter(Boolean).map((profile) => [profile.code, profile]));
  return normalizePortfolioWatchlist(watchlist)
    .filter((item) => ["ready", "waiting_pullback"].includes(item.status))
    .map((item) => {
      const profile = profileByCode.get(item.code) || item.lastSnapshot || null;
      const readiness = evaluatePortfolioWatchReadiness(item, profile);
      const riskGate = resolvePortfolioPositiveWatchRankingGate({
        ...item,
        lastSnapshot: profile || item.lastSnapshot
      });
      const memoryWarnings = getPortfolioCatchdownLossMemoryWarnings(item, profile || item.lastSnapshot || {});
      const memoryBlocked = memoryWarnings.length > 0;
      return {
        code: item.code,
        name: item.name,
        status: item.status,
        priority: item.priority,
        readinessScore: readiness.score,
        readinessLabel: readiness.label,
        reason: item.reason,
        firstTrigger: item.buyTriggers?.[0] || "",
        firstRisk: memoryBlocked ? memoryWarnings[0] : riskGate.ok ? item.riskNotes?.[0] || "" : riskGate.reason,
        positionPlan: item.positionPlan || "",
        trendEvidence: profile ? formatPortfolioSeedVerifiedTrendEvidence(profile) : item.lastSnapshot?.trendSummary || "",
        readinessGaps: memoryBlocked
          ? mergeStringLists(memoryWarnings, riskGate.ok ? readiness.gaps : [riskGate.reason, ...readiness.gaps])
          : riskGate.ok ? readiness.gaps : mergeStringLists([riskGate.reason], readiness.gaps),
        positiveRankingGate: memoryBlocked || !riskGate.ok ? "接盘/追涨风险未解除，不能进入买入准备或低位启动主推荐。" : "通过",
        feeNotes: item.feeNotes || [],
        reviewDate: item.reviewDate || ""
      };
    })
    .sort(comparePortfolioWatchReadiness)
    .slice(0, 8);
}

function buildPortfolioRedeploymentPlan(account = {}, watchlist = [], profiles = []) {
  const totalAsset = Number(account.totalAsset || 0);
  const cash = Number(account.cash || 0);
  const receivableCash = Number(account.receivableCash || 0);
  const pendingBuy = Number(account.pendingBuyAmount || 0);
  const investedValue = Number(account.investedValue || 0);
  const positionWeightPct = resolvePortfolioStoredWeightPct(account.positionWeightPct, investedValue, totalAsset);
  const cashPct = totalAsset > 0 && Number.isFinite(cash) ? cash / totalAsset * 100 : null;
  const cashLikePct = totalAsset > 0 && Number.isFinite(cash + receivableCash) ? (cash + receivableCash) / totalAsset * 100 : null;
  const pendingBuyPct = totalAsset > 0 && Number.isFinite(pendingBuy) ? pendingBuy / totalAsset * 100 : null;
  const accountBudget = buildPortfolioAccountRiskBudget(account);
  const redeploymentCashTriggerPct = finiteNumberOr(process.env.PORTFOLIO_REDEPLOYMENT_CASH_TRIGGER_PCT, 60);
  const redeploymentMaxPositionPct = finiteNumberOr(process.env.PORTFOLIO_REDEPLOYMENT_MAX_POSITION_PCT, 35);
  const pressureActive = Number.isFinite(cashPct)
    && cashPct >= redeploymentCashTriggerPct
    && (!Number.isFinite(positionWeightPct) || positionWeightPct <= redeploymentMaxPositionPct)
    && (!Number.isFinite(pendingBuyPct) || pendingBuyPct <= 3)
    && !accountBudget.blockNewBuys;
  const profileByCode = new Map((profiles || []).filter((profile) => profile?.code).map((profile) => [profile.code, profile]));
  const watchItems = normalizePortfolioWatchlist(watchlist).filter((item) => item.status !== "removed");
  const itemByCode = new Map(watchItems.map((item) => [item.code, item]));
  for (const profile of profiles || []) {
    if (profile?.code && !itemByCode.has(profile.code)) {
      itemByCode.set(profile.code, {
        code: profile.code,
        name: profile.name || "",
        shareClass: profile.shareClass || profile.fees?.shareClass || "",
        status: "watch",
        priority: 3,
        reason: "系统低位/回调候选联网资料，需要纳入再部署复核。",
        lastSnapshot: profile
      });
    }
  }

  const candidates = [...itemByCode.values()]
    .filter((item) => ["ready", "waiting_pullback", "watch"].includes(normalizePortfolioWatchStatus(item.status || "watch")))
    .map((item) => {
      const profile = profileByCode.get(item.code) || item.lastSnapshot || null;
      const readiness = evaluatePortfolioWatchReadiness(item, profile);
      const verifiedBuy = Boolean(profile && hasVerifiedPortfolioBuySetup(profile));
      const starterBuy = Boolean(profile && hasPortfolioStarterBuySetup(profile));
      const themeMicroStarter = Boolean(profile && hasPortfolioThemeMicroStarterSetup(profile));
      const feeVerified = Boolean(profile && hasVerifiedPortfolioFeeEvidence(profile));
      const hardGap = readiness.gaps.find(isPortfolioRedeploymentHardGap);
      const buyTargetWeightPct = themeMicroStarter ? 1 : starterBuy ? 1.5 : 2.5;
      const buyGuard = (verifiedBuy || starterBuy || themeMicroStarter)
        ? evaluatePortfolioBuyDiscipline(
            { action: "BUY", code: item.code, name: item.name || profile?.name || "", targetWeightPct: buyTargetWeightPct },
            profile,
            account.positions || [],
            account
          )
        : { ok: false, reason: readiness.gaps?.[0] || "还没有形成可执行买点。", evidence: [] };
      const executable = Boolean(buyGuard.ok && (verifiedBuy || starterBuy || themeMicroStarter) && feeVerified && !hardGap);
      const suggestedTargetWeightPct = executable ? buyTargetWeightPct : 0;
      const firstGap = executable
        ? themeMicroStarter
          ? "主力/预热题材和低位温和转强支持微型试探，仍需盘前确认。"
          : "低位/回调/费用条件支持小仓试探，仍需盘前确认。"
        : hardGap || buyGuard.reason || readiness.gaps?.[0] || "等待下一次复核。";
      return {
        code: item.code,
        name: item.name || profile?.name || "",
        shareClass: item.shareClass || profile?.shareClass || profile?.fees?.shareClass || "",
        status: normalizePortfolioWatchStatus(item.status || "watch"),
        priority: Number(item.priority || 3),
        readinessScore: readiness.score,
        readinessLabel: readiness.label,
        redeploymentAction: executable ? (verifiedBuy ? "verified_buy" : themeMicroStarter ? "theme_micro_starter" : "starter_buy") : "watch",
        redeploymentActionText: executable
          ? (verifiedBuy ? "可分批首仓" : themeMicroStarter ? "可微型试探" : "可小仓试探")
          : "只观察触发条件",
        suggestedTargetWeightPct,
        suggestedAmount: suggestedTargetWeightPct && totalAsset > 0 ? round(totalAsset * suggestedTargetWeightPct / 100, 2) : 0,
        firstGap,
        trendEvidence: profile ? formatPortfolioSeedVerifiedTrendEvidence(profile) : item.lastSnapshot?.trendSummary || "",
        realtimeEvidence: profile ? formatPortfolioRealtimeEvidence(profile) : "",
        feeEvidence: profile ? formatPortfolioFeeVerificationEvidence(profile) : (item.feeNotes || [])[0] || "",
        buyGuard: {
          ok: Boolean(buyGuard.ok),
          reason: buyGuard.reason || "",
          evidence: normalizeStringArray(buyGuard.evidence).slice(0, 4)
        },
        dataBasis: mergeStringLists(item.dataBasis, [
          "来源：portfolio_redeployment_plan",
          profile?.sources?.[0] || "",
          profile?.estimateTime ? `实时估算时间：${profile.estimateTime}` : ""
        ])
      };
    })
    .filter((item) => item.code)
    .sort((a, b) =>
      Number(["verified_buy", "starter_buy", "theme_micro_starter"].includes(b.redeploymentAction)) - Number(["verified_buy", "starter_buy", "theme_micro_starter"].includes(a.redeploymentAction))
      || Number(b.readinessScore || 0) - Number(a.readinessScore || 0)
      || Number(a.priority || 3) - Number(b.priority || 3)
    )
    .slice(0, 6);
  const executableCount = candidates.filter((item) => ["verified_buy", "starter_buy", "theme_micro_starter"].includes(item.redeploymentAction)).length;
  const summary = pressureActive
    ? executableCount
      ? `现金${formatFallbackPct(cashPct)}且仓位不高，发现${executableCount}只可小仓再部署候选。`
      : `现金${formatFallbackPct(cashPct)}且仓位不高，但候选仍缺关键触发条件，必须写清前三个缺口。`
    : "现金/仓位/回撤预算暂未触发强制再部署。";
  return {
    pressureActive,
    summary,
    account: {
      cashPct: Number.isFinite(cashPct) ? round(cashPct, 1) : null,
      cashLikePct: Number.isFinite(cashLikePct) ? round(cashLikePct, 1) : null,
      positionWeightPct: Number.isFinite(positionWeightPct) ? round(positionWeightPct, 1) : null,
      pendingBuyPct: Number.isFinite(pendingBuyPct) ? round(pendingBuyPct, 1) : null,
      riskLevel: accountBudget.level || ""
    },
    discipline: pressureActive
      ? "不能继续空泛等待；可执行候选给0.5%-2.5%试探仓，不可执行候选写清触发条件和复核时间。"
      : "按正常仓位纪律复核。",
    candidates
  };
}

function isPortfolioRedeploymentHardGap(gap = "") {
  return /缺少可验证净值|走势下钻|基金规模.*(?:不能作为可直接买入|偏小)|前十大集中度.*(?:过高|偏高)|费用\/份额|特殊\/平台份额|可申购渠道|普通渠道可申购|起购门槛|题材拥挤|追涨风险|暂时回避|仍是回避|前十大持仓盘中|前十大持仓实际集中|底层持仓止跌|表面回调可能继续下探|题材退潮|主力资金撤离|主力撤离|接盘风险|旧新闻|旧催化|今天的买点|当前题材雷达.*(?:过期|缺少刷新时间|刷新时间无法验证)|重新刷新主力资金\/新闻催化/.test(String(gap || ""));
}

function formatPortfolioRealtimeEvidence(profile = {}) {
  const pieces = [];
  const estimatedChange = finiteMetricNumber(profile.estimatedChangePct);
  if (Number.isFinite(estimatedChange)) pieces.push(`实时估算${formatFallbackPct(estimatedChange)}`);
  if (profile.estimateTime) {
    const freshness = formatEstimateFreshnessLabel(estimateFreshnessMinutes(profile.estimateTime));
    pieces.push(`更新时间${profile.estimateTime}${freshness ? `（${freshness}）` : ""}`);
  }
  return pieces.join("，");
}

function ensurePortfolioRedeploymentPlanReviewed(decision = {}, account = {}, watchlist = [], options = {}) {
  const plan = buildPortfolioRedeploymentPlan(account, watchlist, options.profiles || []);
  if (!plan.pressureActive) return decision;
  const actions = normalizePortfolioActions(decision.actions || []);
  const existingKeys = new Set(actions.map((action) => `${action.action}:${action.code}`));
  const nextActions = [...actions];
  for (const candidate of plan.candidates.slice(0, 3)) {
    if (existingKeys.has(`BUY:${candidate.code}`) || existingKeys.has(`WATCH:${candidate.code}`) || existingKeys.has(`HOLD:${candidate.code}`)) {
      continue;
    }
    const canBuy = ["verified_buy", "starter_buy", "theme_micro_starter"].includes(candidate.redeploymentAction);
    const action = canBuy ? "BUY" : "WATCH";
    const amount = canBuy ? candidate.suggestedAmount : 0;
    nextActions.push({
      action,
      code: candidate.code,
      name: candidate.name,
      amount,
      targetWeightPct: canBuy ? candidate.suggestedTargetWeightPct : 0,
      reason: canBuy
        ? `系统再部署纪律：${candidate.name || candidate.code} 已出现${candidate.redeploymentActionText}条件，现金长期空转时应给小仓试错，而不是继续泛泛等待。`
        : `系统再部署纪律：${candidate.name || candidate.code} 需要被复核，但本轮仍不买；${candidate.firstGap}`,
      rotationCheck: "再部署只选择低位回调/启动修复候选，不因新闻热度追涨。",
      positionCheck: candidate.trendEvidence,
      chaseRisk: candidate.firstGap,
      feeCheck: candidate.feeEvidence,
      riskControl: canBuy
        ? candidate.redeploymentAction === "theme_micro_starter"
          ? "单笔只做0.5%-1.2%微型试探；若主力线索变弱、新闻催化落空、实时估算转弱或费用证据失效，下一轮撤回。"
          : "单笔只做0.5%-2.5%试探；若实时估算转弱、回撤修复失败或费用证据失效，下一轮撤回。"
        : "只放观察，触发条件未满足前不提交虚拟申购。",
      dataBasis: mergeStringLists(candidate.dataBasis, [
        "来源：portfolio_redeployment_guard",
        candidate.realtimeEvidence,
        candidate.buyGuard?.reason || ""
      ])
    });
    existingKeys.add(`${action}:${candidate.code}`);
  }
  return {
    ...decision,
    actions: nextActions,
    learningNotes: mergeStringLists(decision.learningNotes, [
      `系统再部署纪律：${plan.summary}`
    ])
  };
}

function buildPortfolioThemeOpportunityPlan(account = {}, watchlist = [], profiles = [], marketSnapshot = null) {
  const totalAsset = Number(account.totalAsset || 0);
  const accountBudget = buildPortfolioAccountRiskBudget(account);
  const profileByCode = new Map((profiles || []).filter((profile) => profile?.code).map((profile) => [profile.code, profile]));
  const watchItems = normalizePortfolioWatchlist(watchlist).filter((item) => item.status !== "removed");
  const itemByCode = new Map(watchItems.map((item) => [item.code, item]));
  for (const profile of profiles || []) {
    if (profile?.code && !itemByCode.has(profile.code)) {
      itemByCode.set(profile.code, {
        code: profile.code,
        name: profile.name || "",
        shareClass: profile.shareClass || profile.fees?.shareClass || "",
        status: "watch",
        priority: 3,
        reason: "系统主力/预热题材候选联网资料，需要纳入机会复核。",
        lastSnapshot: profile
      });
    }
  }
  const themeLaneItems = collectPortfolioThemeOpportunityLeaderboardItems(marketSnapshot);
  const candidates = [...itemByCode.values()]
    .filter((item) => item.code && ["ready", "waiting_pullback", "watch"].includes(normalizePortfolioWatchStatus(item.status || "watch")))
    .map((item) => {
      const profile = profileByCode.get(item.code) || item.lastSnapshot || null;
      const evidenceSource = profile || item;
      const themeEvidenceSource = refreshPortfolioCandidateThemesWithMarketRadar({
        ...evidenceSource,
        code: item.code || evidenceSource?.code || "",
        name: item.name || evidenceSource?.name || "",
        shareClass: item.shareClass || evidenceSource?.shareClass || evidenceSource?.fees?.shareClass || "",
        marketThemeRefresh: evidenceSource?.marketThemeRefresh || item.marketThemeRefresh || null,
        holdingThemeRefresh: evidenceSource?.holdingThemeRefresh || item.holdingThemeRefresh || null,
        matchedThemes: evidenceSource?.matchedThemes || item.matchedThemes || [],
        seed: {
          ...(evidenceSource?.seed || {}),
          matchedThemes: evidenceSource?.seed?.matchedThemes || evidenceSource?.matchedThemes || item.matchedThemes || [],
          marketThemeRefresh: evidenceSource?.seed?.marketThemeRefresh || evidenceSource?.marketThemeRefresh || item.seed?.marketThemeRefresh || null,
          holdingThemeRefresh: evidenceSource?.seed?.holdingThemeRefresh || evidenceSource?.holdingThemeRefresh || item.seed?.holdingThemeRefresh || null
        }
      }, marketSnapshot);
      const theme = selectPortfolioActionableThemeSignal(themeEvidenceSource);
      if (!theme) return null;
      const lane = findPortfolioThemeOpportunityLaneForTheme(theme, themeLaneItems);
      const readiness = evaluatePortfolioWatchReadiness(item, profile);
      const verifiedBuy = Boolean(profile && hasVerifiedPortfolioBuySetup(profile));
      const starterBuy = Boolean(profile && hasPortfolioStarterBuySetup(profile));
      const themeMicroStarter = Boolean(profile && hasPortfolioThemeMicroStarterSetup(profile));
      const targetWeightPct = themeMicroStarter ? 1 : starterBuy ? 1.5 : verifiedBuy ? 2.5 : 0;
      const catalystGap = hasThemeLeaderOrPreheatSignal(theme) && !hasTraceableFreshThemeCatalystContext(theme)
        ? "缺可追溯的新闻时事/产业催化来源，不能把主力热度直接当买点。"
        : "";
      const capitalFlowGap = hasThemeLeaderOrPreheatSignal(theme)
        && hasTraceableFreshThemeCatalystContext(theme)
        && !hasPositiveThemeMainCapitalEvidence(theme)
        ? "缺少正向主力资金或主力流入榜确认，不能把新闻预热直接写成微型试探。"
        : "";
      const hardGap = catalystGap || capitalFlowGap || readiness.gaps.find(isPortfolioRedeploymentHardGap);
      const feeVerified = Boolean(profile && hasVerifiedPortfolioFeeEvidence(profile));
      const buyGuard = targetWeightPct > 0
        ? evaluatePortfolioBuyDiscipline(
            { action: "BUY", code: item.code, name: item.name || profile?.name || "", targetWeightPct },
            profile,
            account.positions || [],
            account
          )
        : { ok: false, reason: readiness.gaps?.[0] || "题材有线索，但基金买点还没有形成。", evidence: [] };
      const executable = Boolean(targetWeightPct > 0 && buyGuard.ok && feeVerified && !hardGap && !accountBudget.blockNewBuys);
      const opportunityAction = executable
        ? verifiedBuy
          ? "verified_theme_buy"
          : themeMicroStarter
            ? "theme_micro_starter"
            : "theme_starter_buy"
        : "theme_watch";
      const trendEvidence = profile ? formatPortfolioSeedVerifiedTrendEvidence(profile) : item.lastSnapshot?.trendSummary || "";
      const themeEvidence = formatCandidateThemeEvidence({ matchedThemes: [theme] });
      const score = scorePortfolioThemeOpportunityCandidate({
        item,
        profile,
        theme,
        lane,
        readinessScore: readiness.score,
        executable,
        hardGap,
        buyGuard
      });
      return {
        code: item.code,
        name: item.name || profile?.name || "",
        shareClass: item.shareClass || profile?.shareClass || profile?.fees?.shareClass || "",
        status: normalizePortfolioWatchStatus(item.status || "watch"),
        priority: Number(item.priority || 3),
        score,
        themeName: theme.name || theme.id || "",
        laneTitle: lane?.title || formatPortfolioThemeOpportunityLaneTitle(theme),
        opportunityAction,
        opportunityActionText: formatPortfolioThemeOpportunityActionText(opportunityAction),
        executable,
        suggestedTargetWeightPct: executable ? targetWeightPct : 0,
        suggestedAmount: executable && totalAsset > 0 ? round(totalAsset * targetWeightPct / 100, 2) : 0,
        firstGap: executable
          ? "主力/预热题材与基金买点同时成立，只允许小仓验证。"
          : hardGap || buyGuard.reason || readiness.gaps?.[0] || "等待基金买点、费用或持仓前景补齐。",
        themeEvidence,
        trendEvidence,
        catalyst: theme.catalystProfile?.summary || "",
        newsLogic: theme.newsLogic || theme.primaryCatalyst || "",
        buyGuard: {
          ok: Boolean(buyGuard.ok),
          reason: buyGuard.reason || "",
          evidence: normalizeStringArray(buyGuard.evidence).slice(0, 4)
        },
        dataBasis: mergeStringLists([
          "来源：portfolio_theme_opportunity_plan",
          marketSnapshot?.fetchedAt ? `市场快照：${marketSnapshot.fetchedAt}` : "",
          lane?.title ? `题材榜单：${lane.title}` : "",
          themeEvidence,
          capitalFlowGap,
          theme.newsLogic ? `题材逻辑：${theme.newsLogic}` : "",
          theme.catalystProfile?.summary ? `催化性质：${theme.catalystProfile.summary}` : "",
          profile?.sources?.[0] || ""
        ])
      };
    })
    .filter(Boolean)
    .sort((a, b) =>
      Number(b.executable) - Number(a.executable)
      || Number(b.score || 0) - Number(a.score || 0)
      || Number(a.priority || 3) - Number(b.priority || 3)
    )
    .slice(0, 6);
  return {
    active: Boolean(themeLaneItems.length || candidates.length),
    summary: candidates.length
      ? `发现${candidates.length}只与主力进场/题材预热/低位轮动相关的基金机会，必须逐只给买入复核或观察拦截理由。`
      : themeLaneItems.length
        ? `题材榜单已有${themeLaneItems.length}条主力/预热线索，但自选池还没有匹配基金，必须扩展代表基金数据源。`
        : "本轮题材榜单暂未形成主力/预热机会。",
    themeLeaders: themeLaneItems.slice(0, 5),
    candidates
  };
}

function ensurePortfolioThemeOpportunityReviewed(decision = {}, account = {}, watchlist = [], options = {}) {
  const plan = buildPortfolioThemeOpportunityPlan(account, watchlist, options.profiles || [], options.marketSnapshot || null);
  if (!plan.candidates.length) {
    return ensurePortfolioThemeRepresentativeRecallAction(decision, plan);
  }
  const normalized = {
    ...decision,
    actions: normalizePortfolioActions(decision?.actions),
    watchlistUpdates: normalizePortfolioWatchlistUpdates(decision?.watchlistUpdates),
    team: Array.isArray(decision?.team) ? decision.team : [],
    riskNotes: Array.isArray(decision?.riskNotes) ? decision.riskNotes : [],
    learningNotes: Array.isArray(decision?.learningNotes) ? decision.learningNotes : [],
    sources: Array.isArray(decision?.sources) ? decision.sources : []
  };
  const existingKeys = new Set(normalized.actions.map((action) => `${action.action}:${action.code}`));
  const nextActions = [...normalized.actions];
  for (const candidate of plan.candidates.slice(0, 3)) {
    if (existingKeys.has(`BUY:${candidate.code}`) || existingKeys.has(`WATCH:${candidate.code}`) || existingKeys.has(`HOLD:${candidate.code}`)) {
      continue;
    }
    const canBuy = Boolean(candidate.executable);
    const action = canBuy ? "BUY" : "WATCH";
    const themeLogicBrief = formatPortfolioThemeOpportunityCustomerLogic(candidate);
    nextActions.push({
      action,
      code: candidate.code,
      name: candidate.name,
      amount: canBuy ? candidate.suggestedAmount : 0,
      targetWeightPct: canBuy ? candidate.suggestedTargetWeightPct : 0,
      reason: canBuy
        ? `系统主力/预热机会纪律：${candidate.themeName} 进入${candidate.laneTitle}；${themeLogicBrief}；${candidate.name || candidate.code} 同时通过买点和费用复核，本轮只做小仓验证。`
        : `系统主力/预热机会纪律：${candidate.themeName} 有线索；${themeLogicBrief}；但${candidate.name || candidate.code} 暂不买，${candidate.firstGap}`,
      rankingBasis: `${candidate.laneTitle || "主力/预热题材"}机会处理器，${canBuy ? "采纳小仓复核" : "不采纳买入"}`,
      rotationCheck: candidate.newsLogic || candidate.themeEvidence || "题材有主力/预热线索，但仍需基金自身买点确认。",
      positionCheck: candidate.trendEvidence || "等待净值和低位证据复核。",
      chaseRisk: candidate.firstGap,
      feeCheck: canBuy ? "费用/份额已通过系统买入纪律复核；下单前仍需确认申赎规则。" : "费用/份额或结构性缺口未完全通过前，暂不提交申购。",
      riskControl: canBuy
        ? candidate.opportunityAction === "theme_micro_starter"
          ? "微型试探上限1.2%；若主力流入消失、新闻催化落空或基金转弱，下一轮撤回。"
          : "小仓试探上限2.5%；若题材拥挤、回调失败或盘中转弱，下一轮撤回。"
        : "只放观察，下一轮先查主力资金是否延续、新闻逻辑是否兑现、基金是否温和转强。",
      dataBasis: mergeStringLists(candidate.dataBasis, candidate.buyGuard?.evidence, ["来源：portfolio_theme_opportunity_guard"])
    });
    existingKeys.add(`${action}:${candidate.code}`);
  }
  return {
    ...normalized,
    actions: nextActions,
    learningNotes: mergeStringLists(normalized.learningNotes, [
      `系统主力/预热机会纪律：${plan.summary}`
    ]),
    sources: mergeStringLists(normalized.sources, ["portfolio_theme_opportunity_guard"])
  };
}

function ensurePortfolioThemeRepresentativeRecallAction(decision = {}, plan = {}) {
  if (!plan?.active || !Array.isArray(plan.themeLeaders) || !plan.themeLeaders.length) return decision;
  const normalized = {
    ...decision,
    actions: normalizePortfolioActions(decision?.actions),
    watchlistUpdates: normalizePortfolioWatchlistUpdates(decision?.watchlistUpdates),
    team: Array.isArray(decision?.team) ? decision.team : [],
    riskNotes: Array.isArray(decision?.riskNotes) ? decision.riskNotes : [],
    learningNotes: Array.isArray(decision?.learningNotes) ? decision.learningNotes : [],
    sources: Array.isArray(decision?.sources) ? decision.sources : []
  };
  const alreadyCovered = normalized.actions.some((action) =>
    action.action === "WATCH"
    && /代表基金|主力预热|题材预热|主力进场/.test(`${action.name || ""} ${action.reason || ""} ${action.rankingBasis || ""}`)
  );
  const expansionKeywords = collectPortfolioThemeRepresentativeExpansionKeywords(plan.themeLeaders);
  const carrierAnchors = collectPortfolioThemeRepresentativeCarrierAnchors(plan.themeLeaders);
  const recallReason = formatPortfolioThemeRepresentativeRecallReason(plan.themeLeaders);
  const action = alreadyCovered ? [] : [{
    action: "WATCH",
    code: "",
    name: "主力预热代表基金召回",
    amount: 0,
    targetWeightPct: 0,
    reason: recallReason,
    rankingBasis: "主力/预热题材代表基金缺口处理器，当前先召回代表基金，不给买入金额。",
    rotationCheck: recallReason,
    positionCheck: [
      "当前缺可验证代表基金，先补基金净值走势、前十大持仓、份额费率和追涨风险。",
      expansionKeywords.length ? `优先搜索：${expansionKeywords.slice(0, 8).join(" / ")}` : "",
      carrierAnchors.length ? `承载锚点：${carrierAnchors.slice(0, 6).join(" / ")}` : ""
    ].filter(Boolean).join("；"),
    chaseRisk: "未找到代表基金前，不能把题材热度包装成低位启动买点。",
    feeCheck: "代表基金补齐后必须核验A/C/D/I份额、申购费、销售服务费和赎回规则。",
    riskControl: "0元观察；下一轮每个题材至少补3只可承载的代表基金，覆盖低费指数/主动基金/备选份额，再决定微型试探、继续观察或排除。",
    dataBasis: mergeStringLists([
      "来源：portfolio_theme_opportunity_guard",
      "来源：theme_representative_recall",
      expansionKeywords.length ? `代表基金搜索词：${expansionKeywords.slice(0, 10).join("/")}` : "",
      carrierAnchors.length ? `承载锚点：${carrierAnchors.slice(0, 8).join("/")}` : "",
      ...plan.themeLeaders.slice(0, 3).map((item) => `${item.title || "题材榜"}：${item.name || ""}${item.whyMove ? `，${item.whyMove}` : ""}`)
    ])
  }];
  return {
    ...normalized,
    actions: [...normalized.actions, ...action].slice(0, 10),
    learningNotes: mergeStringLists(normalized.learningNotes, [
      `系统主力/预热机会纪律：${plan.summary}；当前先召回代表基金，不允许用泛泛等待替代。`
    ]),
    riskNotes: mergeStringLists(normalized.riskNotes, [
      "主力/预热题材缺代表基金时不得直接买入；必须先补前十大持仓承载、走势、费用和追涨风险。"
    ]),
    sources: mergeStringLists(normalized.sources, ["portfolio_theme_opportunity_guard", "theme_representative_recall"])
  };
}

function formatPortfolioThemeRepresentativeRecallReason(themeLeaders = []) {
  const leaders = (themeLeaders || []).slice(0, 3);
  const names = leaders.map((item) => item.name).filter(Boolean).join(" / ");
  const lead = leaders[0] || {};
  const whyMove = shortenPortfolioCustomerText(lead.whyMove || lead.newsLogic || lead.reason || "", 96);
  const catalyst = lead.catalyst ? `催化：${shortenPortfolioCustomerText(lead.catalyst, 42)}` : "";
  const expansionKeywords = collectPortfolioThemeRepresentativeExpansionKeywords(leaders).slice(0, 6);
  const carrierAnchors = collectPortfolioThemeRepresentativeCarrierAnchors(leaders).slice(0, 5);
  return [
    `系统主力/预热机会纪律：${names || "主力/预热题材"} 已进入题材榜，但当前自选池缺少可验证代表基金`,
    whyMove ? `为什么动：${whyMove.replace(/^为什么动[:：]\s*/, "")}` : "",
    catalyst,
    expansionKeywords.length ? `搜索词：${expansionKeywords.join("/")}` : "",
    carrierAnchors.length ? `承载锚点：${carrierAnchors.join("/")}` : "",
    "下一步每个题材至少扩充3只代表基金候选，并逐只验证前十大持仓/指数名称是否承载题材、5日/10日是否温和转强、A/C/D/I费用和追涨风险；补齐前买入金额为0元"
  ].filter(Boolean).join("；");
}

function collectPortfolioThemeRepresentativeExpansionKeywords(themeLeaders = []) {
  return [...new Set((themeLeaders || [])
    .flatMap((item) => [
      item.name,
      ...(Array.isArray(item.carrierSearchKeywords) ? item.carrierSearchKeywords : []),
      item.whyMove,
      item.newsLogic,
      item.catalyst
    ])
    .flatMap((value) => String(value || "").split(/[，,、/；;+\s]+/))
    .map((value) => value.trim())
    .filter(isThemeOpportunitySearchKeywordUseful))]
    .slice(0, 18);
}

function collectPortfolioThemeRepresentativeCarrierAnchors(themeLeaders = []) {
  return [...new Set((themeLeaders || [])
    .flatMap((item) => [
      ...(Array.isArray(item.carrierAnchors) ? item.carrierAnchors : []),
      item.name,
      item.catalyst
    ])
    .flatMap((value) => String(value || "").split(/[，,、/；;+\s]+/))
    .map((value) => value.trim())
    .filter(isThemeOpportunityAnchorKeywordUseful))]
    .slice(0, 12);
}

function formatPortfolioThemeOpportunityCustomerLogic(candidate = {}) {
  const whyMove = candidate.newsLogic
    ? `为什么动：${shortenPortfolioCustomerText(candidate.newsLogic, 82)}`
    : candidate.catalyst
      ? `为什么动：${shortenPortfolioCustomerText(candidate.catalyst, 58)}`
      : "";
  const themeProof = candidate.themeEvidence
    ? `资金/题材：${shortenPortfolioCustomerText(candidate.themeEvidence, 82)}`
    : "";
  const fundProof = candidate.trendEvidence
    ? `代表基金：${shortenPortfolioCustomerText(candidate.trendEvidence, 78)}`
    : "";
  const parts = [whyMove, themeProof, fundProof].filter(Boolean);
  return parts.length ? parts.join("；") : "题材逻辑、主力资金和代表基金承载仍需同步复核";
}

function collectPortfolioThemeOpportunityLeaderboardItems(marketSnapshot = null) {
  const leaderboards = marketSnapshot?.themeLeaderboards || buildThemeLeaderboards(marketSnapshot?.themeRadar || []);
  const playbookItems = collectThemeMainForcePlaybookOpportunityItems(marketSnapshot);
  const playbookByKey = new Map();
  for (const item of playbookItems) {
    for (const key of [item.id, item.name].map((value) => normalizeIntentText(value)).filter(Boolean)) {
      if (!playbookByKey.has(key)) playbookByKey.set(key, item);
    }
  }
  const lanes = [
    ["mainCapital", "主力进场榜"],
    ["preheat", "题材预热榜"],
    ["lowRotation", "低位轮动榜"]
  ];
  const leaderboardItems = lanes.flatMap(([key, fallbackTitle]) =>
    (leaderboards?.[key]?.items || []).slice(0, 3).map((item) => {
      const playbook = [item.id, item.name]
        .map((value) => playbookByKey.get(normalizeIntentText(value)))
        .find(Boolean) || {};
      return {
        laneKey: key,
        title: playbook.title || leaderboards?.[key]?.title || fallbackTitle,
        id: item.id || playbook.id || "",
        name: item.name || playbook.name || "",
        score: Number(item.score || playbook.score || 0),
        reason: playbook.reason || item.reason || "",
        catalyst: playbook.catalyst || item.catalyst || "",
        sourceType: playbook.sourceType || item.sourceType || "",
        newsLogic: playbook.newsLogic || item.newsLogic || "",
        whyMove: playbook.whyMove || item.whyMove || "",
        capitalProof: playbook.capitalProof || "",
        carrierSearchKeywords: normalizeStringArray(playbook.carrierSearchKeywords),
        carrierAnchors: normalizeStringArray(playbook.carrierAnchors),
        playbookAction: playbook.playbookAction || ""
      };
    })
  );
  if (leaderboardItems.length) return leaderboardItems;
  return playbookItems.slice(0, 9).map((item) => ({
    laneKey: item.laneKey || item.sourceKey || "",
    title: item.title || item.laneTitle || "主力/预热题材",
    id: item.id || "",
    name: item.name || "",
    score: Number(item.score || 0),
    reason: item.reason || "",
    catalyst: item.catalyst || "",
    sourceType: item.sourceType || "",
    newsLogic: item.newsLogic || "",
    whyMove: item.whyMove || "",
    capitalProof: item.capitalProof || "",
    carrierSearchKeywords: normalizeStringArray(item.carrierSearchKeywords),
    carrierAnchors: normalizeStringArray(item.carrierAnchors),
    playbookAction: item.playbookAction || item.action || ""
  }));
}

function selectPortfolioActionableThemeSignal(candidate = {}) {
  return getCandidateThemeSignals(candidate)
    .filter((theme) => isFreshActionableThemeSupportForCandidate(candidate, theme))
    .sort((a, b) => scorePortfolioActionableThemeSignal(b) - scorePortfolioActionableThemeSignal(a))[0] || null;
}

function scorePortfolioActionableThemeSignal(theme = {}) {
  return Number(theme.capitalFollowScore || 0)
    + Number(theme.preheatScore || 0) * 0.8
    + Number(theme.rotationScore || 0) * 0.45
    + Number(theme.lowPositionScore || 0) * 0.35
    + Number(theme.catalystProfile?.score || 0) * 0.8
    + scoreThemeMainForceOpportunity(theme) * 0.65
    + (hasTraceableFreshThemeCatalystContext(theme) ? 12 : hasThemeLeaderOrPreheatSignal(theme) ? -20 : 0)
    - Number(theme.crowdingScore || 0) * 0.4;
}

function findPortfolioThemeOpportunityLaneForTheme(theme = {}, laneItems = []) {
  const themeKeys = new Set([theme.id, theme.name, ...(theme.themeKeywords || []), ...(theme.fundKeywords || []), ...(theme.keywords || [])]
    .map((item) => normalizeIntentText(item)).filter(Boolean));
  return (laneItems || []).find((item) => {
    const itemKeys = [item.id, item.name].map((value) => normalizeIntentText(value)).filter(Boolean);
    return itemKeys.some((key) =>
      themeKeys.has(key)
      || [...themeKeys].some((themeKey) => themeKey.includes(key) || key.includes(themeKey))
    );
  }) || null;
}

function formatPortfolioThemeOpportunityLaneTitle(theme = {}) {
  if (theme.leaderSignal === "capital_entering" || theme.positionSignal === "main_capital_entering") return "主力进场榜";
  if (theme.leaderSignal === "preheat_catalyst" || theme.positionSignal === "preheat_catalyst_watch") return "题材预热榜";
  if (theme.positionSignal === "low_position_rotation" || theme.stage === "low_position_rotation") return "低位轮动榜";
  return "主力/预热题材";
}

function formatPortfolioThemeOpportunityActionText(action = "") {
  const labels = {
    verified_theme_buy: "可分批首仓",
    theme_starter_buy: "可小仓试探",
    theme_micro_starter: "可微型试探",
    theme_watch: "先观察补证据"
  };
  return labels[action] || "机会复核";
}

function scorePortfolioThemeOpportunityCandidate({ item = {}, profile = null, theme = {}, lane = null, readinessScore = 0, executable = false, hardGap = "", buyGuard = {} } = {}) {
  const trend = profile?.trendProfile || item.lastSnapshot?.trendProfile || {};
  const low120 = finiteMetricNumber(trend.lowPositionPct120);
  const r20 = finiteMetricNumber(trend.return20dPct);
  return Math.max(0, Math.min(100,
    Number(readinessScore || 0) * 0.32
    + scorePortfolioActionableThemeSignal(theme) * 0.45
    + (lane ? 10 : 0)
    + (executable ? 18 : 0)
    + (hasPortfolioThemeMicroStarterSetup(profile) ? 8 : 0)
    + (hasTraceableFreshThemeCatalystContext(theme) ? 8 : hasThemeLeaderOrPreheatSignal(theme) ? -16 : 0)
    + (Number.isFinite(low120) && low120 <= 60 ? 7 : 0)
    - (Number.isFinite(r20) && r20 > 8 ? 8 : 0)
    - (hardGap ? 18 : 0)
    - (buyGuard?.ok === false ? 6 : 0)
  ));
}

function buildPortfolioMissedFollowThroughReviewQueue(db = {}) {
  const account = db.account || {};
  const watchlist = normalizePortfolioWatchlist(db.watchlist || []);
  const itemByCode = new Map(watchlist.map((item) => [item.code, item]));
  const transactions = getPortfolioDiagnosticTransactions(db);
  const orders = getPortfolioDiagnosticOrders(db);
  const candidates = mergePortfolioBacktestOpportunityCandidates(
    findPortfolioBacktestMissedFollowThroughCandidates({
      watchlist,
      transactions,
      orders,
      totalAsset: account.totalAsset || 0
    }),
    findPortfolioBacktestMissedThemeMomentumCandidates({
      watchlist,
      transactions,
      orders,
      totalAsset: account.totalAsset || 0
    })
  );
  return candidates.slice(0, 6).map((candidate) => {
    const item = itemByCode.get(candidate.code) || {};
    const firstTrigger = normalizeStringArray(item.buyTriggers)[0] || "";
    const firstRisk = normalizeStringArray(item.riskNotes)[0] || "";
    const firstFee = normalizeStringArray(item.feeNotes)[0] || "";
    const themeMomentum = candidate.opportunityKind === "theme_momentum";
    return {
      code: candidate.code,
      name: candidate.name || item.name || "",
      status: item.status || candidate.status || "watch",
      readinessScore: candidate.readinessScore,
      followThroughPct: candidate.followThroughPct,
      estimatedStarterOpportunity: candidate.estimatedStarterOpportunity,
      opportunityKind: candidate.opportunityKind || "follow_through",
      themeMicroStarter: Boolean(candidate.themeMicroStarter),
      themeName: candidate.themeName || "",
      newsLogic: candidate.newsLogic || "",
      evidence: candidate.evidence || "",
      reviewAction: themeMomentum
        ? "微型试探 / 主动降级 / 明确复查时间三选一"
        : "小仓试探 / 主动降级 / 明确复查时间三选一",
      firstTrigger,
      firstRisk,
      firstFee,
      reason: shortenPortfolioCustomerText(item.reason || "", 90),
      reviewDate: item.reviewDate || "",
      dataBasis: mergeStringLists(item.dataBasis, [
        "来源：portfolio_missed_follow_through_review",
        themeMomentum ? "类型：主力预热机会成本复核" : "",
        candidate.themeEvidence || "",
        candidate.newsLogic ? `新闻逻辑：${candidate.newsLogic}` : "",
        candidate.evidence,
        Number.isFinite(candidate.estimatedStarterOpportunity) ? `估算少赚约${candidate.estimatedStarterOpportunity}元` : ""
      ])
    };
  });
}

function ensurePortfolioMissedFollowThroughReviewed(decision = {}, db = {}) {
  const queue = buildPortfolioMissedFollowThroughReviewQueue(db);
  if (!queue.length) return decision;
  const account = db.account || {};
  const totalAsset = Number(account.totalAsset || 0);
  const actions = normalizePortfolioActions(decision.actions || []);
  const existingKeys = new Set(actions.map((action) => `${action.action}:${action.code}`));
  const nextActions = [...actions];
  for (const candidate of queue.slice(0, 3)) {
    if (!candidate.code) continue;
    if ([...existingKeys].some((key) => key.endsWith(`:${candidate.code}`))) continue;
    const themeMomentum = candidate.opportunityKind === "theme_momentum";
    const canProbe = Boolean(candidate.themeMicroStarter) || candidate.status === "ready" || Number(candidate.readinessScore || 0) >= 85;
    const targetWeightPct = canProbe ? candidate.themeMicroStarter ? 1.2 : 1.5 : 0;
    const themeWhyMove = themeMomentum && candidate.newsLogic
      ? `为什么动：${shortenPortfolioCustomerText(candidate.newsLogic, 88)}；`
      : "";
    nextActions.push({
      action: canProbe ? "BUY" : "WATCH",
      code: candidate.code,
      name: candidate.name,
      amount: canProbe && totalAsset > 0 ? round(totalAsset * targetWeightPct / 100, 2) : 0,
      targetWeightPct,
      reason: canProbe
        ? themeMomentum
          ? `系统主力预热机会成本复核：${candidate.themeName || "相关题材"} ${themeWhyMove}${candidate.name || candidate.code} 等待后继续走强；本轮只给1.2%以内微型试探，而不是继续笼统观望。`
          : `系统机会成本复核：${candidate.name || candidate.code} 等待后继续走强，若费用和净值复核通过，本轮应给1.5%以内小仓试探，而不是继续笼统观望。`
        : themeMomentum
          ? `系统主力预热机会成本复核：${candidate.themeName || "相关题材"} ${themeWhyMove}${candidate.name || candidate.code} 等待后继续走强，但本轮仍需主动降级或写清复查时间；${candidate.firstTrigger || "触发条件未补齐"}。`
          : `系统机会成本复核：${candidate.name || candidate.code} 等待后继续走强，但本轮仍需主动降级或写清复查时间；${candidate.firstTrigger || "触发条件未补齐"}。`,
      rotationCheck: themeMomentum
        ? candidate.newsLogic || "只跟随主力刚进场或题材预热，必须能解释大涨背后的新闻/资金逻辑。"
        : "只处理低位/回调后继续转强的候选，不因新闻热度追高。",
      positionCheck: candidate.evidence,
      chaseRisk: candidate.firstRisk || "若继续走强后涨幅过快，下一轮主动降级为等待回撤。",
      feeCheck: candidate.firstFee || "执行前仍需核验份额类别、申购费、销售服务费和赎回规则。",
      riskControl: canProbe
        ? themeMomentum
          ? "仅作微型验证；若主力流入消失、新闻催化落空、题材退潮或基金转弱，下一轮撤回或降级。"
          : "仅作小仓验证；若盘中估算转弱、回调修复失败或费用证据不足，系统执行守卫会拦截或降级观察。"
        : "不买但必须设置复查时间，避免观察池长期沉淀后继续错过。",
      dataBasis: mergeStringLists(candidate.dataBasis, [
        "来源：portfolio_missed_follow_through_guard",
        themeMomentum ? "来源：portfolio_missed_theme_momentum_guard" : "",
        Number.isFinite(candidate.estimatedStarterOpportunity) ? `等待机会成本估算${candidate.estimatedStarterOpportunity}元` : ""
      ])
    });
    existingKeys.add(`${canProbe ? "BUY" : "WATCH"}:${candidate.code}`);
  }
  return {
    ...decision,
    actions: nextActions,
    learningNotes: mergeStringLists(decision.learningNotes, [
      `系统机会成本复核：${queue.slice(0, 3).map((item) => `${item.code} ${item.name}`.trim()).join(" / ")} 等待后继续走强，本轮必须给小仓/微型试探、主动降级或复查时间。`
    ])
  };
}

function buildPortfolioHeldPositionReviewQueue(positions = [], profiles = []) {
  const profileByCode = new Map((profiles || []).filter(Boolean).map((profile) => [profile.code, profile]));
  return (positions || [])
    .filter((position) => position?.code && Number(position.currentValue || 0) > 0)
    .slice(0, 12)
    .map((position) => {
      const profile = profileByCode.get(position.code) || position.fundSnapshot || null;
      const riskReview = buildPortfolioHeldPositionRiskReview(position, profile);
      return {
        code: position.code,
        name: position.name || profile?.name || "",
        currentValue: round(Number(position.currentValue || 0), 2),
        weightPct: round(Number(position.weightPct || 0), 2),
        unrealizedPnlPct: round(Number(position.unrealizedPnlPct || 0), 2),
        trendEvidence: profile ? formatPortfolioSeedVerifiedTrendEvidence(profile) : position.fundSnapshot?.trendSummary || "",
        riskReview,
        firstRisk: riskReview[0] || "",
        reduceTrigger: inferPortfolioHeldPositionReduceTrigger(riskReview),
        feeEvidence: profile ? formatPortfolioFeeVerificationEvidence(profile) : "",
        reviewSource: "held_position_review_queue"
      };
    });
}

function buildPortfolioHeldPositionRiskReview(position = {}, profile = null) {
  const trend = profile?.trendProfile || position.fundSnapshot?.trendProfile || {};
  const actionability = profile?.actionability || position.fundSnapshot?.actionability || {};
  const themeSource = profile || position.fundSnapshot || {};
  const review = [];
  if (!profile || !trend.ok) {
    review.push("缺少当前净值/走势复核，不能默认放任持仓。");
  }
  if (trend.trendLabel === "breakdown") review.push("趋势破位，需评估减仓或止损。");
  if (trend.trendLabel === "weakening") review.push("趋势转弱，需降低仓位或收紧复查。");
  if (trend.trendLabel === "extended_uptrend" || trend.entryBias === "wait_pullback") review.push("短期偏热或等待回撤，需防止利润回吐。");
  const return20d = finiteMetricNumber(trend.return20dPct);
  const drawdown = finiteMetricNumber(trend.drawdownFromRecentHighPct);
  const unrealized = finiteMetricNumber(position.unrealizedPnlPct);
  const peakUnrealized = finiteMetricNumber(position.peakUnrealizedPnlPct);
  const storedGiveback = finiteMetricNumber(position.profitGivebackPct);
  const computedGiveback = Number.isFinite(peakUnrealized) && Number.isFinite(unrealized)
    ? Math.max(0, round(peakUnrealized - unrealized, 2))
    : 0;
  const profitGiveback = Number.isFinite(storedGiveback) ? Math.max(storedGiveback, computedGiveback) : computedGiveback;
  const givebackLimit = Math.abs(finiteNumberOr(process.env.PORTFOLIO_PROFIT_GIVEBACK_PCT, 4));
  if (Number.isFinite(return20d) && return20d > 12) review.push(`近20日${formatFallbackPct(return20d)}，需要止盈/减仓边界。`);
  if (Number.isFinite(drawdown) && drawdown <= -10) review.push(`距高点${formatFallbackPct(drawdown)}，回撤扩大需复核止损。`);
  if (Number.isFinite(profitGiveback) && profitGiveback >= givebackLimit) {
    review.push(`浮盈已回吐${round(profitGiveback, 2)}个百分点，需启动回吐保护。`);
  }
  if (Number.isFinite(peakUnrealized) && peakUnrealized > 2 && Number.isFinite(unrealized) && unrealized < 0) {
    review.push(`曾浮盈${formatFallbackPct(peakUnrealized)}但当前转亏${formatFallbackPct(unrealized)}，需减仓复核。`);
  }
  const themeRetreatWarnings = [
    ...getPortfolioHoldingThemeRetreatWarnings(themeSource),
    ...getCandidateThemeRetreatWarnings(themeSource),
    ...getStaleThemeCatchdownWarnings(themeSource)
  ];
  if (themeRetreatWarnings.length) {
    review.push(`当前题材风险：${themeRetreatWarnings[0]}。持仓先减仓复核，不能等跌完再解释为回调。`);
  } else if (themeSource.marketThemeRefresh?.noCurrentThemeMatch) {
    review.push("旧题材线索未被当前题材雷达确认，持仓需要收紧复核，不能继续按旧逻辑加仓。");
  } else {
    const holdingThemeSupportGap = getPortfolioHoldingThemeSupportGap(themeSource);
    if (holdingThemeSupportGap) {
      review.push(`底层持仓复核：${holdingThemeSupportGap} 持仓需要收紧复核，不能用大题材热度掩盖底层方向缺证。`);
    }
  }
  if (actionability.action === "avoid") review.push("可操作性已转为回避，不能继续无条件持有。");
  if (actionability.action === "wait") review.push("可操作性偏等待，暂不加仓并设置复查。");
  if (!review.length) review.push("持仓走势未触发减仓警报，继续按纪律持有。");
  return review;
}

function inferPortfolioHeldPositionReduceTrigger(riskReview = []) {
  const text = (riskReview || []).join("；");
  if (/题材退潮|主力资金撤离|主力撤离|接盘风险|底层方向缺证|同方向/.test(text)) return "若主力资金没有重新回流，先分批降低该题材持仓，避免把退潮误判成回调。";
  if (/破位|止损|回避/.test(text)) return "若下一次复核仍破位或可操作性回避，优先减仓。";
  if (/转弱|回撤扩大/.test(text)) return "若20日/60日继续转弱或距高点回撤扩大，减仓观察。";
  if (/偏热|等待回撤|止盈/.test(text)) return "若短期继续冲高后量能转弱，分批止盈或降仓。";
  return "维持持仓，但下一次每日决策仍需逐只复核。";
}

function buildPortfolioReadyWatchlistReviewActions(watchlist = [], existingActions = [], options = {}) {
  const profiles = Array.isArray(options) ? options : options.profiles || [];
  const profileByCode = new Map((profiles || []).filter(Boolean).map((profile) => [profile.code, profile]));
  const existingCodes = new Set((existingActions || []).map((action) => action.code).filter(Boolean));
  return normalizePortfolioWatchlist(watchlist)
    .filter((item) => item.status === "ready" && item.code && !existingCodes.has(item.code))
    .slice(0, 5)
    .map((item) => {
      const profile = profileByCode.get(item.code) || item.lastSnapshot || null;
      const trendEvidence = profile ? formatPortfolioSeedVerifiedTrendEvidence(profile) : item.lastSnapshot?.trendSummary || "";
      const memoryWarnings = getPortfolioCatchdownLossMemoryWarnings(item, profile || item.lastSnapshot || {});
      const memoryWarning = memoryWarnings[0] || "";
      return {
        action: "WATCH",
        code: item.code,
        name: item.name || profile?.name || "",
        amount: 0,
        targetWeightPct: 0,
        reason: "系统补充复查动作：接近可买自选候选未被模型逐项评估，本轮先列入观察，不允许静默遗漏。",
        dataBasis: ["来源：ready_watchlist_review_fallback", trendEvidence, item.reason].filter(Boolean),
        rotationCheck: item.setupEvidence?.[0] || trendEvidence || "等待轮动/低位证据复查。",
        positionCheck: trendEvidence || "等待净值复核。",
        chaseRisk: memoryWarning || item.riskNotes?.[0] || "若短期涨幅扩大，继续等待回撤，不能追涨。",
        feeCheck: item.feeNotes?.[0] || "份额和费用待复核。",
        riskControl: memoryWarning
          ? "历史接盘冷却未解除前保持0元观察；必须等主力资金回流、新鲜催化和代表持仓承载成立后再恢复微型试探。"
          : item.buyTriggers?.[0] || "下一次盘前继续复查买入触发条件。"
      };
    });
}

function formatPortfolioRankingBoardReviewBasis(list = {}, item = {}) {
  const rank = Number(item.rank || 0);
  const title = list.title || list.id || "经理榜单";
  const rankText = rank > 0 ? `第${rank}名` : "靠前项";
  const actionText = item.action ? `，榜单动作：${item.action}` : "";
  const reasonText = item.reason ? `；${item.reason}` : "";
  return `${title}${rankText}，系统补充复核，防止榜单项被今日操作遗漏${actionText}${reasonText}`;
}

function inferPortfolioRankingBoardReviewAction(list = {}, item = {}) {
  const listId = String(list.id || "");
  const actionText = `${item.action || ""} ${item.reason || ""} ${item.decision?.nextStep || ""}`;
  if (listId === "sell_risk") {
    return /优先卖出|卖出|减仓|止损|止盈|回吐/.test(actionText) ? "SELL" : "HOLD";
  }
  if (isPortfolioRankingBoardBuyReviewList(listId) && isPortfolioRankingBoardBuyReviewText(actionText)) {
    if (listId === "theme_momentum" && !hasTraceablePortfolioRankingThemeMomentumEvidence(list, item)) {
      return "WATCH";
    }
    return "BUY";
  }
  if (listId === "replacement_choice") return "WATCH";
  if (listId === "user_holding_alerts") return "WATCH";
  return "WATCH";
}

function hasTraceablePortfolioRankingThemeMomentumEvidence(list = {}, item = {}) {
  const text = [
    list.title,
    item.action,
    item.reason,
    ...(Array.isArray(item.facts) ? item.facts : []),
    ...(Array.isArray(item.decision?.highlights) ? item.decision.highlights : []),
    ...(Array.isArray(item.decision?.risks) ? item.decision.risks : []),
    ...(Array.isArray(item.decision?.gaps) ? item.decision.gaps : []),
    item.decision?.nextStep
  ].filter(Boolean).join(" ");
  const hasWhyMove = /为什么动|大涨逻辑|题材逻辑|新闻|催化|政策|订单|产业|落地|发布|获批|会议|财报|公告/.test(text);
  const hasTrace = /(?:\d{1,2}:\d{2}|东方财富|新浪财经|财联社|证券时报|上证报|中证报|快讯|电报|source[:=])/i.test(text);
  const hasCapital = /主力|资金|流入|抢筹|净流入|主力进场|资金开始配合/.test(text);
  return hasWhyMove && hasTrace && hasCapital;
}

function isPortfolioUserHoldingDeRiskAlert(list = {}, item = {}) {
  if (String(list.id || "") !== "user_holding_alerts") return false;
  const text = [
    item.action,
    item.reason,
    ...(Array.isArray(item.facts) ? item.facts : []),
    ...(Array.isArray(item.decision?.highlights) ? item.decision.highlights : []),
    ...(Array.isArray(item.decision?.risks) ? item.decision.risks : []),
    ...(Array.isArray(item.decision?.gaps) ? item.decision.gaps : []),
    item.decision?.nextStep
  ].filter(Boolean).join(" ");
  return /卖出|减仓|止损|止盈|回吐|接盘|退潮|主力(?:资金)?撤离|资金撤离|旧题材|历史热点|回调不是买点|回调不能当买点/.test(text);
}

function isPortfolioRankingBoardBuyReviewList(listId = "") {
  return new Set([
    "decision_synthesis",
    "buy_preparation",
    "launch_setup",
    "cash_redeployment",
    "position_sizing",
    "theme_momentum",
    "rotation_opportunity"
  ]).has(String(listId || ""));
}

function isPortfolioRankingBoardBuyReviewText(text = "") {
  const body = String(text || "");
  if (!/(买入复核|优先买入|小仓试探|微型试探|启动仓复核|可分批|可小仓|主力预热微型试探|主力预热买入复核)/.test(body)) {
    return false;
  }
  return !/(0元观察|观察补证据|继续观察|先观察|等待|回避|暂不|不买|补证据|缺[^，。；;]{0,24}(?:证据|确认|核验|持仓|费用|净值|买点)|风险未解除|追涨|退潮|接盘|降温观察|数据不足)/.test(body);
}

function resolvePortfolioRankingReviewTargetWeight(list = {}, item = {}, reviewAction = "") {
  if (reviewAction !== "BUY") return 0;
  const text = `${list.title || ""} ${list.id || ""} ${item.action || ""} ${item.reason || ""} ${item.decision?.nextStep || ""}`;
  if (/微型|0\.5%-1\.2%|1\.2%/.test(text)) return 1.2;
  if (/小仓|1\.5%/.test(text)) return 1.5;
  if (/启动仓|2\.5%|0\.5%-2\.5%|分批/.test(text)) return 2.5;
  return 1;
}

function buildPortfolioRankingBoardReviewActions(board = {}, existingActions = []) {
  const lists = Array.isArray(board?.lists) ? board.lists : [];
  const existingCodes = new Set((existingActions || []).map((action) => action.code).filter(Boolean));
  const watchedListIds = new Set(["decision_synthesis", "buy_preparation", "launch_setup", "cash_redeployment", "position_sizing", "quality_score", "manager_stability", "portfolio_fit", "theme_allocation", "theme_momentum", "rotation_opportunity", "stale_catchdown_risk", "chase_risk", "drawdown_defense", "data_confidence", "fee_suitability", "replacement_choice", "holdings_outlook", "opportunity_cost", "sell_risk", "user_holding_alerts"]);
  const actions = [];
  for (const list of lists) {
    if (!watchedListIds.has(String(list?.id || ""))) continue;
    for (const item of (Array.isArray(list.items) ? list.items : []).slice(0, 3)) {
      const code = String(item?.code || "").match(/^\d{6}$/)?.[0] || "";
      if (!code || existingCodes.has(code)) continue;
      const reviewAction = inferPortfolioRankingBoardReviewAction(list, item);
      const targetWeightPct = resolvePortfolioRankingReviewTargetWeight(list, item, reviewAction);
      const basis = formatPortfolioRankingBoardReviewBasis(list, item);
      const decision = item.decision || {};
      const highlights = normalizeStringArray(decision.highlights);
      const risks = normalizeStringArray(decision.risks);
      const gaps = normalizeStringArray(decision.gaps);
      const facts = normalizeStringArray(item.facts);
      const userHoldingDeRiskAlert = isPortfolioUserHoldingDeRiskAlert(list, item);
      const catchdownRiskReview = isPortfolioRankingBoardCatchdownRiskReview(list, item);
      actions.push({
        action: reviewAction,
        code,
        name: item.name || "",
        amount: 0,
        targetWeightPct,
        rankingBasis: basis,
        reason: userHoldingDeRiskAlert
          ? `${basis}；用户真实持仓卖出/减仓提醒：这不是普通观察项，经理必须提示客户复核卖点、成本和到账规则；由于该仓位不一定属于虚拟组合，本轮不提交虚拟赎回。`
          : catchdownRiskReview
            ? `${basis}；接盘风险复核：这不是低位启动，本轮只能0元观察，不能试探买入；必须等新鲜催化、主力资金回流、代表持仓止跌和基金低位温和转强同时出现。`
          : `${basis}；本轮先给${reviewAction === "BUY" ? "买入" : reviewAction === "SELL" ? "分批减仓/卖出" : reviewAction === "HOLD" ? "持仓" : "观察"}复核，不允许静默跳过。`,
        dataBasis: mergeStringLists([
          "来源：manager_ranking_board",
          userHoldingDeRiskAlert ? "来源：user_holding_derisk_alert" : "",
          catchdownRiskReview ? "来源：stale_catchdown_risk_guard" : "",
          item.source ? `榜单来源：${item.source}` : "",
          item.score ? `榜单评分${item.score}` : "",
          ...facts
        ], highlights.slice(0, 2)),
        rotationCheck: catchdownRiskReview
          ? "题材退潮或主力撤离未解除，不能把表面回调当成低位启动。"
          : highlights[0] || item.reason || "按经理榜单复核轮动、低位和用户持仓提醒。",
        positionCheck: catchdownRiskReview
          ? "先看代表持仓是否止跌、主力是否回流；未确认前维持0元观察。"
          : facts.join("；") || item.reason || "等待走势和位置证据复核。",
        chaseRisk: catchdownRiskReview
          ? risks[0] || "旧题材/主力撤离后的反弹容易变成接盘，不给买入金额。"
          : risks[0] || gaps[0] || "若榜单项缺少低位、转强或费用证据，保持观察，不追涨。",
        feeCheck: facts.find((fact) => /[ACDI]类|费用|申购|销售服务费|赎回/.test(fact)) || "执行前仍需核验份额类别、申购费、销售服务费和赎回规则。",
        riskControl: userHoldingDeRiskAlert
          ? (decision.nextStep || "优先提醒对应用户复核卖出/减仓；先确认客户真实成本、持有份额、赎回费和到账日，不提交虚拟组合赎回单。")
          : catchdownRiskReview
            ? "榜单机会本轮只保留为0元观察；等新鲜新闻/政策催化、主力资金回流、代表持仓止跌、基金低位温和转强同时成立后，再允许重新进入小仓复核。"
          : decision.nextStep || (reviewAction === "SELL"
            ? "先复核赎回到账和减仓比例，禁止用补仓替代风控。"
            : reviewAction === "BUY"
              ? "只按榜单给小仓复核；执行前仍要经过净值、费用、仓位和题材退潮守卫。"
            : "下一轮继续跟踪榜单触发条件，未满足前不提交虚拟申购。")
      });
      existingCodes.add(code);
    }
  }
  return actions;
}

function isPortfolioRankingBoardCatchdownRiskReview(list = {}, item = {}) {
  return String(list?.id || "") === "stale_catchdown_risk"
    || isPortfolioCustomerCatchdownAvoidAction({
      ...item,
      listId: list?.id || "",
      listTitle: list?.title || ""
    });
}

function buildPortfolioHeldPositionReviewActions(positions = [], existingActions = [], options = {}) {
  const profiles = Array.isArray(options) ? options : options.profiles || [];
  const profileByCode = new Map((profiles || []).filter(Boolean).map((profile) => [profile.code, profile]));
  const existingCodes = new Set((existingActions || []).map((action) => action.code).filter(Boolean));
  return (positions || [])
    .filter((position) => position?.code && Number(position.currentValue || 0) > 0 && !existingCodes.has(position.code))
    .slice(0, 8)
    .map((position) => {
      const profile = profileByCode.get(position.code) || position.fundSnapshot || null;
      const trendEvidence = profile ? formatPortfolioSeedVerifiedTrendEvidence(profile) : position.fundSnapshot?.trendSummary || "";
      const riskReview = buildPortfolioHeldPositionRiskReview(position, profile);
      const reduceGuard = evaluatePortfolioSellDiscipline(
        {
          action: "SELL",
          code: position.code,
          name: position.name || profile?.name || "",
          amount: round(Number(position.currentValue || 0), 2),
          targetWeightPct: 0,
          reason: `系统持仓复查：${riskReview.slice(0, 2).join("；") || "持仓风险复核"}`,
          riskControl: inferPortfolioHeldPositionReduceTrigger(riskReview)
        },
        profile,
        position
      );
      const reduceByGuard = reduceGuard.ok && shouldReduceHeldPositionFromReview(riskReview, profile, position);
      return {
        action: reduceByGuard ? "SELL" : "HOLD",
        code: position.code,
        name: position.name || profile?.name || "",
        amount: reduceByGuard ? round(Number(position.currentValue || 0), 2) : 0,
        targetWeightPct: reduceByGuard ? 0 : round(Number(position.weightPct || 0), 2),
        reason: reduceByGuard
          ? "系统补充分批减仓动作：已有持仓未被模型逐项评估，且持仓复查证据已触发降风险条件。"
          : "系统补充持仓复查动作：已有持仓未被模型逐项评估，本轮先按纪律持有，不允许静默遗漏。",
        dataBasis: [
          "来源：held_position_review_fallback",
          trendEvidence,
          ...riskReview.slice(0, 2),
          reduceByGuard ? reduceGuard.reason : ""
        ].filter(Boolean),
        rotationCheck: riskReview[0] || "持仓轮动状态待复核。",
        positionCheck: trendEvidence || "等待净值复核。",
        chaseRisk: riskReview.find((item) => /偏热|回撤|破位|转弱|回避/.test(item)) || "未触发主要持仓风险警报。",
        feeCheck: profile ? formatPortfolioFeeVerificationEvidence(profile) : "份额和费用待复核。",
        riskControl: reduceByGuard
          ? (reduceGuard.riskControl || "只做系统限额内的分批减仓，下一轮继续复核是否追加。")
          : inferPortfolioHeldPositionReduceTrigger(riskReview)
      };
    });
}

function shouldReduceHeldPositionFromReview(riskReview = [], profile = null, position = {}) {
  const text = (riskReview || []).join("；");
  const trend = profile?.trendProfile || position.fundSnapshot?.trendProfile || {};
  const actionability = profile?.actionability || position.fundSnapshot?.actionability || {};
  const return20d = finiteMetricNumber(trend.return20dPct);
  const return60d = finiteMetricNumber(trend.return60dPct);
  return /破位|转弱|回撤扩大|回避/.test(text)
    || /题材退潮|主力资金撤离|主力撤离|接盘风险|同方向.*(?:退潮|主力资金撤离|主力撤离)|底层持仓复核.*(?:当前题材雷达没有确认|底层方向缺证)/.test(text)
    || actionability.action === "avoid"
    || /回吐保护|当前转亏/.test(text)
    || (actionability.action === "wait" && /缺少当前净值\/走势复核|浮盈已回吐|当前转亏/.test(text))
    || (Number.isFinite(return20d) && return20d > 20 && Number.isFinite(return60d) && return60d > 24)
    || (/偏热|等待回撤/.test(text) && Number.isFinite(return20d) && return20d > 12);
}

function ensurePortfolioReadyWatchlistReviewed(decision, watchlist = [], options = {}) {
  const normalized = {
    ...decision,
    actions: normalizePortfolioActions(decision?.actions),
    watchlistUpdates: normalizePortfolioWatchlistUpdates(decision?.watchlistUpdates),
    team: Array.isArray(decision?.team) ? decision.team : [],
    riskNotes: Array.isArray(decision?.riskNotes) ? decision.riskNotes : [],
    learningNotes: Array.isArray(decision?.learningNotes) ? decision.learningNotes : [],
    sources: Array.isArray(decision?.sources) ? decision.sources : []
  };
  const fallbackActions = buildPortfolioReadyWatchlistReviewActions(watchlist, normalized.actions, options);
  if (!fallbackActions.length) return normalized;
  return {
    ...normalized,
    actions: [...normalized.actions, ...fallbackActions],
    learningNotes: mergeStringLists(
      normalized.learningNotes,
      [`系统补充了 ${fallbackActions.length} 条接近可买自选候选复查动作，防止每日决策遗漏购买准备队列。`]
    ),
    sources: mergeStringLists(normalized.sources, ["ready_watchlist_review_fallback"])
  };
}

function ensurePortfolioHeldPositionsReviewed(decision, positions = [], options = {}) {
  const normalized = {
    ...decision,
    actions: normalizePortfolioActions(decision?.actions),
    watchlistUpdates: normalizePortfolioWatchlistUpdates(decision?.watchlistUpdates),
    team: Array.isArray(decision?.team) ? decision.team : [],
    riskNotes: Array.isArray(decision?.riskNotes) ? decision.riskNotes : [],
    learningNotes: Array.isArray(decision?.learningNotes) ? decision.learningNotes : [],
    sources: Array.isArray(decision?.sources) ? decision.sources : []
  };
  const fallbackActions = buildPortfolioHeldPositionReviewActions(positions, normalized.actions, options);
  if (!fallbackActions.length) return normalized;
  return {
    ...normalized,
    actions: [...normalized.actions, ...fallbackActions],
    learningNotes: mergeStringLists(
      normalized.learningNotes,
      [`系统补充了 ${fallbackActions.length} 条已有持仓复查动作，防止每日决策忽略仓位风险。`]
    ),
    sources: mergeStringLists(normalized.sources, ["held_position_review_fallback"])
  };
}

function ensurePortfolioRankingBoardReviewed(decision, managerRankings = {}) {
  const normalized = {
    ...decision,
    actions: normalizePortfolioActions(decision?.actions),
    watchlistUpdates: normalizePortfolioWatchlistUpdates(decision?.watchlistUpdates),
    team: Array.isArray(decision?.team) ? decision.team : [],
    riskNotes: Array.isArray(decision?.riskNotes) ? decision.riskNotes : [],
    learningNotes: Array.isArray(decision?.learningNotes) ? decision.learningNotes : [],
    sources: Array.isArray(decision?.sources) ? decision.sources : []
  };
  const lists = Array.isArray(managerRankings?.lists) ? managerRankings.lists : [];
  if (!lists.length) return normalized;
  const rankingItemsByCode = new Map();
  for (const list of lists) {
    for (const item of (Array.isArray(list.items) ? list.items : []).slice(0, 3)) {
      const code = String(item?.code || "").match(/^\d{6}$/)?.[0] || "";
      if (!code) continue;
      const entries = rankingItemsByCode.get(code) || [];
      entries.push({ list, item });
      rankingItemsByCode.set(code, entries);
    }
  }
  let enrichedCount = 0;
  const enrichedActions = normalized.actions.map((action) => {
    const entry = selectPortfolioRankingBoardEntryForAction(action, rankingItemsByCode.get(action.code) || []);
    if (!entry) return action;
    const basis = action.rankingBasis || formatPortfolioRankingBoardReviewBasis(entry.list, entry.item);
    const dataBasis = mergeStringLists(action.dataBasis, ["来源：manager_ranking_board"]);
    const upgraded = upgradePortfolioRankingBoardWatchAction(action, entry);
    if (basis !== action.rankingBasis || dataBasis.length !== action.dataBasis.length || upgraded.action !== action.action) enrichedCount += 1;
    return {
      ...upgraded,
      rankingBasis: basis,
      dataBasis
    };
  });
  const fallbackActions = buildPortfolioRankingBoardReviewActions(managerRankings, enrichedActions);
  if (!fallbackActions.length && !enrichedCount) return normalized;
  return {
    ...normalized,
    actions: [...enrichedActions, ...fallbackActions],
    learningNotes: mergeStringLists(
      normalized.learningNotes,
      [
        enrichedCount ? `系统为 ${enrichedCount} 条既有动作补充经理榜单依据。` : "",
        fallbackActions.length ? `系统补充了 ${fallbackActions.length} 条经理榜单靠前项复核动作，防止榜单和今日操作割裂。` : ""
      ]
    ),
    sources: mergeStringLists(normalized.sources, ["manager_ranking_board_guard"])
  };
}

function upgradePortfolioRankingBoardWatchAction(action = {}, entry = {}) {
  const currentAction = String(action.action || "").toUpperCase();
  if (currentAction !== "WATCH") return action;
  const reviewAction = inferPortfolioRankingBoardReviewAction(entry.list, entry.item);
  if (reviewAction !== "BUY") return action;
  const targetWeightPct = resolvePortfolioRankingReviewTargetWeight(entry.list, entry.item, reviewAction);
  const nextStep = entry.item?.decision?.nextStep || "";
  return {
    ...action,
    action: "BUY",
    amount: 0,
    targetWeightPct,
    reason: [
      action.reason || "",
      "系统榜单升级：该候选已进入主力/预热或买入准备的可执行小仓复核，不能继续空泛观察；下单前仍由净值、费用、仓位和题材退潮守卫二次拦截。"
    ].filter(Boolean).join(" "),
    riskControl: nextStep || action.riskControl || "只按榜单给小仓复核；执行前仍要经过净值、费用、仓位和题材退潮守卫。"
  };
}

function selectPortfolioRankingBoardEntryForAction(action = {}, entries = []) {
  if (!entries.length) return null;
  const actionText = String(action.action || "").toUpperCase();
  const preferredIds = actionText === "BUY"
    ? ["buy_preparation", "cash_redeployment", "position_sizing", "launch_setup", "theme_momentum", "data_confidence", "quality_score", "manager_stability", "portfolio_fit", "theme_allocation", "stale_catchdown_risk", "drawdown_defense", "decision_synthesis", "rotation_opportunity", "fee_suitability", "replacement_choice", "holdings_outlook", "opportunity_cost"]
    : actionText === "SELL"
      ? ["sell_risk", "drawdown_defense", "stale_catchdown_risk", "chase_risk", "decision_synthesis", "opportunity_cost"]
      : actionText === "HOLD"
        ? ["sell_risk", "drawdown_defense", "data_confidence", "decision_synthesis", "holdings_outlook", "stale_catchdown_risk", "chase_risk"]
        : ["buy_preparation", "cash_redeployment", "position_sizing", "launch_setup", "theme_momentum", "data_confidence", "quality_score", "manager_stability", "portfolio_fit", "theme_allocation", "drawdown_defense", "stale_catchdown_risk", "chase_risk", "decision_synthesis", "rotation_opportunity", "fee_suitability", "replacement_choice", "holdings_outlook"];
  return [...entries].sort((a, b) => {
    const aRank = preferredIds.indexOf(String(a.list?.id || ""));
    const bRank = preferredIds.indexOf(String(b.list?.id || ""));
    return (aRank === -1 ? 99 : aRank) - (bRank === -1 ? 99 : bRank)
      || Number(a.item?.rank || 99) - Number(b.item?.rank || 99);
  })[0] || null;
}

function inferPortfolioWatchStatusFromAnswerProfile(profile = {}, role = "buy_reference") {
  const seedScore = Math.max(60, Number(scoreResearchDigestForPullbackSetup(profile)) || 0);
  const seedStatus = inferPortfolioWatchStatusFromSeedCandidate(profile, seedScore, profile);
  if (seedStatus === "blocked") return "blocked";
  if (profile?.actionability?.action === "avoid" || profile?.trendProfile?.entryBias === "avoid_now") return "blocked";
  if (role === "backup") return seedStatus === "blocked" ? "blocked" : "waiting_pullback";
  if (seedStatus === "ready") return "ready";
  if (profile?.trendProfile?.entryBias === "wait_pullback" || profile?.actionability?.action === "wait") return "waiting_pullback";
  return "watch";
}

function formatAnswerWatchlistStatusReason(status, role, profile = null) {
  if (status === "ready" && isMainlineLaunchWatchProfile(profile)) {
    return "净值、新闻逻辑、主力线索和持仓承载已满足主线启动微型验证条件，可作为接近可买自选复核。";
  }
  if (status === "ready") return "净值和走势证据已满足低位回调/启动候选条件，可作为接近可买自选复核。";
  if (status === "blocked") return "系统复核识别到偏热、追涨或回避风险，写入暂不买入而不是可买。";
  if (status === "waiting_pullback") {
    return role === "backup"
      ? "回答中属于备选观察，必须等待触发条件满足后再升级。"
      : "暂未完全证明低位启动，先等待回调/确认。";
  }
  return "作为普通观察候选保留，等待更多数据确认。";
}

function isMainlineLaunchWatchProfile(profile = null) {
  if (!profile) return false;
  return hasPortfolioThemeMicroStarterSetup(profile)
    && !hasThemeLowBaseMicroStarterTrendSetup(profile.trendProfile || {})
    && !hasVerifiedPortfolioBuySetup(profile);
}

function formatAnswerWatchlistGapEvidence(profile = {}, options = {}) {
  const status = String(options.status || "");
  const role = String(options.role || "");
  const userText = String(options.userText || "");
  const context = String(options.context || "");
  const text = normalizeIntentText(`${userText} ${context}`);
  const shouldExplainGap = isPullbackSetupRequest(userText)
    || /(回调|回踩|回撤|低位|启动|追涨|备选|观察|等待)/.test(text);
  if (!shouldExplainGap) return "";

  const gaps = buildPullbackSetupCandidateGaps(profile);
  if (gaps.length) {
    return `观察缺口：${gaps.slice(0, 4).join("；")}。`;
  }
  if (status === "ready") {
    if (isMainlineLaunchWatchProfile(profile)) {
      return "观察缺口：主线启动微型验证条件暂已满足，下一次复核新闻、主力资金和代表持仓是否延续。";
    }
    return "观察缺口：低位启动条件暂已满足，等待下一次净值确认。";
  }
  if (role === "backup") {
    return "观察缺口：回答定位为备选，仍需下一次盘前触发确认。";
  }
  return "";
}

function buildAnswerWatchBuyTriggers(status, role, profile = null, options = {}) {
  if (options.catchdownRejected) {
    return [
      "新鲜新闻/政策催化重新出现，且不是旧新闻复炒。",
      "主力资金回流、代表持仓止跌、基金低位温和转强同时成立后，才允许重新评估。"
    ];
  }
  if (status === "blocked") {
    return ["重新回到低位、回撤消化且5日/10日温和转强后，才允许重新评估。"];
  }
  if (status === "ready") {
    if (isMainlineLaunchWatchProfile(profile)) {
      return [
        "主力资金和新闻催化继续成立，代表持仓不冲高回落，才允许0.5%-1.2%微型验证。",
        "题材不进入拥挤/追涨状态，基金前十大仍能承载龙头或指数标的。"
      ];
    }
    return [
      "下一次净值更新后仍保持回调完成或启动前夜，且近20日涨幅不超过10%。",
      "主题没有进入拥挤/追涨状态，费用和份额类别适合计划持有期。"
    ];
  }
  return [
    role === "backup" ? "备选候选需等回踩确认或5日/10日重新转强。" : "等待低位和回调完成证据更完整。",
    "若近20日或近60日涨幅快速扩大，继续降级观察，避免追涨。"
  ];
}

function buildAnswerWatchRiskNotes(status, profile = {}, options = {}) {
  const trend = profile.trendProfile || {};
  return [
    options.catchdownRejected ? "已被系统写入接盘风险排除候选，只能0元观察，不能给买入金额。" : status === "blocked" ? "已被系统写入暂不买入，不能在执行方案中给买入金额。" : "",
    Number.isFinite(Number(trend.return20dPct)) ? `近20日${formatFallbackPct(trend.return20dPct)}，需防止短线过热。` : "",
    Number.isFinite(Number(trend.drawdownFromRecentHighPct)) ? `距近期高点${formatFallbackPct(trend.drawdownFromRecentHighPct)}，回撤深度需复查。` : "",
    "自选池只记录候选，不等同于自动下单。"
  ].filter(Boolean);
}

function formatAnswerWatchPositionPlan(status, role, profile = null, options = {}) {
  if (options.catchdownRejected) return "0元观察；不是低位启动，等新鲜催化、主力资金回流、代表持仓止跌和基金低位温和转强同时出现后再复核。";
  if (status === "ready" && isMainlineLaunchWatchProfile(profile)) return "只按主线启动微型验证处理，单笔0.5%-1.2%，若新闻或主力退潮立即撤回。";
  if (status === "ready") return "触发后只做卫星仓小额分批，先验证不追涨。";
  if (status === "blocked") return "暂不买入；只有重新形成低位启动证据后才复查。";
  if (role === "backup") return "先作为备选观察，不给买入金额，等待触发条件。";
  return "先观察，等回调完成和低位证据确认后再进入分批评估。";
}

function scoreAnswerWatchPriority(status, role) {
  if (status === "ready") return 1;
  if (status === "waiting_pullback" && role === "backup") return 3;
  if (status === "waiting_pullback") return 2;
  if (status === "blocked") return 5;
  return 4;
}

function persistAnswerWatchlistCandidates({ userText = "", answerText = "", chartProfiles = [], source = "fund_answer_watchlist" } = {}) {
  if (String(process.env.PORTFOLIO_ANSWER_WATCHLIST_ENABLED ?? "true") === "false") return [];
  const updates = buildPortfolioWatchlistUpdatesFromAnswerProfiles(chartProfiles, { userText, answerText, source });
  if (!updates.length) return [];
  try {
    const db = readPortfolioDb();
    ensurePortfolioAccount(db, getEffectiveConfig());
    const applied = applyPortfolioWatchlistUpdates(db, updates, {
      profiles: Array.isArray(chartProfiles) ? chartProfiles : [chartProfiles].filter(Boolean),
      source
    });
    if (applied.length) {
      writePortfolioDb(db);
      updateStats({
        counters: {
          answerWatchlistUpdates: 1,
          answerWatchlistCandidates: applied.length
        },
        last: { lastAnswerWatchlistUpdateAt: new Date().toISOString() }
      });
    }
    return applied;
  } catch (error) {
    console.warn("[answer-watchlist-update-error]", error.message);
    recordError(error, { answerWatchlistUpdateFailures: 1 });
    return [];
  }
}

function inferPortfolioWatchStatusFromSeedCandidate(candidate = {}, seedScore = 0, profile = null) {
  if (!profile || !profile.trendProfile?.ok) {
    return "waiting_pullback";
  }
  if (hasPortfolioVerifiedSeedChaseRisk(candidate, profile)) {
    return "blocked";
  }
  if (getPortfolioActionableThemeSupportGap(profile)) {
    return "waiting_pullback";
  }
  const verifiedReady = Number(seedScore) >= 60 && (
    hasVerifiedPortfolioBuySetup(profile)
    || hasPortfolioThemeMicroStarterSetup(profile)
  );
  if (verifiedReady) {
    return "ready";
  }
  return "waiting_pullback";
}

function hasVerifiedPortfolioBuySetup(profile = {}) {
  const trend = profile?.trendProfile || {};
  if (!trend.ok) return false;
  if (getPortfolioActionableThemeSupportGap(profile)) return false;
  const signal = trend.pullbackSetup?.signal || "";
  const return20d = finiteMetricNumber(trend.return20dPct);
  const return60d = finiteMetricNumber(trend.return60dPct);
  return ["pullback_complete", "launch_setup"].includes(signal)
    && trend.trendLabel !== "extended_uptrend"
    && trend.entryBias !== "wait_pullback"
    && trend.entryBias !== "avoid_now"
    && isEarlyTurnSetupTrend(trend)
    && hasPullbackLowPositionEvidence(trend)
    && Number.isFinite(return20d)
    && return20d <= 10
    && Number.isFinite(return60d)
    && return60d <= 24;
}

function hasPortfolioStarterBuySetup(profile = {}) {
  const trend = profile?.trendProfile || {};
  if (!trend.ok || hasVerifiedPortfolioBuySetup(profile)) return false;
  if (getPortfolioActionableThemeSupportGap(profile)) return false;
  const signal = trend.pullbackSetup?.signal || "";
  if (!["pullback_complete", "launch_setup"].includes(signal)) return false;
  if (trend.trendLabel === "extended_uptrend" || trend.entryBias === "wait_pullback" || trend.entryBias === "avoid_now") return false;
  if (["wait", "avoid"].includes(profile?.actionability?.action)) return false;
  if (!hasPullbackLowPositionEvidence(trend)) return false;

  const r5 = finiteMetricNumber(trend.return5dPct);
  const r10 = finiteMetricNumber(trend.return10dPct);
  const r20 = finiteMetricNumber(trend.return20dPct);
  const r60 = finiteMetricNumber(trend.return60dPct);
  return Number.isFinite(r5)
    && r5 > 0
    && r5 <= 4.5
    && Number.isFinite(r10)
    && r10 >= -2
    && r10 <= 7
    && Number.isFinite(r20)
    && r20 >= -6
    && r20 <= 10
    && Number.isFinite(r60)
    && r60 <= 24
    && !hasHighChaseTheme(profile)
    && !hasStaleThemeCatchdownRisk(profile)
    && !hasHoldingRealtimeCatchdownRisk(profile);
}

function hasPortfolioThemeMicroStarterSetup(profile = {}) {
  const trend = profile?.trendProfile || {};
  if (!trend.ok || hasVerifiedPortfolioBuySetup(profile) || hasPortfolioStarterBuySetup(profile)) return false;
  if (getPortfolioActionableThemeSupportGap(profile)) return false;
  if (!hasActionabilityMicroStarterSupport(profile, trend)) return false;
  if (!hasVerifiedThemeCarrierEvidence(profile)) return false;
  if (!isPullbackTrendFreshEnough(profile)) return false;
  if (hasHighChaseTheme(profile) || hasThemeRetreatRisk(profile) || hasStaleThemeCatchdownRisk(profile)) return false;
  if (hasHoldingRealtimeCatchdownRisk(profile)) return false;
  if (profile?.actionability?.action === "avoid") return false;
  const blockers = normalizeStringArray(profile?.actionability?.decisionBlocker);
  if (profile?.actionability?.action === "wait" && !blockers.some((item) => item.includes("小仓试探"))) return false;
  return hasThemeLowBaseMicroStarterTrendSetup(trend) || hasThemeLaunchProbeTrendSetup(trend);
}

function hasVerifiedPortfolioFeeEvidence(profile = {}) {
  const fees = profile?.fees || {};
  const shareClass = String(fees.shareClass || profile.shareClass || "").toUpperCase();
  const feeModel = fees.shareClassFeeModel || profile.shareClassFeeModel || {};
  const impact = fees.feeImpact || profile.feeImpact || {};
  const missing = new Set(normalizeStringArray(impact.missingFeeData || fees.missingFeeData));
  const oneYearCost = toNumber(impact.oneYearCostPer10000);
  if (!shareClass || !feeModel.label || feeModel.type === "unknown") return false;
  const specialAvailability = evaluatePortfolioSpecialShareClassAvailability(profile);
  if (specialAvailability.required && !specialAvailability.ok) return false;
  if (["share_class", "subscription_or_sales_service_fee", "sales_service_fee", "subscription_fee"].some((item) => missing.has(item))) {
    return false;
  }
  if (Number.isFinite(oneYearCost)) return true;
  if (["C", "E"].includes(shareClass)) {
    return Number.isFinite(toNumber(fees.salesServiceFeePct)) && feeModel.type === "sales_service_fee";
  }
  if (["A", "B"].includes(shareClass)) {
    return Number.isFinite(toNumber(fees.currentRatePct)) || Number.isFinite(toNumber(fees.sourceRatePct));
  }
  return Boolean(fees.source || fees.feeRules?.subscription || fees.feeRules?.redemption);
}

function evaluatePortfolioSpecialShareClassAvailability(profile = {}) {
  const fees = profile?.fees || {};
  const impact = fees.feeImpact || profile.feeImpact || {};
  const shareClass = String(fees.shareClass || profile.shareClass || "").toUpperCase();
  const feeModel = fees.shareClassFeeModel || profile.shareClassFeeModel || {};
  const required = feeModel.type === "special_or_platform_class"
    || ["D", "I", "Y"].includes(shareClass)
    || impact.holdingPeriodFit === "channel_or_institution_only_check";
  if (!required) return { required: false, ok: true, reason: "", evidence: [] };

  const channelSignals = [
    fees.retailAvailable,
    fees.ordinaryRetailAvailable,
    fees.availableForPurchase,
    fees.subscriptionAvailable,
    fees.channelAvailability,
    fees.purchaseAvailability,
    fees.subscriptionAvailability,
    profile.retailAvailable,
    profile.ordinaryRetailAvailable,
    profile.availableForPurchase,
    profile.subscriptionAvailable,
    profile.channelAvailability,
    profile.purchaseAvailability,
    profile.subscriptionAvailability
  ].flatMap(normalizePortfolioAvailabilitySignals);
  const subscriptionRules = String(
    fees.feeRules?.subscription
    || fees.subscriptionRules
    || impact.subscriptionRules
    || profile.subscriptionRules
    || ""
  ).trim();
  const minPurchase = toNumber(fees.minPurchase ?? profile.minPurchase ?? profile.seed?.minPurchase);
  const hasRetailOpenSignal = channelSignals.some(isPortfolioShareAvailabilityOpenSignal);
  const hasClosedSignal = channelSignals.some(isPortfolioShareAvailabilityClosedSignal)
    || isPortfolioShareAvailabilityClosedSignal(subscriptionRules);
  const hasMinPurchase = Number.isFinite(minPurchase);
  const hasSubscriptionRules = Boolean(subscriptionRules);
  const missing = [];
  if (!hasRetailOpenSignal) missing.push("普通渠道可申购");
  if (!hasMinPurchase) missing.push("起购门槛");
  if (!hasSubscriptionRules) missing.push("申购规则");
  if (hasClosedSignal) missing.push("渠道限制");
  const ok = hasRetailOpenSignal && hasMinPurchase && hasSubscriptionRules && !hasClosedSignal;
  const label = shareClass ? `${shareClass}类` : "特殊/平台份额";
  return {
    required: true,
    ok,
    reason: ok
      ? `${label}特殊份额已验证普通渠道可申购、起购门槛和申购规则。`
      : `${label}特殊/平台份额缺少${missing.join("、")}验证，不能直接买入。`,
    evidence: [
      `${label}特殊/平台份额`,
      hasRetailOpenSignal ? "普通渠道可申购已验证" : "缺普通渠道可申购验证",
      hasMinPurchase ? `起购门槛${minPurchase}元` : "缺起购门槛",
      hasSubscriptionRules ? "申购规则已抓取" : "缺申购规则",
      hasClosedSignal ? "存在渠道限制信号" : ""
    ].filter(Boolean)
  };
}

function normalizePortfolioAvailabilitySignals(value) {
  if (value === null || value === undefined || value === "") return [];
  if (Array.isArray(value)) return value.flatMap(normalizePortfolioAvailabilitySignals);
  if (typeof value === "object") {
    return Object.entries(value)
      .filter(([key]) => /status|state|note|text|label|available|availability|retail|ordinary|channel|subscription|purchase/i.test(key))
      .flatMap(([, entry]) => normalizePortfolioAvailabilitySignals(entry));
  }
  return [String(value).trim()].filter(Boolean);
}

function isPortfolioShareAvailabilityOpenSignal(value = "") {
  const text = String(value || "").trim().toLowerCase();
  return /^(true|yes|available|open|retail_open|ordinary_retail_open|purchase_open|subscription_open)$/.test(text)
    || /普通.*(?:可申购|可购买|开放)|面向普通投资者|渠道.*(?:可申购|可购买|开放)|开放申购|可申购|可购买/.test(text);
}

function isPortfolioShareAvailabilityClosedSignal(value = "") {
  const text = String(value || "").trim().toLowerCase();
  return /^(false|no|closed|unavailable|blocked|suspended|institution_only|platform_only)$/.test(text)
    || /暂停.*申购|暂停.*买入|不可申购|不可购买|不开放|仅.*(?:机构|特定|平台)|机构专属|平台专属|渠道受限/.test(text);
}

function hasPortfolioVerifiedSeedChaseRisk(candidate = {}, profile = {}) {
  const trend = profile?.trendProfile || {};
  const return20d = finiteMetricNumber(trend.return20dPct);
  const return60d = finiteMetricNumber(trend.return60dPct);
  if (trend.trendLabel === "extended_uptrend" || trend.entryBias === "avoid_now") return true;
  if (Number.isFinite(return20d) && return20d > 10) return true;
  if (Number.isFinite(return60d) && return60d > 24) return true;
  if (profile?.actionability?.action === "avoid") return true;
  return hasHighChaseTheme(profile)
    || hasHighChaseTheme(candidate)
    || hasStaleThemeCatchdownRisk(profile)
    || hasStaleThemeCatchdownRisk(candidate);
}

function formatPortfolioSeedStatusReason(status, profile = null) {
  if (!profile) {
    return "待净值下钻确认，先观察，不能仅凭榜单召回标记可买。";
  }
  if (!profile.trendProfile?.ok) {
    return "净值下钻暂不可用，先观察，不标记可买。";
  }
  if (status === "ready") {
    if (profile && hasPortfolioThemeMicroStarterSetup(profile) && !hasVerifiedPortfolioBuySetup(profile)) {
      return hasThemeLowBaseMicroStarterTrendSetup(profile.trendProfile || {})
        ? "已用净值、新闻逻辑、主力线索和持仓承载验证低位主力预热微型试探条件。"
        : "已用净值、新闻逻辑、主力线索和持仓承载验证主线启动微型验证条件。";
    }
    return "已用净值下钻验证低位/回撤证据，且20日、60日涨幅未过热。";
  }
  if (status === "blocked") {
    return "净值下钻显示偏热、等待消化或追涨风险，暂不作为可买候选。";
  }
  const themeWaitingReason = formatPortfolioThemeSeedWaitingReason(profile);
  if (themeWaitingReason) return themeWaitingReason;
  return "净值下钻尚未证明回调完成和低位启动，等待下一轮信号确认。";
}

function formatPortfolioThemeSeedWaitingReason(profile = {}) {
  const theme = selectPortfolioActionableThemeSignal(profile);
  if (!theme || !hasTraceableFreshThemeCatalystContext(theme)) return "";
  const gaps = buildPullbackSetupCandidateGaps(profile, { requireThemeOpportunityBacking: true });
  const firstGap = gaps.find((item) =>
    /前十大|承载|持仓|回调完成|启动前夜|5日\/10日|低位|过热|追涨|费用|份额|净值|数据/.test(item)
  ) || gaps[0] || "";
  const lane = formatPortfolioThemeOpportunityLaneTitle(theme);
  const name = theme.name || theme.id || "相关题材";
  return `${lane}（${name}）已有新闻/资金线索，但${firstGap || "基金买点、持仓承载或费用证据还没过关"}，先观察补证据，不能把题材热度直接当买点。`;
}

function formatPortfolioSeedVerifiedTrendEvidence(profile = null) {
  if (!profile) return "净值验证：待下钻确认";
  const trend = profile.trendProfile || {};
  if (!trend.ok) return `净值验证：${trend.note || profile.error || "走势数据不足"}`;
  return [
    `净值验证：趋势${formatTrendLabel(trend.trendLabel)}`,
    `入场${formatEntryBiasForCandidate(trend.entryBias, profile)}`,
    hasThemeRetreatNoBuyOverride(profile) ? "题材退潮/主力撤离，不能把回调当买点" : "",
    Number.isFinite(Number(trend.return5dPct)) ? `5日${formatFallbackPct(trend.return5dPct)}` : "",
    Number.isFinite(Number(trend.return10dPct)) ? `10日${formatFallbackPct(trend.return10dPct)}` : "",
    Number.isFinite(Number(trend.return20dPct)) ? `20日${formatFallbackPct(trend.return20dPct)}` : "",
    Number.isFinite(Number(trend.return60dPct)) ? `60日${formatFallbackPct(trend.return60dPct)}` : "",
    Number.isFinite(Number(trend.lowPositionPct120)) ? `120日位置${round(Number(trend.lowPositionPct120), 1)}%` : "",
    Number.isFinite(Number(trend.drawdownFromRecentHighPct)) ? `距高点${formatFallbackPct(trend.drawdownFromRecentHighPct)}` : ""
  ].filter(Boolean).join("，");
}

function formatPortfolioFeeVerificationEvidence(profile = {}) {
  const fees = profile?.fees || {};
  const shareClass = fees.shareClass || profile.shareClass || "";
  const feeModel = fees.shareClassFeeModel || profile.shareClassFeeModel || {};
  const impact = fees.feeImpact || profile.feeImpact || {};
  const missing = normalizeStringArray(impact.missingFeeData || fees.missingFeeData);
  const specialAvailability = evaluatePortfolioSpecialShareClassAvailability(profile);
  return [
    "费用验证：",
    shareClass ? `${shareClass}类` : "份额未知",
    feeModel.label || "费用模型未知",
    Number.isFinite(toNumber(impact.oneYearCostPer10000)) ? `每万元1年约${round(toNumber(impact.oneYearCostPer10000), 0)}元` : "",
    specialAvailability.required ? specialAvailability.reason : "",
    missing.length ? `缺失${missing.slice(0, 3).join("/")}` : ""
  ].filter(Boolean).join("，");
}

function scorePortfolioWatchSeedPriority(seedScore, status, seedKind = "") {
  if (status === "blocked") return 5;
  if (status === "ready" && ["主线启动验证候选", "低位主力预热候选", "主力预热代表基金候选"].includes(seedKind)) return 1;
  if (status === "ready" && (seedScore >= 72 || seedKind === "低位启动前夜候选")) return 1;
  if (status === "ready") return 2;
  if (status === "waiting_pullback" && ["主线启动验证候选", "低位主力预热候选", "主力预热代表基金候选"].includes(seedKind)) return 2;
  if (status === "waiting_pullback" && (seedScore >= 64 || seedKind === "低位启动前夜候选")) return 3;
  if (seedScore >= 56) return 4;
  return 4;
}

function formatPortfolioSeedReturnEvidence(candidate = {}) {
  return [
    Number.isFinite(toNumber(candidate.oneWeekPct)) ? `近1周${formatFallbackPct(candidate.oneWeekPct)}` : "",
    Number.isFinite(toNumber(candidate.oneMonthPct)) ? `近1月${formatFallbackPct(candidate.oneMonthPct)}` : "",
    Number.isFinite(toNumber(candidate.threeMonthPct)) ? `近3月${formatFallbackPct(candidate.threeMonthPct)}` : "",
    Number.isFinite(toNumber(candidate.sixMonthPct)) ? `近6月${formatFallbackPct(candidate.sixMonthPct)}` : ""
  ].filter(Boolean).join("，");
}

function formatPortfolioSeedThemeEvidence(candidate = {}) {
  const theme = (candidate.matchedThemes || [])[0];
  if (!theme) return "";
  return [
    `题材${theme.name || ""}`,
    isFreshActionableThemeSupportForCandidate(candidate, theme) ? "可跟踪题材支撑" : "",
    theme.leaderSignal === "capital_entering" || theme.positionSignal === "main_capital_entering" ? "主力进场" : "",
    theme.leaderSignal === "preheat_catalyst" || theme.positionSignal === "preheat_catalyst_watch" ? "题材预热" : "",
    theme.positionSignal === "low_position_rotation" ? "低位轮动" : "",
    isStaleThemeCatchdownRiskTheme(theme) ? "接盘风险" : "",
    theme.positionSignal === "acceptable_position" ? "位置尚可" : "",
    Number.isFinite(Number(theme.capitalFollowScore)) ? `主力${round(Number(theme.capitalFollowScore), 1)}` : "",
    Number.isFinite(Number(theme.preheatScore)) ? `预热${round(Number(theme.preheatScore), 1)}` : "",
    Number.isFinite(Number(theme.rotationScore)) ? `轮动${round(Number(theme.rotationScore), 1)}` : "",
    Number.isFinite(Number(theme.lowPositionScore)) ? `低位${round(Number(theme.lowPositionScore), 1)}` : "",
    Number.isFinite(Number(theme.capitalRetreatScore)) ? `退潮${round(Number(theme.capitalRetreatScore), 1)}` : "",
    Number.isFinite(Number(theme.crowdingScore)) ? `拥挤${round(Number(theme.crowdingScore), 1)}` : ""
  ].filter(Boolean).join("，");
}

function compactPortfolioSeedCandidateForModel(candidate = {}) {
  return {
    code: candidate.code || "",
    name: candidate.name || "",
    shareClass: candidate.shareClass || "",
    type: candidate.type || "",
    score: candidate.portfolioWatchlistSeedScore ?? null,
    oneWeekPct: candidate.oneWeekPct ?? "",
    oneMonthPct: candidate.oneMonthPct ?? "",
    threeMonthPct: candidate.threeMonthPct ?? "",
    sixMonthPct: candidate.sixMonthPct ?? "",
    oneYearPct: candidate.oneYearPct ?? "",
    keywords: (candidate.keywords || []).slice(0, 8),
    matchedThemes: candidate.matchedThemes || [],
    themeSupport: hasFreshActionableThemeSupport(candidate) ? "主力/预热/低位轮动支撑" : "",
    themeRisk: hasStaleThemeCatchdownRisk(candidate)
      ? getStaleThemeCatchdownWarnings(candidate)[0] || "题材退潮或主力撤离，回调不能当买点"
      : "",
    setupDiscoverySource: candidate.setupDiscoverySource || "",
    source: candidate.source || ""
  };
}

function inferPortfolioWatchStatusFromAction(action = {}) {
  if (action.action === "BUY") return "in_position";
  const text = [
    action.reason,
    action.rotationCheck,
    action.positionCheck,
    action.chaseRisk,
    action.riskControl
  ].filter(Boolean).join(" ");
  if (/(回避|不买|过热|偏热|追涨|拥挤|风险高|不符合)/.test(text)) return "blocked";
  if (/(等待|等回撤|等回调|回踩|回撤|回调)/.test(text)) return "waiting_pullback";
  if (/(可买|分批|低位|启动|回调完成|修复|轮动)/.test(text)) return "ready";
  return "watch";
}

function mergePortfolioProfiles(...groups) {
  const byCode = new Map();
  for (const profile of groups.flat().filter(Boolean)) {
    if (profile.code) byCode.set(profile.code, profile);
  }
  return [...byCode.values()];
}

function enforcePortfolioRiskBudget(actions = [], account = {}, profiles = []) {
  const normalized = normalizePortfolioActions(actions);
  const riskActions = buildPortfolioRiskBudgetActions(account, profiles);
  if (!riskActions.length) return normalized;

  const merged = [...normalized];
  for (const riskAction of riskActions) {
    const index = merged.findIndex((action) => action.code && action.code === riskAction.code);
    if (index < 0) {
      merged.push(riskAction);
      continue;
    }
    const current = merged[index];
    const currentTarget = Number.isFinite(Number(current.targetWeightPct)) ? Number(current.targetWeightPct) : 0;
    const riskTarget = Number.isFinite(Number(riskAction.targetWeightPct)) ? Number(riskAction.targetWeightPct) : 0;
    merged[index] = {
      ...current,
      ...riskAction,
      action: "SELL",
      amount: Math.max(Number(current.amount || 0), Number(riskAction.amount || 0)),
      targetWeightPct: Math.min(currentTarget, riskTarget),
      reason: [riskAction.reason, current.reason].filter(Boolean).join(" "),
      dataBasis: mergeStringLists(current.dataBasis, riskAction.dataBasis, ["来源：portfolio_risk_budget_guard"]),
      rotationCheck: current.rotationCheck || riskAction.rotationCheck,
      positionCheck: current.positionCheck || riskAction.positionCheck,
      chaseRisk: [current.chaseRisk, riskAction.chaseRisk].filter(Boolean).join("；"),
      feeCheck: current.feeCheck || riskAction.feeCheck,
      riskControl: [riskAction.riskControl, current.riskControl].filter(Boolean).join(" ")
    };
  }
  return merged.slice(0, 10);
}

function buildPortfolioRiskBudgetActions(account = {}, profiles = []) {
  const positions = Array.isArray(account.positions) ? account.positions : [];
  if (!positions.length) return [];
  const accountBudget = buildPortfolioAccountRiskBudget(account);
  const profileByCode = new Map((profiles || []).filter(Boolean).map((profile) => [profile.code, profile]));
  const byCode = new Map();
  const addRiskAction = (position, reason, dataBasis, options = {}) => {
    if (!position?.code || Number(position.currentValue || 0) <= 0) return;
    const existing = byCode.get(position.code);
    const action = {
      action: "SELL",
      code: position.code,
      name: position.name || profileByCode.get(position.code)?.name || "",
      amount: round(Number(position.currentValue || 0), 2),
      targetWeightPct: 0,
      reason,
      dataBasis: mergeStringLists(dataBasis, [`持仓市值 ${round(Number(position.currentValue || 0), 2)}元`], ["来源：portfolio_risk_budget_guard"]),
      rotationCheck: "风控优先于轮动加仓，先降低回撤暴露。",
      positionCheck: options.positionCheck || "触发组合风控复核",
      chaseRisk: options.chaseRisk || "回撤预算触发，暂停追涨和新增风险。",
      feeCheck: "赎回费按平台实际规则复核；系统只提交分批赎回计划。",
      riskControl: options.riskControl || "先按系统卖出上限分批降风险，下一轮继续复核是否追加。"
    };
    if (!existing) {
      byCode.set(position.code, action);
      return;
    }
    byCode.set(position.code, {
      ...existing,
      reason: [existing.reason, reason].filter(Boolean).join(" "),
      dataBasis: mergeStringLists(existing.dataBasis, action.dataBasis),
      positionCheck: [existing.positionCheck, action.positionCheck].filter(Boolean).join("；"),
      chaseRisk: [existing.chaseRisk, action.chaseRisk].filter(Boolean).join("；"),
      riskControl: [existing.riskControl, action.riskControl].filter(Boolean).join(" ")
    });
  };

  if (accountBudget.reduceRisk) {
    const ordered = [...positions].sort((a, b) => Number(b.weightPct || 0) - Number(a.weightPct || 0));
    for (const position of ordered.slice(0, 5)) {
      addRiskAction(
        position,
        `系统账户回撤控制：组合距峰值回撤${formatFallbackPct(accountBudget.drawdownFromPeakPct)}，已超过${accountBudget.maxDrawdownPct}%预算，必须分批降风险。`,
        [
          `账户峰值 ${accountBudget.peakTotalAsset}元`,
          `账户回撤 ${formatFallbackPct(accountBudget.drawdownFromPeakPct)}`,
          `最大回撤预算 ${accountBudget.maxDrawdownPct}%`
        ],
        {
          positionCheck: "账户级最大回撤预算触发",
          chaseRisk: "账户回撤超预算，所有新增买入暂停，优先降低仓位。",
          riskControl: "账户级回撤超预算，本轮只允许风控减仓或持有复核，不允许新增风险。"
        }
      );
    }
  }

  const exposureSummary = buildPortfolioExposureSummary(positions);
  const exposureCandidates = selectPortfolioExposureRiskReductionCandidates(positions, profileByCode, exposureSummary);
  for (const candidate of exposureCandidates) {
    addRiskAction(
      candidate.position,
      `系统组合集中度控制：${candidate.reason}，先分批降低同题材暴露。`,
      candidate.dataBasis,
      {
        positionCheck: "组合穿透暴露过高",
        chaseRisk: "同题材和底层持仓重叠偏高，不能继续把新闻热度当成持有理由。",
        riskControl: "先按系统卖出上限分批降温；若下一次复核低位轮动证据恢复，再评估保留剩余仓位。"
      }
    );
  }

  for (const position of positions) {
    const profile = profileByCode.get(position.code);
    const positionBudget = buildPortfolioPositionRiskBudget(position, profile);
    if (!positionBudget.reduceRisk) continue;
    addRiskAction(
      position,
      `系统单仓回撤控制：${positionBudget.triggers.slice(0, 2).join("；")}。`,
      [
        `单仓浮盈亏 ${formatFallbackPct(positionBudget.unrealizedPnlPct)}`,
        `历史浮盈峰值 ${formatFallbackPct(positionBudget.peakUnrealizedPnlPct)}`,
        `浮盈回吐 ${formatFallbackPct(-positionBudget.profitGivebackPct)}`
      ],
      {
        positionCheck: positionBudget.level === "severe" ? "单仓止损线触发" : "浮盈回吐保护触发",
        chaseRisk: "单仓风险触发，禁止用加仓摊薄替代止损或止盈。",
        riskControl: positionBudget.level === "severe"
          ? "先按严重风险上限纪律性减仓；若下一次复核仍低于止损线，继续追加。"
          : "先分批锁定部分利润；若重新转强再评估是否保留剩余仓位。"
      }
    );
  }

  return [...byCode.values()];
}

function selectPortfolioExposureRiskReductionCandidates(positions = [], profileByCode = new Map(), exposureSummary = {}) {
  const topTheme = exposureSummary.themeClusters?.[0] || null;
  const repeated = exposureSummary.overlappingHoldings?.[0] || null;
  const severeTheme = topTheme && Number(topTheme.positionWeightPct || 0) >= 25;
  const severeOverlap = repeated && Number(repeated.fundCount || 0) >= 3;
  if (exposureSummary.riskLevel !== "high" || (!severeTheme && !severeOverlap)) return [];
  const riskNote = normalizeStringArray(exposureSummary.riskNotes)[0] || "同题材暴露过度集中";
  return (positions || [])
    .filter((position) => position?.code && Number(position.currentValue || 0) > 0)
    .map((position) => {
      const profile = profileByCode.get(position.code) || position.fundSnapshot || {};
      const themeHit = severeTheme && doesPortfolioPositionMatchTheme(position, topTheme.theme);
      const overlapHit = severeOverlap && doesPortfolioPositionHoldRepeatedUnderlying(position, repeated);
      if (!themeHit && !overlapHit) return null;
      const trend = profile.trendProfile || position.fundSnapshot?.trendProfile || {};
      const actionability = profile.actionability || position.fundSnapshot?.actionability || {};
      const hotScore = trend.trendLabel === "extended_uptrend" || trend.entryBias === "wait_pullback" ? 10 : 0;
      const actionScore = ["wait", "avoid"].includes(actionability.action) ? 10 : 0;
      const givebackScore = Math.min(10, Math.max(0, Number(position.profitGivebackPct || 0)));
      const lossScore = Number(position.unrealizedPnlPct || 0) < 0 ? 4 : 0;
      const weightScore = Number(position.weightPct || 0);
      const repeatedLabel = repeated ? [repeated.code, repeated.name].filter(Boolean).join(" ") : "";
      return {
        position,
        score: weightScore + hotScore + actionScore + givebackScore + lossScore,
        reason: [
          severeTheme ? `同题材暴露${topTheme.theme}约${formatFallbackPlainPct(topTheme.positionWeightPct)}` : "",
          severeOverlap ? `底层重叠${repeatedLabel || "重复持仓"}涉及${repeated.fundCount}只基金` : "",
          riskNote
        ].filter(Boolean).join("；"),
        dataBasis: [
          "来源：portfolio_exposure_concentration_guard",
          severeTheme ? `同题材暴露 ${topTheme.theme} ${formatFallbackPlainPct(topTheme.positionWeightPct)}` : "",
          severeOverlap ? `底层重叠 ${repeatedLabel || "重复持仓"} ${repeated.fundCount}只基金` : "",
          `持仓标签 ${collectPortfolioPositionThemeTags(position).join("/") || "未识别"}`,
          Number.isFinite(Number(position.profitGivebackPct)) ? `浮盈回吐 ${round(Number(position.profitGivebackPct), 2)}pct` : ""
        ].filter(Boolean)
      };
    })
    .filter(Boolean)
    .sort((a, b) => Number(b.score || 0) - Number(a.score || 0))
    .slice(0, 2);
}

function doesPortfolioPositionMatchTheme(position = {}, theme = "") {
  const target = String(theme || "").trim();
  if (!target) return false;
  return collectPortfolioPositionThemeTags(position).some((tag) => areThemeTermsRelated(tag, target));
}

function doesPortfolioPositionHoldRepeatedUnderlying(position = {}, repeated = {}) {
  const targetCode = String(repeated?.code || "").trim();
  const targetName = String(repeated?.name || "").trim();
  if (!targetCode && !targetName) return false;
  return collectPortfolioPositionHoldingItems(position).some((holding) => {
    return (targetCode && String(holding.code || "").trim() === targetCode)
      || (targetName && String(holding.name || "").trim() === targetName);
  });
}

function buildPortfolioAccountRiskBudget(account = {}) {
  const totalAsset = round(Number(account.totalAsset || 0), 2) || 0;
  const peakTotalAsset = round(Number(account.peakTotalAsset || account.initialCapital || totalAsset), 2) || totalAsset;
  const derivedDrawdownFromPeakPct = peakTotalAsset > 0 ? round((totalAsset / peakTotalAsset - 1) * 100, 2) : null;
  const drawdownFromPeakPct = Number.isFinite(Number(derivedDrawdownFromPeakPct))
    ? derivedDrawdownFromPeakPct
    : (Number.isFinite(Number(account.drawdownFromPeakPct)) ? round(Number(account.drawdownFromPeakPct), 2) : 0);
  const drawdownAbs = Math.abs(Math.min(0, Number(drawdownFromPeakPct || 0)));
  const warningThresholdPct = Math.abs(finiteNumberOr(process.env.PORTFOLIO_ACCOUNT_DRAWDOWN_WARN_PCT, 3));
  const maxDrawdownPct = Math.abs(finiteNumberOr(process.env.PORTFOLIO_MAX_ACCOUNT_DRAWDOWN_PCT, 6));
  const severeDrawdownPct = Math.abs(finiteNumberOr(process.env.PORTFOLIO_SEVERE_ACCOUNT_DRAWDOWN_PCT, 9));
  const level = drawdownAbs >= severeDrawdownPct
    ? "severe"
    : drawdownAbs >= maxDrawdownPct
      ? "breached"
      : drawdownAbs >= warningThresholdPct
        ? "warning"
        : "normal";
  return {
    level,
    label: {
      normal: "回撤正常",
      warning: "回撤预警",
      breached: "回撤超预算",
      severe: "严重回撤"
    }[level],
    totalAsset,
    peakTotalAsset,
    drawdownFromPeakPct,
    warningThresholdPct,
    maxDrawdownPct,
    severeDrawdownPct,
    blockNewBuys: ["breached", "severe"].includes(level),
    reduceRisk: ["breached", "severe"].includes(level),
    throttleNewBuys: level === "warning"
  };
}

function buildPortfolioPositionRiskBudget(position = {}, profile = null) {
  const unrealizedPnlPct = finiteMetricNumber(position.unrealizedPnlPct);
  const peakUnrealizedPnlPct = finiteMetricNumber(position.peakUnrealizedPnlPct);
  const profitGivebackPct = Number.isFinite(peakUnrealizedPnlPct) && Number.isFinite(unrealizedPnlPct)
    ? Math.max(0, round(peakUnrealizedPnlPct - unrealizedPnlPct, 2))
    : 0;
  const stopLossPct = Math.abs(finiteNumberOr(process.env.PORTFOLIO_POSITION_STOP_LOSS_PCT, 8));
  const profitProtectionStartPct = Math.abs(finiteNumberOr(process.env.PORTFOLIO_PROFIT_PROTECTION_START_PCT, 8));
  const profitGivebackLimitPct = Math.abs(finiteNumberOr(process.env.PORTFOLIO_PROFIT_GIVEBACK_PCT, 4));
  const trend = profile?.trendProfile || position.fundSnapshot?.trendProfile || {};
  const trendDrawdown = finiteMetricNumber(trend.drawdownFromRecentHighPct);
  const themeSource = profile || position.fundSnapshot || {};
  const themeRetreatWarnings = [
    ...getPortfolioHoldingThemeRetreatWarnings(themeSource),
    ...getCandidateThemeRetreatWarnings(themeSource),
    ...getStaleThemeCatchdownWarnings(themeSource)
  ];
  const triggers = [];

  if (Number.isFinite(unrealizedPnlPct) && unrealizedPnlPct <= -stopLossPct) {
    triggers.push(`浮亏${formatFallbackPct(unrealizedPnlPct)}触及${stopLossPct}%单仓止损线`);
  }
  if (
    Number.isFinite(peakUnrealizedPnlPct)
    && Number.isFinite(unrealizedPnlPct)
    && peakUnrealizedPnlPct >= profitProtectionStartPct
    && profitGivebackPct >= profitGivebackLimitPct
  ) {
    triggers.push(`曾浮盈${formatFallbackPct(peakUnrealizedPnlPct)}，已回吐${round(profitGivebackPct, 2)}个百分点`);
  }
  if (
    Number.isFinite(peakUnrealizedPnlPct)
    && Number.isFinite(unrealizedPnlPct)
    && peakUnrealizedPnlPct > 2
    && unrealizedPnlPct < 0
    && profitGivebackPct >= profitGivebackLimitPct
  ) {
    triggers.push(`曾浮盈${formatFallbackPct(peakUnrealizedPnlPct)}但当前转亏${formatFallbackPct(unrealizedPnlPct)}，需要回吐保护`);
  }
  if (Number.isFinite(trendDrawdown) && trendDrawdown <= -12 && ["breakdown", "weakening"].includes(trend.trendLabel)) {
    triggers.push(`走势${formatTrendLabel(trend.trendLabel)}且距高点${formatFallbackPct(trendDrawdown)}`);
  }
  triggers.push(...themeRetreatWarnings.slice(0, 2));

  const level = triggers.some((item) => /止损|破位/.test(item)) ? "severe" : triggers.length ? "warning" : "normal";
  return {
    level,
    label: {
      normal: "正常",
      warning: "需减仓复核",
      severe: "止损风险"
    }[level],
    reduceRisk: triggers.length > 0,
    unrealizedPnlPct,
    peakUnrealizedPnlPct,
    profitGivebackPct,
    stopLossPct,
    profitProtectionStartPct,
    profitGivebackLimitPct,
    triggers
  };
}

function enforcePortfolioBuyDiscipline(actions = [], profiles = [], positions = [], account = null) {
  const profileByCode = new Map((profiles || []).filter(Boolean).map((profile) => [profile.code, profile]));
  return normalizePortfolioActions(actions).map((action) => {
    if (action.action !== "BUY") return action;
    const guard = evaluatePortfolioBuyDiscipline(action, profileByCode.get(action.code), positions, account);
    if (guard.ok) return action;
    const rankingBoardSourced = isPortfolioRankingBoardSourcedAction(action);
    const rankingBlockReason = rankingBoardSourced
      ? "系统榜单二次校验：榜单只负责把机会抬出来，执行层按净值、题材退潮/接盘风险、底层持仓、费用和仓位重新拦截为0元观察。"
      : "";
    return {
      ...action,
      action: "WATCH",
      amount: 0,
      targetWeightPct: 0,
      reason: [action.reason, guard.reason, rankingBlockReason].filter(Boolean).join(" "),
      dataBasis: mergeStringLists(
        action.dataBasis,
        guard.evidence,
        ["来源：portfolio_buy_discipline_guard"],
        rankingBoardSourced ? ["来源：ranking_board_buy_execution_guard"] : []
      ),
      chaseRisk: [action.chaseRisk, guard.reason].filter(Boolean).join("；"),
      riskControl: formatPortfolioBlockedBuyRiskControl(action, rankingBoardSourced)
    };
  });
}

function isPortfolioRankingBoardSourcedAction(action = {}) {
  const text = [
    action.rankingBasis,
    action.source,
    action.reason,
    action.riskControl,
    ...(Array.isArray(action.dataBasis) ? action.dataBasis : [])
  ].filter(Boolean).join(" ");
  return /manager_ranking_board|系统榜单升级|经理榜单|榜单/.test(text);
}

function formatPortfolioBlockedBuyRiskControl(action = {}, rankingBoardSourced = false) {
  const fallback = "本轮不提交虚拟申购，下一次盘前复核低位/回调/拥挤度证据。";
  if (!rankingBoardSourced) {
    const current = String(action.riskControl || "");
    return current && !/(买入|申购|建仓|试探|加仓)/.test(current) ? current : fallback;
  }
  return "榜单机会本轮只保留为0元观察；等主力资金回流、新闻催化保持新鲜、代表持仓止跌并完成净值/费用复核后，再允许重新进入小仓复核。";
}

function evaluatePortfolioBuyDiscipline(action = {}, profile = null, positions = [], account = null) {
  if (!action.code) {
    return {
      ok: false,
      reason: "系统买入纪律拦截：缺少基金代码，不能提交虚拟申购。",
      evidence: []
    };
  }
  if (account) {
    const accountBudget = buildPortfolioAccountRiskBudget(account);
    if (accountBudget.blockNewBuys) {
      return {
        ok: false,
        reason: `系统买入纪律拦截：账户距峰值回撤${formatFallbackPct(accountBudget.drawdownFromPeakPct)}，已超过${accountBudget.maxDrawdownPct}%最大回撤预算，暂停新增买入。`,
        evidence: [
          `账户峰值 ${accountBudget.peakTotalAsset}元`,
          `账户回撤 ${formatFallbackPct(accountBudget.drawdownFromPeakPct)}`,
          "来源：portfolio_account_drawdown_guard"
        ]
      };
    }
  }
  if (!profile) {
    return {
      ok: false,
      reason: "系统买入纪律拦截：缺少联网补全资料，不能提交虚拟申购。",
      evidence: []
    };
  }
  const nav = getProfileNav(profile);
  if (!nav) {
    return {
      ok: false,
      reason: "系统买入纪律拦截：缺少可验证单位净值，不能提交虚拟申购。",
      evidence: [profile.error || ""].filter(Boolean)
    };
  }
  const trend = profile.trendProfile || {};
  if (!trend.ok) {
    return {
      ok: false,
      reason: "系统买入纪律拦截：缺少可验证走势、回调和低位证据，不能提交虚拟申购。",
      evidence: [trend.note || profile.error || ""].filter(Boolean)
    };
  }
  const trendEvidence = formatPortfolioSeedVerifiedTrendEvidence(profile);
  const themeMicroStarter = hasPortfolioThemeMicroStarterSetup(profile);
  const textualCatchdownWarnings = getTextualCatchdownWarnings(action, profile);
  if (textualCatchdownWarnings.length) {
    return {
      ok: false,
      reason: `系统买入纪律拦截：${textualCatchdownWarnings[0]}`,
      evidence: [trendEvidence, textualCatchdownWarnings[0], "来源：portfolio_text_catchdown_guard"].filter(Boolean)
    };
  }
  const themeSupportGap = getPortfolioActionableThemeSupportGap(profile);
  if (themeSupportGap) {
    return {
      ok: false,
      reason: `系统买入纪律拦截：${themeSupportGap}`,
      evidence: [trendEvidence, formatCandidateThemeEvidence(profile), formatHoldingsOutlookEvidence(profile), "来源：portfolio_theme_support_guard"].filter(Boolean)
    };
  }
  const holdingRealtimeWarning = getHoldingRealtimeCatchdownWarning(profile);
  if (holdingRealtimeWarning) {
    return {
      ok: false,
      reason: `系统买入纪律拦截：${holdingRealtimeWarning}`,
      evidence: [trendEvidence, holdingRealtimeWarning, "来源：portfolio_holding_realtime_guard"].filter(Boolean)
    };
  }
  if (hasPortfolioVerifiedSeedChaseRisk(action, profile)
    || trend.entryBias === "wait_pullback"
    || trend.entryBias === "avoid_now"
    || profile.actionability?.action === "wait"
    || profile.actionability?.action === "avoid") {
    if (!themeMicroStarter) {
      return {
        ok: false,
        reason: "系统买入纪律拦截：净值下钻显示偏热、等待回撤或追涨风险，不能提交虚拟申购。",
        evidence: [trendEvidence]
      };
    }
  }
  const structuralHardGap = buildPortfolioWatchStructuralReadinessGaps(
    { code: action.code, name: action.name || profile.name || "", status: "ready" },
    profile
  ).find(isPortfolioRedeploymentHardGap);
  if (structuralHardGap) {
    return {
      ok: false,
      reason: `系统买入纪律拦截：${structuralHardGap}`,
      evidence: [trendEvidence, structuralHardGap]
    };
  }
  if (!hasVerifiedPortfolioBuySetup(profile)) {
    if (!hasPortfolioStarterBuySetup(profile) && !themeMicroStarter) {
      return {
        ok: false,
        reason: "系统买入纪律拦截：缺少回调完成/启动前夜、5日/10日刚转强和低位证据，不能提交虚拟申购。",
        evidence: [trendEvidence]
      };
    }
  }
  const feeEvidence = formatPortfolioFeeVerificationEvidence(profile);
  const specialAvailability = evaluatePortfolioSpecialShareClassAvailability(profile);
  if (specialAvailability.required && !specialAvailability.ok) {
    return {
      ok: false,
      reason: "系统买入纪律拦截：D/I/Y等特殊或平台份额缺少可申购渠道、起购门槛或申购规则验证，不能提交虚拟申购。",
      evidence: [trendEvidence, feeEvidence, ...specialAvailability.evidence].filter(Boolean)
    };
  }
  if (!hasVerifiedPortfolioFeeEvidence(profile)) {
    return {
      ok: false,
      reason: "系统买入纪律拦截：缺少可验证费用/份额证据，不能提交虚拟申购。",
      evidence: [trendEvidence, feeEvidence].filter(Boolean)
    };
  }
  const exposureGuard = evaluatePortfolioBuyExposureDiscipline(action, profile, positions);
  if (!exposureGuard.ok) {
    return {
      ok: false,
      reason: exposureGuard.reason,
      evidence: [trendEvidence, feeEvidence, ...exposureGuard.evidence].filter(Boolean)
    };
  }
  if (hasPortfolioStarterBuySetup(profile)) {
    return {
      ok: true,
      reason: "系统买入纪律确认：低位回调已满足，小仓启动试探可执行，但仍需控制在卫星仓。",
      evidence: [trendEvidence, feeEvidence, "来源：portfolio_starter_buy_guard"].filter(Boolean)
    };
  }
  if (themeMicroStarter) {
    return {
      ok: true,
      reason: formatPortfolioThemeMicroStarterBuyReason(profile),
      evidence: [trendEvidence, formatCandidateThemeEvidence(profile), feeEvidence, "来源：portfolio_theme_micro_starter_guard"].filter(Boolean)
    };
  }
  return { ok: true, reason: "", evidence: [trendEvidence, feeEvidence].filter(Boolean) };
}

function formatPortfolioThemeMicroStarterBuyReason(profile = {}) {
  const trend = profile?.trendProfile || {};
  if (!hasThemeLowBaseMicroStarterTrendSetup(trend) && hasThemeLaunchProbeTrendSetup(trend)) {
    return "系统买入纪律确认：题材有主力进场/预热催化，基金能承载主线且尚未过热，只允许微型验证仓跟随，不允许重仓追随。";
  }
  return "系统买入纪律确认：题材有主力进场/预热催化，基金处在低位温和转强，只允许微型试探仓验证，不允许重仓追随。";
}

function evaluatePortfolioBuyExposureDiscipline(action = {}, profile = null, positions = []) {
  const exposureKey = getPortfolioExposureKey(profile || action);
  if (!exposureKey) return { ok: true, reason: "", evidence: [] };
  const sameExposure = findPortfolioSameExposurePositions(positions, exposureKey, action.code);
  const sameExposureValue = sameExposure.reduce((sum, position) => sum + Number(position.currentValue || 0), 0);
  if (sameExposureValue <= 0) return { ok: true, reason: "", evidence: [] };
  const evidence = [
    `同类暴露：${exposureKey}`,
    `已有同类持仓：${sameExposure.map((item) => `${item.code} ${item.name || ""} ${round(Number(item.currentValue || 0), 2)}元`).join("；")}`
  ];
  if (sameExposure.length >= finiteNumberOr(process.env.PORTFOLIO_BUY_MAX_SAME_EXPOSURE_FUNDS, 1)) {
    return {
      ok: false,
      reason: "系统买入纪律拦截：组合中已有同一指数/同主题暴露，不能用另一只基金重复买入；应复核原持仓或替代份额。",
      evidence
    };
  }
  return { ok: true, reason: "", evidence };
}

function getPortfolioActionableThemeSupportGap(candidate = {}) {
  const themeSignals = getCandidateThemeSignals(candidate);
  const textualCatchdownWarnings = getTextualCatchdownWarnings(candidate);
  if (textualCatchdownWarnings.length) return textualCatchdownWarnings[0];
  const directHoldingThemeRetreatWarning = getDirectPortfolioHoldingThemeRetreatWarnings(candidate)[0];
  if (directHoldingThemeRetreatWarning) return directHoldingThemeRetreatWarning;
  const playbookRiskWarnings = getThemeMainForcePlaybookRiskWarnings(candidate);
  if (playbookRiskWarnings.length) return playbookRiskWarnings[0];
  const catchdownWarnings = getStaleThemeCatchdownWarnings(candidate);
  if (catchdownWarnings.length) return catchdownWarnings[0];
  const unconfirmedWarnings = getUnrefreshedMarketThemeWarnings(candidate);
  if (unconfirmedWarnings.length) return unconfirmedWarnings[0];
  const staleCatalystWarnings = getStaleCatalystThemeWarnings(candidate);
  if (staleCatalystWarnings.length) return staleCatalystWarnings[0];
  const staleThemeRefreshWarnings = getStalePortfolioThemeRefreshWarnings(candidate);
  if (staleThemeRefreshWarnings.length) return staleThemeRefreshWarnings[0];
  const holdingThemeGap = getPortfolioHoldingThemeSupportGap(candidate);
  if (holdingThemeGap) return holdingThemeGap;
  if (!themeSignals.length) {
    if (hasPortfolioCurrentThemeRadarSupport(candidate)) return "";
    const requiredTheme = getPortfolioThemeSupportRequirement(candidate);
    if (requiredTheme) {
      return `基金名称/标签显示为${requiredTheme}方向，但当前题材雷达没有确认当前主力进场、题材预热或低位轮动支撑，不能只凭走势当启动买点。`;
    }
    return "";
  }
  if (hasFreshActionableThemeSupport(candidate)) return "";
  if (hasActionableThemeSupport(candidate)) {
    return "低位轮动标签缺少当前题材雷达刷新，不能只凭旧标签和净值回调做买入准备。";
  }
  return "缺少当前主力进场、题材预热或低位轮动支撑，不能把回调当成启动买点。";
}

function getUnrefreshedMarketThemeWarnings(candidate = {}) {
  return getCandidateThemeSignals(candidate)
    .filter(isUnrefreshedMarketThemeSignal)
    .map((theme) => {
      const name = theme.name || theme.id || "相关题材";
      return `${name}旧题材线索未被当前题材雷达确认，不能拿历史热点、旧新闻或旧主力标签当今天的买入依据。`;
    })
    .slice(0, 3);
}

function getStaleCatalystThemeWarnings(candidate = {}) {
  return getCandidateThemeSignals(candidate)
    .filter((theme) =>
      theme?.catalystProfile?.fresh === false
      && !isUnrefreshedMarketThemeSignal(theme)
    )
    .map((theme) => {
      const name = theme.name || theme.id || "相关题材";
      const freshness = theme.catalystProfile?.freshnessLabel ? `（${theme.catalystProfile.freshnessLabel}）` : "";
      return `${name}只有旧新闻/旧催化${freshness}，没有新的新闻时事或主力接力确认，不能把低位回调当今天的买点。`;
    })
    .slice(0, 3);
}

function getTextualCatchdownWarnings(...sources) {
  const seen = new Set();
  const segments = sources
    .flatMap((source) => collectPortfolioCatchdownTextSegments(source, seen))
    .map((text) => String(text || "").replace(/\s+/g, " ").trim())
    .filter(Boolean);
  const unconfirmedOldTheme = segments.find(isTextualUnconfirmedThemeRiskSegment);
  if (unconfirmedOldTheme) {
    return [`文本证据显示旧题材未被当前题材雷达确认，不能拿历史热点、旧新闻或旧主力标签当今天的买入依据：${formatTextualUnconfirmedThemeRiskEvidence(unconfirmedOldTheme)}`];
  }
  const risky = segments.find(isTextualCatchdownRiskSegment);
  if (!risky) return [];
  return [`文本证据显示题材退潮、主力撤离或接盘风险，不能把回调当买点：${shortenPortfolioCustomerText(risky, 96)}`];
}

function collectPortfolioCatchdownTextSegments(value, seen = new Set()) {
  if (value === null || value === undefined) return [];
  if (typeof value === "string") return [value];
  if (typeof value !== "object") return [];
  if (seen.has(value)) return [];
  seen.add(value);
  const keys = [
    "reason",
    "riskControl",
    "chaseRisk",
    "positionCheck",
    "rotationCheck",
    "trendSummary",
    "newsLogic",
    "primaryCatalyst",
    "source",
    "statusText",
    "reviewDate"
  ];
  const arrayKeys = [
    "riskNotes",
    "readinessGaps",
    "setupEvidence",
    "buyTriggers",
    "dataBasis",
    "learningNotes",
    "decisiveEvidence",
    "decisionBlocker",
    "risks",
    "gaps"
  ];
  const nestedKeys = ["actionability", "holdingsOutlook", "marketThemeRefresh", "holdingThemeRefresh", "trendProfile", "seed"];
  const segments = [];
  for (const key of keys) {
    if (typeof value[key] === "string") segments.push(value[key]);
  }
  for (const key of arrayKeys) {
    if (Array.isArray(value[key])) segments.push(...value[key].filter((item) => typeof item === "string"));
  }
  if (value.decision && typeof value.decision === "object") {
    segments.push(...collectPortfolioCatchdownTextSegments(value.decision, seen));
  }
  for (const key of nestedKeys) {
    if (value[key] && typeof value[key] === "object") {
      segments.push(...collectPortfolioCatchdownTextSegments(value[key], seen));
    }
  }
  return segments;
}

function isTextualCatchdownRiskSegment(text = "") {
  const value = String(text || "");
  if (!value) return false;
  if (/(?:暂无|没有|未见|无明显|已解除|风险解除|解除接盘|不构成).{0,16}(?:接盘|退潮|主力撤离|资金撤离|资金流出)|(?:已被|已经被|当前题材雷达(?:已|已经)).{0,12}(?:确认|验证)/.test(value)) {
    return false;
  }
  return /退潮接盘|接盘风险|题材退潮|主力资金撤离|主力撤离|资金撤离|资金流出|回调(?:不是|不作为|不能当|不能作为)买点|不能把回调当(?:成)?买点|表面回调可能继续下探|前十大持仓盘中明显走弱|底层持仓(?:盘中)?(?:明显)?走弱|底层持仓止跌|持仓实时降级/.test(value)
    || isTextualUnconfirmedThemeRiskSegment(value);
}

function isTextualUnconfirmedThemeRiskSegment(text = "") {
  const value = String(text || "");
  if (!value) return false;
  if (/(?:已被|已经被|当前题材雷达(?:已|已经)).{0,12}(?:确认|验证)|(?:未确认|旧题材|历史热点).{0,16}(?:已解除|风险解除|不构成)/.test(value)) {
    return false;
  }
  return /(?:旧题材|旧主力标签|历史热点|旧新闻|旧催化).{0,48}(?:未被|未获|没有|未重新|未通过).{0,32}(?:当前题材雷达|当前雷达|当天题材雷达|今日题材雷达).{0,16}(?:确认|验证)|(?:当前题材雷达|当前雷达|当天题材雷达|今日题材雷达).{0,20}(?:未确认|没有确认|未重新确认|未获确认).{0,48}(?:旧题材|旧主力标签|历史热点|旧新闻|旧催化)|(?:旧题材线索)?未被当前题材雷达确认|(?=.*(?:当前题材雷达|当前雷达))(?=.*(?:未被|未确认|未重新确认|未获确认))(?=.*(?:旧题材|旧主力标签|历史热点|旧新闻|旧催化))/.test(value);
}

function formatTextualUnconfirmedThemeRiskEvidence(text = "") {
  const value = String(text || "");
  const labels = [];
  if (/历史热点/.test(value)) labels.push("历史热点");
  if (/旧主力标签|旧主力/.test(value)) labels.push("旧主力标签");
  if (/旧新闻|旧催化/.test(value)) labels.push("旧新闻/旧催化");
  if (/旧题材/.test(value)) labels.push("旧题材线索");
  const label = [...new Set(labels)].slice(0, 3).join("、") || "旧题材线索";
  return `${label}缺少当前题材雷达确认`;
}

function getPortfolioWatchThemeSupportGap(item = {}, evidence = null) {
  const profile = evidence || item.lastSnapshot || {};
  return getPortfolioActionableThemeSupportGap({
    ...profile,
    code: profile.code || item.code || "",
    name: profile.name || item.name || "",
    type: profile.type || item.type || "",
    matchedThemes: profile.matchedThemes || item.matchedThemes || [],
    marketThemeRefresh: profile.marketThemeRefresh || item.marketThemeRefresh || null,
    holdingThemeRefresh: profile.holdingThemeRefresh || item.holdingThemeRefresh || null,
    seed: {
      ...(profile.seed || {}),
      matchedThemes: profile.seed?.matchedThemes || profile.matchedThemes || item.matchedThemes || [],
      marketThemeRefresh: profile.seed?.marketThemeRefresh || item.seed?.marketThemeRefresh || null,
      holdingThemeRefresh: profile.seed?.holdingThemeRefresh || item.seed?.holdingThemeRefresh || null
    }
  });
}

function enforcePortfolioSellDiscipline(actions = [], profiles = [], positions = []) {
  const profileByCode = new Map((profiles || []).filter(Boolean).map((profile) => [profile.code, profile]));
  const positionByCode = new Map((positions || []).filter(Boolean).map((position) => [position.code, position]));
  return normalizePortfolioActions(actions).map((action) => {
    if (action.action !== "SELL") return action;
    const position = positionByCode.get(action.code);
    const guard = evaluatePortfolioSellDiscipline(action, profileByCode.get(action.code), position);
    if (guard.ok) {
      return {
        ...action,
        reason: [action.reason, guard.reason].filter(Boolean).join(" "),
        dataBasis: mergeStringLists(action.dataBasis, guard.evidence, ["来源：portfolio_sell_discipline_guard"]),
        riskControl: action.riskControl || guard.riskControl || "本轮只做纪律性分批减仓，下一次每日决策继续复核是否需要追加卖出。"
      };
    }
    return {
      ...action,
      action: "HOLD",
      amount: 0,
      targetWeightPct: round(Number(position?.weightPct || action.targetWeightPct || 0), 2),
      reason: [action.reason, guard.reason].filter(Boolean).join(" "),
      dataBasis: mergeStringLists(action.dataBasis, guard.evidence, ["来源：portfolio_sell_discipline_guard"]),
      chaseRisk: [action.chaseRisk, guard.reason].filter(Boolean).join("；"),
      riskControl: action.riskControl || "本轮不提交虚拟赎回，下一次复核破位、转弱、回撤扩大或止盈证据后再决定。"
    };
  });
}

function enforcePortfolioLedgerIntegrityGuard(actions = [], db = {}) {
  const issues = findPortfolioLedgerIntegrityIssues(db);
  if (!issues.length) return normalizePortfolioActions(actions);
  const issueSummary = issues.slice(0, 3).map((item) => `${item.label}${item.value ? `：${item.value}` : ""}`).join("；");
  return normalizePortfolioActions(actions).map((action) => {
    if (action.action !== "BUY") return action;
    return {
      ...action,
      action: "WATCH",
      amount: 0,
      targetWeightPct: 0,
      reason: `系统账本完整性拦截：${issueSummary}。现金、应收或持仓可能失真，先修复账本再买入。`,
      riskControl: "重复成交、卡滞订单或重复应收未处理前，禁止扩大仓位；只能观察候选和补数据。",
      dataBasis: mergeStringLists(action.dataBasis, [
        ...issues.map((item) => `${item.label}=${item.value || item.note || ""}`),
        "来源：portfolio_ledger_integrity_guard"
      ])
    };
  });
}

function findPortfolioLedgerIntegrityIssues(db = {}) {
  const diagnostics = buildPortfolioBacktestDiagnostics(db);
  const ledgerIssueLabels = new Set(["重复成交回测", "订单卡滞回测", "重复应收回测"]);
  return (diagnostics.items || []).filter((item) =>
    ledgerIssueLabels.has(item.label)
    || (item.severity === "critical" && /订单|成交|应收|账本|净值/.test(`${item.label} ${item.note || ""}`))
  );
}

function buildPortfolioStarterBuyFollowUpQueue(db = {}) {
  const account = db.account || {};
  const totalAsset = Number(account.totalAsset || 0);
  const orders = getPortfolioDiagnosticOrders(db);
  const transactions = getPortfolioDiagnosticTransactions(db);
  const activeBuyOrders = orders
    .filter((order) => String(order.side || "").toUpperCase() === "BUY")
    .filter((order) => !["cancelled", "rejected", "settled"].includes(String(order.status || "").toLowerCase()))
    .filter((order) => Number(order.amount || order.actualAmount || 0) > 0)
    .map((order) => buildPortfolioStarterBuyFollowUpFromOrder(order, totalAsset));
  const recentBuyTransactions = transactions
    .filter((transaction) => String(transaction.side || "").toUpperCase() === "BUY")
    .filter((transaction) => !hasActivePortfolioOrderForCode(orders, transaction.code, "BUY"))
    .map((transaction) => buildPortfolioStarterBuyFollowUpFromTransaction(transaction, totalAsset));
  return [...activeBuyOrders, ...recentBuyTransactions]
    .filter((item) => item?.code && Number(item.weightPct || 0) <= 3)
    .sort((a, b) => Date.parse(b.submittedAt || b.date || "") - Date.parse(a.submittedAt || a.date || ""))
    .slice(0, 5);
}

function buildPortfolioStarterBuyFollowUpFromOrder(order = {}, totalAsset = 0) {
  const amount = Number(order.amount || order.actualAmount || 0);
  const weightPct = totalAsset > 0 ? round(amount / totalAsset * 100, 2) : null;
  const status = String(order.status || "");
  const confirmed = ["confirmed"].includes(status.toLowerCase());
  return {
    code: order.code || "",
    name: order.name || "",
    side: "BUY",
    status,
    amount: round(amount, 2),
    weightPct,
    submittedAt: order.submittedAt || "",
    priceDate: order.priceDate || "",
    confirmDate: order.confirmDate || "",
    navDate: order.navDate || order.confirmedNavDate || order.navSnapshot?.date || "",
    nav: order.nav || order.confirmedNav || order.navSnapshot?.nav || null,
    followUpAction: confirmed
      ? "确认后复核：加到3%-5% / 继续观察 / 退出三选一"
      : "确认前不追加：等待净值和份额落账",
    scaleTrigger: "确认净值后，若走势仍是低位修复且5日/10日温和转强，可评估加到3%-5%。",
    exitTrigger: "若确认前后盘中估算转弱、主题过热或费用/份额证据失效，维持观察或撤出。",
    dataBasis: mergeStringLists([
      "来源：portfolio_starter_buy_follow_up_order",
      order.id ? `orderId=${order.id}` : "",
      order.confirmDate ? `confirmDate=${order.confirmDate}` : ""
    ])
  };
}

function buildPortfolioStarterBuyFollowUpFromTransaction(transaction = {}, totalAsset = 0) {
  const amount = Number(transaction.amount || 0);
  const weightPct = totalAsset > 0 ? round(amount / totalAsset * 100, 2) : null;
  return {
    code: transaction.code || "",
    name: transaction.name || "",
    side: "BUY",
    status: "confirmed",
    amount: round(amount, 2),
    weightPct,
    date: transaction.date || transaction.createdAt || "",
    navDate: transaction.navDate || "",
    nav: transaction.nav || null,
    followUpAction: "确认后复核：加到3%-5% / 继续观察 / 退出三选一",
    scaleTrigger: "若确认后没有追涨、回调修复继续成立且持仓前景支持，可评估加到3%-5%。",
    exitTrigger: "若买入后跌破修复结构、费用证据缺失或主题热度反转，退出或降为观察。",
    dataBasis: mergeStringLists([
      "来源：portfolio_starter_buy_follow_up_transaction",
      transaction.orderId ? `orderId=${transaction.orderId}` : ""
    ])
  };
}

function hasActivePortfolioOrderForCode(orders = [], code = "", side = "") {
  const targetCode = String(code || "").trim();
  const targetSide = String(side || "").toUpperCase();
  if (!targetCode) return false;
  return (orders || []).some((order) =>
    String(order.code || "").trim() === targetCode
    && (!targetSide || String(order.side || "").toUpperCase() === targetSide)
    && !["cancelled", "rejected", "settled"].includes(String(order.status || "").toLowerCase())
  );
}

function ensurePortfolioStarterBuyFollowUpReviewed(decision = {}, db = {}) {
  const queue = buildPortfolioStarterBuyFollowUpQueue(db);
  if (!queue.length) return decision;
  const actions = normalizePortfolioActions(decision.actions || []);
  const existingCodes = new Set(actions.map((action) => String(action.code || "")).filter(Boolean));
  const nextActions = [...actions];
  for (const item of queue) {
    if (!item.code || existingCodes.has(item.code)) continue;
    const confirmed = String(item.status || "").toLowerCase() === "confirmed";
    nextActions.push({
      action: confirmed ? "HOLD" : "WATCH",
      code: item.code,
      name: item.name,
      amount: 0,
      targetWeightPct: 0,
      reason: confirmed
        ? `系统试探仓跟踪：${item.name || item.code} 已确认小仓，下一轮必须决定加到3%-5%、继续观察或退出，不能买完就悬空。`
        : `系统试探仓跟踪：${item.name || item.code} 仍在确认中，确认前不追加买入，先等待净值和份额落账。`,
      rotationCheck: "试探仓只跟踪原低位修复逻辑，不因短期新闻或单日估算涨幅追加。",
      positionCheck: item.followUpAction,
      chaseRisk: item.exitTrigger,
      feeCheck: "后续加仓前继续复核份额类别、申购费、销售服务费和赎回规则。",
      riskControl: item.scaleTrigger,
      dataBasis: mergeStringLists(item.dataBasis, ["来源：portfolio_starter_buy_follow_up_guard"])
    });
    existingCodes.add(item.code);
  }
  return {
    ...decision,
    actions: nextActions,
    learningNotes: mergeStringLists(decision.learningNotes, [
      `系统试探仓跟踪：${queue.map((item) => `${item.code} ${item.name}`.trim()).join(" / ")} 必须给加仓、观察或退出条件。`
    ])
  };
}

function enforcePortfolioHeldPositionRiskOverrides(actions = [], profiles = [], positions = []) {
  const profileByCode = new Map((profiles || []).filter(Boolean).map((profile) => [profile.code, profile]));
  const positionByCode = new Map((positions || []).filter(Boolean).map((position) => [position.code, position]));
  return normalizePortfolioActions(actions).map((action) => {
    if (!action.code || !["HOLD", "WATCH"].includes(action.action)) return action;
    const position = positionByCode.get(action.code);
    if (!position || Number(position.currentValue || 0) <= 0) return action;
    const profile = profileByCode.get(action.code) || position.fundSnapshot || null;
    const riskReview = buildPortfolioHeldPositionRiskReview(position, profile);
    if (!shouldReduceHeldPositionFromReview(riskReview, profile, position)
      && !hasPortfolioHeldActionReduceEvidence(action, position)) {
      return action;
    }
    const proposedSell = {
      ...action,
      action: "SELL",
      amount: round(Number(position.currentValue || action.amount || 0), 2),
      targetWeightPct: 0,
      reason: [
        `系统风控覆盖模型${action.action}：持仓已触发降风险条件，不能继续无条件持有。`,
        action.reason,
        riskReview.slice(0, 3).join("；")
      ].filter(Boolean).join(" "),
      dataBasis: mergeStringLists(action.dataBasis, [
        "来源：portfolio_held_position_risk_override",
        ...riskReview.slice(0, 3)
      ]),
      chaseRisk: [
        action.chaseRisk,
        riskReview.find((item) => /偏热|等待回撤|回撤|破位|转弱|回避|止盈/.test(item)) || ""
      ].filter(Boolean).join("；"),
      riskControl: action.riskControl || inferPortfolioHeldPositionReduceTrigger(riskReview)
    };
    const guard = evaluatePortfolioSellDiscipline(proposedSell, profile, position);
    if (!guard.ok) {
      return {
        ...action,
        dataBasis: mergeStringLists(action.dataBasis, guard.evidence, ["来源：portfolio_held_position_risk_override_blocked"]),
        chaseRisk: [action.chaseRisk, guard.reason].filter(Boolean).join("；"),
        riskControl: action.riskControl || "本轮暂不自动减仓，下一次复核需补足可验证卖出证据。"
      };
    }
    return {
      ...proposedSell,
      reason: [proposedSell.reason, guard.reason].filter(Boolean).join(" "),
      dataBasis: mergeStringLists(proposedSell.dataBasis, [guard.reason], guard.evidence),
      riskControl: guard.riskControl || proposedSell.riskControl || "按系统限额先做分批降仓，下一轮继续复核是否追加。"
    };
  });
}

function evaluatePortfolioSellDiscipline(action = {}, profile = null, position = null) {
  if (!action.code) {
    return {
      ok: false,
      reason: "系统卖出纪律拦截：缺少基金代码，不能提交虚拟赎回。",
      evidence: []
    };
  }
  if (!position || Number(position.currentValue || 0) <= 0) {
    return {
      ok: false,
      reason: "系统卖出纪律拦截：组合中没有可卖持仓，不能提交虚拟赎回。",
      evidence: []
    };
  }
  const fallbackProfile = profile || position.fundSnapshot || {};
  const nav = getProfileNav(profile) || getPortfolioPositionFallbackNav(position);
  if (!nav) {
    return {
      ok: false,
      reason: "系统卖出纪律拦截：缺少可验证单位净值，不能提交虚拟赎回。",
      evidence: [formatPortfolioPositionEvidence(position), profile.error || ""].filter(Boolean)
    };
  }
  const trend = fallbackProfile.trendProfile || {};
  const evidence = [
    formatPortfolioPositionEvidence(position),
    formatPortfolioSeedVerifiedTrendEvidence(fallbackProfile),
    formatPortfolioSellFallbackNavEvidence(profile, position)
  ].filter(Boolean);
  const signals = collectPortfolioSellDisciplineSignals(action, fallbackProfile, position);
  if (!trend.ok && !signals.length) {
    return {
      ok: false,
      reason: "系统卖出纪律拦截：缺少可验证走势、破位、转弱或止盈证据，不能提交虚拟赎回。",
      evidence: mergeStringLists(evidence, [trend.note || profile?.error || ""])
    };
  }
  if (!signals.length) {
    return {
      ok: false,
      reason: "系统卖出纪律拦截：缺少破位、转弱、回撤扩大或止盈证据，不能提交虚拟赎回。",
      evidence
    };
  }

  return {
    ok: true,
    reason: `系统卖出纪律确认：${signals.slice(0, 3).join("；")}。`,
    evidence: mergeStringLists(evidence, signals.map((signal) => `卖出证据：${signal}`)),
    riskControl: signals.some((signal) => /破位|回避|止损/.test(signal))
      ? "先按系统上限纪律性减仓，若下一次复核仍破位或回避，再评估追加卖出。"
      : "先按系统上限分批止盈/降仓，不做一次性清仓。"
  };
}

function hasPortfolioHeldActionReduceEvidence(action = {}, position = {}) {
  const actionText = [
    action.reason,
    action.rotationCheck,
    action.positionCheck,
    action.chaseRisk,
    action.riskControl
  ].filter(Boolean).join(" ");
  if (!actionText) return false;
  const return20d = extractPctAfterLabel(actionText, "20日");
  const return60d = extractPctAfterLabel(actionText, "60日");
  const highPosition = /(?:120日位置|250日位置)\s*(?:=|为|约)?\s*(?:9\d(?:\.\d+)?|100(?:\.0+)?)%/.test(actionText);
  const hotLanguage = /高位强势|高追风险|偏热|等待回撤|等回撤|追涨风险|不符合新增买入|利润回吐|浮盈回吐|降至|减仓|降仓|卖出/.test(actionText);
  const giveback = finiteMetricNumber(position.profitGivebackPct);
  if (/题材退潮|主力资金撤离|主力撤离|资金撤离|接盘风险|同方向.*(?:退潮|主力资金撤离|主力撤离)|底层持仓.*(?:退潮|缺证|未确认)/.test(actionText)) return true;
  return (hotLanguage && highPosition)
    || (hotLanguage && Number.isFinite(return20d) && return20d > 12)
    || (hotLanguage && Number.isFinite(return60d) && return60d > 24)
    || (/利润回吐|浮盈回吐|减仓|降仓|卖出/.test(actionText) && Number.isFinite(giveback) && giveback >= Math.abs(finiteNumberOr(process.env.PORTFOLIO_PROFIT_GIVEBACK_PCT, 4)));
}

function collectPortfolioSellDisciplineSignals(action = {}, profile = {}, position = {}) {
  const trend = profile.trendProfile || {};
  const actionability = profile.actionability || {};
  const return20d = finiteMetricNumber(trend.return20dPct);
  const return60d = finiteMetricNumber(trend.return60dPct);
  const drawdown = finiteMetricNumber(trend.drawdownFromRecentHighPct);
  const unrealized = finiteMetricNumber(position.unrealizedPnlPct);
  const peakUnrealized = finiteMetricNumber(position.peakUnrealizedPnlPct);
  const profitGiveback = Number.isFinite(peakUnrealized) && Number.isFinite(unrealized)
    ? Math.max(0, round(peakUnrealized - unrealized, 2))
    : 0;
  const storedProfitGiveback = finiteMetricNumber(position.profitGivebackPct);
  const effectiveProfitGiveback = Number.isFinite(storedProfitGiveback)
    ? Math.max(storedProfitGiveback, profitGiveback)
    : profitGiveback;
  const stopLossPct = Math.abs(finiteNumberOr(process.env.PORTFOLIO_POSITION_STOP_LOSS_PCT, 8));
  const givebackPct = Math.abs(finiteNumberOr(process.env.PORTFOLIO_PROFIT_GIVEBACK_PCT, 4));
  const actionText = [
    action.reason,
    action.rotationCheck,
    action.positionCheck,
    action.chaseRisk,
    action.riskControl
  ].filter(Boolean).join(" ");
  const signals = [];
  const themeSignals = [
    ...getPortfolioHoldingThemeRetreatWarnings(profile),
    ...getCandidateThemeRetreatWarnings(profile),
    ...getStaleThemeCatchdownWarnings(profile)
  ];
  signals.push(...themeSignals.slice(0, 2));
  if (trend.trendLabel === "breakdown") signals.push("趋势破位，需要止损或降低风险敞口");
  if (trend.trendLabel === "weakening") signals.push("趋势转弱，需要减仓观察");
  if (actionability.action === "avoid" || trend.entryBias === "avoid_now") signals.push("可操作性已转为回避");
  if (actionability.action === "wait" && /缺少当前净值\/走势复核|浮盈已回吐|当前转亏|回吐保护/.test(actionText)) {
    signals.push("可操作性偏等待且持仓复查提示数据缺口或回吐风险");
  }
  if (Number.isFinite(drawdown) && drawdown <= -10) signals.push(`距高点${formatFallbackPct(drawdown)}，回撤扩大`);
  if (trend.trendLabel === "extended_uptrend" || trend.entryBias === "wait_pullback") signals.push("短期偏热或等待回撤，适合分批止盈");
  if (Number.isFinite(return20d) && return20d > 12) signals.push(`近20日${formatFallbackPct(return20d)}，需止盈防回吐`);
  if (Number.isFinite(return60d) && return60d > 24) signals.push(`近60日${formatFallbackPct(return60d)}，需降仓控制追涨暴露`);
  const actionReturn20d = extractPctAfterLabel(actionText, "20日");
  const actionReturn60d = extractPctAfterLabel(actionText, "60日");
  if (/高位强势|高追风险|偏热|等待回撤|等回撤|追涨风险|不符合新增买入/.test(actionText)) {
    signals.push("模型持仓理由已识别高位/追涨风险，需要降仓观察");
  }
  if (Number.isFinite(actionReturn20d) && actionReturn20d > 12) signals.push(`模型持仓理由显示近20日${formatFallbackPct(actionReturn20d)}，需止盈防回吐`);
  if (Number.isFinite(actionReturn60d) && actionReturn60d > 24) signals.push(`模型持仓理由显示近60日${formatFallbackPct(actionReturn60d)}，需降仓控制追涨暴露`);
  if (/账户回撤|组合回撤|最大回撤预算/.test(actionText)) signals.push("账户级最大回撤预算触发，需要降低组合风险");
  if (/同题材暴露|底层重叠|组合集中度|穿透暴露/.test(actionText)) {
    signals.push("组合同题材或底层持仓重叠偏高，需要分批降低集中风险");
  }
  if (/题材退潮|主力资金撤离|主力撤离|资金撤离|接盘风险|同方向.*(?:退潮|主力资金撤离|主力撤离)|底层持仓.*(?:退潮|缺证|未确认)/.test(actionText)) {
    signals.push("模型持仓理由已识别题材退潮或主力撤离，需要分批降低题材风险");
  }
  if (Number.isFinite(unrealized) && unrealized <= -stopLossPct) signals.push(`持仓浮亏${formatFallbackPct(unrealized)}，触及单仓止损线`);
  if (/浮盈回吐|利润回吐|回吐保护|浮盈已回吐|当前转亏/.test(actionText) && effectiveProfitGiveback >= givebackPct) {
    signals.push(`历史浮盈${Number.isFinite(peakUnrealized) ? formatFallbackPct(peakUnrealized) : "曾转正"}，已回吐${round(effectiveProfitGiveback, 2)}个百分点`);
  }
  if (Number.isFinite(unrealized) && unrealized >= 8 && /(止盈|减仓|降仓|锁定|兑现)/.test(actionText)) {
    signals.push(`持仓浮盈${formatFallbackPct(unrealized)}，模型给出止盈/减仓意图`);
  }
  return mergeStringLists(signals);
}

function extractPctAfterLabel(text, label) {
  const escaped = String(label || "").replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
  const match = String(text || "").match(new RegExp(`${escaped}\\s*(?:=|为|约)?\\s*([+-]?\\d+(?:\\.\\d+)?)%`));
  if (!match) return NaN;
  const value = Number(match[1]);
  return Number.isFinite(value) ? value : NaN;
}

function getPortfolioPositionFallbackNav(position = {}) {
  return toNumber(position.lastNav)
    || toNumber(position.fundSnapshot?.nav)
    || toNumber(position.fundSnapshot?.unitNav)
    || null;
}

function formatPortfolioSellFallbackNavEvidence(profile = null, position = {}) {
  if (getProfileNav(profile)) return "";
  const nav = getPortfolioPositionFallbackNav(position);
  if (!nav) return "";
  const date = position.lastNavDate || position.fundSnapshot?.navDate || position.fundSnapshot?.snapshotDate || "";
  return [
    `持仓净值兜底：使用上次确认净值${round(nav, 4)}`,
    date ? `日期${date}` : "",
    "来源：portfolio_sell_last_confirmed_nav_guard"
  ].filter(Boolean).join("，");
}

function formatPortfolioPositionEvidence(position = {}) {
  return [
    "持仓验证：",
    position.code || "",
    position.name || "",
    Number.isFinite(Number(position.currentValue)) ? `市值${round(Number(position.currentValue), 2)}元` : "",
    Number.isFinite(Number(position.weightPct)) ? `仓位${round(Number(position.weightPct), 2)}%` : "",
    Number.isFinite(Number(position.unrealizedPnlPct)) ? `浮盈亏${formatFallbackPct(position.unrealizedPnlPct)}` : ""
  ].filter(Boolean).join("，");
}

function getPortfolioExposureKey(item = {}) {
  return item?.exposureKey
    || item?.seed?.exposureKey
    || item?.fundSnapshot?.exposureKey
    || getCandidateExposureKey(item)
    || getCandidateExposureKey(item?.seed || {})
    || getCandidateExposureKey(item?.fundSnapshot || {});
}

function findPortfolioSameExposurePositions(positions = [], exposureKey = "", excludeCode = "") {
  if (!exposureKey) return [];
  return (positions || []).filter((position) => {
    if (!position?.code || position.code === excludeCode) return false;
    return getPortfolioExposureKey(position) === exposureKey;
  });
}

function getPortfolioSameExposureValue(positions = [], item = {}) {
  const exposureKey = getPortfolioExposureKey(item);
  if (!exposureKey) return 0;
  return (positions || [])
    .filter((position) => getPortfolioExposureKey(position) === exposureKey)
    .reduce((sum, position) => sum + Number(position.currentValue || 0), 0);
}

function applyPortfolioWatchlistUpdates(db, updates = [], options = {}) {
  db.watchlist = normalizePortfolioWatchlist(db.watchlist);
  const normalizedUpdates = normalizePortfolioWatchlistUpdates(updates);
  if (!normalizedUpdates.length) return [];
  const now = new Date().toISOString();
  const profileByCode = new Map((options.profiles || []).filter(Boolean).map((profile) => [profile.code, profile]));
  const byCode = new Map(db.watchlist.map((item) => [item.code, item]));
  const applied = [];

  for (const update of normalizedUpdates) {
    const profile = profileByCode.get(update.code);
    const existing = byCode.get(update.code);
    const evidenceProfile = profile || existing?.lastSnapshot || null;
    const effectiveUpdate = update.operation === "REMOVE"
      ? update
      : {
          ...update,
          status: update.status || existing?.status || ""
        };
    const guardedUpdate = update.operation === "REMOVE"
      ? update
      : guardPortfolioWatchlistReadyUpdate(effectiveUpdate, evidenceProfile, existing);
    const snapshot = profile ? buildPortfolioFundSnapshot(profile) : update.lastSnapshot || existing?.lastSnapshot || null;
    const defaults = {
      now,
      addedAt: existing?.addedAt || now,
      updatedAt: now,
      name: guardedUpdate.name || existing?.name || profile?.name || "",
      shareClass: guardedUpdate.shareClass || existing?.shareClass || profile?.fees?.shareClass || profile?.shareClass || inferFundShareClass(profile?.name || guardedUpdate.name || existing?.name || ""),
      type: guardedUpdate.type || existing?.type || profile?.type || "",
      source: guardedUpdate.source || options.source || existing?.source || "",
      sourceRunId: options.run?.id || existing?.sourceRunId || "",
      lastSnapshot: snapshot
    };

    if (guardedUpdate.operation === "REMOVE") {
      const removed = normalizePortfolioWatchItem({
        ...(existing || guardedUpdate),
        status: "removed",
        reason: guardedUpdate.reason || existing?.reason || "模型建议移出自选基金池。",
        updatedAt: now
      }, defaults);
      if (removed) {
        byCode.set(removed.code, removed);
        applied.push(removed);
      }
      continue;
    }

    const merged = normalizePortfolioWatchItem({
      ...(existing || {}),
      ...guardedUpdate,
      status: guardedUpdate.status || existing?.status || "watch",
      priority: guardedUpdate.priority || existing?.priority || 3,
      reason: guardedUpdate.reason || existing?.reason || "",
      setupEvidence: mergeStringLists(guardedUpdate.setupEvidence, existing?.setupEvidence),
      buyTriggers: mergeStringLists(guardedUpdate.buyTriggers, existing?.buyTriggers),
      riskNotes: mergeStringLists(guardedUpdate.riskNotes, existing?.riskNotes),
      feeNotes: mergeStringLists(guardedUpdate.feeNotes, existing?.feeNotes),
      dataBasis: mergeStringLists(guardedUpdate.dataBasis, existing?.dataBasis),
      alternativeShareClasses: mergePortfolioWatchAlternatives(guardedUpdate.alternativeShareClasses, existing?.alternativeShareClasses),
      sameExposureAlternatives: mergePortfolioWatchAlternatives(guardedUpdate.sameExposureAlternatives, existing?.sameExposureAlternatives),
      updatedAt: now
    }, defaults);
    if (!merged) continue;
    byCode.set(merged.code, merged);
    applied.push(merged);
  }

  db.watchlist = normalizePortfolioWatchlist([...byCode.values()]);
  if (applied.length) {
    db.updatedAt = now;
  }
  return applied.map(summarizePortfolioWatchItem);
}

function guardPortfolioWatchlistReadyUpdate(update = {}, profile = null, existing = null) {
  if (update.status !== "ready") {
    return update;
  }
  const verifiedStatus = inferPortfolioWatchStatusFromSeedCandidate(update, 60, profile);
  if (verifiedStatus === "ready") {
    const freshness = evaluatePortfolioWatchlistFreshness({ ...(existing || {}), ...update, status: "ready" }, profile);
    if (!freshness.ok) {
      const guardReason = `系统时效验证降级：${freshness.issues[0]}`;
      return {
        ...update,
        status: "waiting_pullback",
        priority: Math.max(Number(update.priority || 3), 3),
        reason: [update.reason, guardReason].filter(Boolean).join(" "),
        riskNotes: mergeStringLists(update.riskNotes, [guardReason]),
        dataBasis: mergeStringLists(update.dataBasis, ["来源：watchlist_freshness_guard"])
      };
    }
    const readiness = evaluatePortfolioWatchReadiness({ ...(existing || {}), ...update, status: "ready" }, profile);
    const readinessGuard = buildPortfolioReadyStatusReadinessGuard("ready", readiness);
    if (readinessGuard) {
      return {
        ...update,
        status: readinessGuard.status,
        priority: Math.max(Number(update.priority || 3), 3),
        reason: [update.reason, readinessGuard.reason].filter(Boolean).join(" "),
        riskNotes: mergeStringLists(update.riskNotes, [readinessGuard.reason]),
        dataBasis: mergeStringLists(update.dataBasis, ["来源：watchlist_readiness_guard"])
      };
    }
    return update;
  }
  const guardReason = verifiedStatus === "blocked"
    ? "系统净值验证拦截：候选偏热、仍需回撤或存在追涨风险，不能写入可买状态。"
    : "系统净值验证降级：缺少低位回调完成证据，不能仅凭描述写入可买状态。";
  return {
    ...update,
    status: verifiedStatus,
    priority: verifiedStatus === "blocked" ? 5 : Math.max(Number(update.priority || 3), 3),
    reason: [update.reason, guardReason].filter(Boolean).join(" "),
    riskNotes: mergeStringLists(update.riskNotes, [guardReason]),
    dataBasis: mergeStringLists(update.dataBasis, [
      profile?.trendProfile?.ok ? formatPortfolioSeedVerifiedTrendEvidence(profile) : "净值验证：缺失或不足"
    ])
  };
}

function mergeStringLists(...groups) {
  const values = [];
  for (const item of groups.flat()) {
    const text = String(item || "").trim();
    if (text && !values.includes(text)) values.push(text);
  }
  return values;
}

function summarizePortfolioWatchlistForModel(watchlist = []) {
  return normalizePortfolioWatchlist(watchlist)
    .filter((item) => item.status !== "removed")
    .slice(0, 30)
    .map((item) => {
      const readiness = evaluatePortfolioWatchReadiness(item);
      return {
        code: item.code,
        name: item.name,
        shareClass: item.shareClass,
        type: item.type,
        status: item.status,
        priority: item.priority,
        readinessScore: readiness.score,
        readinessLabel: readiness.label,
        candidateRole: item.candidateRole,
        reason: item.reason,
        setupEvidence: item.setupEvidence,
        buyTriggers: item.buyTriggers,
        riskNotes: item.riskNotes,
        feeNotes: item.feeNotes,
        positionPlan: item.positionPlan,
        readinessGaps: readiness.gaps,
        reviewDate: item.reviewDate,
        alternativeShareClasses: item.alternativeShareClasses || [],
        sameExposureAlternatives: item.sameExposureAlternatives || [],
        trendSummary: item.lastSnapshot?.trendSummary || "",
        updatedAt: item.updatedAt
      };
    });
}

async function getFundWorkflowWatchlistContext(userText = "", options = {}) {
  if (String(process.env.FUND_WORKFLOW_WATCHLIST_CONTEXT ?? "true") === "false") {
    return { candidates: [], summary: "经理自选候选池：未启用。" };
  }
  try {
    const db = options.db || readPortfolioDb();
    const limit = options.limit ?? 6;
    let activeWatchlist = getActivePortfolioWatchlist(db);
    let candidates = selectFundWorkflowWatchlistCandidates(activeWatchlist, userText, {
      limit,
      now: options.now
    });
    const staleRefreshCandidates = selectFundWorkflowStaleWatchlistRefreshCandidates(activeWatchlist, userText, {
      limit: Math.max(0, Number(limit || 0) - candidates.length),
      now: options.now
    });
    if (staleRefreshCandidates.length) {
      const profiles = await enrichFunds(staleRefreshCandidates.map((item) => item.code), { limit: getFundAnalysisEnrichmentLimit() });
      const refreshUpdates = buildPortfolioWatchlistRecheckUpdates(staleRefreshCandidates, { profiles })
        .map((update) => ({
          ...update,
          source: "fund_workflow_watchlist_refresh",
          dataBasis: mergeStringLists(update.dataBasis, ["来源：fund_workflow_watchlist_refresh"])
        }));
      if (refreshUpdates.length) {
        applyPortfolioWatchlistUpdates(db, refreshUpdates, {
          profiles,
          source: "fund_workflow_watchlist_refresh"
        });
        if (options.persist !== false) writePortfolioDb(db);
        activeWatchlist = getActivePortfolioWatchlist(db);
        candidates = selectFundWorkflowWatchlistCandidates(activeWatchlist, userText, {
          limit,
          now: options.now
        });
      }
      updateStats({ counters: { fundWorkflowWatchlistRefreshes: staleRefreshCandidates.length } });
    }
    return {
      candidates,
      summary: buildFundWorkflowWatchlistSummary(candidates)
    };
  } catch (error) {
    console.warn("[fund-workflow-watchlist-context-error]", error.message);
    recordError(error, { fundWorkflowWatchlistContextFailures: 1 });
    return { candidates: [], summary: "经理自选候选池：读取失败，本轮只使用市场候选。" };
  }
}

function selectFundWorkflowWatchlistCandidates(watchlist = [], userText = "", options = {}) {
  const limit = Math.max(0, Number(options.limit ?? 6) || 0);
  if (!limit) return [];
  const wantsPullbackSetup = isPullbackSetupRequest(userText);
  return normalizePortfolioWatchlist(watchlist)
    .filter((item) => ["ready", "waiting_pullback", "watch"].includes(item.status))
    .filter((item) => !hasFundWorkflowWatchlistThemeBlocker(item))
    .filter((item) => isFundWorkflowWatchlistFreshEnough(item, options))
    .map((item) => {
      const readiness = evaluatePortfolioWatchReadiness(item);
      const setupFocus = isLowBaseLaunchWatchSeed(item) || /回调完成|启动前夜|低位|刚转强/.test([
        item.reason,
        item.candidateRole,
        item.positionPlan,
        ...(item.setupEvidence || []),
        ...(item.readinessGaps || [])
      ].join(" "));
      const score = Number(readiness.score || 0)
        + (item.status === "ready" ? 28 : item.status === "waiting_pullback" ? 14 : 0)
        + (setupFocus ? 18 : 0)
        - Number(item.priority || 3);
      return {
        ...summarizePortfolioWatchItem(item),
        workflowWatchlistScore: wantsPullbackSetup ? score : score - (setupFocus ? 0 : 8)
      };
    })
    .sort((a, b) => Number(b.workflowWatchlistScore || 0) - Number(a.workflowWatchlistScore || 0)
      || String(b.updatedAt || "").localeCompare(String(a.updatedAt || "")))
    .slice(0, limit);
}

function selectFundWorkflowStaleWatchlistRefreshCandidates(watchlist = [], userText = "", options = {}) {
  const limit = Math.max(0, Number(options.limit ?? 3) || 0);
  if (!limit) return [];
  const wantsPullbackSetup = isPullbackSetupRequest(userText);
  return normalizePortfolioWatchlist(watchlist)
    .filter((item) => ["ready", "waiting_pullback"].includes(item.status))
    .filter((item) => !hasFundWorkflowWatchlistThemeBlocker(item))
    .filter((item) => !isFundWorkflowWatchlistFreshEnough(item, options))
    .filter((item) => !wantsPullbackSetup || isLowBaseLaunchWatchSeed(item) || /回调完成|启动前夜|低位|刚转强/.test([
      item.reason,
      item.candidateRole,
      item.positionPlan,
      ...(item.setupEvidence || []),
      ...(item.readinessGaps || [])
    ].join(" ")))
    .sort((a, b) => Number(a.priority || 3) - Number(b.priority || 3)
      || String(b.updatedAt || "").localeCompare(String(a.updatedAt || "")))
    .slice(0, limit);
}

function hasFundWorkflowWatchlistThemeBlocker(item = {}) {
  const readinessGaps = normalizeStringArray(item.readinessGaps).length
    ? normalizeStringArray(item.readinessGaps)
    : evaluatePortfolioWatchReadiness(item, item.lastSnapshot).gaps;
  const text = [
    item.reason,
    item.candidateRole,
    item.positionPlan,
    ...(item.setupEvidence || []),
    ...(item.buyTriggers || []),
    ...(item.riskNotes || []),
    ...readinessGaps,
    item.lastSnapshot?.reason,
    item.lastSnapshot?.themeEvidence,
    item.lastSnapshot?.rotationCheck,
    item.lastSnapshot?.actionability?.decisionBlocker,
    item.lastSnapshot?.actionability?.blocker
  ].flat().filter(Boolean).join(" ");
  return hasPortfolioCustomerThemeEvidenceBlocker({ reason: text });
}

function isFundWorkflowWatchlistFreshEnough(item = {}, options = {}) {
  const status = normalizePortfolioWatchStatus(item.status || "watch");
  if (!["ready", "waiting_pullback"].includes(status)) return true;
  const freshness = evaluatePortfolioWatchlistFreshness(item, item.lastSnapshot, {
    now: options.now,
    ignoreReviewAge: false
  });
  return freshness.ok;
}

function buildFundWorkflowWatchlistSummary(candidates = []) {
  if (!candidates.length) return "经理自选候选池：暂无可复用的接近可买或等待回调候选。";
  return [
    "经理自选候选池（优先复核，不自动买入）：",
    ...candidates.map((item) => {
      const effectiveAction = formatPortfolioWatchlistEffectiveAction(item.portfolioWatchlist?.status || item.status);
      const fields = [
        `${item.code} ${item.name || ""}`.trim(),
        `状态=${item.statusText || formatPortfolioWatchStatus(item.status)}`,
        effectiveAction ? `执行结论=${effectiveAction}` : "",
        `准备度=${item.readinessScore}/${item.readinessLabel || ""}`,
        item.candidateRole ? `角色=${item.candidateRole}` : "",
        item.reason ? `备选理由=${item.reason}` : "",
        item.readinessGaps?.length ? `缺口=${item.readinessGaps.slice(0, 2).join("/")}` : "",
        item.buyTriggers?.length ? `触发=${item.buyTriggers.slice(0, 2).join("/")}` : "",
        item.feeNotes?.length ? `费用=${item.feeNotes.slice(0, 1).join("/")}` : "",
        item.alternativeShareClasses?.length ? `替代份额=${formatPortfolioWatchAlternativesText(item.alternativeShareClasses)}` : "",
        item.sameExposureAlternatives?.length ? `同类替代=${formatPortfolioWatchAlternativesText(item.sameExposureAlternatives)}` : ""
      ].filter(Boolean);
      return `- ${fields.join("，")}`;
    })
  ].join("\n");
}

function formatPortfolioWatchlistEffectiveAction(status = "") {
  const normalized = normalizePortfolioWatchStatus(status || "watch");
  const labels = {
    ready: "可进入主推荐复核，仍需按金额分批",
    waiting_pullback: "只能列入备选观察，等待触发条件",
    watch: "只观察不买，不能作为主推荐",
    blocked: "暂不买入，先修复数据或风险缺口",
    in_position: "已有持仓，只做持仓复核",
    removed: "已移出，不参与本轮推荐"
  };
  return labels[normalized] || labels.watch;
}

function mergeFundWorkflowWatchlistIntoDeepDive(deepDive, watchlistCandidates = [], userText = "") {
  const converted = (watchlistCandidates || []).map(portfolioWatchItemToDeepDiveCandidate).filter((item) => item.code);
  if (!converted.length) return deepDive;
  const base = deepDive && typeof deepDive === "object"
    ? { ...deepDive, candidates: Array.isArray(deepDive.candidates) ? [...deepDive.candidates] : [] }
    : {
        ok: true,
        focus: "portfolio_watchlist_reuse",
        selectionDiscipline: isPullbackSetupRequest(userText) ? "prefer_pullback_complete_launch_setup_not_chase" : "balanced_theme_relevance",
        candidates: []
      };
  const byCode = new Map();
  for (const item of converted) {
    byCode.set(item.code, item);
  }
  for (const candidate of base.candidates || []) {
    const code = candidate?.code || candidate?.seed?.code || "";
    if (!code) continue;
    const watchCandidate = byCode.get(code);
    byCode.set(code, watchCandidate ? mergePortfolioWatchCandidateDigest(watchCandidate, candidate) : candidate);
  }
  const candidates = [...byCode.values()];
  base.candidates = base.selectionDiscipline === "prefer_pullback_complete_launch_setup_not_chase"
    ? candidates.sort((a, b) => scoreResearchDigestForPullbackSetup(b) - scoreResearchDigestForPullbackSetup(a))
    : candidates;
  base.portfolioWatchlistCandidates = watchlistCandidates;
  return base;
}

function portfolioWatchItemToDeepDiveCandidate(item = {}) {
  const snapshot = item.lastSnapshot || {};
  const trendProfile = snapshot.trendProfile || {};
  const readiness = item.readinessScore === undefined
    ? evaluatePortfolioWatchReadiness(item)
    : { score: item.readinessScore, label: item.readinessLabel || "", gaps: item.readinessGaps || [] };
  const action = item.status === "ready" ? "staged_buy" : item.status === "waiting_pullback" ? "wait" : "watch";
  return {
    ok: Boolean(trendProfile.ok),
    code: item.code || "",
    name: item.name || "",
    type: item.type || "",
    shareClass: item.shareClass || "",
    trendProfile,
    actionability: {
      action,
      actionText: formatActionabilityAction(action),
      score: readiness.score,
      decisionBlocker: readiness.gaps || item.readinessGaps || [],
      decisiveEvidence: [
        item.reason,
        ...(item.setupEvidence || []),
        ...(item.buyTriggers || [])
      ].filter(Boolean).slice(0, 4)
    },
    fees: snapshot.fees || {
      shareClass: item.shareClass || "",
      shareClassFeeModel: item.feeNotes?.[0] ? { label: item.feeNotes[0] } : null
    },
    seed: {
      code: item.code || "",
      name: item.name || "",
      keywords: ["经理自选候选池", ...(isLowBaseLaunchWatchSeed(item) ? ["低位启动前夜候选"] : [])],
      setupDiscoverySource: item.source || item.dataBasis?.find((value) => /来源|召回/.test(value)) || "portfolio_watchlist_context",
      alternativeShareClasses: item.alternativeShareClasses || [],
      sameExposureAlternatives: item.sameExposureAlternatives || []
    },
    portfolioWatchlist: {
      status: item.status || "",
      statusText: item.statusText || formatPortfolioWatchStatus(item.status),
      readinessScore: readiness.score,
      readinessLabel: readiness.label,
      readinessGaps: readiness.gaps || item.readinessGaps || [],
      candidateRole: item.candidateRole || "",
      reason: item.reason || "",
      positionPlan: item.positionPlan || ""
    },
    sources: [
      ...(Array.isArray(snapshot.sources) ? snapshot.sources : []),
      ...(item.dataBasis || [])
    ].filter(Boolean)
  };
}

function mergePortfolioWatchCandidateDigest(watchCandidate = {}, marketCandidate = {}) {
  const preferMarket = marketCandidate?.ok !== false && marketCandidate?.trendProfile?.ok;
  const primary = preferMarket ? marketCandidate : watchCandidate;
  const fallback = preferMarket ? watchCandidate : marketCandidate;
  return applyPortfolioWatchlistReadinessOverride({
    ...fallback,
    ...primary,
    portfolioWatchlist: watchCandidate.portfolioWatchlist || marketCandidate.portfolioWatchlist,
    seed: {
      ...(watchCandidate.seed || {}),
      ...(marketCandidate.seed || {}),
      keywords: [...new Set([...(watchCandidate.seed?.keywords || []), ...(marketCandidate.seed?.keywords || [])].filter(Boolean))]
    },
    sources: [...new Set([...(watchCandidate.sources || []), ...(marketCandidate.sources || [])].filter(Boolean))]
  }, watchCandidate);
}

function applyPortfolioWatchlistReadinessOverride(candidate = {}, watchCandidate = {}) {
  const blocker = getPortfolioWatchlistMainCandidateBlocker(candidate) || getPortfolioWatchlistMainCandidateBlocker(watchCandidate);
  if (!blocker) return candidate;
  const status = normalizePortfolioWatchStatus(candidate.portfolioWatchlist?.status || watchCandidate.portfolioWatchlist?.status || watchCandidate.status || "watch");
  const action = status === "waiting_pullback" ? "wait" : "watch";
  const actionability = candidate.actionability || {};
  return {
    ...candidate,
    actionability: {
      ...actionability,
      action,
      actionText: formatActionabilityAction(action),
      score: Math.min(Number.isFinite(Number(actionability.score)) ? Number(actionability.score) : 60, status === "waiting_pullback" ? 58 : 45),
      decisiveEvidence: mergeStringLists(actionability.decisiveEvidence, [
        `自选池执行结论=${formatPortfolioWatchlistEffectiveAction(status)}`
      ]).slice(0, 5),
      decisionBlocker: mergeStringLists([blocker], actionability.decisionBlocker).slice(0, 5)
    }
  };
}

function getPortfolioWatchlistMainCandidateBlocker(candidate = {}) {
  const watch = candidate.portfolioWatchlist || {};
  const rawStatus = watch.status || candidate.status || "";
  if (!rawStatus) return "";
  const status = normalizePortfolioWatchStatus(rawStatus);
  if (status === "ready") return "";
  if (status === "waiting_pullback") return "经理自选池状态为等待回调，只能列入备选观察，不能作为主推荐。";
  if (status === "watch") return "经理自选池状态为观察中，说明仍有规模、费用、持仓或走势缺口，不能作为主推荐。";
  if (status === "blocked") return "经理自选池状态为暂不买，数据或风险缺口未修复前不能推荐买入。";
  if (status === "in_position") return "经理自选池状态为已持仓，只能做持仓复核，不能当作新增主推荐。";
  if (status === "removed") return "经理自选池状态为已移出，不参与本轮推荐。";
  return "";
}

function summarizePortfolioWatchItem(item = {}) {
  const readiness = evaluatePortfolioWatchReadiness(item);
  return {
    code: item.code,
    name: item.name,
    shareClass: item.shareClass || "",
    type: item.type || "",
    status: item.status || "watch",
    statusText: formatPortfolioWatchStatus(item.status),
    priority: item.priority || 3,
    readinessScore: readiness.score,
    readinessLabel: readiness.label,
    candidateRole: item.candidateRole || "",
    reason: item.reason || "",
    setupEvidence: item.setupEvidence || [],
    buyTriggers: item.buyTriggers || [],
    riskNotes: item.riskNotes || [],
    feeNotes: item.feeNotes || [],
    positionPlan: item.positionPlan || "",
    readinessGaps: readiness.gaps,
    reviewDate: item.reviewDate || "",
    dataBasis: item.dataBasis || [],
    alternativeShareClasses: item.alternativeShareClasses || [],
    sameExposureAlternatives: item.sameExposureAlternatives || [],
    source: item.source || "",
    sourceRunId: item.sourceRunId || "",
    lastSnapshot: item.lastSnapshot || null,
    addedAt: item.addedAt || "",
    updatedAt: item.updatedAt || ""
  };
}

function buildPortfolioReadyStatusReadinessGuard(status, readiness = {}) {
  if (status !== "ready") return null;
  const gaps = readiness.gaps || [];
  const structuralGap = gaps.find(isPortfolioWatchStructuralReadinessGap);
  if (structuralGap) {
    return {
      status: "watch",
      reason: `系统买入准备验证降级：${structuralGap}`
    };
  }
  if (Number(readiness.score || 0) < 85) {
    const firstGap = gaps.find((gap) => !/条件已满足/.test(gap)) || "准备度不足，不能写入可买状态。";
    return {
      status: "waiting_pullback",
      reason: `系统买入准备验证降级：${firstGap}`
    };
  }
  return null;
}

function isPortfolioWatchStructuralReadinessGap(gap = "") {
  return /基金规模|前十大集中度|持仓承载|前十大持仓未命中题材龙头|前十大持仓实际集中|承载逻辑需复核|目标主题匹配度不足|特殊\/平台份额|可申购渠道|普通渠道可申购|起购门槛|题材退潮|主力资金撤离|主力撤离|接盘风险|低位轮动标签缺少当前题材雷达刷新|当前题材雷达.*(?:过期|缺少刷新时间|刷新时间无法验证)|重新刷新主力资金\/新闻催化/.test(String(gap || ""));
}

function buildPortfolioWatchReadinessGaps(item = {}, profile = null) {
  const evidence = profile || item.lastSnapshot || null;
  const trend = evidence?.trendProfile || {};
  const gaps = [];
  const themeRetreatWarnings = [
    ...getDirectPortfolioHoldingThemeRetreatWarnings(evidence),
    ...getDirectPortfolioHoldingThemeRetreatWarnings(item),
    ...getCandidateThemeRetreatWarnings(evidence),
    ...getCandidateThemeRetreatWarnings(item),
    ...getStaleThemeCatchdownWarnings(evidence),
    ...getStaleThemeCatchdownWarnings(item),
    ...getStaleCatalystThemeWarnings(evidence),
    ...getStaleCatalystThemeWarnings(item),
    ...getStalePortfolioThemeRefreshWarnings(evidence),
    ...getStalePortfolioThemeRefreshWarnings(item)
  ];
  if (!evidence || !trend.ok) {
    gaps.push(...themeRetreatWarnings);
    const holdingCarrierGap = getPortfolioWatchHoldingCarrierGap(evidence);
    if (holdingCarrierGap) gaps.push(holdingCarrierGap);
    gaps.push("缺少可验证净值/走势下钻，不能进入买入执行。");
    return gaps;
  }
  const signal = trend.pullbackSetup?.signal || "";
  if (!["pullback_complete", "launch_setup"].includes(signal)) {
    gaps.push("还差回调完成或启动前夜信号。");
  }
  if (!isEarlyTurnSetupTrend(trend)) {
    gaps.push("还差5日/10日刚转强证据。");
  }
  if (!hasPullbackLowPositionEvidence(trend)) {
    gaps.push("还差120日低位或距高点回撤证据。");
  }
  const return20d = finiteMetricNumber(trend.return20dPct);
  const return60d = finiteMetricNumber(trend.return60dPct);
  if (!Number.isFinite(return20d)) {
    gaps.push("缺少近20日涨幅验证。");
  } else if (return20d > 10) {
    gaps.push(`近20日${formatFallbackPct(return20d)}，需降温到10%以内。`);
  }
  if (!Number.isFinite(return60d)) {
    gaps.push("缺少近60日涨幅验证。");
  } else if (return60d > 24) {
    gaps.push(`近60日${formatFallbackPct(return60d)}，需消化到24%以内。`);
  }
  if (trend.entryBias === "wait_pullback") {
    gaps.push("入场判断仍是等待回撤。");
  } else if (trend.entryBias === "avoid_now") {
    gaps.push("入场判断仍是暂时回避。");
  }
  if (evidence.actionability?.action === "wait") {
    gaps.push("可操作性仍是等待。");
  } else if (evidence.actionability?.action === "avoid") {
    gaps.push("可操作性仍是回避。");
  }
  if (hasHighChaseTheme(evidence) || hasHighChaseTheme(item)) {
    gaps.push("题材拥挤或追涨风险仍需下降。");
  }
  const themeSupportGap = getPortfolioWatchThemeSupportGap(item, evidence);
  if (themeSupportGap) {
    gaps.push(themeSupportGap);
  }
  const holdingCarrierGap = getPortfolioWatchHoldingCarrierGap(evidence);
  if (holdingCarrierGap) {
    gaps.push(holdingCarrierGap);
  }
  gaps.push(...themeRetreatWarnings);
  const specialAvailability = evaluatePortfolioSpecialShareClassAvailability(evidence);
  if (specialAvailability.required && !specialAvailability.ok) {
    gaps.push(specialAvailability.reason);
  } else if (!hasVerifiedPortfolioFeeEvidence(evidence)) {
    gaps.push("还差可验证费用/份额证据。");
  }
  gaps.push(...buildPortfolioWatchStructuralReadinessGaps(item, evidence));
  const freshness = evaluatePortfolioWatchlistFreshness(item, evidence);
  gaps.push(...freshness.issues);
  if (!gaps.length && item.status === "ready") {
    return ["低位/启动/刚转强/不过热/费用条件已满足，下一次盘前确认后再分批评估。"];
  }
  return gaps;
}

function getPortfolioWatchHoldingCarrierGap(evidence = null) {
  return mergeStringLists(
    evidence?.actionability?.decisionBlocker,
    evidence?.actionability?.holdingsOutlook?.risks,
    evidence?.holdingsOutlook?.risks
  ).find((gap) => /持仓承载|前十大持仓未命中题材龙头|前十大持仓与目标主题匹配度不足/.test(gap)) || "";
}

function buildPortfolioWatchStructuralReadinessGaps(item = {}, evidence = null) {
  const gaps = [];
  const scaleYi = getPortfolioWatchFundScaleYi(item, evidence);
  if (Number.isFinite(scaleYi)) {
    if (scaleYi < 0.5) {
      gaps.push(`基金规模${round(scaleYi, 2)}亿偏小，不能作为可直接买入候选。`);
    } else if (scaleYi < 1) {
      gaps.push(`基金规模${round(scaleYi, 2)}亿偏小，需先观察流动性和清盘风险。`);
    }
  }
  const top10Pct = getPortfolioWatchTop10Pct(item, evidence);
  if (Number.isFinite(top10Pct)) {
    if (top10Pct >= 70) {
      gaps.push(`前十大集中度${formatFallbackPlainPct(top10Pct)}过高，单一持仓波动可能放大回撤。`);
    } else if (top10Pct >= 60) {
      gaps.push(`前十大集中度${formatFallbackPlainPct(top10Pct)}偏高，只能观察或小仓复核。`);
    }
  }
  const holdingsOutlook = resolvePortfolioWatchHoldingsOutlook({
    ...item,
    lastSnapshot: evidence || item.lastSnapshot
  });
  const holdingRealtimeWarning = getHoldingRealtimeCatchdownWarning(evidence || item.lastSnapshot || item);
  if (holdingRealtimeWarning) {
    gaps.push(holdingRealtimeWarning);
  }
  const holdingCarrierRisk = normalizeStringArray(holdingsOutlook.risks).find((risk) =>
    /前十大持仓未命中题材龙头|前十大持仓与目标主题匹配度不足/.test(risk)
  );
  if (holdingCarrierRisk) {
    gaps.push(holdingCarrierRisk);
  }
  return gaps;
}

function getPortfolioWatchFundScaleYi(item = {}, evidence = null) {
  const values = [
    evidence?.scale,
    evidence?.fundScale,
    evidence?.fundSize,
    evidence?.size,
    evidence?.seed?.scale,
    evidence?.seed?.fundScale,
    item.scale,
    item.fundScale,
    item.fundSize,
    item.size,
    item.lastSnapshot?.scale,
    item.lastSnapshot?.seed?.scale
  ];
  for (const value of values) {
    const parsed = parsePortfolioFundScaleYi(value);
    if (Number.isFinite(parsed)) return parsed;
  }
  const text = [
    evidence?.reason,
    evidence?.fundOverview,
    evidence?.profileText,
    item.reason,
    ...(evidence?.actionability?.decisiveEvidence || []),
    ...(item.setupEvidence || []),
    ...(item.riskNotes || [])
  ].filter(Boolean).join(" ");
  const match = text.match(/(?:规模|基金规模)[^\d-]{0,8}([0-9]+(?:\.[0-9]+)?)\s*(亿|亿元|万|万元)?/);
  if (!match) return null;
  return parsePortfolioFundScaleYi(`${match[1]}${match[2] || "亿"}`);
}

function parsePortfolioFundScaleYi(value) {
  if (value === null || value === undefined || value === "") return null;
  if (typeof value === "number") return Number.isFinite(value) ? value : null;
  if (typeof value === "object") {
    const values = [value.valueYi, value.y, value.value, value.scale, value.fundScale, value.fundSize, value.size];
    for (const item of values) {
      const parsed = parsePortfolioFundScaleYi(item);
      if (Number.isFinite(parsed)) return parsed;
    }
    return null;
  }
  const text = String(value || "").replace(/,/g, "").trim();
  const match = text.match(/([0-9]+(?:\.[0-9]+)?)/);
  if (!match) return null;
  const numeric = Number(match[1]);
  if (!Number.isFinite(numeric)) return null;
  if (/万/.test(text) && !/亿/.test(text)) return round(numeric / 10000, 4);
  return numeric;
}

function getPortfolioWatchTop10Pct(item = {}, evidence = null) {
  const values = [
    evidence?.holdingsOutlook?.concentration?.top10Pct,
    evidence?.actionability?.holdingsOutlook?.concentration?.top10Pct,
    evidence?.concentration?.top10Pct,
    evidence?.fundSnapshot?.holdingsOutlook?.concentration?.top10Pct,
    item.holdingsOutlook?.concentration?.top10Pct,
    item.lastSnapshot?.holdingsOutlook?.concentration?.top10Pct,
    item.lastSnapshot?.actionability?.holdingsOutlook?.concentration?.top10Pct
  ];
  for (const value of values) {
    const parsed = parsePortfolioPctMetric(value);
    if (Number.isFinite(parsed)) return parsed;
  }
  const text = [
    evidence?.holdingsOutlook?.evidence,
    evidence?.actionability?.holdingsOutlook?.evidence,
    evidence?.reason,
    item.reason,
    ...(evidence?.holdingsOutlook?.risks || []),
    ...(evidence?.actionability?.holdingsOutlook?.risks || []),
    ...(evidence?.actionability?.decisiveEvidence || []),
    ...(item.setupEvidence || []),
    ...(item.riskNotes || [])
  ].filter(Boolean).join(" ");
  const match = text.match(/前十大(?:集中度|约)?[^\d+-]{0,12}([0-9]+(?:\.[0-9]+)?)\s*%/);
  return match ? parsePortfolioPctMetric(`${match[1]}%`) : null;
}

function parsePortfolioPctMetric(value) {
  if (value === null || value === undefined || value === "") return null;
  if (typeof value === "number") {
    if (!Number.isFinite(value)) return null;
    return value > 0 && value <= 1 ? round(value * 100, 2) : value;
  }
  const match = String(value || "").replace(/,/g, "").match(/([0-9]+(?:\.[0-9]+)?)/);
  if (!match) return null;
  const numeric = Number(match[1]);
  if (!Number.isFinite(numeric)) return null;
  return numeric > 0 && numeric <= 1 ? round(numeric * 100, 2) : numeric;
}

function evaluatePortfolioWatchReadiness(item = {}, profile = null) {
  const status = normalizePortfolioWatchStatus(item.status || "watch");
  const evidence = profile || item.lastSnapshot || null;
  const trend = evidence?.trendProfile || {};
  const gaps = buildPortfolioWatchReadinessGaps(item, profile);
  let score = evidence && trend.ok ? 100 : 18;
  for (const gap of gaps) {
    score -= scorePortfolioWatchReadinessGapPenalty(gap);
  }
  if (gaps.some((gap) => gap.includes("条件已满足"))) {
    score = Math.max(score, 88);
  }
  const statusCaps = {
    ready: 100,
    waiting_pullback: 78,
    watch: 58,
    blocked: 24,
    in_position: 68,
    removed: 0
  };
  score = Math.min(score, statusCaps[status] ?? 58);
  const riskCap = getPortfolioWatchStructuralReadinessCap(gaps);
  if (Number.isFinite(riskCap)) score = Math.min(score, riskCap);
  const bounded = Math.round(clampScore(score));
  return {
    score: bounded,
    label: formatPortfolioWatchReadinessLabel(bounded),
    gaps
  };
}

function getPortfolioWatchStructuralReadinessCap(gaps = []) {
  const text = (gaps || []).join(" ");
  if (/题材退潮|主力资金撤离|主力撤离|接盘风险|低位轮动标签缺少当前题材雷达刷新|当前题材雷达.*(?:过期|缺少刷新时间|刷新时间无法验证)|重新刷新主力资金\/新闻催化/.test(text)) return 46;
  if (/当前主力进场|题材预热|低位轮动支撑/.test(text)) return 58;
  if (/特殊\/平台份额|可申购渠道|普通渠道可申购|起购门槛/.test(text)) return 58;
  if (/基金规模.*不能作为可直接买入|前十大集中度.*过高/.test(text)) return 58;
  if (/持仓承载|前十大持仓未命中题材龙头|承载逻辑需复核|目标主题匹配度不足/.test(text)) return 58;
  if (/基金规模.*偏小|前十大集中度.*偏高/.test(text)) return 78;
  return null;
}

function scorePortfolioWatchReadinessGapPenalty(gap = "") {
  const text = String(gap || "");
  if (/缺少可验证净值|走势下钻/.test(text)) return 70;
  if (/基金规模.*不能作为可直接买入/.test(text)) return 30;
  if (/前十大集中度.*过高/.test(text)) return 24;
  if (/特殊\/平台份额|可申购渠道|普通渠道可申购|起购门槛/.test(text)) return 32;
  if (/持仓承载|前十大持仓未命中题材龙头|承载逻辑需复核|目标主题匹配度不足/.test(text)) return 26;
  if (/基金规模.*偏小/.test(text)) return 16;
  if (/前十大集中度.*偏高/.test(text)) return 18;
  if (/回调完成|启动前夜/.test(text)) return 18;
  if (/120日低位|距高点回撤/.test(text)) return 16;
  if (/近20日.*需降温|近60日.*需消化/.test(text)) return 16;
  if (/等待回撤|可操作性仍是等待|入场判断仍是等待/.test(text)) return 14;
  if (/暂时回避|仍是回避/.test(text)) return 28;
  if (/题材退潮|主力资金撤离|主力撤离|低位轮动标签缺少当前题材雷达刷新|当前题材雷达.*(?:过期|缺少刷新时间|刷新时间无法验证)|重新刷新主力资金\/新闻催化/.test(text)) return 34;
  if (/当前主力进场|题材预热|低位轮动支撑/.test(text)) return 24;
  if (/题材拥挤|追涨风险/.test(text)) return 16;
  if (/费用\/份额/.test(text)) return 10;
  if (/快照已过期|重新下钻|复核已过期/.test(text)) return 18;
  if (/缺少近20日|缺少近60日/.test(text)) return 8;
  return 7;
}

function formatPortfolioWatchReadinessLabel(score) {
  const value = Number(score);
  if (value >= 85) return "买入准备充分";
  if (value >= 70) return "接近可买，等盘前确认";
  if (value >= 55) return "备选观察";
  if (value >= 35) return "条件不足";
  return "暂不买入";
}

function comparePortfolioWatchReadiness(a = {}, b = {}) {
  return getPortfolioWatchReadinessScore(b) - getPortfolioWatchReadinessScore(a)
    || Number(a.priority || 3) - Number(b.priority || 3)
    || String(b.updatedAt || "").localeCompare(String(a.updatedAt || ""));
}

function getPortfolioWatchReadinessScore(item = {}) {
  const score = Number(item.readinessScore ?? item.score);
  return Number.isFinite(score) ? score : evaluatePortfolioWatchReadiness(item).score;
}

function isPortfolioActiveOrder(order = {}) {
  return Boolean(order)
    && !PORTFOLIO_ACTIVE_ORDER_FINAL_STATUSES.has(String(order.status || "").toLowerCase());
}

function getPortfolioActiveOrders(orders = []) {
  return (orders || []).filter(isPortfolioActiveOrder);
}

function getPortfolioOrderDedupeKey(order = {}) {
  const side = String(order.side || order.action || "").toUpperCase();
  const code = String(order.code || "").trim();
  return side && code ? `${side}:${code}` : "";
}

function hasActivePortfolioOrderForAction(orders = [], action = {}, side = "") {
  const actionSide = String(side || action.side || action.action || "").toUpperCase();
  const code = String(action.code || "").trim();
  if (!actionSide || !code) return false;
  return getPortfolioActiveOrders(orders).some((order) =>
    String(order.side || "").toUpperCase() === actionSide
    && String(order.code || "").trim() === code
  );
}

function cancelDuplicatePortfolioActiveOrders(db = {}, result = null) {
  const activeOrders = getPortfolioActiveOrders(db.orders || []);
  const byKey = new Map();
  const cancelled = [];

  for (const order of activeOrders) {
    const key = getPortfolioOrderDedupeKey(order);
    if (!key) continue;
    if (!byKey.has(key)) byKey.set(key, []);
    byKey.get(key).push(order);
  }

  for (const group of byKey.values()) {
    if (group.length <= 1) continue;
    const sorted = [...group].sort(comparePortfolioOrderPriorityForDedupe);
    const keep = sorted[0];
    for (const duplicate of sorted.slice(1)) {
      const beforeStatus = duplicate.status || "";
      const cancelledOrder = cancelPortfolioActiveOrder(
        db,
        duplicate,
        `同一基金同方向已有未完成订单 ${keep.id || ""}，为避免重复提交已自动取消。`,
        result
      );
      if (cancelledOrder) cancelled.push({ order: duplicate, beforeStatus, keep });
    }
  }

  if (cancelled.length) {
    syncPortfolioActiveOrderReservations(db);
  }
  return cancelled;
}

function comparePortfolioOrderPriorityForDedupe(a = {}, b = {}) {
  return String(a.acceptedDate || a.priceDate || "").localeCompare(String(b.acceptedDate || b.priceDate || ""))
    || String(a.submittedAt || a.createdAt || "").localeCompare(String(b.submittedAt || b.createdAt || ""))
    || String(a.id || "").localeCompare(String(b.id || ""));
}

function cancelPortfolioActiveOrder(db = {}, order = {}, reason = "", result = null) {
  if (!order || !isPortfolioActiveOrder(order)) return null;
  const beforeStatus = order.status || "";
  order.status = "cancelled";
  order.cancelledAt = new Date().toISOString();
  order.cancelReason = reason || "系统自动取消未完成订单。";
  releasePortfolioOrderReservation(db, order);
  addOrderTimeline(order, "cancelled", order.cancelReason);
  if (result) {
    result.orderUpdates.push({
      id: order.id,
      code: order.code,
      name: order.name,
      side: order.side,
      beforeStatus,
      afterStatus: order.status,
      priceDate: order.priceDate,
      confirmDate: order.confirmDate
    });
    result.notes.push({
      action: order.side,
      code: order.code,
      name: order.name,
      status: "cancelled",
      reason: order.cancelReason
    });
    result.updatedOrders += 1;
  }
  return order;
}

function releasePortfolioOrderReservation(db = {}, order = {}) {
  if (!db.account || typeof db.account !== "object" || order.reservationReleasedAt) return false;
  const side = String(order.side || "").toUpperCase();
  const amount = round(Number(order.amount || order.actualAmount || 0), 2);
  if (side === "BUY" && amount > 0) {
    db.account.cash = round(Number(db.account.cash || 0) + amount, 2);
    db.account.pendingBuyAmount = round(Math.max(0, Number(db.account.pendingBuyAmount || 0) - amount), 2);
  }
  order.reservationReleasedAt = new Date().toISOString();
  return true;
}

function cancelStalePortfolioActiveOrders(db = {}, result = null, referenceDate = getZonedDateTime(getEffectiveConfig().portfolioTimezone).date) {
  const impossibleSellOrders = findImpossiblePortfolioSellOrders(db);
  const staleOrders = findStalePortfolioActiveOrders(db.orders || [], referenceDate)
    .filter((order) => shouldCancelStalePortfolioOrder(order, referenceDate));
  const ordersToCancel = dedupePortfolioOrdersByIdOrIdentity([
    ...impossibleSellOrders,
    ...staleOrders
  ]);
  const cancelled = [];
  for (const order of ordersToCancel) {
    const impossibleSell = impossibleSellOrders.includes(order);
    let reason = "";
    if (impossibleSell) {
      reason = "账户已无对应持仓或可卖份额，系统取消旧赎回，避免继续显示为待处理订单。";
    } else if (String(order.side || "").toUpperCase() === "BUY") {
      reason = `确认日 ${order.confirmDate || order.priceDate || "-"} 已过，仍没有可验证净值或份额确认，系统取消旧申购并释放冻结现金。`;
    } else {
      reason = `确认日 ${order.confirmDate || order.priceDate || "-"} 已过，仍未完成确认，系统取消旧赎回并释放待卖份额。`;
    }
    const cancelledOrder = cancelPortfolioActiveOrder(db, order, reason, result);
    if (cancelledOrder) cancelled.push(cancelledOrder);
  }
  if (cancelled.length) {
    syncPortfolioActiveOrderReservations(db);
    recalculatePortfolioAccount(db.account);
  }
  return cancelled;
}

function findImpossiblePortfolioSellOrders(db = {}) {
  return getPortfolioActiveOrders(db.orders || [])
    .filter((order) => shouldRejectImpossiblePortfolioSellOrder(db, order));
}

function dedupePortfolioOrdersByIdOrIdentity(orders = []) {
  const seen = new Set();
  const unique = [];
  for (const order of orders || []) {
    if (!order) continue;
    const key = order.id || [
      order.side,
      order.code,
      order.status,
      order.priceDate,
      order.confirmDate,
      order.amount,
      order.requestedUnits
    ].join("|");
    if (seen.has(key)) continue;
    seen.add(key);
    unique.push(order);
  }
  return unique;
}

function shouldCancelStalePortfolioOrder(order = {}, referenceDate = getZonedDateTime(getEffectiveConfig().portfolioTimezone).date) {
  if (!isPortfolioActiveOrder(order)) return false;
  const status = String(order.status || "").toLowerCase();
  const confirmDate = normalizePortfolioEventDate(order.confirmDate);
  const priceDate = normalizePortfolioEventDate(order.priceDate || order.acceptedDate);
  const anchorDate = confirmDate || priceDate;
  if (!anchorDate) return false;
  const staleDays = daysBetweenPortfolioDates(anchorDate, referenceDate);
  const graceDays = Math.max(1, Number(process.env.PORTFOLIO_ORDER_STALE_CANCEL_DAYS || 4));
  if (!Number.isFinite(staleDays) || staleDays < graceDays) return false;
  if (order.navSnapshot?.nav && confirmDate && confirmDate <= referenceDate && status !== "priced") return false;
  return ["queued", "submitted", "priced", "pending"].includes(status);
}

function daysBetweenPortfolioDates(startDate, endDate) {
  const start = Date.parse(normalizePortfolioEventDate(startDate) || "");
  const end = Date.parse(normalizePortfolioEventDate(endDate) || "");
  if (!Number.isFinite(start) || !Number.isFinite(end)) return null;
  return Math.floor((end - start) / 86400000);
}

function syncPortfolioActiveOrderReservations(db = {}) {
  if (!db.account || !Array.isArray(db.account.positions)) return;
  for (const position of db.account.positions) {
    position.pendingSellUnits = 0;
    position.pendingSellAmount = 0;
  }

  const activeOrders = getPortfolioActiveOrders(db.orders || []);
  db.account.pendingBuyAmount = round(activeOrders
    .filter((order) => String(order.side || "").toUpperCase() === "BUY")
    .reduce((sum, order) => sum + Number(order.amount || 0), 0), 2);

  const sellOrdersByCode = new Map();
  for (const order of activeOrders) {
    if (String(order.side || "").toUpperCase() !== "SELL" || !order.code) continue;
    if (!sellOrdersByCode.has(order.code)) sellOrdersByCode.set(order.code, []);
    sellOrdersByCode.get(order.code).push(order);
  }

  for (const position of db.account.positions) {
    const orders = sellOrdersByCode.get(position.code) || [];
    if (!orders.length) continue;
    let remainingUnits = Math.max(0, Number(position.units || 0));
    let pendingUnits = 0;
    let pendingAmount = 0;
    for (const order of orders.sort(comparePortfolioOrderPriorityForDedupe)) {
      const requestedUnits = Number(order.requestedUnits || 0);
      const fallbackUnits = Number(position.currentValue || 0) > 0
        ? Number(position.units || 0) * (Number(order.amount || 0) / Number(position.currentValue || 1))
        : 0;
      const units = Math.min(remainingUnits, Math.max(0, requestedUnits || fallbackUnits));
      if (units <= 0) continue;
      pendingUnits += units;
      pendingAmount += Number(order.amount || 0);
      remainingUnits = Math.max(0, remainingUnits - units);
    }
    position.pendingSellUnits = round(pendingUnits, 6);
    position.pendingSellAmount = round(pendingAmount, 2);
  }
}

function evaluatePortfolioWatchlistFreshness(item = {}, profile = null, options = {}) {
  const status = normalizePortfolioWatchStatus(item.status || "watch");
  if (!["ready", "waiting_pullback"].includes(status)) {
    return { ok: true, issues: [] };
  }
  const nowMs = Date.parse(options.now || new Date().toISOString());
  const issues = [];
  const maxSnapshotAgeDays = status === "ready"
    ? finiteNumberOr(process.env.PORTFOLIO_WATCH_READY_MAX_SNAPSHOT_AGE_DAYS, 5)
    : finiteNumberOr(process.env.PORTFOLIO_WATCH_WAITING_MAX_SNAPSHOT_AGE_DAYS, 10);
  const maxReviewAgeDays = finiteNumberOr(process.env.PORTFOLIO_WATCH_MAX_REVIEW_AGE_DAYS, 14);
  const snapshotDate = extractPortfolioWatchSnapshotDate(profile || item.lastSnapshot || {});
  const snapshotAge = daysSincePortfolioDate(snapshotDate, nowMs);
  if (Number.isFinite(snapshotAge)) {
    if (snapshotAge > maxSnapshotAgeDays) {
      issues.push(`净值快照已过期${snapshotAge}天，需要重新下钻后才能买入。`);
    }
  } else {
    issues.push("缺少净值快照日期，需要重新下钻后才能买入。");
  }

  if (!options.ignoreReviewAge) {
    const reviewAge = daysSincePortfolioDate(item.updatedAt || item.addedAt || "", nowMs);
    if (Number.isFinite(reviewAge) && reviewAge > maxReviewAgeDays) {
      issues.push(`自选复查已超过${reviewAge}天，需要重新复核后才能买入。`);
    }
  }

  return { ok: issues.length === 0, issues };
}

function extractPortfolioWatchSnapshotDate(snapshot = {}) {
  return String(
    snapshot.snapshotDate
    || snapshot.navDate
    || snapshot.date
    || snapshot.trendProfile?.latestDate
    || snapshot.trendProfile?.snapshotDate
    || ""
  ).trim();
}

function daysSincePortfolioDate(value, nowMs = Date.now()) {
  const text = String(value || "").trim();
  if (!text || !Number.isFinite(nowMs)) return null;
  const dateText = text.match(/\d{4}-\d{2}-\d{2}/)?.[0] || text;
  const parsed = Date.parse(dateText.length === 10 ? `${dateText}T00:00:00Z` : dateText);
  if (!Number.isFinite(parsed)) return null;
  return Math.max(0, Math.floor((nowMs - parsed) / 86400000));
}

function formatPortfolioWatchStatus(value) {
  const labels = {
    ready: "接近可买",
    waiting_pullback: "等待回调",
    watch: "继续观察",
    blocked: "暂不买入",
    in_position: "已进入持仓",
    removed: "已移出"
  };
  return labels[value] || labels.watch;
}

async function submitPortfolioOrders(db, actions, profiles, run, config = getEffectiveConfig()) {
  const profileByCode = new Map((profiles || []).map((profile) => [profile.code, profile]));
  const orders = [];
  const notes = [];
  cancelDuplicatePortfolioActiveOrders(db);
  recalculatePortfolioAccount(db.account);

  for (const [index, action] of actions.entries()) {
    assertPortfolioRunActive(run);
    if (index > 0) {
      await yieldToEventLoop();
    }
    markPortfolioRunProgress(
      db,
      run,
      `正在校验交易规则并生成虚拟订单（${index + 1}/${actions.length} ${action.action} ${action.code || action.name || ""}）。`
    );
    await yieldToEventLoop();
    if (action.action === "BUY") {
      if (hasActivePortfolioOrderForAction(db.orders, action, "BUY")) {
        notes.push({
          action: "BUY",
          code: action.code,
          name: action.name,
          status: "skipped",
          reason: "已有同一基金未完成申购订单，本轮不重复提交。",
          originalAction: action
        });
        continue;
      }
      const profile = profileByCode.get(action.code);
      const nav = getProfileNav(profile);
      if (!action.code) {
        notes.push({ action: "BUY", status: "skipped", reason: "缺少基金代码，无法提交申购申请。", originalAction: action });
        continue;
      }
      if (!nav) {
        notes.push({
          action: "BUY",
          code: action.code,
          name: action.name || profile?.name || "",
          status: "skipped",
          reason: "未抓取到可验证单位净值，不提交申购申请。",
          originalAction: action
        });
        continue;
      }
      const existingPosition = db.account.positions.find((item) => item.code === action.code);
      if (existingPosition?.units) {
        existingPosition.currentValue = round(Number(existingPosition.units || 0) * nav, 2);
        existingPosition.lastNav = nav;
        existingPosition.lastNavDate = profile?.snapshotDate || existingPosition.lastNavDate || "";
        existingPosition.fundSnapshot = buildPortfolioFundSnapshot(profile, existingPosition);
        recalculatePortfolioAccount(db.account);
      }
      const amount = resolvePortfolioTradeAmount(db.account, action, "BUY", null, profile);
      if (amount <= 0) {
        notes.push({
          action: "BUY",
          code: action.code,
          name: action.name || profile?.name || "",
          status: "skipped",
          reason: "目标仓位未高于当前持仓，或现金不足，未执行买入。",
          originalAction: action
        });
        continue;
      }
      const order = createPortfolioOrder({
        side: "BUY",
        action,
        amount,
        profile,
        run,
        config
      });
      db.account.cash = round(Number(db.account.cash || 0) - amount, 2);
      db.account.pendingBuyAmount = round(Number(db.account.pendingBuyAmount || 0) + amount, 2);
      db.orders.push(order);
      orders.push(order);
    }

    if (action.action === "SELL") {
      if (hasActivePortfolioOrderForAction(db.orders, action, "SELL")) {
        notes.push({
          action: "SELL",
          code: action.code,
          name: action.name,
          status: "skipped",
          reason: "已有同一基金未完成赎回订单，本轮不重复提交。",
          originalAction: action
        });
        continue;
      }
      const position = db.account.positions.find((item) => item.code === action.code);
      if (!position || Number(position.currentValue || 0) <= 0) {
        notes.push({
          action: "SELL",
          code: action.code,
          name: action.name,
          status: "skipped",
          reason: "组合中没有这只基金的可卖持仓。",
          originalAction: action
        });
        continue;
      }
      const profile = profileByCode.get(action.code);
      const nav = getProfileNav(profile) || position.lastNav || null;
      if (!nav) {
        notes.push({
          action: "SELL",
          code: action.code,
          name: position.name || action.name,
          status: "skipped",
          reason: "缺少当前净值，无法计算赎回份额，未提交赎回申请。",
          originalAction: action
        });
        continue;
      }
      if (position.units) {
        position.currentValue = round(Number(position.units || 0) * nav, 2);
        position.lastNav = nav;
        position.lastNavDate = profile?.snapshotDate || position.lastNavDate || "";
        position.fundSnapshot = buildPortfolioFundSnapshot(profile, position);
        recalculatePortfolioAccount(db.account);
      }
      const amount = resolvePortfolioTradeAmount(db.account, action, "SELL", position);
      if (amount <= 0) {
        notes.push({
          action: "SELL",
          code: action.code,
          name: position.name || action.name,
          status: "skipped",
          reason: "目标仓位未低于当前持仓，未执行卖出。",
          originalAction: action
        });
        continue;
      }
      const ratio = amount / Number(position.currentValue || 1);
      const requestedUnits = round(Number(position.units || 0) * ratio, 6);
      const order = createPortfolioOrder({
        side: "SELL",
        action,
        amount,
        units: requestedUnits,
        profile,
        position,
        run,
        config
      });
      position.pendingSellUnits = round(Number(position.pendingSellUnits || 0) + requestedUnits, 6);
      position.pendingSellAmount = round(Number(position.pendingSellAmount || 0) + amount, 2);
      position.updatedAt = new Date().toISOString();
      db.orders.push(order);
      orders.push(order);
    }
  }

  db.account.positions = db.account.positions.filter((position) => Number(position.currentValue || 0) > 0.5);
  recalculatePortfolioAccount(db.account);
  return { orders, notes };
}

function createPortfolioOrder({ side, action, amount, units = 0, profile, position = null, run, config }) {
  const submittedAt = new Date();
  const tradingProfile = inferFundTradingProfile(profile, action);
  const submission = buildFundOrderSchedule(submittedAt, tradingProfile, config);
  const limitCheck = buildFundLimitCheck(profile, amount, tradingProfile);
  const code = action.code || profile?.code || position?.code || "";
  const name = action.name || profile?.name || position?.name || "";
  return {
    id: createId("ord"),
    runId: run.id,
    side,
    status: submission.status,
    code,
    name,
    amount: round(amount, 2),
    requestedUnits: units ? round(units, 6) : 0,
    targetWeightPct: action.targetWeightPct || 0,
    submittedAt: submittedAt.toISOString(),
    submitDate: submission.submitDate,
    acceptedDate: submission.acceptedDate,
    priceDate: submission.priceDate,
    confirmDate: side === "BUY" ? submission.buyConfirmDate : submission.sellConfirmDate,
    settlementDate: side === "SELL" ? submission.sellSettlementDate : "",
    cutoffTime: tradingProfile.cutoffTime,
    beforeCutoff: submission.beforeCutoff,
    scheduleReason: submission.reason,
    tradingProfile,
    limitCheck,
    reason: action.reason,
    dataBasis: action.dataBasis,
    riskControl: action.riskControl,
    fundSnapshot: buildPortfolioFundSnapshot(profile, position),
    navSnapshot: null,
    timeline: [
      {
        at: submittedAt.toISOString(),
        status: submission.status,
        note: submission.reason
      }
    ],
    source: profile?.sources?.[0] || ""
  };
}

async function processPortfolioOrderLifecycle(db, run, config = getEffectiveConfig()) {
  ensurePortfolioAccount(db, config);
  db.orders = Array.isArray(db.orders) ? db.orders : [];
  db.settlements = Array.isArray(db.settlements) ? db.settlements : [];

  const now = getZonedDateTime(config.portfolioTimezone);
  const result = {
    transactions: [],
    orderUpdates: [],
    settlementEvents: [],
    notes: [],
    updatedOrders: 0
  };

  dedupePortfolioSettlements(db, result);
  repairDuplicatePortfolioTransactions(db, result);
  for (const settlement of db.settlements) {
    if (settlement.status !== "pending") continue;
    if (settlement.dueDate && settlement.dueDate <= now.date) {
      settlement.status = "settled";
      settlement.settledAt = new Date().toISOString();
      db.account.cash = round(Number(db.account.cash || 0) + Number(settlement.amount || 0), 2);
      db.account.receivableCash = round(Math.max(0, Number(db.account.receivableCash || 0) - Number(settlement.amount || 0)), 2);
      result.settlementEvents.push(settlement);
      result.updatedOrders += 1;
    }
  }

  cancelDuplicatePortfolioActiveOrders(db, result);
  const activeOrders = db.orders.filter((order) => !["confirmed", "cancelled", "rejected", "settled"].includes(order.status));
  if (!activeOrders.length) {
    syncPortfolioActiveOrderReservations(db);
    recalculatePortfolioAccount(db.account);
    return result;
  }

  const profileCodes = mergeFundCodes(activeOrders.map((order) => order.code));
  const profiles = profileCodes.length ? await enrichFunds(profileCodes, { limit: getPortfolioProfileEnrichmentLimit() }) : [];
  const profileByCode = new Map(profiles.map((profile) => [profile.code, profile]));

  for (const order of activeOrders) {
    const beforeStatus = order.status;
    const profile = profileByCode.get(order.code);

    if (order.status === "queued" && order.acceptedDate <= now.date) {
      order.status = "submitted";
      addOrderTimeline(order, "submitted", `已到达估值交易日 ${order.acceptedDate}，等待净值。`);
    }

    if (order.confirmDate <= now.date && shouldRejectImpossiblePortfolioSellOrder(db, order)) {
      rejectImpossiblePortfolioSellOrder(order, result);
      continue;
    }

    if (!order.navSnapshot && order.priceDate <= now.date) {
      const navSnapshot = await resolveOrderNavSnapshot(order, profile).catch((error) => {
        result.notes.push({
          action: order.side,
          code: order.code,
          name: order.name,
          status: "pending",
          reason: `净值抓取失败：${error.message}`
        });
        return null;
      });
      if (navSnapshot?.nav) {
        order.navSnapshot = navSnapshot;
        order.status = "priced";
        order.fundSnapshot = buildPortfolioFundSnapshot(profile) || order.fundSnapshot;
        addOrderTimeline(order, "priced", `已取得 ${navSnapshot.date} 单位净值 ${navSnapshot.nav}，等待 ${order.confirmDate} 确认。`);
      } else if (order.acceptedDate < now.date) {
        addOrderTimeline(order, order.status, `仍未取得估值日 ${order.priceDate} 的可验证净值，暂不确认。`);
      }
    }

    if (order.navSnapshot?.nav && order.confirmDate <= now.date && order.status !== "confirmed") {
      if (hasPortfolioTransactionForOrderDedupe(db, order, run)) {
        rejectDuplicatePortfolioConfirmOrder(db, order, result);
        continue;
      }
      const transaction =
        order.side === "BUY"
          ? confirmPortfolioBuyOrder(db, order, profile, run)
          : confirmPortfolioSellOrder(db, order, profile, run);
      if (transaction) {
        result.transactions.push(transaction);
        result.updatedOrders += 1;
      }
    }

    if (beforeStatus !== order.status) {
      result.orderUpdates.push({
        id: order.id,
        code: order.code,
        name: order.name,
        side: order.side,
        beforeStatus,
        afterStatus: order.status,
        priceDate: order.priceDate,
        confirmDate: order.confirmDate
      });
      result.updatedOrders += 1;
    }
  }

  cancelStalePortfolioActiveOrders(db, result, now.date);
  syncPortfolioActiveOrderReservations(db);
  recalculatePortfolioAccount(db.account);
  return result;
}

function shouldRejectImpossiblePortfolioSellOrder(db = {}, order = {}) {
  if (String(order.side || "").toUpperCase() !== "SELL") return false;
  const position = (db.account?.positions || []).find((item) => item.code === order.code);
  if (!position) return true;
  const requestedUnits = Number(order.requestedUnits || 0);
  const positionUnits = Number(position.units || 0);
  return !Number.isFinite(requestedUnits)
    || requestedUnits <= 0
    || !Number.isFinite(positionUnits)
    || positionUnits <= 0;
}

function rejectImpossiblePortfolioSellOrder(order = {}, result = null) {
  const beforeStatus = order.status;
  order.status = "rejected";
  order.rejectedAt = new Date().toISOString();
  order.rejectionReason = "赎回确认时已无可卖持仓或份额，系统自动作废该旧订单。";
  addOrderTimeline(order, "rejected", order.rejectionReason);
  if (result) {
    result.notes.push({
      action: order.side,
      code: order.code,
      name: order.name,
      status: "rejected",
      reason: order.rejectionReason
    });
    result.orderUpdates.push({
      id: order.id,
      code: order.code,
      name: order.name,
      side: order.side,
      beforeStatus,
      afterStatus: order.status,
      priceDate: order.priceDate,
      confirmDate: order.confirmDate
    });
    result.updatedOrders += 1;
  }
}

function hasPortfolioTransactionForOrderDedupe(db = {}, order = {}, run = {}) {
  const key = getPortfolioTransactionDedupeKey({
    date: run.date || order.confirmDate || order.priceDate || order.submittedAt,
    side: order.side,
    code: order.code
  });
  if (!key) return false;
  return (db.transactions || []).some((transaction) =>
    !transaction.reversed
    && getPortfolioTransactionDedupeKey(transaction) === key
  );
}

function repairDuplicatePortfolioTransactions(db = {}, result = null) {
  db.transactions = Array.isArray(db.transactions) ? db.transactions : [];
  const duplicateGroups = findDuplicatePortfolioTradeGroups(db.transactions);
  const reversed = [];
  for (const group of duplicateGroups) {
    const sorted = [...(group.transactions || [])].sort(comparePortfolioTransactionPriorityForDedupe);
    const keep = sorted[0];
    for (const transaction of sorted.slice(1)) {
      if (!transaction || transaction.reversed) continue;
      transaction.reversed = true;
      transaction.reversedAt = new Date().toISOString();
      transaction.reversalReason = `同一交易日同一基金同方向已有成交 ${keep.id || keep.orderId || ""}，本条标记为重复成交冲销，保留审计但不再参与能力诊断。`;
      reversed.push(transaction);
      if (result) {
        result.notes.push({
          action: transaction.side,
          code: transaction.code,
          name: transaction.name,
          status: "reversed",
          reason: transaction.reversalReason
        });
        result.updatedOrders += 1;
      }
    }
  }
  if (reversed.length) {
    db.updatedAt = new Date().toISOString();
  }
  return reversed;
}

function comparePortfolioTransactionPriorityForDedupe(a = {}, b = {}) {
  const orderEvidenceDiff = (a.orderId ? 0 : 1) - (b.orderId ? 0 : 1);
  if (orderEvidenceDiff) return orderEvidenceDiff;
  return String(a.createdAt || a.date || "").localeCompare(String(b.createdAt || b.date || ""))
    || String(a.id || "").localeCompare(String(b.id || ""));
}

function getPortfolioTransactionDedupeKey(value = {}) {
  const date = normalizePortfolioEventDate(value.date || value.navDate || value.createdAt || value.confirmedAt);
  const side = String(value.side || value.action || "").toUpperCase();
  const code = String(value.code || "").trim();
  return date && side && code && ["BUY", "SELL"].includes(side) ? `${date}|${side}|${code}` : "";
}

function rejectDuplicatePortfolioConfirmOrder(db = {}, order = {}, result = null) {
  const beforeStatus = order.status || "";
  order.status = "rejected";
  order.rejectedAt = new Date().toISOString();
  order.rejectionReason = "同一交易日同一基金同方向已有确认成交，系统拒绝重复确认，避免虚拟账本重复买卖。";
  releasePortfolioOrderReservation(db, order);
  addOrderTimeline(order, "rejected", order.rejectionReason);
  if (result) {
    result.notes.push({
      action: order.side,
      code: order.code,
      name: order.name,
      status: "rejected",
      reason: order.rejectionReason
    });
    result.orderUpdates.push({
      id: order.id,
      code: order.code,
      name: order.name,
      side: order.side,
      beforeStatus,
      afterStatus: order.status,
      priceDate: order.priceDate,
      confirmDate: order.confirmDate
    });
    result.updatedOrders += 1;
  }
}

function dedupePortfolioSettlements(db = {}, result = null) {
  db.settlements = Array.isArray(db.settlements) ? db.settlements : [];
  if (!db.account || typeof db.account !== "object") db.account = {};
  const groups = findDuplicatePortfolioSettlementGroups(db.settlements);
  const cancelled = [];
  for (const group of groups) {
    const sorted = [...group.settlements].sort(comparePortfolioSettlementPriority);
    const keep = sorted[0];
    for (const settlement of sorted.slice(1)) {
      if (settlement.status === "cancelled") continue;
      const beforeStatus = settlement.status || "";
      settlement.status = "cancelled";
      settlement.cancelledAt = new Date().toISOString();
      settlement.cancellationReason = `同一赎回订单 ${group.key} 已保留 ${keep.id || "较早记录"}，本条重复应收作废。`;
      if (beforeStatus === "pending") {
        db.account.receivableCash = round(Math.max(0, Number(db.account.receivableCash || 0) - Number(settlement.amount || 0)), 2);
      }
      cancelled.push(settlement);
      if (result) {
        result.notes.push({
          action: "SETTLEMENT",
          code: settlement.code,
          name: settlement.name,
          status: "cancelled",
          reason: settlement.cancellationReason
        });
        result.updatedOrders += 1;
      }
    }
  }
  return cancelled;
}

function findDuplicatePortfolioSettlementGroups(settlements = []) {
  const groups = new Map();
  for (const settlement of settlements || []) {
    if (!settlement || settlement.status === "cancelled") continue;
    const key = getPortfolioSettlementDedupeKey(settlement);
    if (!key) continue;
    if (!groups.has(key)) groups.set(key, { key, settlements: [] });
    groups.get(key).settlements.push(settlement);
  }
  return [...groups.values()].filter((group) => group.settlements.length > 1);
}

function getPortfolioSettlementDedupeKey(settlement = {}) {
  if (settlement.orderId) return `order:${settlement.orderId}`;
  const code = String(settlement.code || "").trim();
  const dueDate = normalizePortfolioEventDate(settlement.dueDate || settlement.date || settlement.createdAt);
  const amount = round(Number(settlement.amount || 0), 2);
  if (!code || !dueDate || !Number.isFinite(amount) || amount <= 0) return "";
  return `fallback:${code}|${dueDate}|${amount}`;
}

function comparePortfolioSettlementPriority(a = {}, b = {}) {
  const statusRank = { settled: 0, pending: 1, cancelled: 2 };
  const rankDiff = (statusRank[a.status] ?? 9) - (statusRank[b.status] ?? 9);
  if (rankDiff) return rankDiff;
  return String(a.createdAt || a.settledAt || "").localeCompare(String(b.createdAt || b.settledAt || ""));
}

function findPortfolioSettlementForOrder(settlements = [], orderId = "") {
  const id = String(orderId || "").trim();
  if (!id) return null;
  return (settlements || []).find((settlement) =>
    settlement?.orderId === id && ["pending", "settled"].includes(String(settlement.status || ""))
  ) || null;
}

async function resolveOrderNavSnapshot(order, profile) {
  const profileNav = getProfileNav(profile);
  if (profileNav && profile?.snapshotDate === order.priceDate) {
    return {
      date: profile.snapshotDate,
      nav: round(profileNav, 4),
      source: profile.sources?.[0] || "",
      quality: "exact_profile_nav"
    };
  }

  const point = await fetchFundNavPointForDate(order.code, order.priceDate);
  if (point?.unitNav) {
    return {
      date: point.date,
      nav: round(point.unitNav, 4),
      cumulativeNav: point.cumulativeNav,
      source: `https://fund.eastmoney.com/f10/F10DataApi.aspx?type=lsjz&code=${order.code}`,
      quality: point.date === order.priceDate ? "exact_nav_history" : "nearest_nav_history"
    };
  }

  return null;
}

function confirmPortfolioBuyOrder(db, order, profile, run) {
  const nav = Number(order.navSnapshot?.nav || 0);
  if (!nav) return null;

  let position = db.account.positions.find((item) => item.code === order.code);
  if (!position) {
    position = {
      code: order.code,
      name: order.name || profile?.name || "",
      units: 0,
      costAmount: 0,
      currentValue: 0,
      realizedPnl: 0,
      createdAt: new Date().toISOString()
    };
    db.account.positions.push(position);
  }

  const previousUnits = Number(position.units || 0);
  const boughtUnits = Number(order.amount || 0) / nav;
  position.name = order.name || position.name || profile?.name || "";
  position.units = round(previousUnits + boughtUnits, 6);
  position.costAmount = round(Number(position.costAmount || 0) + Number(order.amount || 0), 2);
  position.currentValue = round(position.units * nav, 2);
  position.averageCostNav = position.units > 0 ? round(position.costAmount / position.units, 4) : null;
  position.lastNav = nav;
  position.lastNavDate = order.navSnapshot.date;
  position.lastTradeNav = nav;
  position.lastTradeUnits = round(boughtUnits, 6);
  position.lastTradeAmount = order.amount;
  position.lastReason = order.reason;
  position.lastRiskControl = order.riskControl;
  position.fundSnapshot = buildPortfolioFundSnapshot(profile, position) || order.fundSnapshot;
  position.dataSource = profile?.sources?.[0] || order.source || "";
  position.updatedAt = new Date().toISOString();
  accountUpdateInvestedCostBasis(db.account);

  db.account.pendingBuyAmount = round(Math.max(0, Number(db.account.pendingBuyAmount || 0) - Number(order.amount || 0)), 2);
  order.status = "confirmed";
  order.confirmedAt = new Date().toISOString();
  order.actualAmount = round(Number(order.amount || 0), 2);
  order.confirmedNav = nav;
  order.confirmedNavDate = order.navSnapshot.date;
  order.confirmedUnits = round(boughtUnits, 6);
  order.navQuality = order.navSnapshot.quality || "";
  order.navSource = order.navSnapshot.source || "";
  addOrderTimeline(order, "confirmed", `申购确认：${order.amount}元 / ${nav} = ${round(boughtUnits, 6)}份。`);

  return recordPortfolioTransaction(db, run, order, order.amount, "BUY", profile, {
    nav,
    navDate: order.navSnapshot.date,
    units: boughtUnits,
    beforeUnits: previousUnits,
    afterUnits: position.units,
    order
  });
}

function confirmPortfolioSellOrder(db, order, profile, run) {
  const nav = Number(order.navSnapshot?.nav || 0);
  const position = db.account.positions.find((item) => item.code === order.code);
  if (!nav || !position) return null;

  const requestedUnits = Math.min(Number(order.requestedUnits || 0), Number(position.units || 0));
  if (requestedUnits <= 0) return null;

  const previousUnits = Number(position.units || 0);
  const amount = round(requestedUnits * nav, 2);
  const ratio = requestedUnits / Number(position.units || 1);
  const costReduced = round(Number(position.costAmount || 0) * ratio, 2);
  position.costAmount = round(Number(position.costAmount || 0) - costReduced, 2);
  position.currentValue = round(Math.max(0, Number(position.currentValue || 0) - amount), 2);
  position.units = round(Number(position.units || 0) - requestedUnits, 6);
  position.averageCostNav = position.units > 0 ? round(position.costAmount / position.units, 4) : null;
  position.realizedPnl = round(Number(position.realizedPnl || 0) + amount - costReduced, 2);
  position.pendingSellUnits = round(Math.max(0, Number(position.pendingSellUnits || 0) - requestedUnits), 6);
  position.pendingSellAmount = round(Math.max(0, Number(position.pendingSellAmount || 0) - Number(order.amount || 0)), 2);
  position.lastNav = nav;
  position.lastNavDate = order.navSnapshot.date;
  position.lastTradeNav = nav;
  position.lastTradeUnits = requestedUnits;
  position.lastTradeAmount = amount;
  position.lastReason = order.reason;
  position.lastRiskControl = order.riskControl;
  position.fundSnapshot = buildPortfolioFundSnapshot(profile, position) || order.fundSnapshot;
  position.dataSource = profile?.sources?.[0] || order.source || "";
  position.updatedAt = new Date().toISOString();
  accountUpdateInvestedCostBasis(db.account);

  const existingSettlement = findPortfolioSettlementForOrder(db.settlements, order.id);
  if (!existingSettlement) {
    db.account.receivableCash = round(Number(db.account.receivableCash || 0) + amount, 2);
    const settlement = {
      id: createId("set"),
      orderId: order.id,
      runId: run.id,
      code: order.code,
      name: order.name,
      amount,
      dueDate: order.settlementDate,
      status: "pending",
      createdAt: new Date().toISOString()
    };
    db.settlements.push(settlement);
  }
  order.status = "confirmed";
  order.confirmedAt = new Date().toISOString();
  order.actualAmount = amount;
  order.confirmedNav = nav;
  order.confirmedNavDate = order.navSnapshot.date;
  order.confirmedUnits = round(requestedUnits, 6);
  order.navQuality = order.navSnapshot.quality || "";
  order.navSource = order.navSnapshot.source || "";
  addOrderTimeline(order, "confirmed", `赎回确认：${requestedUnits}份 * ${nav} = ${amount}元，预计 ${order.settlementDate} 到账。`);

  return recordPortfolioTransaction(db, run, order, amount, "SELL", profile, {
    nav,
    navDate: order.navSnapshot.date,
    units: requestedUnits,
    beforeUnits: previousUnits,
    afterUnits: position.units,
    order
  });
}

function addOrderTimeline(order, status, note) {
  order.timeline = Array.isArray(order.timeline) ? order.timeline : [];
  const latest = order.timeline[order.timeline.length - 1];
  if (latest?.status === status && latest?.note === note) {
    return;
  }
  order.timeline.push({
    at: new Date().toISOString(),
    status,
    note
  });
}

function recordPortfolioTransaction(db, run, action, amount, side, profile, execution = {}) {
  const transaction = {
    id: createId("txn"),
    runId: run.id,
    date: run.date,
    createdAt: new Date().toISOString(),
    side,
    code: action.code,
    name: action.name || profile?.name || "",
    amount: round(amount, 2),
    nav: execution.nav ? round(Number(execution.nav), 4) : null,
    navDate: execution.navDate || profile?.snapshotDate || "",
    units: execution.units ? round(Number(execution.units), 6) : 0,
    beforeUnits: execution.beforeUnits === undefined ? null : round(Number(execution.beforeUnits || 0), 6),
    afterUnits: execution.afterUnits === undefined ? null : round(Number(execution.afterUnits || 0), 6),
    reason: action.reason,
    dataBasis: action.dataBasis,
    riskControl: action.riskControl,
    fundSnapshot: buildPortfolioFundSnapshot(profile),
    orderId: execution.order?.id || "",
    orderStatus: execution.order?.status || "",
    source: profile?.sources?.[0] || action.source || ""
  };
  db.transactions.push(transaction);
  return transaction;
}

function resolvePortfolioTradeAmount(account, action, side, position = null, profile = null) {
  const totalAsset = Number(account.totalAsset || 0);
  const targetWeightPct = Number(action.targetWeightPct || 0);
  const requestedAmount = Number(action.amount || 0);

  if (side === "BUY") {
    const currentPosition = (account.positions || []).find((item) => item.code === action.code);
    const currentValue = Number(currentPosition?.currentValue || 0);
    const targetValue = targetWeightPct > 0 ? (totalAsset * targetWeightPct) / 100 : null;
    const targetDelta = targetValue === null ? requestedAmount : Math.max(0, targetValue - currentValue);
    const proposedAmount = requestedAmount > 0 && targetDelta > 0 ? Math.min(requestedAmount, targetDelta) : targetDelta;
    const cashLimitedAmount = Math.min(Number(account.cash || 0), Math.max(0, proposedAmount || 0));
    return capPortfolioBuyAmountByDiscipline(account, action, cashLimitedAmount, currentValue, profile);
  }

  if (side === "SELL") {
    const currentValue = Number(position?.currentValue || 0);
    const targetValue = targetWeightPct > 0 ? (totalAsset * targetWeightPct) / 100 : null;
    const targetDelta = targetValue === null ? requestedAmount : Math.max(0, currentValue - targetValue);
    const proposedAmount = requestedAmount > 0 && targetDelta > 0 ? Math.min(requestedAmount, targetDelta) : targetDelta;
    const positionLimitedAmount = Math.min(currentValue, Math.max(0, proposedAmount || 0));
    return capPortfolioSellAmountByDiscipline(account, action, positionLimitedAmount, position);
  }

  return 0;
}

function capPortfolioBuyAmountByDiscipline(account = {}, action = {}, amount = 0, currentValue = 0, profile = null) {
  const totalAsset = Number(account.totalAsset || 0);
  const cash = Number(account.cash || 0);
  if (!Number.isFinite(totalAsset) || totalAsset <= 0 || !Number.isFinite(cash) || cash <= 0) return 0;
  const maxSingleFundWeightPct = finiteNumberOr(process.env.PORTFOLIO_BUY_MAX_SINGLE_FUND_WEIGHT_PCT, 6);
  const maxSingleOrderWeightPct = finiteNumberOr(process.env.PORTFOLIO_BUY_MAX_SINGLE_ORDER_WEIGHT_PCT, 4);
  const starterMaxSingleOrderWeightPct = finiteNumberOr(process.env.PORTFOLIO_STARTER_BUY_MAX_SINGLE_ORDER_WEIGHT_PCT, 2.5);
  const themeMicroStarterMaxSingleOrderWeightPct = finiteNumberOr(process.env.PORTFOLIO_THEME_MICRO_STARTER_MAX_SINGLE_ORDER_WEIGHT_PCT, 1.2);
  const maxSameExposureWeightPct = finiteNumberOr(process.env.PORTFOLIO_BUY_MAX_SAME_EXPOSURE_WEIGHT_PCT, 8);
  const minCashReservePct = finiteNumberOr(process.env.PORTFOLIO_BUY_MIN_CASH_RESERVE_PCT, 20);
  const accountBudget = buildPortfolioAccountRiskBudget(account);
  if (accountBudget.blockNewBuys) return 0;
  const drawdownThrottleWeightPct = accountBudget.throttleNewBuys
    ? Math.max(0, finiteNumberOr(process.env.PORTFOLIO_DRAWDOWN_BUY_MAX_SINGLE_ORDER_WEIGHT_PCT, 1))
    : maxSingleOrderWeightPct;
  const setupMaxSingleOrderWeightPct = hasPortfolioThemeMicroStarterSetup(profile)
    ? Math.min(maxSingleOrderWeightPct, themeMicroStarterMaxSingleOrderWeightPct)
    : hasPortfolioStarterBuySetup(profile) && !hasVerifiedPortfolioBuySetup(profile)
      ? Math.min(maxSingleOrderWeightPct, starterMaxSingleOrderWeightPct)
      : maxSingleOrderWeightPct;
  const maxSingleFundValue = Math.max(0, totalAsset * maxSingleFundWeightPct / 100);
  const maxSingleOrderAmount = Math.max(0, totalAsset * Math.min(setupMaxSingleOrderWeightPct, drawdownThrottleWeightPct) / 100);
  const maxSameExposureValue = Math.max(0, totalAsset * maxSameExposureWeightPct / 100);
  const minCashReserve = Math.max(0, totalAsset * minCashReservePct / 100);
  const availableAfterReserve = Math.max(0, cash - minCashReserve);
  const remainingFundRoom = Math.max(0, maxSingleFundValue - Number(currentValue || 0));
  const sameExposureValue = getPortfolioSameExposureValue(account.positions || [], profile || action);
  const remainingExposureRoom = sameExposureValue > 0
    ? Math.max(0, maxSameExposureValue - sameExposureValue)
    : maxSameExposureValue;
  const capped = Math.min(
    Math.max(0, Number(amount || 0)),
    maxSingleOrderAmount,
    remainingFundRoom,
    remainingExposureRoom,
    availableAfterReserve
  );
  return round(capped, 2);
}

function capPortfolioSellAmountByDiscipline(account = {}, action = {}, amount = 0, position = null) {
  const totalAsset = Number(account.totalAsset || 0);
  const currentValue = Number(position?.currentValue || 0);
  if (!Number.isFinite(totalAsset) || totalAsset <= 0 || !Number.isFinite(currentValue) || currentValue <= 0) return 0;
  const severe = isSeverePortfolioSellAction(action);
  const maxPositionPct = severe
    ? finiteNumberOr(process.env.PORTFOLIO_SELL_SEVERE_MAX_POSITION_PCT, 80)
    : finiteNumberOr(process.env.PORTFOLIO_SELL_MAX_POSITION_PCT, 50);
  const maxSingleOrderWeightPct = severe
    ? finiteNumberOr(process.env.PORTFOLIO_SELL_SEVERE_MAX_SINGLE_ORDER_WEIGHT_PCT, 8)
    : finiteNumberOr(process.env.PORTFOLIO_SELL_MAX_SINGLE_ORDER_WEIGHT_PCT, 6);
  const maxPositionAmount = Math.max(0, currentValue * maxPositionPct / 100);
  const maxSingleOrderAmount = Math.max(0, totalAsset * maxSingleOrderWeightPct / 100);
  const capped = Math.min(
    Math.max(0, Number(amount || 0)),
    currentValue,
    maxPositionAmount,
    maxSingleOrderAmount
  );
  return round(capped, 2);
}

function isSeverePortfolioSellAction(action = {}) {
  const text = [
    action.reason,
    action.rotationCheck,
    action.positionCheck,
    action.chaseRisk,
    action.riskControl,
    ...(action.dataBasis || [])
  ].filter(Boolean).join(" ");
  return /(破位|止损|回避|假设失效|风控|风险失效|清仓)/.test(text);
}

function buildPortfolioFundSnapshot(profile, position = null) {
  if (!profile) {
    return null;
  }

  const nav = getProfileNav(profile);
  const periods = profile.riskMetrics?.periods || {};
  const oneYear = periods["1y"] || {};
  const threeYear = periods["3y"] || {};
  const fiveYear = periods["5y"] || {};
  const trendProfile = profile.trendProfile || null;
  const actionability = profile.actionability || null;
  const topHoldings = (profile.holdings?.equityTopHoldings || profile.topHoldings || profile.topStocks || []).slice(0, 10).map((item) => {
    if (typeof item === "string") return item;
    return [item.code, item.name, item.netValuePct ? `${item.netValuePct}%` : ""].filter(Boolean).join(" ");
  });

  return {
    code: profile.code || position?.code || "",
    name: profile.name || position?.name || "",
    nav: nav ? round(nav, 4) : null,
    navDate: profile.snapshotDate || "",
    navBasis: profile.unitNav ? "latest_confirmed_unit_nav" : profile.estimatedNav ? "estimated_nav" : "missing",
    estimatedNav: toNumber(profile.estimatedNav),
    estimatedChangePct: toNumber(profile.estimatedChangePct),
    estimateTime: profile.estimateTime || "",
    returns: profile.returns || {},
    risk: {
      oneYear: pickRiskPeriod(oneYear),
      threeYear: pickRiskPeriod(threeYear),
      fiveYear: pickRiskPeriod(fiveYear)
    },
    trendProfile,
    actionability,
    matchedThemes: Array.isArray(profile.matchedThemes) ? profile.matchedThemes : [],
    marketThemeRefresh: profile.marketThemeRefresh || null,
    holdingThemeRefresh: profile.holdingThemeRefresh || null,
    holdingsOutlook: profile.holdingsOutlook || profile.actionability?.holdingsOutlook || null,
    fees: profile.fees ? {
      shareClass: profile.fees.shareClass || profile.shareClass || "",
      shareClassFeeModel: profile.fees.shareClassFeeModel || profile.shareClassFeeModel || null,
      currentRatePct: profile.fees.currentRatePct || "",
      salesServiceFeePct: profile.fees.salesServiceFeePct || "",
      feeImpact: profile.fees.feeImpact || null,
      feeDecisionRule: profile.fees.feeDecisionRule || "",
      missingFeeData: profile.fees.missingFeeData || []
    } : null,
    scale: profile.scale || null,
    holdingRealtimePulse: compactFundHoldingRealtimePulse(profile.holdingRealtimePulse),
    topHoldings,
    trendSummary: buildPortfolioTrendSummary({ trendProfile, actionability, oneYear, threeYear, profile }),
    sources: profile.sources || []
  };
}

function buildPortfolioTrendSummary({ trendProfile, actionability, oneYear = {}, threeYear = {}, profile = {} }) {
  if (trendProfile?.ok) {
    const parts = [
      trendProfile.return20dPct !== null && trendProfile.return20dPct !== undefined ? `20日${formatSignedNumber(trendProfile.return20dPct)}%` : "",
      trendProfile.return60dPct !== null && trendProfile.return60dPct !== undefined ? `60日${formatSignedNumber(trendProfile.return60dPct)}%` : "",
      trendProfile.return120dPct !== null && trendProfile.return120dPct !== undefined ? `120日${formatSignedNumber(trendProfile.return120dPct)}%` : "",
      trendProfile.drawdownFromRecentHighPct !== null && trendProfile.drawdownFromRecentHighPct !== undefined ? `距高点${formatSignedNumber(trendProfile.drawdownFromRecentHighPct)}%` : "",
      `趋势${formatTrendLabel(trendProfile.trendLabel)}`,
      `入场${formatEntryBiasForCandidate(trendProfile.entryBias, profile)}`,
      hasThemeRetreatNoBuyOverride(profile) ? "题材退潮/主力撤离，回调不作为买点" : "",
      actionability?.action ? `自评${formatActionabilityAction(actionability.action)}${actionability.allocationBand ? ` ${actionability.allocationBand}` : ""}` : ""
    ].filter(Boolean);
    return parts.join("，");
  }

  const trendParts = [
    oneYear.ok ? `1年${formatSignedNumber(oneYear.totalReturnPct)}%` : "",
    threeYear.ok ? `3年${formatSignedNumber(threeYear.totalReturnPct)}%` : "",
    oneYear.ok ? `回撤${oneYear.maxDrawdownPct}%` : "",
    oneYear.ok && oneYear.sharpe !== null ? `夏普${oneYear.sharpe}` : ""
  ].filter(Boolean);
  return trendParts.join("，") || "走势数据不足";
}

function formatTrendLabel(value) {
  const labels = {
    breakdown: "破位",
    extended_uptrend: "偏热",
    pullback_complete: "回调完成",
    launch_setup: "启动前夜",
    rebound_repair: "修复",
    uptrend: "上行",
    weakening: "转弱",
    range_or_mixed: "震荡"
  };
  return labels[value] || value || "未知";
}

function formatEntryBias(value) {
  const labels = {
    buyable_now: "可买",
    staged_buy: "分批",
    BUY: "可买",
    BATCH: "分批",
    STAGE: "分批",
    WAIT: "等回撤",
    AVOID: "回避",
    wait_pullback: "等回撤",
    hold_observe: "持有观察",
    avoid_now: "回避"
  };
  return labels[value] || value || "观察";
}

function hasThemeRetreatNoBuyOverride(candidate = {}) {
  return Boolean(candidate && typeof candidate === "object" && (
    hasStaleThemeCatchdownRisk(candidate)
    || hasThemeRetreatRisk(candidate)
  ));
}

function formatEntryBiasForCandidate(value, candidate = {}) {
  if (hasThemeRetreatNoBuyOverride(candidate)) return "回调但不买";
  return formatEntryBias(value);
}

function formatActionabilityAction(value) {
  const labels = {
    buy: "买入",
    staged_buy: "分批",
    BUY: "买入",
    BATCH: "分批",
    STAGE: "分批",
    WAIT: "等待",
    AVOID: "回避",
    hold: "持有",
    wait: "等待",
    watch: "观察",
    avoid: "回避",
    need_specific_fund: "需具体基金"
  };
  return labels[value] || value || "观察";
}

function formatFitLabel(value) {
  const labels = {
    fit: "适合",
    tactical_only: "只适合战术小仓位",
    weak_fit: "适配度偏弱",
    not_suitable: "不适合当前买入",
    strong_fit: "高度适配"
  };
  return labels[value] || value || "观察";
}

function pickRiskPeriod(period) {
  if (!period?.ok) {
    return { ok: false, note: period?.note || "数据不足" };
  }
  return {
    ok: true,
    totalReturnPct: period.totalReturnPct,
    annualizedReturnPct: period.annualizedReturnPct,
    annualizedVolatilityPct: period.annualizedVolatilityPct,
    maxDrawdownPct: period.maxDrawdownPct,
    sharpe: period.sharpe,
    startDate: period.startDate,
    endDate: period.endDate
  };
}

function inferFundTradingProfile(profile = {}, action = {}) {
  const text = `${profile.name || ""} ${action.name || ""} ${profile.code || action.code || ""}`.toLowerCase();
  const holdings = profile.holdings || {};
  const qdii = /qdii|全球|海外|美国|纳斯达克|标普|日经|越南|印度|德国|法国|香港|港股/.test(text);
  const money = /货币|现金|添利宝|余额/.test(text);
  const bond = /债券|债基|短债|中短债|纯债|可转债/.test(text) || Boolean(holdings.bondTopHoldings?.length);
  const etf = /etf/.test(text) && !/联接/.test(text);
  const crossBorderEtf = etf && /港股|香港|纳斯达克|标普|日经|海外|qdii/.test(text);
  const kind = qdii ? "qdii_or_overseas" : money ? "money_market" : bond ? "bond" : etf ? "exchange_etf_or_feeder" : "domestic_open_end";

  return {
    kind,
    cutoffTime: "15:00",
    calendar: qdii || crossBorderEtf ? "cn_trading_day_plus_overseas_delay" : "cn_trading_day_weekend_only",
    buyConfirmLag: qdii ? 2 : 1,
    sellConfirmLag: qdii ? 2 : 1,
    sellCashLag: qdii ? 5 : money ? 1 : bond ? 2 : 3,
    navDelayDays: qdii ? 1 : 0,
    canIntradayTrade: crossBorderEtf,
    timezoneSensitive: qdii || crossBorderEtf,
    notes: [
      "模拟规则按公开基金常见申购/赎回流程处理：交易日 15:00 截止，非交易日或 15:00 后顺延。",
      qdii || crossBorderEtf ? "海外/QDII 类产品存在净值披露和确认时差，本系统会延后确认。" : "",
      etf ? "ETF/联接/场内场外规则可能不同，当前按基金申赎账本模拟，不模拟真实场内撮合。" : "",
      "节假日历、基金暂停申购、限购额度以基金公告为准；未抓到公告时只做风险标记。"
    ].filter(Boolean)
  };
}

function buildFundOrderSchedule(date, tradingProfile, config = getEffectiveConfig()) {
  const zoned = getZonedDateTime(config.portfolioTimezone);
  const submitDate = zoned.date;
  const hhmm = zoned.hhmm;
  const beforeCutoff = hhmm < tradingProfile.cutoffTime;
  let acceptedDate = submitDate;
  let reason = "交易日 15:00 前提交，按当日估值日排队。";

  if (!isPortfolioTradingDay(acceptedDate)) {
    acceptedDate = nextPortfolioTradingDay(acceptedDate);
    reason = `非交易日提交，顺延至 ${acceptedDate} 作为估值日。`;
  } else if (!beforeCutoff) {
    acceptedDate = nextPortfolioTradingDay(acceptedDate);
    reason = `15:00 后提交，顺延至 ${acceptedDate} 作为估值日。`;
  }

  const buyConfirmDate = addPortfolioTradingDays(acceptedDate, tradingProfile.buyConfirmLag);
  const sellConfirmDate = addPortfolioTradingDays(acceptedDate, tradingProfile.sellConfirmLag);
  const sellSettlementDate = addPortfolioTradingDays(sellConfirmDate, tradingProfile.sellCashLag);
  return {
    submitDate,
    acceptedDate,
    priceDate: acceptedDate,
    buyConfirmDate,
    sellConfirmDate,
    sellSettlementDate,
    beforeCutoff,
    status: acceptedDate === submitDate && beforeCutoff ? "submitted" : "queued",
    reason
  };
}

function buildFundLimitCheck(profile, amount, tradingProfile) {
  const minPurchase = toNumber(profile?.fees?.minPurchase);
  const softCap = Number(process.env.PORTFOLIO_SINGLE_ORDER_SOFT_CAP || 20000);
  return {
    status: "unknown",
    minPurchase,
    amount: round(Number(amount || 0), 2),
    softCap,
    passedSoftCap: Number(amount || 0) <= softCap,
    note:
      Number(amount || 0) > softCap
        ? `单笔超过本系统软上限 ${softCap} 元，需要复查基金公告中的限购/暂停申购。`
        : "未接入基金公司实时公告限购数据，按软上限和净值可验证性先做模拟。"
  };
}

function isPortfolioTradingDay(date) {
  const day = getDateOnlyWeekday(date);
  return day !== 0 && day !== 6;
}

function getDateOnlyWeekday(date) {
  return parseDateOnlyUtc(date).getUTCDay();
}

function nextPortfolioTradingDay(date) {
  let current = addDays(date, 1);
  let guard = 0;
  while (!isPortfolioTradingDay(current)) {
    current = addDays(current, 1);
    guard += 1;
    if (guard > 14) {
      throw new Error(`无法计算下一个交易日：${date}`);
    }
  }
  return current;
}

function addPortfolioTradingDays(date, days) {
  let current = date;
  let remaining = Math.max(0, Number(days || 0));
  while (remaining > 0) {
    current = nextPortfolioTradingDay(current);
    remaining -= 1;
  }
  return current;
}

function addDays(date, days) {
  const value = parseDateOnlyUtc(date);
  value.setUTCDate(value.getUTCDate() + Number(days || 0));
  return formatUtcDate(value);
}

function parseDateOnlyUtc(date) {
  const match = String(date || "").match(/^(\d{4})-(\d{2})-(\d{2})$/);
  if (!match) {
    throw new Error(`无效日期：${date}`);
  }
  const [, year, month, day] = match;
  return new Date(Date.UTC(Number(year), Number(month) - 1, Number(day)));
}

function formatUtcDate(date) {
  const year = date.getUTCFullYear();
  const month = String(date.getUTCMonth() + 1).padStart(2, "0");
  const day = String(date.getUTCDate()).padStart(2, "0");
  return `${year}-${month}-${day}`;
}

function formatWeekdayLabel(value) {
  const labels = ["周日", "周一", "周二", "周三", "周四", "周五", "周六"];
  return labels[normalizeWeekday(value, 5)] || "周五";
}

async function pushPortfolioRunIfConfigured(db, run, config) {
  const target = resolvePortfolioPushTarget(config, db);
  if (!target?.receiveId) {
    run.push = { ok: false, skipped: true, reason: "未配置飞书推送目标；在飞书里和机器人说一句话后可自动记录 chat_id。" };
    writePortfolioDb(db);
    return;
  }

  try {
    const trendImages = await buildPortfolioTrendCardImages(run, config).catch((error) => {
      console.warn("[portfolio-trend-image-error]", run.id, error.message);
      recordError(error, { portfolioTrendImageFailures: 1 });
      return [];
    });
    await sendFeishuMessage(target.receiveId, run.card || "虚拟基金经理任务完成。", {
      receiveIdType: target.receiveIdType || "chat_id",
      kind: "portfolio",
      images: trendImages
    });
    run.push = {
      ok: true,
      receiveIdType: target.receiveIdType || "chat_id",
      receiveId: maskSecret(target.receiveId),
      trendImages: trendImages.length,
      pushedAt: new Date().toISOString()
    };
    updateStats({ counters: { portfolioPushes: 1 }, last: { lastPortfolioPushAt: run.push.pushedAt } });
    writePortfolioDb(db);
  } catch (error) {
    run.push = { ok: false, error: error.message, failedAt: new Date().toISOString() };
    writePortfolioDb(db);
    recordError(error, { portfolioPushFailures: 1 });
  }
}

function resolvePortfolioPushTarget(config, db) {
  if (config.portfolioPushReceiveId) {
    return {
      receiveId: config.portfolioPushReceiveId,
      receiveIdType: config.portfolioPushReceiveType || "chat_id"
    };
  }
  if (config.portfolioAutoBindLastChat && db.autoPushTarget?.receiveId) {
    return db.autoPushTarget;
  }
  return null;
}

function capturePortfolioPushTarget(payload) {
  const message = payload?.event?.message;
  const chatId = message?.chat_id || "";
  if (!chatId) {
    return;
  }

  const config = getEffectiveConfig();
  const now = new Date().toISOString();
  const db = readPortfolioDb();
  db.pushTargets = Array.isArray(db.pushTargets) ? db.pushTargets : [];
  const existing = db.pushTargets.find((target) => target.receiveId === chatId && target.receiveIdType === "chat_id");
  const target = existing || {
    receiveId: chatId,
    receiveIdType: "chat_id",
    label: message.chat_type || "feishu_chat",
    firstSeenAt: now
  };
  target.lastSeenAt = now;
  target.messageId = message.message_id || "";
  if (!existing) {
    db.pushTargets.push(target);
  }
  if (config.portfolioAutoBindLastChat && !config.portfolioPushReceiveId) {
    db.autoPushTarget = {
      receiveId: chatId,
      receiveIdType: "chat_id",
      label: target.label,
      updatedAt: now
    };
  }
  db.updatedAt = now;
  writePortfolioDb(db);
}

function buildPortfolioDecisionCard({ decision, watchlistUpdates = [], account, orders = [], transactions, executionNotes = [], settlementEvents = [], run }) {
  const actionLines = decision.actions.length
    ? interspersePortfolioBlocks(decision.actions.map(formatPortfolioCustomerActionLine))
    : ["今日没有生成买卖动作。"];
  const digestLines = formatPortfolioCustomerDecisionDigest(decision, account);
  const nextStepLines = formatPortfolioCustomerNextStepLines({ decision, orders, watchlistUpdates });
  const teamLines = decision.team.map(formatPortfolioCustomerTeamLine);
  const transactionLines = transactions.length
    ? transactions.map(formatPortfolioCustomerTransactionLine)
    : ["无实际账本变动。"];
  const orderLines = orders.length
    ? orders.map(formatPortfolioCustomerOrderLine)
    : ["本次没有提交新的申购/赎回申请。"];
  const settlementLines = settlementEvents.length
    ? settlementEvents.map((item) => `${item.code} ${item.name} ${item.amount}元已到账。`)
    : [];
  const noteLines = executionNotes.length
    ? executionNotes.map((item) => `${formatPortfolioActionLabel(item.action || "SKIP")} ${item.code || ""} ${item.name || ""}：${item.reason}`)
    : [];
  const watchlistLines = watchlistUpdates.length
    ? watchlistUpdates.slice(0, 8).map(formatPortfolioWatchLine)
    : ["本次没有更新自选基金池。"];
  const riskLines = formatPortfolioCustomerNoteLines(decision.riskNotes, { maxItems: 4, maxLength: 92 });
  const learningLines = formatPortfolioCustomerNoteLines(decision.learningNotes, { maxItems: 3, maxLength: 96 });

  const card = [
    `虚拟基金经理日报 ${run.date}`,
    "",
    ...digestLines,
    "",
    `今日手法：${shortenPortfolioCustomerText(decision.summary, 110) || decision.summary}`,
    decision.marketView ? `市场判断：${shortenPortfolioCustomerText(decision.marketView, 140)}` : "",
    "",
    "投委会意见：",
    ...teamLines,
    "",
    "今日操作：",
    ...actionLines,
    nextStepLines.length ? "" : "",
    nextStepLines.length ? "下一步：" : "",
    ...nextStepLines,
    "",
    "申购/赎回申请：",
    ...orderLines,
    settlementLines.length ? "" : "",
    settlementLines.length ? "到账更新：" : "",
    ...settlementLines,
    "",
    "已确认成交：",
    ...transactionLines,
    noteLines.length ? "" : "",
    noteLines.length ? "未执行说明：" : "",
    ...noteLines,
    "",
    "自选基金池：",
    ...watchlistLines,
    "",
    formatPortfolioCustomerAccountLine(account),
    formatPortfolioCustomerDrawdownLine(account),
    riskLines.length ? ["", "风险控制：", ...riskLines].join("\n") : "",
    learningLines.length ? ["", "回溯学习点：", ...learningLines].join("\n") : "",
    "",
    `数据来源：${(run.sources || []).slice(0, 6).join("；") || "公开市场快照与基金公开资料"}`
  ]
    .filter(Boolean)
    .join("\n");
  return normalizePortfolioUserFacingText(card, account);
}

function formatPortfolioCustomerDecisionDigest(decision = {}, account = {}) {
  const actions = Array.isArray(decision.actions) ? decision.actions : [];
  const buyCount = actions.filter((item) => String(item.action || "").toUpperCase() === "BUY").length;
  const sellCount = actions.filter((item) => String(item.action || "").toUpperCase() === "SELL").length;
  const watchCount = actions.filter((item) => String(item.action || "").toUpperCase() === "WATCH").length;
  const cashPct = computePortfolioCustomerCashPct(account);
  let headline = "";
  if (buyCount && sellCount) {
    headline = "直接结论：先把高位拥挤风险降下来，同时只拿小仓位验证低位候选。";
  } else if (buyCount) {
    headline = "直接结论：有低位候选进入小仓验证，执行上仍然按分批和触发条件来。";
  } else if (sellCount) {
    headline = "直接结论：今天重点是保护组合，不把减仓资金立刻追进热门方向。";
  } else if (watchCount) {
    headline = "直接结论：今天只把候选放进观察，不把还没确认的走势包装成买点。";
  } else if (Number.isFinite(cashPct) && cashPct >= 60) {
    headline = "直接结论：现金较多，下一步必须复核低位启动候选，不能只停留在等机会。";
  } else {
    headline = "直接结论：今天以复核组合为主，买卖动作要等触发条件更清楚。";
  }
  const focus = [
    shortenPortfolioCustomerText(decision.summary || "", 90),
    shortenPortfolioCustomerText(decision.marketView || "", 90)
  ].filter(Boolean);
  return [headline, focus.length ? `本次重点：${focus.slice(0, 2).join("；")}` : ""].filter(Boolean);
}

function formatPortfolioCustomerNextStepLines({ decision = {}, orders = [], watchlistUpdates = [] } = {}) {
  const lines = [];
  const actions = Array.isArray(decision.actions) ? decision.actions : [];
  const buy = actions.find((item) => String(item.action || "").toUpperCase() === "BUY")
    || orders.find((item) => String(item.side || "").toUpperCase() === "BUY");
  const sell = actions.find((item) => String(item.action || "").toUpperCase() === "SELL")
    || orders.find((item) => String(item.side || "").toUpperCase() === "SELL");
  const watch = actions.find((item) => String(item.action || "").toUpperCase() === "WATCH")
    || watchlistUpdates.find((item) => ["ready", "waiting_pullback", "watch"].includes(normalizePortfolioWatchStatus(item.status || "watch")));

  if (buy) {
    lines.push("- 买入后先看走势是否继续低位修复；确认前不追加，确认后再决定加仓、继续观察或退出。");
  }
  if (sell) {
    lines.push("- 减仓资金先回到现金池，不急着追进同一热门方向；等高位回落或新低位主题确认。");
  }
  if (watch) {
    const trigger = shortenPortfolioCustomerText(watch.buyTriggers?.[0] || watch.positionCheck || watch.positionPlan || watch.reason || "", 82);
    lines.push(`- 观察池下一轮只看触发条件，不用“感觉不错”买入${trigger ? `：${trigger}` : "。"}`);
  }
  if (!lines.length && decision.marketView) {
    lines.push(`- 下一轮先复核市场温度和低位候选：${shortenPortfolioCustomerText(decision.marketView, 86)}`);
  }
  return [...new Set(lines)].slice(0, 3);
}

function formatPortfolioCustomerNoteLines(notes = [], options = {}) {
  const maxItems = Math.max(1, Number(options.maxItems || 4));
  const maxLength = Math.max(40, Number(options.maxLength || 90));
  const seen = new Set();
  return normalizeStringArray(notes)
    .map((item) => shortenPortfolioCustomerText(item, maxLength))
    .filter((item) => {
      if (!item || seen.has(item)) return false;
      seen.add(item);
      return true;
    })
    .slice(0, maxItems)
    .map((item) => `- ${item}`);
}

function formatPortfolioCustomerAccountLine(account = {}) {
  const positionPct = Number(account.positionWeightPct);
  const cashPct = computePortfolioCustomerCashPct(account);
  const pendingBuy = Number(account.pendingBuyAmount || 0);
  const receivableCash = Number(account.receivableCash || 0);
  const total = Number(account.totalAsset || 0);
  const receivablePct = total > 0 && Number.isFinite(receivableCash) ? receivableCash * 100 / total : null;
  const pieces = [];
  if (Number.isFinite(positionPct)) {
    const stance = positionPct < 20 ? "仓位偏低" : positionPct > 75 ? "仓位偏高" : "仓位中等";
    pieces.push(`${stance}，约${round(positionPct, 1)}%`);
  }
  if (Number.isFinite(cashPct)) {
    const cashLabel = cashPct >= 60 ? "现金很充足" : cashPct >= 35 ? "现金还有余地" : "现金不算多";
    pieces.push(`${cashLabel}，可动用约${round(cashPct, 1)}%`);
  }
  if (receivableCash > 0) {
    const receivableText = Number.isFinite(receivablePct) ? `赎回款约${round(receivablePct, 1)}%未到账` : "赎回款未到账";
    pieces.push(`${receivableText}，不当作买入火力`);
  }
  if (pendingBuy > 0) {
    pieces.push("有申购在确认中，后续按净值落账复核");
  }
  return `当前资产：${pieces.length ? pieces.join("；") : "账本状态正常，等待下一次净值确认"}。`;
}

function formatPortfolioCustomerDrawdownLine(account = {}) {
  const drawdown = Number(account.drawdownFromPeakPct || 0);
  const label = account.riskBudget?.label || "回撤正常";
  const action = account.riskBudget?.blockNewBuys
    ? "先保护回撤，不扩大新仓"
    : "回撤预算允许继续复核低位候选";
  return `回撤预算：当前距峰值${formatFallbackPct(drawdown)}，${label}；${action}。`;
}

function formatPortfolioCustomerOrderLine(order = {}) {
  const side = formatPortfolioActionLabel(order.side);
  const label = [order.code, order.name].filter(Boolean).join(" ");
  const amount = formatPortfolioCustomerMoney(order.amount);
  const status = formatPortfolioOrderStatus(order.status);
  const confirm = order.confirmDate ? `等 ${order.confirmDate} 确认` : "等待确认";
  const settle = order.settlementDate ? `，预计 ${order.settlementDate} 到账` : "";
  const next = String(order.side || "").toUpperCase() === "BUY"
    ? "确认前不追加，先看净值和份额落账"
    : "到账前不把赎回款当作买入火力";
  const reason = shortenPortfolioCustomerText(order.scheduleReason || order.reason || "", 70);
  return `${side} ${label}${amount ? ` ${amount}` : ""}：${status}，${confirm}${settle}；${next}${reason ? `；${reason}` : ""}`;
}

function formatPortfolioCustomerTransactionLine(item = {}) {
  const side = formatPortfolioActionLabel(item.side);
  const label = [item.code, item.name].filter(Boolean).join(" ");
  const amount = formatPortfolioCustomerMoney(item.amount);
  const trend = shortenPortfolioCustomerText(item.fundSnapshot?.trendSummary || item.reason || "", 72);
  const next = String(item.side || "").toUpperCase() === "BUY"
    ? "已落账，后续按低位修复是否延续来决定加仓或退出"
    : "已确认，后续看风险是否释放，不急着买回同线";
  return `${side} ${label}${amount ? ` ${amount}` : ""}：${next}${trend ? `；走势：${trend}` : ""}`;
}

function formatPortfolioCustomerOrderUpdateLine(item = {}) {
  const side = formatPortfolioActionLabel(item.side);
  const label = [item.code, item.name].filter(Boolean).join(" ");
  const before = formatPortfolioOrderStatus(item.beforeStatus);
  const after = formatPortfolioOrderStatus(item.afterStatus);
  const confirm = item.confirmDate ? `，等 ${item.confirmDate} 确认` : "";
  const meaning = /取消|拒绝/.test(after)
    ? "旧订单已处理，避免继续冻结现金或份额"
    : /确认/.test(after)
      ? "订单进入落账复核"
      : "订单还在流转中";
  return `${side} ${label}：${before}转为${after}${confirm}；${meaning}`;
}

function formatPortfolioCustomerMoney(value) {
  const amount = Number(value || 0);
  if (!Number.isFinite(amount) || amount <= 0) return "";
  if (amount >= 10000) return `约${round(amount / 10000, 1)}万元`;
  return `约${round(amount, 0)}元`;
}

function computePortfolioCustomerCashPct(account = {}) {
  const total = Number(account.totalAsset || 0);
  if (!Number.isFinite(total) || total <= 0) return null;
  const cash = Number(account.cash || 0);
  if (!Number.isFinite(cash)) return null;
  return cash * 100 / total;
}

function formatPortfolioCustomerActionLine(action = {}) {
  const name = [action.code, action.name].filter(Boolean).join(" ");
  const amount = action.amount ? ` 建议${formatPortfolioCustomerMoney(action.amount)}` : "";
  const targetPct = toNumber(action.targetWeightPct);
  const target = Number.isFinite(targetPct) ? ` 目标约${round(targetPct, 1)}%` : "";
  const trend = shortenPortfolioCustomerText(action.positionCheck || action.rotationCheck || action.chaseRisk || "", 64);
  const why = shortenPortfolioCustomerText(action.reason || action.rotationCheck || "见投委会意见", 72);
  const boundary = shortenPortfolioCustomerText(action.riskControl || action.chaseRisk || "", 64);
  const fee = summarizePortfolioCustomerFeeText(action.feeCheck || "");
  const ranking = shortenPortfolioCustomerText(action.rankingBasis || "", 64);
  return [
    `- ${formatPortfolioActionLabel(action.action)} ${name}${amount}${target}`,
    trend ? `  走势：${trend}` : "",
    why && why !== trend ? `  为什么：${why}` : "",
    boundary ? `  边界：${boundary}` : "",
    ranking ? `  榜单：${ranking}` : "",
    fee ? `  费用：${fee}` : ""
  ].filter(Boolean).join("\n");
}

function interspersePortfolioBlocks(blocks = []) {
  return (blocks || []).flatMap((block, index) => index > 0 ? ["", block] : [block]);
}

function formatPortfolioCustomerTeamLine(item = {}) {
  const stance = item.stance ? `（${item.stance}）` : "";
  return `- ${item.agent || "投委"}${stance}：${shortenPortfolioCustomerText(item.reason || "", 90)}`.trim();
}

function shortenPortfolioCustomerText(value = "", maxLength = 120) {
  const rawCleaned = String(value || "")
    .replace(/\s+/g, " ")
    .replace(/（[^（）]{80,}）/g, "")
    .replace(/曾浮盈[+-]?\d+(?:\.\d+)?%但当前转亏[+-]?\d+(?:\.\d+)?%/g, "浮盈已经回吐到转亏")
    .replace(/（\s*）/g, "")
    .trim();
  if (!rawCleaned) return "";
  const localized = normalizeUserFacingFundAnswer(rawCleaned).trim();
  const sentenceSource = localized || rawCleaned;
  const sentences = sentenceSource
    .split(/(?<=[。；;])|(?=系统(?:买入|卖出|组合|单仓|风控))|(?=当前)|(?=若)|(?=费用)|(?=风险)|(?=观察缺口)|(?=触发)/)
    .map((item) => item.replace(/^[；;。,\s]+|[；;。,\s]+$/g, "").trim())
    .filter(Boolean);
  const portfolioLogic = sentences.find((item) =>
    /同题材.*(?:过度|集中)|暴露过度|过度集中/.test(item)
  ) || sentences.find((item) =>
    /同题材.*(?:暴露|集中)|底层重叠|集中度/.test(item)
  );
  const preferred = portfolioLogic || choosePortfolioCustomerSentence(sentences, localized || rawCleaned);
  const compact = compactNumericHeavyCustomerText(
    normalizeUserFacingFundAnswer(preferred),
    Math.min(3, Math.max(1, Math.floor(maxLength / 45)))
  );
  return compact.length <= maxLength ? compact : `${compact.slice(0, Math.max(0, maxLength - 1))}…`;
}

function choosePortfolioCustomerSentence(sentences = [], fallback = "") {
  const candidates = (sentences.length ? sentences : [fallback]).filter(Boolean);
  return candidates
    .map((text, index) => {
      const numericCount = (text.match(/(?:[+-]?\d+(?:\.\d+)?%|\d+(?:\.\d+)?\s*(?:元|万|亿)|近\s*\d+\s*日|\d+\s*日位置|\d{6})/g) || []).length;
      let score = 0;
      if (/(高位|低位|回调|启动|修复|轮动|拥挤|偏热|追涨|回吐|转亏|止盈|止损|减仓|小仓|等待|回避)/.test(text)) score += 8;
      if (/(同题材.*(?:过度|集中)|暴露过度|集中度|底层重叠)/.test(text)) score += 14;
      if (/(因为|因此|所以|不是|不能|需要|必须|适合|不适合|先|后续|下一轮|触发)/.test(text)) score += 4;
      if (/(同题材|底层|持仓|前十大|费用|份额|风控|风险|利润)/.test(text)) score += 3;
      if (text.length < 12) score -= 3;
      if (/^系统/.test(text)) score -= 1;
      score -= numericCount * 2;
      return { text, score, index };
    })
    .sort((a, b) => b.score - a.score || a.index - b.index)[0]?.text || fallback;
}

function summarizePortfolioCustomerFeeText(value = "") {
  const text = normalizeUserFacingFundAnswer(String(value || "")).replace(/\s+/g, " ").trim();
  if (!text) return "";
  const shareClass = text.match(/([A-DI])类/i)?.[1]?.toUpperCase() || "";
  const pieces = [];
  if (shareClass) {
    if (/销售服务费|短期|战术|30-180天/.test(text)) {
      pieces.push(`${shareClass}类偏短中期，别长期拖着不复核`);
    } else if (/前端申购费|中期|长期/.test(text)) {
      pieces.push(`${shareClass}类偏中长期，注意申购和赎回摩擦`);
    } else {
      pieces.push(`${shareClass}类份额已识别`);
    }
  }
  if (/不混买|避免份额混用|不新增同基金其他份额|本次不新增/.test(text)) {
    pieces.push("不和同基金其他份额混买");
  }
  if (/缺|未提供|未知|无法核验/.test(text)) {
    pieces.push("费用/份额还要补齐后再放大仓位");
  }
  return pieces.length ? [...new Set(pieces)].slice(0, 2).join("；") : shortenPortfolioCustomerText(text, 46);
}

function compactNumericHeavyCustomerText(value = "", maxNumbers = 3) {
  const text = String(value || "").trim();
  if (!text) return "";
  const metricPattern = /(?:[+-]?\d+(?:\.\d+)?%|\d+(?:\.\d+)?\s*(?:元|万|亿)|近\s*\d+\s*日|\d+\s*日位置|\d+(?:\.\d+)?\s*分|回撤\s*[+-]?\d+(?:\.\d+)?)/g;
  const clauses = text
    .split(/[；;。]/)
    .flatMap((item) => item.split(/，(?=(?:[^“”"]|“[^”]*”|"[^"]*")*$)/))
    .map((item) => item.replace(/^[，,；;。:\s]+|[，,；;。:\s]+$/g, "").trim())
    .filter(Boolean);
  let usedNumbers = 0;
  const kept = [];
  for (const clause of clauses) {
    const count = (clause.match(metricPattern) || []).length;
    const hasInterpretation = /(走势|低位|高位|回调|启动|修复|转强|转弱|轮动|拥挤|偏热|追涨|风险|触发|边界|费用|份额|持仓|减仓|买入|观察|等待|回避|止盈|止损|重叠|集中|暴露|过度|前景)/.test(clause);
    if (count && usedNumbers + count > maxNumbers && kept.length) continue;
    if (!hasInterpretation && count && kept.length) continue;
    kept.push(clause);
    usedNumbers += count;
    if (usedNumbers >= maxNumbers && kept.length >= 2) break;
  }
  const compact = (kept.length ? kept : [clauses[0] || text]).join("；");
  return compact
    .replace(/系统(?:买入|卖出|组合|单仓|风控)[^：:]{0,18}[：:]\s*/g, "")
    .replace(/；{2,}/g, "；")
    .replace(/^[；;。,\s]+|[；;。,\s]+$/g, "")
    .trim();
}

function buildPortfolioValuationCard({ review, account, positionUpdates, lifecycle = {}, run }) {
  const updateLines = positionUpdates.length
    ? positionUpdates.map((item) => {
        const nav = item.latestNav ? `，净值 ${item.latestNav}${item.navDate ? `（${item.navDate}）` : ""}` : "";
        const trend = item.trend ? `，走势 ${item.trend}` : "";
        return `${item.code} ${item.name}：${item.beforeValue} -> ${item.afterValue}，今日 ${formatSignedNumber(item.dayPnl)}元${nav}${trend}`;
      })
    : ["当前没有持仓，净值复盘只更新现金账户。"];

  const card = [
    `虚拟基金经理晚间复盘 ${run.date}`,
    "",
    `复盘结论：${review.summary}`,
    review.reason ? `原因：${review.reason}` : "",
    "",
    "持仓估值：",
    ...updateLines,
    lifecycle.orderUpdates?.length ? "" : "",
    lifecycle.orderUpdates?.length ? "订单进度：" : "",
    ...(lifecycle.orderUpdates || []).map(formatPortfolioCustomerOrderUpdateLine),
    lifecycle.transactions?.length ? "" : "",
    lifecycle.transactions?.length ? "确认成交：" : "",
    ...(lifecycle.transactions || []).map(formatPortfolioCustomerTransactionLine),
    lifecycle.settlementEvents?.length ? "" : "",
    lifecycle.settlementEvents?.length ? "到账更新：" : "",
    ...(lifecycle.settlementEvents || []).map((item) => `${item.code} ${item.name} ${item.amount}元已到账。`),
    "",
    `总资产：${account.totalAsset}元`,
    `今日盈亏：${formatSignedNumber(account.dayPnl)}元`,
    `累计盈亏：${formatSignedNumber(account.cumulativePnl)}元（按实际投入基准 ${account.investedCostBasis || account.investedCost || 0} 元计 ${formatSignedNumber(account.cumulativePnlPct)}%）`,
    `可用现金：${account.cash}元，待确认申购：${account.pendingBuyAmount || 0}元，应收赎回：${account.receivableCash || 0}元，仓位：${account.positionWeightPct}%`,
    `回撤预算：峰值 ${account.peakTotalAsset || account.totalAsset}元，当前距峰值 ${formatFallbackPct(account.drawdownFromPeakPct || 0)}，状态 ${account.riskBudget?.label || "回撤正常"}`,
    review.nextWatch.length ? ["", "明日观察：", ...review.nextWatch].join("\n") : "",
    review.learningNotes.length ? ["", "回溯学习点：", ...review.learningNotes].join("\n") : "",
    "",
    `数据来源：${(run.sources || []).slice(0, 6).join("；") || "基金公开净值与持仓资料"}`
  ]
    .filter(Boolean)
    .join("\n");
  return normalizePortfolioUserFacingText(card, account);
}

