function formatPortfolioActionLabel(value) {
  const key = String(value || "").trim().toUpperCase();
  return {
    BUY: "买入",
    SELL: "卖出",
    HOLD: "持有",
    WATCH: "观察",
    SKIP: "未执行",
    RESET: "重置"
  }[key] || normalizePortfolioUserFacingText(value || "观察");
}

function formatPortfolioMarketTone(value) {
  const key = String(value || "").trim().toLowerCase();
  return {
    aggressive: "积极",
    neutral: "中性",
    defensive: "防守",
    wait: "等待"
  }[key] || normalizePortfolioUserFacingText(value || "中性");
}

function formatPortfolioOrderStatus(value) {
  const key = String(value || "").trim().toLowerCase();
  return {
    pending: "待处理",
    submitted: "已提交",
    pricing: "待估值",
    confirming: "待确认",
    confirmed: "已确认",
    settled: "已到账",
    cancelled: "已取消",
    rejected: "已拒绝"
  }[key] || normalizePortfolioUserFacingText(value || "待处理");
}

function formatPortfolioWatchLine(item = {}) {
  const head = `${item.code || ""} ${item.name || ""}`.trim();
  const status = item.statusText || formatPortfolioWatchStatus(item.status);
  const reason = shortenPortfolioCustomerText(item.reason || item.setupEvidence?.[0] || "", 72);
  const trigger = shortenPortfolioCustomerText(item.buyTriggers?.[0] || item.positionPlan || "", 72);
  const risk = shortenPortfolioCustomerText(item.riskNotes?.[0] || "", 70);
  const fee = summarizePortfolioCustomerFeeText((item.feeNotes || []).join("；"));
  return [
    `- ${head}（${status}）`,
    reason ? `  关注点：${reason}` : "",
    trigger ? `  触发：${trigger}` : "",
    risk ? `  风险：${risk}` : "",
    fee ? `  费用：${fee}` : ""
  ].filter(Boolean).join("\n");
}

function buildPortfolioCustomerActionDeckStatusLines(deck = {}) {
  const cards = Array.isArray(deck.cards) ? deck.cards : [];
  if (!cards.length) return ["客户行动牌：暂无行动牌数据，先运行盘前观察或导入持仓。"];
  const activeCards = cards.filter((card) => Number(card.count || 0) > 0);
  if (!activeCards.length) {
    return [
      "客户行动牌：暂无直接买卖信号。",
      deck.summary ? `摘要：${deck.summary}` : "下一步：先运行盘前观察或导入持仓，让经理沉淀可复核对象。"
    ];
  }
  const lines = [`客户行动牌：${deck.summary || activeCards.map((card) => `${card.title}${card.count || 0}`).join("，")}。`];
  for (const card of activeCards.slice(0, 5)) {
    const items = Array.isArray(card.items) ? card.items.slice(0, 2) : [];
    const itemText = items.length
      ? items.map((item) => `${item.code || ""} ${item.name || ""}${item.action ? `（${item.action}）` : ""}`.trim()).join("；")
      : card.emptyText || "暂无";
    const firstReason = shortenPortfolioCustomerText(items[0]?.reason || card.summary || "", 54);
    const nextStep = shortenPortfolioCustomerText(items[0]?.nextStep || card.nextStep || "", 64);
    const reasonLabel = formatPortfolioCustomerActionReasonLabel(card.id);
    lines.push(`- ${card.title || "行动"}：${itemText}${firstReason ? `。${reasonLabel}：${firstReason}` : ""}${nextStep ? `。下一步：${nextStep}` : ""}`);
  }
  return lines;
}

function buildPortfolioCustomerDecisionSummaryStatusLines(summary = {}) {
  const lines = Array.isArray(summary.lines) ? summary.lines.filter(Boolean) : [];
  if (!lines.length) return [];
  return [
    `${summary.title || "客户决策摘要"}：${summary.primaryAction || summary.summary || "先看最需要处理的买卖和证据缺口。"}`,
    ...lines.slice(0, 5).map((line) => `- ${line}`)
  ];
}

function buildPortfolioCustomerActionLeaderboardStatusLines(board = {}) {
  const lanes = Array.isArray(board.lanes)
    ? board.lanes.filter((lane) => Number(lane.count || 0) > 0)
    : [];
  if (!lanes.length) return [];
  const lines = [`${board.title || "客户行动排行"}：${board.summary || lanes.map((lane) => `${lane.title}${lane.count || 0}项`).join("，")}。`];
  for (const lane of lanes.slice(0, 5)) {
    const items = Array.isArray(lane.items) ? lane.items.slice(0, 3) : [];
    const top = items[0] || null;
    const results = formatPortfolioCustomerActionLeaderboardResults(items);
    const reason = shortenPortfolioCustomerText(top?.reason || lane.purpose || "", 54);
    const policy = shortenPortfolioCustomerText(lane.sortPolicy || getPortfolioCustomerActionLaneSortPolicy(lane.id), 86);
    lines.push(`- ${lane.title || "行动榜"}：排序口径：${policy}。结果：${results || "暂无第一对象"}${reason ? `。首选理由：${reason}` : ""}`);
  }
  return lines;
}

function formatPortfolioCustomerActionLeaderboardResults(items = []) {
  return (items || [])
    .slice(0, 3)
    .map((item, index) => {
      const subject = [item.code, item.name].filter(Boolean).join(" ") || item.action || "待复核";
      return `${index + 1}. ${subject}`;
    })
    .join("；");
}

function buildPortfolioConsensusRadarStatusLines(radar = {}) {
  const lanes = Array.isArray(radar.lanes)
    ? radar.lanes.filter((lane) => Number(lane.count || 0) > 0)
    : [];
  if (!lanes.length) return [];
  const lines = [`${radar.title || "共识雷达"}：${radar.summary || lanes.map((lane) => `${lane.title}${lane.count || 0}项`).join("，")}。`];
  for (const lane of lanes.slice(0, 4)) {
    const items = Array.isArray(lane.items) ? lane.items.slice(0, 2) : [];
    const itemText = items.length
      ? items.map((item) => `${item.code || ""} ${item.name || ""}${item.action ? `（${item.action}）` : ""}`.trim()).join("；")
      : lane.emptyText || "暂无第一对象";
    const first = items[0] || {};
    const evidence = lane.id === "risk"
      ? first.blockerText || first.reason
      : lane.id === "data"
        ? first.blockerText || first.constraintText || first.reason
        : first.supportText || first.reason;
    const constraint = first.constraintText || first.permission || "";
    const nextStep = first.nextStep || lane.topAction || "";
    lines.push(
      `- ${lane.title || "共识"}：${itemText}` +
        `${evidence ? `。依据：${shortenPortfolioCustomerText(evidence, 58)}` : ""}` +
        `${constraint ? `。约束：${shortenPortfolioCustomerText(constraint, 48)}` : ""}` +
        `${nextStep ? `。下一步：${shortenPortfolioCustomerText(nextStep, 58)}` : ""}`
    );
  }
  return lines;
}

function formatPortfolioCustomerActionReasonLabel(cardId = "") {
  const id = String(cardId || "").trim();
  if (id === "buy") return "买入理由";
  if (id === "wait") return "加备选理由";
  if (id === "avoid") return "暂不买理由";
  if (id === "sell") return "卖出/减仓理由";
  if (id === "data") return "先补证据原因";
  return "判断依据";
}

function buildPortfolioStatusDirectConclusionLines({ account = {}, managerRankings = {}, recentDecision = null, activeOrders = [], todayTransactions = [] } = {}) {
  const consensusConclusion = buildPortfolioStatusConsensusDirectConclusion(managerRankings.consensusRadar || {});
  if (consensusConclusion) {
    return consensusConclusion;
  }
  const deck = managerRankings.customerActionDeck || {};
  const cards = Array.isArray(deck.cards) ? deck.cards : [];
  const activeCards = cards.filter((card) => Number(card.count || 0) > 0);
  const priorityOrder = ["sell", "buy", "wait", "avoid", "data"];
  const selectedCard = priorityOrder
    .map((id) => activeCards.find((card) => card.id === id))
    .find(Boolean)
    || activeCards[0]
    || null;
  const firstItem = Array.isArray(selectedCard?.items) ? selectedCard.items[0] : null;
  const risk = account.riskBudget || buildPortfolioAccountRiskBudget(account);
  const summary = selectedCard
    ? buildPortfolioStatusDirectConclusionText(selectedCard, firstItem, { account, risk, recentDecision, activeOrders, todayTransactions })
    : buildPortfolioStatusFallbackConclusionText({ account, risk, recentDecision, activeOrders, todayTransactions });
  const lines = [`直接结论：${summary}`];
  if (firstItem) {
    const subject = [firstItem.code, firstItem.name].filter(Boolean).join(" ") || selectedCard.title || "优先事项";
    lines.push(`优先处理：${subject}${firstItem.action ? `（${firstItem.action}）` : ""}。`);
    const reason = shortenPortfolioCustomerText(firstItem.reason || selectedCard.summary || "", 72);
    const nextStep = shortenPortfolioCustomerText(firstItem.nextStep || selectedCard.nextStep || "", 72);
    if (reason) lines.push(`为什么：${reason}`);
    if (nextStep) lines.push(`下一步：${nextStep}`);
  } else {
    const next = risk.blockNewBuys
      ? "先保护回撤，不扩大新仓。"
      : "继续等待低位启动、回调完成和数据补齐后再行动。";
    lines.push(`下一步：${next}`);
  }
  return lines;
}

function buildPortfolioStatusConsensusDirectConclusion(radar = {}) {
  const lanes = Array.isArray(radar.lanes) ? radar.lanes : [];
  const laneOrder = ["risk", "buy", "data", "watch"];
  const selectedLane = laneOrder
    .map((id) => lanes.find((lane) => lane.id === id && Number(lane.count || 0) > 0 && Array.isArray(lane.items) && lane.items.length))
    .find(Boolean);
  const first = selectedLane?.items?.[0] || null;
  if (!selectedLane || !first) return null;
  const subject = [first.code, first.name].filter(Boolean).join(" ") || selectedLane.title || "优先事项";
  const action = first.action || first.verdictLabel || selectedLane.topAction || "复核";
  const reason = selectedLane.id === "risk"
    ? first.blockerText || first.reason
    : selectedLane.id === "data"
      ? first.blockerText || first.constraintText || first.reason
      : first.supportText || first.reason;
  const nextStep = first.nextStep || first.constraintText || selectedLane.emptyText || "";
  return [
    `直接结论：${subject} ${action}，这是多榜单交叉后的第一处理对象。`,
    `优先处理：${subject}${first.permission ? `（${first.permission}）` : ""}。`,
    reason ? `为什么：${shortenPortfolioCustomerText(reason, 72)}` : "",
    nextStep ? `下一步：${shortenPortfolioCustomerText(nextStep, 72)}` : ""
  ].filter(Boolean);
}

function buildPortfolioStatusDirectConclusionText(card = {}, item = null, context = {}) {
  const action = String(card.id || "");
  const subject = item ? [item.code, item.name].filter(Boolean).join(" ") : "";
  if (action === "sell") return `${subject ? `${subject} ` : ""}先看卖出/减仓和回吐保护，新增买入让位给风控。`;
  if (action === "buy") return `${subject ? `${subject} ` : ""}进入买入复核，但仍按小仓、分批和触发条件执行。`;
  if (action === "wait") return `${subject ? `${subject} ` : ""}值得继续盯，但今天重点是等触发，不把观察对象包装成买点。`;
  if (action === "avoid") return `${subject ? `${subject} ` : ""}先回避或降级观察，等高位降温、回撤或证据补齐。`;
  if (action === "data") return `${subject ? `${subject} ` : ""}先补数据，净值、费率或持仓证据没齐前不给买入金额。`;
  return buildPortfolioStatusFallbackConclusionText(context);
}

function buildPortfolioStatusFallbackConclusionText({ account = {}, risk = null, recentDecision = null, activeOrders = [], todayTransactions = [] } = {}) {
  const budget = risk || account.riskBudget || buildPortfolioAccountRiskBudget(account);
  if (budget.blockNewBuys) return "账户回撤触发防线，今天先保护本金，不扩大新仓。";
  if ((activeOrders || []).length) return "有订单还在确认或到账中，先等流转落账，再评估下一步买卖。";
  if ((todayTransactions || []).length) return "今天已有成交，下一步先看成交后的仓位和风险是否符合计划。";
  if (recentDecision?.summary) return shortenPortfolioCustomerText(recentDecision.summary, 86);
  const cashPct = computePortfolioCustomerCashPct(account);
  if (Number.isFinite(cashPct) && cashPct >= 65) return "现金较多，但仍要等低位启动和回调完成信号，不为了出手而出手。";
  return "暂无必须立即买卖的信号，先维护持仓风险和低位候选池。";
}

function buildPortfolioAccountStatusLines(account = {}, options = {}) {
  const compact = Boolean(options.compact);
  if (!compact) {
    const lines = [
      `总资产：${account.totalAsset}元`,
      `可用现金：${account.cash}元`
    ];
    if (account.pendingBuyAmount || account.receivableCash) {
      lines.push(`待确认申购：${account.pendingBuyAmount || 0}元，应收赎回：${account.receivableCash || 0}元`);
    }
    lines.push(`当前仓位：${account.positionWeightPct}%`);
    lines.push(`累计盈亏：${formatSignedNumber(account.cumulativePnl)}元（按实际投入基准 ${account.investedCostBasis || account.investedCost || 0} 元计 ${formatSignedNumber(account.cumulativePnlPct)}%）`);
    return lines;
  }
  const cashPct = computePortfolioCustomerCashPct(account);
  const risk = account.riskBudget || buildPortfolioAccountRiskBudget(account);
  const cashText = Number.isFinite(cashPct)
    ? cashPct >= 65
      ? "现金充足，重点等待低位候选触发"
      : cashPct >= 35
        ? "现金仍可分批，但不适合一次打满"
        : "现金余量偏低，新增买入要先看风险预算"
    : "现金状态待复核";
  const positionText = Number(account.positionWeightPct || 0) <= 0
    ? "当前空仓"
    : Number(account.positionWeightPct || 0) >= 70
      ? "仓位偏高"
      : Number(account.positionWeightPct || 0) >= 35
        ? "中等仓位"
        : "低仓位";
  const pnlText = Number(account.cumulativePnl || 0) >= 0
    ? `累计仍为正收益，收益率按实际投入基准计算`
    : `累计承压，后续先解释亏损来源`;
  const pendingText = account.pendingBuyAmount || account.receivableCash
    ? "有申购/赎回在路上，未确认前不把它当成已成交"
    : "暂无待确认资金流转";
  const next = risk.blockNewBuys
    ? "先保护回撤，不扩大新仓"
    : "下一步优先复核低位启动、回调完成和已有仓位风险";
  return [
    `账户简版：${positionText}；${cashText}；${pnlText}。`,
    `资金流转：${pendingText}。`,
    `回撤边界：${risk.label || "回撤正常"}，当前距峰值${formatFallbackPct(risk.drawdownFromPeakPct || account.drawdownFromPeakPct || 0)}；${next}。`
  ];
}

function buildPortfolioPositionStatusLines(positions = [], options = {}) {
  const values = (positions || []).filter((position) => position?.code || position?.name);
  if (!values.length) return ["暂无基金持仓，当前为 100% 现金。"];
  const compact = Boolean(options.compact);
  if (!compact) return buildPortfolioPositionDetailStatusLines(values);
  const limit = Math.max(1, Number(options.limit || 4));
  const ranked = values
    .map((position) => ({ position, budget: position.riskBudget || buildPortfolioPositionRiskBudget(position) }))
    .sort(comparePortfolioPositionStatusPriority);
  const lines = [
    "持仓简版：先看持有、减仓和止盈边界；完整账本字段和走势证据可在后台持仓终端展开。"
  ];
  for (const item of ranked.slice(0, limit)) {
    lines.push(formatPortfolioPositionCompactLine(item.position, { budget: item.budget }));
  }
  if (ranked.length > limit) {
    lines.push(`还有 ${ranked.length - limit} 只持仓可在后台持仓终端查看。`);
  }
  return lines;
}

function buildPortfolioPositionDetailStatusLines(positions = []) {
  const lines = [];
  for (const position of positions) {
    lines.push(
      `${position.code} ${position.name || ""}：${position.currentValue}元，占比 ${position.weightPct}%` +
        `，浮动盈亏 ${formatSignedNumber(position.unrealizedPnl)}元（${formatSignedNumber(position.unrealizedPnlPct)}%）`
    );
    const snapshot = position.fundSnapshot || {};
    const navLine = [
      snapshot.nav ? `净值 ${snapshot.nav}` : position.lastNav ? `净值 ${position.lastNav}` : "",
      snapshot.navDate || position.lastNavDate ? `日期 ${snapshot.navDate || position.lastNavDate}` : "",
      position.units ? `份额 ${position.units}` : "",
      position.averageCostNav ? `成本净值 ${position.averageCostNav}` : ""
    ].filter(Boolean);
    if (navLine.length) {
      lines.push(navLine.join("，"));
    }
    if (snapshot.trendSummary) {
      lines.push(`走势/风险：${snapshot.trendSummary}`);
    }
    if (position.lastReason) {
      lines.push(`理由：${position.lastReason}`);
    }
  }
  return lines;
}

function comparePortfolioPositionStatusPriority(a = {}, b = {}) {
  const score = (item) => {
    const budget = item.budget || {};
    if (budget.level === "severe") return 0;
    if (budget.reduceRisk || budget.level === "warning") return 1;
    if (Number(item.position?.profitGivebackPct || budget.profitGivebackPct || 0) >= 2.5) return 2;
    if (Number(item.position?.unrealizedPnlPct || 0) < 0) return 3;
    return 4;
  };
  return score(a) - score(b)
    || Number(b.position?.weightPct || 0) - Number(a.position?.weightPct || 0)
    || String(a.position?.code || "").localeCompare(String(b.position?.code || ""));
}

function formatPortfolioPositionCompactLine(position = {}, options = {}) {
  const budget = options.budget || position.riskBudget || buildPortfolioPositionRiskBudget(position);
  const head = `${position.code || ""} ${position.name || ""}`.trim();
  const status = formatPortfolioPositionCompactStatus(position, budget);
  const focus = selectPortfolioPositionCompactFocus(position, budget);
  const nextStep = selectPortfolioPositionCompactNextStep(position, budget);
  const boundary = selectPortfolioPositionCompactBoundary(position, budget);
  return `- ${head}${status ? `（${status}）` : ""}；关注：${shortenPortfolioCustomerText(focus, 56)}；下一步：${shortenPortfolioCustomerText(nextStep, 58)}；边界：${shortenPortfolioCustomerText(boundary, 58)}`;
}

function formatPortfolioPositionCompactStatus(position = {}, budget = {}) {
  if (budget.level === "severe") return "止损风险";
  if (budget.reduceRisk || budget.level === "warning") return "减仓复核";
  const givebackPct = Number(position.profitGivebackPct || budget.profitGivebackPct || 0);
  if (givebackPct >= 2.5) return "止盈复核";
  if (Number(position.unrealizedPnlPct || 0) < 0) return "承压观察";
  if (Number(position.weightPct || 0) >= 8) return "核心持有";
  return "继续持有";
}

function selectPortfolioPositionCompactFocus(position = {}, budget = {}) {
  const trigger = (budget.triggers || [])[0];
  if (trigger) return trigger;
  const trendText = normalizePortfolioPositionTrendForCustomer(position.fundSnapshot?.trendSummary || "");
  if (trendText) return trendText;
  if (position.lastReason) return position.lastReason;
  return "暂未触发明确买卖信号，按仓位和风险线继续观察。";
}

function selectPortfolioPositionCompactNextStep(position = {}, budget = {}) {
  if (budget.level === "severe") return "优先复核卖出或止损，不用补仓摊薄风险。";
  if (budget.reduceRisk || budget.level === "warning") return "下一次决策先复核减仓或止盈，不新增同方向仓位。";
  if (Number(position.profitGivebackPct || budget.profitGivebackPct || 0) >= 2.5) return "先确认是否锁定部分利润，再决定是否继续持有。";
  if (Number(position.unrealizedPnlPct || 0) < 0) return "继续观察是否转强，若扩大亏损先降风险。";
  return "继续持有观察，等盘前观察或今日操作复核是否需要调仓。";
}

function selectPortfolioPositionCompactBoundary(position = {}, budget = {}) {
  const trigger = (budget.triggers || [])[0];
  if (trigger) return trigger;
  if (Number(position.unrealizedPnlPct || 0) < 0) return "若继续转弱或亏损扩大，优先复核减仓，不用加仓摊薄。";
  if (Number(position.weightPct || 0) >= 8) return "单仓较重时不继续加仓，先等同题材拥挤度和走势确认。";
  return "没有新的确认信号前，不因短期新闻热度追涨加仓。";
}

function normalizePortfolioPositionTrendForCustomer(text = "") {
  const value = String(text || "").trim();
  if (!value) return "";
  if (/偏热|追涨|高位|extended|拥挤/.test(value)) return "走势偏热，先防利润回吐和同题材拥挤。";
  if (/破位|转弱|weak|回撤扩大/.test(value)) return "走势转弱，先看止损、止盈或减仓边界。";
  if (/回调|修复|低位|pullback/.test(value)) return "走势处在回调修复阶段，重点看能否重新转强。";
  return shortenPortfolioCustomerText(value, 56);
}

function buildPortfolioRecentDecisionStatusLines(run = {}, options = {}) {
  if (!run) return [];
  const actions = Array.isArray(run.actions) ? run.actions : [];
  const limit = Math.max(1, Number(options.limit || 5));
  const lines = [`最近一次决策：${run.date || "未知日期"}`];
  const summary = shortenPortfolioCustomerText(run.summary || run.title || "", 90);
  if (summary) {
    lines.push(`决策摘要：${summary}`);
  }
  if (actions.length) {
    lines.push("动作摘要：");
    for (const action of actions.slice(0, limit)) {
      lines.push(formatPortfolioCustomerActionLine(action));
    }
    if (actions.length > limit) {
      lines.push(`还有 ${actions.length - limit} 个动作可在后台时间线查看。`);
    }
    const boundary = actions
      .map((action) => action.riskControl || action.chaseRisk || action.positionCheck || "")
      .find(Boolean);
    if (boundary) {
      lines.push(`总边界：${shortenPortfolioCustomerText(boundary, 86)}`);
    }
  } else {
    lines.push("动作摘要：本轮没有买入或卖出动作，经理只保留观察和等待触发。");
  }
  lines.push("完整推演：后台“虚拟组合 -> 时间线”可查看投委会、执行流转和原文。");
  return lines;
}

function buildPortfolioTodayOperationStatusLines({ today = "", transactions = [], recentDecision = null } = {}, options = {}) {
  const compact = Boolean(options.compact);
  const limit = Math.max(1, Number(options.limit || (compact ? 4 : 8)));
  const lines = [`今日操作 ${today}：`];
  const values = Array.isArray(transactions) ? transactions : [];
  if (values.length) {
    if (compact) {
      lines.push("今日成交简版：先看动作含义，净值、份额和完整流水可在后台订单终端展开。");
    }
    for (const item of values.slice(0, limit)) {
      lines.push(compact ? `- ${formatPortfolioCustomerTransactionLine(item)}` : formatPortfolioTransactionDetailStatusLine(item));
    }
    if (values.length > limit) {
      lines.push(`还有 ${values.length - limit} 笔成交可在后台订单终端查看。`);
    }
  } else if (recentDecision?.date === today) {
    lines.push("今天已生成投委会决策，但买入/卖出需要经过申购/赎回申请、估值日净值、确认日，不会下单即成交。");
  } else {
    lines.push("今天还没有生成新的买入/卖出流水。可以在后台“虚拟组合”页点击“生成今日操作”，或等定时任务自动运行。");
  }
  return lines;
}

function buildPortfolioActiveOrderStatusLines(orders = [], options = {}) {
  const values = Array.isArray(orders) ? orders : [];
  if (!values.length) return [];
  const compact = Boolean(options.compact);
  const limit = Math.max(1, Number(options.limit || (compact ? 4 : 8)));
  const lines = ["待处理订单："];
  if (compact) {
    lines.push("订单简版：只看还在确认还是等待到账；完整估值日、确认日和金额可在后台订单终端展开。");
  }
  for (const order of values.slice(0, limit)) {
    lines.push(compact ? `- ${formatPortfolioCustomerOrderLine(order)}` : formatPortfolioOrderDetailStatusLine(order));
  }
  if (values.length > limit) {
    lines.push(`还有 ${values.length - limit} 笔待处理订单可在后台订单终端查看。`);
  }
  return lines;
}

function formatPortfolioTransactionDetailStatusLine(item = {}) {
  const tradeDetail = [
    `${item.side} ${item.code || ""} ${item.name || ""} ${item.amount}元`,
    item.nav ? `净值${item.nav}` : "",
    item.units ? `份额${item.units}` : ""
  ].filter(Boolean).join("，");
  return `${tradeDetail}：${item.reason || "见当日投委会记录"}`;
}

function formatPortfolioOrderDetailStatusLine(order = {}) {
  return `${order.side} ${order.code} ${order.name} ${order.amount}元：${order.status}，估值日 ${order.priceDate}，确认日 ${order.confirmDate}` +
    `${order.settlementDate ? `，到账日 ${order.settlementDate}` : ""}`;
}

function buildPortfolioWatchlistStatusLines(watchlist = [], options = {}) {
  const normalized = normalizePortfolioWatchlist(watchlist).filter((item) => item.status !== "removed");
  if (!normalized.length) return ["暂无自选基金。"];
  const limitPerStatus = Math.max(1, Number(options.limitPerStatus || 4));
  const compact = Boolean(options.compact);
  const rankingCitationMap = options.rankingCitationMap || buildPortfolioWatchRankingCitationMap(options.managerRankings);
  const statusOrder = ["ready", "waiting_pullback", "watch", "blocked", "in_position"];
  const groups = statusOrder
    .map((status) => ({
      status,
      label: formatPortfolioWatchStatus(status),
      items: normalized.filter((item) => item.status === status)
    }))
    .filter((group) => group.items.length);
  const lines = [
    `合计 ${normalized.length} 只：${groups.map((group) => `${group.label}${group.items.length}只`).join("，")}。`
  ];
  if (compact) {
    lines.push("自选池简版：先看动作含义和触发条件，完整费率、净值、替代份额和详细证据可在后台自选池展开。");
  }
  lines.push(...buildPortfolioWatchlistLaunchEveLines(normalized, { compact }));
  lines.push(...buildPortfolioWatchlistActionQueueLines(normalized, { compact }));

  for (const group of groups) {
    lines.push(`【${group.label}】${group.items.length}只`);
    for (const rawItem of group.items.slice(0, limitPerStatus)) {
      const item = summarizePortfolioWatchItem(rawItem);
      lines.push(compact
        ? formatPortfolioWatchCompactLine(item, { rankingCitationMap })
        : formatPortfolioWatchDetailLine(item, { rankingCitationMap }));
    }
    if (group.items.length > limitPerStatus) {
      lines.push(`还有 ${group.items.length - limitPerStatus} 只同状态候选，可在管理页自选基金池查看。`);
    }
  }
  return lines;
}

function buildPortfolioWatchRankingCitationMap(managerRankings = {}) {
  const lists = Array.isArray(managerRankings?.lists) ? managerRankings.lists : [];
  const byCode = new Map();
  for (const list of lists) {
    const items = Array.isArray(list?.items) ? list.items : [];
    for (const item of items) {
      const code = String(item?.code || "").match(/^\d{6}$/)?.[0] || "";
      if (!code) continue;
      const refs = byCode.get(code) || [];
      refs.push({
        title: list.title || "经理榜单",
        rank: item.rank || "",
        action: item.action || item.status || ""
      });
      byCode.set(code, refs);
    }
  }
  const consensusLanes = Array.isArray(managerRankings?.consensusRadar?.lanes) ? managerRankings.consensusRadar.lanes : [];
  for (const lane of consensusLanes) {
    const items = Array.isArray(lane?.items) ? lane.items : [];
    for (const item of items) {
      const code = String(item?.code || "").match(/^\d{6}$/)?.[0] || "";
      if (!code) continue;
      const refs = byCode.get(code) || [];
      refs.push({
        title: `共识雷达·${lane.title || "共识"}`,
        rank: item.rank || item.matrixRank || "",
        action: item.action || item.verdictLabel || lane.topAction || ""
      });
      byCode.set(code, refs);
    }
  }
  return byCode;
}

function formatPortfolioWatchRankingCitationText(code = "", rankingCitationMap = null) {
  const refs = rankingCitationMap?.get?.(String(code || "")) || [];
  return refs
    .slice(0, 4)
    .map((item) => `${item.title}${item.rank ? `#${item.rank}` : ""}${item.action ? `/${item.action}` : ""}`)
    .join("；");
}

function shortenPortfolioCitationText(value = "", maxLength = 100) {
  const text = normalizePortfolioUserFacingText(value || "").replace(/\s+/g, " ").trim();
  if (!text || text.length <= maxLength) return text;
  return `${text.slice(0, Math.max(0, maxLength - 1)).trim()}…`;
}

function buildPortfolioWatchlistLaunchEveLines(watchlist = [], options = {}) {
  const compact = Boolean(options.compact);
  const focusItems = normalizePortfolioWatchlist(watchlist)
    .filter((item) => isLowBaseLaunchWatchSeed(item))
    .filter((item) => !["blocked", "removed", "in_position"].includes(item.status))
    .map((item) => ({ ...item, ...evaluatePortfolioWatchReadiness(item) }))
    .sort(comparePortfolioWatchReadiness)
    .slice(0, 3);
  if (!focusItems.length) return [];
  const lines = ["启动前夜重点复核："];
  for (const item of focusItems) {
    const gap = item.gaps?.[0] || buildPortfolioWatchReadinessGaps(item)[0] || "等待净值下钻确认";
    const trigger = item.buyTriggers?.[0] || "下一次净值更新后复核是否低位转强";
    if (compact) {
      lines.push(`- ${item.code} ${item.name || ""}：关注低位启动前夜；下一步：${shortenPortfolioCustomerText(trigger, 58)}；边界：${shortenPortfolioCustomerText(gap, 58)}。`);
    } else {
      lines.push(`- ${item.code} ${item.name || ""}（准备度${item.score}，${item.label}）：${gap}；触发=${trigger}；纪律=等净值下钻确认后再进入买点评估，不自动买入。`);
    }
  }
  return lines;
}

function buildPortfolioWatchlistActionQueueLines(watchlist = [], options = {}) {
  const compact = Boolean(options.compact);
  const ready = normalizePortfolioWatchlist(watchlist)
    .filter((item) => item.status === "ready")
    .map((item) => ({ ...item, ...evaluatePortfolioWatchReadiness(item) }))
    .sort(comparePortfolioWatchReadiness)
    .slice(0, 3);
  const waiting = normalizePortfolioWatchlist(watchlist)
    .filter((item) => item.status === "waiting_pullback")
    .map((item) => ({ ...item, ...evaluatePortfolioWatchReadiness(item) }))
    .sort(comparePortfolioWatchReadiness)
    .slice(0, 3);
  if (!ready.length && !waiting.length) return ["购买准备队列：暂无接近可买或等待回调候选。"];
  const lines = ["购买准备队列："];
  for (const item of [...ready, ...waiting]) {
    const status = item.status === "ready" ? "接近可买" : "等待回调";
    const trigger = item.buyTriggers?.[0] || item.positionPlan || "等待下一次复查";
    const risk = item.riskNotes?.[0] || "风险边界待补充";
    const gap = item.gaps?.[0] || buildPortfolioWatchReadinessGaps(item)[0] || "等待下一次复查";
    if (compact) {
      lines.push(`- ${item.code} ${item.name || ""}（${status}）：下一步：${shortenPortfolioCustomerText(trigger, 58)}；边界：${shortenPortfolioCustomerText(risk || gap, 58)}。`);
    } else {
      lines.push(`- ${item.code} ${item.name || ""}（${status}，准备度${item.score}，${item.label}）：触发=${trigger}；缺口=${gap}；风险=${risk}；复查=${item.reviewDate || "下一次盘前观察"}`);
    }
  }
  return lines;
}

function formatPortfolioWatchCompactLine(item = {}, options = {}) {
  const head = `${item.code || ""} ${item.name || ""}`.trim();
  const status = item.statusText || formatPortfolioWatchStatus(item.status);
  const rankingCitation = formatPortfolioWatchRankingCitationText(item.code, options.rankingCitationMap);
  const focus = item.reason
    || item.setupEvidence?.[0]
    || item.positionPlan
    || "等待经理下一轮复核。";
  const nextStep = item.buyTriggers?.[0]
    || item.positionPlan
    || item.readinessGaps?.[0]
    || item.reviewDate
    || "继续观察，不满足触发条件前不推进买入。";
  const boundary = item.riskNotes?.[0]
    || item.readinessGaps?.[0]
    || "风险边界待下一次净值和持仓资料确认；费用和替代份额在后台详情页查看。";
  const parts = [
    `${head}${status ? `（${status}）` : ""}`,
    `关注：${shortenPortfolioCustomerText(focus, 54)}`,
    `下一步：${shortenPortfolioCustomerText(nextStep, 58)}`,
    `边界：${shortenPortfolioCustomerText(boundary, 58)}`,
    rankingCitation ? `上榜：${shortenPortfolioCitationText(rankingCitation, 100)}` : ""
  ].filter(Boolean);
  return `- ${parts.join("；")}`;
}

function formatPortfolioWatchDetailLine(item = {}, options = {}) {
  const head = `${item.code || ""} ${item.name || ""}`.trim();
  const readiness = item.readinessScore === undefined ? evaluatePortfolioWatchReadiness(item) : { score: item.readinessScore, label: item.readinessLabel || "" };
  const rankingCitation = formatPortfolioWatchRankingCitationText(item.code, options.rankingCitationMap);
  const meta = [
    item.shareClass ? `${item.shareClass}类` : "",
    item.type || "",
    item.candidateRole || "",
    `准备度${readiness.score}${readiness.label ? `/${readiness.label}` : ""}`,
    `优先级${item.priority || 3}`
  ].filter(Boolean).join("，");
  const trendEvidence = formatPortfolioWatchSnapshotEvidence(item.lastSnapshot || {});
  const parts = [
    `${head}${meta ? `（${meta}）` : ""}`,
    item.reason ? `备选理由：${item.reason}` : "",
    item.setupEvidence?.length ? `证据：${item.setupEvidence.slice(0, 3).join("；")}` : "",
    item.buyTriggers?.length ? `触发：${item.buyTriggers.slice(0, 2).join("；")}` : "",
    item.riskNotes?.length ? `风险边界：${item.riskNotes.slice(0, 2).join("；")}` : "",
    item.feeNotes?.length ? `费用/份额：${item.feeNotes.slice(0, 2).join("；")}` : "",
    item.alternativeShareClasses?.length ? `替代份额：${formatPortfolioWatchAlternativesText(item.alternativeShareClasses)}` : "",
    item.sameExposureAlternatives?.length ? `同类替代：${formatPortfolioWatchAlternativesText(item.sameExposureAlternatives)}` : "",
    item.positionPlan ? `仓位计划：${item.positionPlan}` : "",
    item.readinessGaps?.length ? `买入缺口：${item.readinessGaps.slice(0, 3).join("；")}` : "",
    rankingCitation ? `上榜依据：${rankingCitation}` : "",
    trendEvidence ? `最新走势：${trendEvidence}` : "",
    item.reviewDate ? `复查：${item.reviewDate}` : ""
  ].filter(Boolean);
  return `- ${parts.join("；")}`;
}

function formatPortfolioWatchAlternativesText(items = []) {
  return (items || [])
    .slice(0, 3)
    .map((item) => [item.code, item.name || "", item.shareClass ? `${item.shareClass}类` : "", item.statusText || formatPortfolioWatchStatus(item.status)].filter(Boolean).join(" "))
    .join(" / ");
}

function formatPortfolioWatchSnapshotEvidence(snapshot = {}) {
  const trend = snapshot.trendProfile || {};
  return [
    snapshot.trendSummary && snapshot.trendSummary !== "走势数据不足" ? snapshot.trendSummary : "",
    snapshot.nav ? `净值${snapshot.nav}${snapshot.navDate ? `（${snapshot.navDate}）` : ""}` : "",
    Number.isFinite(Number(trend.lowPositionPct120)) ? `120日位置${round(Number(trend.lowPositionPct120), 1)}%` : "",
    Number.isFinite(Number(trend.drawdownFromRecentHighPct)) ? `距高点${formatSignedNumber(trend.drawdownFromRecentHighPct)}%` : ""
  ].filter(Boolean).join("，");
}

function buildPortfolioManagerProfileContext(config, db = null) {
  const schedule = [
    `盘前观察：${config.portfolioPremarketTime || "09:00"}`,
    `操作决策：${config.portfolioDecisionTime || "14:20"}`,
    `晚间复盘：${config.portfolioReviewTime || "21:30"}`,
    `周计划与总结：每${formatWeekdayLabel(config.portfolioWeeklyReviewDay)} ${config.portfolioWeeklyReviewTime || "16:30"}`
  ].join("；");
  const behavior = db ? summarizePortfolioManagerBehavior(db) : null;
  const capabilityDiagnostics = db ? buildPortfolioCapabilityDiagnostics(db) : null;
  const capabilityActionQueue = db ? buildPortfolioCapabilityActionQueue(db) : [];
  const backtestDiagnostics = db ? buildPortfolioBacktestDiagnostics(db) : null;
  return [
    `规定性画像：${normalizePortfolioManagerProfile(config.portfolioManagerProfile)}`,
    `风险风格：${config.portfolioRiskProfile || "balanced"}`,
    `自动汇报节奏：${schedule}`,
    behavior ? `账本行为画像：${JSON.stringify(behavior, null, 2)}` : "",
    backtestDiagnostics ? `历史回测诊断：${JSON.stringify(backtestDiagnostics, null, 2)}` : "",
    capabilityDiagnostics ? `组合能力诊断：${JSON.stringify(capabilityDiagnostics, null, 2)}` : "",
    capabilityActionQueue.length ? `能力修复队列：${JSON.stringify(capabilityActionQueue, null, 2)}` : ""
  ]
    .filter(Boolean)
    .join("\n");
}

function normalizePortfolioManagerProfile(value) {
  const text = String(value || "").trim();
  const lines = [text || DEFAULT_PORTFOLIO_MANAGER_PROFILE];
  const current = () => lines.join("\n");
  for (const item of REQUIRED_PORTFOLIO_MANAGER_PROFILE_LINES) {
    if (!item.pattern.test(current())) {
      lines.push(item.line);
    }
  }
  const output = lines.join("\n").trim();
  if (output.length <= 4000) return output;
  const requiredTail = REQUIRED_PORTFOLIO_MANAGER_PROFILE_LINES.map((item) => item.line).join("\n");
  return `${output.slice(0, Math.max(0, 4000 - requiredTail.length - 2)).trim()}\n${requiredTail}`.slice(0, 4000);
}

function summarizePortfolioManagerBehavior(db) {
  const account = summarizePortfolioAccount(db.account || createPortfolioAccount(getEffectiveConfig()));
  const transactions = (db.transactions || []).filter((item) => ["BUY", "SELL"].includes(item.side)).slice(-50);
  const buys = transactions.filter((item) => item.side === "BUY");
  const sells = transactions.filter((item) => item.side === "SELL");
  const recentRuns = (db.runs || []).slice(-20);
  const recentOrders = (db.orders || []).slice(-30);
  const watchlist = getActivePortfolioWatchlist(db);
  return {
    currentPositionWeightPct: account.positionWeightPct,
    currentCash: account.cash,
    accountDrawdownFromPeakPct: account.drawdownFromPeakPct,
    accountRiskBudgetLevel: account.riskBudget?.level || "normal",
    accountRiskBudgetLabel: account.riskBudget?.label || "回撤正常",
    watchlistCount: watchlist.length,
    readyWatchlistCount: watchlist.filter((item) => item.status === "ready").length,
    waitingWatchlistCount: watchlist.filter((item) => item.status === "waiting_pullback").length,
    recentTradeCount: transactions.length,
    recentBuyCount: buys.length,
    recentSellCount: sells.length,
    averageBuyAmount: averageAmount(buys),
    averageSellAmount: averageAmount(sells),
    activeOrderCount: recentOrders.filter((order) => !["confirmed", "cancelled", "rejected", "settled"].includes(order.status)).length,
    latestRunTypes: recentRuns.slice(-6).map((run) => `${run.date || ""}:${run.type || ""}:${run.status || ""}`).filter(Boolean)
  };
}

function averageAmount(items) {
  if (!items.length) return 0;
  return round(items.reduce((sum, item) => sum + Number(item.amount || 0), 0) / items.length, 2);
}

function buildPortfolioWeeklyContext(db, endDate) {
  const startDate = addDays(endDate, -6);
  const inRange = (item) => isDateStringInRange(item.date || item.submitDate || item.createdAt || item.startedAt || item.completedAt, startDate, endDate);
  return {
    startDate,
    endDate,
    runs: (db.runs || []).filter(inRange).map(summarizePortfolioRunBrief),
    orders: (db.orders || []).filter(inRange).map(summarizePortfolioOrder),
    transactions: (db.transactions || []).filter(inRange).slice(-50),
    settlements: (db.settlements || []).filter(inRange).slice(-30),
    equity: (db.dailyEquity || []).filter(inRange).slice(-10),
    account: summarizePortfolioAccount(db.account)
  };
}

function compactPortfolioWeeklyContext(context = {}) {
  return {
    startDate: context.startDate || "",
    endDate: context.endDate || "",
    runs: (context.runs || []).slice(-14).map(compactPortfolioWeeklyRun),
    failedRuns: (context.runs || []).filter((run) => run.status === "failed" || run.error).slice(-6).map(compactPortfolioWeeklyRun),
    orders: (context.orders || []).slice(-20).map(compactPortfolioWeeklyOrder),
    transactions: (context.transactions || []).slice(-30).map(compactPortfolioWeeklyTransaction),
    settlements: (context.settlements || []).slice(-12).map(compactPortfolioWeeklySettlement),
    equity: (context.equity || []).slice(-10).map(compactPortfolioWeeklyEquity),
    account: compactPortfolioWeeklyAccount(context.account || {})
  };
}

function compactPortfolioWeeklyRun(run = {}) {
  return {
    type: run.type || "",
    title: run.title || "",
    date: run.date || "",
    status: run.status || "",
    summary: String(run.summary || "").slice(0, 360),
    error: String(run.error || "").slice(0, 240),
    durationMs: run.durationMs || 0
  };
}

function compactPortfolioWeeklyOrder(order = {}) {
  return {
    side: order.side || "",
    status: order.status || "",
    code: order.code || "",
    name: order.name || "",
    amount: round(Number(order.amount || 0), 2),
    submitDate: order.submitDate || "",
    priceDate: order.priceDate || "",
    confirmDate: order.confirmDate || "",
    settlementDate: order.settlementDate || ""
  };
}

function compactPortfolioWeeklyTransaction(item = {}) {
  return {
    date: item.date || item.createdAt || "",
    side: item.side || item.type || "",
    code: item.code || "",
    name: item.name || "",
    amount: round(Number(item.amount || item.cashAmount || 0), 2),
    nav: item.nav || item.unitNav || "",
    units: item.units || ""
  };
}

function compactPortfolioWeeklySettlement(item = {}) {
  return {
    date: item.date || item.createdAt || "",
    status: item.status || "",
    side: item.side || "",
    code: item.code || "",
    amount: round(Number(item.amount || 0), 2)
  };
}

function compactPortfolioWeeklyEquity(item = {}) {
  const investedCostBasis = resolvePortfolioSnapshotInvestedCostBasis(item);
  const cumulativePnl = round(Number(item.cumulativePnl || 0), 2);
  return {
    date: item.date || "",
    totalAsset: round(Number(item.totalAsset || 0), 2),
    cash: round(Number(item.cash || 0), 2),
    investedValue: round(Number(item.investedValue || 0), 2),
    investedCost: round(Number(item.investedCost || 0), 2),
    investedCostBasis,
    dayPnl: round(Number(item.dayPnl || 0), 2),
    cumulativePnl,
    cumulativePnlPct: repairPortfolioSnapshotCumulativePnlPct(item, { cumulativePnl, investedCostBasis }),
    drawdownFromPeakPct: round(Number(item.drawdownFromPeakPct || 0), 2)
  };
}

function compactPortfolioWeeklyAccount(account = {}) {
  const investedCostBasis = resolvePortfolioSnapshotInvestedCostBasis(account);
  const cumulativePnl = round(Number(account.cumulativePnl || 0), 2);
  return {
    initialCapital: round(Number(account.initialCapital || 0), 2),
    cash: round(Number(account.cash || 0), 2),
    availableCash: round(Number(account.availableCash || account.cash || 0), 2),
    pendingBuyAmount: round(Number(account.pendingBuyAmount || 0), 2),
    receivableCash: round(Number(account.receivableCash || 0), 2),
    investedValue: round(Number(account.investedValue || 0), 2),
    investedCost: round(Number(account.investedCost || 0), 2),
    investedCostBasis,
    totalAsset: round(Number(account.totalAsset || 0), 2),
    peakTotalAsset: round(Number(account.peakTotalAsset || account.totalAsset || 0), 2),
    drawdownFromPeakPct: round(Number(account.drawdownFromPeakPct || 0), 2),
    riskBudget: compactPortfolioWeeklyRiskBudget(account.riskBudget),
    positionWeightPct: round(Number(account.positionWeightPct || 0), 2),
    dayPnl: round(Number(account.dayPnl || 0), 2),
    cumulativePnl,
    cumulativePnlPct: repairPortfolioSnapshotCumulativePnlPct(account, { cumulativePnl, investedCostBasis }),
    positions: (account.positions || []).map(compactPortfolioWeeklyPosition)
  };
}

function compactPortfolioWeeklyPosition(position = {}) {
  const snapshot = position.fundSnapshot || {};
  return {
    code: position.code || "",
    name: position.name || "",
    currentValue: round(Number(position.currentValue || 0), 2),
    costAmount: round(Number(position.costAmount || 0), 2),
    weightPct: round(Number(position.weightPct || 0), 2),
    unrealizedPnl: round(Number(position.unrealizedPnl || 0), 2),
    unrealizedPnlPct: round(Number(position.unrealizedPnlPct || 0), 2),
    peakUnrealizedPnlPct: Number.isFinite(Number(position.peakUnrealizedPnlPct)) ? round(Number(position.peakUnrealizedPnlPct), 2) : null,
    profitGivebackPct: round(Number(position.profitGivebackPct || 0), 2),
    lastNav: position.lastNav || snapshot.nav || null,
    lastNavDate: position.lastNavDate || snapshot.navDate || "",
    riskBudget: compactPortfolioWeeklyRiskBudget(position.riskBudget),
    trendSummary: snapshot.trendSummary || "",
    trendProfile: compactPortfolioTrendProfile(snapshot.trendProfile),
    actionability: compactPortfolioActionabilityProfile(snapshot.actionability),
    fees: snapshot.fees ? {
      shareClass: snapshot.fees.shareClass || "",
      shareClassFeeModel: snapshot.fees.shareClassFeeModel || null,
      feeImpact: snapshot.fees.feeImpact || null
    } : null,
    scale: snapshot.scale || null,
    topHoldings: (snapshot.topHoldings || []).slice(0, 10)
  };
}

function compactPortfolioWeeklyRiskBudget(riskBudget = null) {
  if (!riskBudget || typeof riskBudget !== "object") return null;
  return {
    level: riskBudget.level || "",
    label: riskBudget.label || "",
    drawdownFromPeakPct: finiteMetricNumber(riskBudget.drawdownFromPeakPct),
    blockNewBuys: Boolean(riskBudget.blockNewBuys),
    reduceRisk: Boolean(riskBudget.reduceRisk),
    throttleNewBuys: Boolean(riskBudget.throttleNewBuys),
    triggers: normalizeStringArray(riskBudget.triggers).slice(0, 4)
  };
}

function isDateStringInRange(value, startDate, endDate) {
  const date = extractDateOnly(value);
  return Boolean(date && date >= startDate && date <= endDate);
}

function extractDateOnly(value) {
  return String(value || "").match(/\d{4}-\d{2}-\d{2}/)?.[0] || "";
}

function buildPortfolioStatusAnswer(userText, intent) {
  const db = readPortfolioDb();
  const config = getEffectiveConfig();
  ensurePortfolioAccount(db, config);
  const account = summarizePortfolioAccount(db.account);
  const recentDecision = [...(db.runs || [])]
    .reverse()
    .find((run) => run.type === "decision" && run.status === "completed");
  const recentValuation = [...(db.runs || [])]
    .reverse()
    .find((run) => run.type === "valuation" && run.status === "completed");
  const today = getZonedDateTime(config.portfolioTimezone).date;
  const todayRuns = [...(db.runs || [])].filter((run) => run.date === today && run.status === "completed");
  const todayTransactions = [...(db.transactions || [])].filter((item) => item.date === today && ["BUY", "SELL"].includes(item.side));
  const positions = account.positions || [];
  const wantsOperation = isPortfolioOperationQuestion(userText);
  const wantsPosition = isPortfolioPositionQuestion(userText);
  const wantsWatchlist = isPortfolioWatchlistQuestion(userText);
  const wantsSchedule = isPortfolioScheduleQuestion(userText);
  const wantsProfile = isPortfolioProfileQuestion(userText);
  const wantsOnlyProfileOrSchedule = (wantsSchedule || wantsProfile) && !wantsOperation && !wantsPosition && !wantsWatchlist;
  const managerRankings = buildPortfolioRankingBoard(db);
  const activeOrders = (db.orders || []).filter((order) => !["confirmed", "cancelled", "rejected", "settled"].includes(order.status));

  const lines = ["虚拟基金经理账本"];
  lines.push("");
  if (wantsSchedule || wantsProfile) {
    lines.push("自动汇报节奏：");
    lines.push(`盘前观察：每天 ${config.portfolioPremarketTime}，只观察市场和持仓，不下单。`);
    lines.push(`操作决策：每天 ${config.portfolioDecisionTime}，生成今日手法并提交虚拟申购/赎回申请。`);
    lines.push(`晚间复盘：每天 ${config.portfolioReviewTime}，处理订单确认、估值和当日复盘。`);
    lines.push(`周计划与总结：每${formatWeekdayLabel(config.portfolioWeeklyReviewDay)} ${config.portfolioWeeklyReviewTime}，总结本周并规划下周。`);
    lines.push(`时区：${config.portfolioTimezone}。`);
    lines.push("");
  }
  if (wantsProfile) {
    const behavior = summarizePortfolioManagerBehavior(db);
    lines.push("基金经理画像：");
    lines.push(`规定性画像：${normalizePortfolioManagerProfile(config.portfolioManagerProfile)}`);
    lines.push(`当前配置风格：${config.portfolioRiskProfile || "balanced"}。`);
    lines.push(
      `账本行为画像：当前仓位 ${behavior.currentPositionWeightPct}%，可用现金 ${behavior.currentCash}元；` +
        `自选基金 ${behavior.watchlistCount} 只，其中接近可买 ${behavior.readyWatchlistCount} 只、等待回调 ${behavior.waitingWatchlistCount} 只；` +
        `最近 ${behavior.recentTradeCount} 笔确认交易，买入 ${behavior.recentBuyCount} 笔、卖出 ${behavior.recentSellCount} 笔；` +
        `平均买入 ${behavior.averageBuyAmount}元，平均卖出 ${behavior.averageSellAmount}元，未完成订单 ${behavior.activeOrderCount} 张。`
    );
    lines.push("");
  }
  if (wantsOnlyProfileOrSchedule) {
    lines.push(`当前自动运行：${config.portfolioEnabled ? "已启用" : "已停用"}。`);
  } else {
    lines.push(...buildPortfolioStatusDirectConclusionLines({
      account,
      managerRankings,
      recentDecision,
      activeOrders,
      todayTransactions
    }));
    lines.push("");
    lines.push(...buildPortfolioAccountStatusLines(account, { compact: !wantsPosition }));
  }

  if (!wantsOnlyProfileOrSchedule) {
    lines.push("");
    lines.push(...buildPortfolioCustomerDecisionSummaryStatusLines(managerRankings.customerDecisionSummary || {}));
    const consensusLines = buildPortfolioConsensusRadarStatusLines(managerRankings.consensusRadar || {});
    if (consensusLines.length) {
      lines.push("");
      lines.push(...consensusLines);
    }
    const leaderboardLines = buildPortfolioCustomerActionLeaderboardStatusLines(managerRankings.customerActionLeaderboard || {});
    if (leaderboardLines.length) {
      lines.push("");
      lines.push(...leaderboardLines);
    }
    lines.push("");
    lines.push(...buildPortfolioCustomerActionDeckStatusLines(managerRankings.customerActionDeck || {}));
  }

  if (wantsPosition || (!wantsOperation && !wantsOnlyProfileOrSchedule && !wantsWatchlist)) {
    lines.push("");
    lines.push("当前持仓：");
    lines.push(...buildPortfolioPositionStatusLines(positions, {
      compact: !wantsPosition,
      limit: wantsPosition ? 20 : 4
    }));
  }

  const exposureSummary = buildPortfolioExposureSummary(account.positions || []);
  if ((wantsPosition || wantsOperation || (!wantsOnlyProfileOrSchedule && !wantsWatchlist)) && exposureSummary.riskNotes.length) {
    lines.push("");
    lines.push("组合穿透暴露：");
    lines.push(...formatPortfolioExposureSummaryLines(exposureSummary));
  }

  if (wantsWatchlist || (!wantsOperation && !wantsOnlyProfileOrSchedule)) {
    const watchlist = getActivePortfolioWatchlist(db);
    lines.push("");
    lines.push("自选基金池：");
    if (watchlist.length) {
      lines.push(...buildPortfolioWatchlistStatusLines(watchlist, {
        limitPerStatus: wantsWatchlist ? 5 : 2,
        managerRankings,
        compact: !wantsWatchlist
      }));
    } else {
      lines.push("暂无自选基金。下一次盘前观察、今日操作或周总结会开始沉淀候选池。");
    }
  }

  if (wantsOperation || todayRuns.length || todayTransactions.length) {
    lines.push("");
    lines.push(...buildPortfolioTodayOperationStatusLines({
      today,
      transactions: todayTransactions,
      recentDecision
    }, {
      compact: !wantsOperation,
      limit: wantsOperation ? 8 : 4
    }));

    if (activeOrders.length) {
      lines.push("");
      lines.push(...buildPortfolioActiveOrderStatusLines(activeOrders, {
        compact: !wantsOperation,
        limit: wantsOperation ? 8 : 4
      }));
    }

    if (recentDecision) {
      lines.push("");
      lines.push(...buildPortfolioRecentDecisionStatusLines(recentDecision, { limit: wantsOperation ? 6 : 4 }));
    }
  }

  if (recentValuation) {
    lines.push("");
    lines.push(`最近复盘：${recentValuation.date}`);
    if (recentValuation.accountAfter) {
      lines.push(
        `复盘后资产 ${recentValuation.accountAfter.totalAsset}元，仓位 ${recentValuation.accountAfter.positionWeightPct}%` +
          `，累计盈亏 ${formatSignedNumber(recentValuation.accountAfter.cumulativePnl)}元。`
      );
    }
  }

  lines.push("");
  lines.push(`数据来源：服务器虚拟组合账本 ${path.basename(PORTFOLIO_DB_PATH)}。`);
  lines.push(`路由：${intent.reason || "portfolio_status"}。`);
  return lines.join("\n");
}

function getPortfolioPublicState(db = readPortfolioDb(), options = {}) {
  const config = getEffectiveConfig();
  const lightweight = Boolean(options.lightweight);
  ensurePortfolioAccount(db, config);
  const target = resolvePortfolioPushTarget(config, db);
  const recentRunLimit = lightweight ? 6 : 20;
  const recentItemLimit = lightweight ? 10 : 30;
  const summarizePosition = lightweight ? summarizePortfolioPositionBrief : summarizePortfolioPosition;
  const summarizeAccount = lightweight ? summarizePortfolioAccountBrief : summarizePortfolioAccount;
  const summarizeWatch = lightweight ? summarizePortfolioWatchItemBrief : summarizePortfolioWatchItem;
  const summarizeRun = lightweight
    ? (run) => summarizePortfolioRunBrief(run, db.account)
    : (run) => summarizePortfolioRun(run, db.account);
  const summarizeTransaction = lightweight ? summarizePortfolioTransactionBrief : (item) => item;
  const summarizeEquity = lightweight ? summarizePortfolioEquityBrief : (item) => item;
  return {
    dbPath: PORTFOLIO_DB_PATH,
    enabled: Boolean(config.portfolioEnabled),
    lightweight,
    retentionDays: Number(config.portfolioRetentionDays || 90),
    scheduler: {
      premarketTime: config.portfolioPremarketTime,
      decisionTime: config.portfolioDecisionTime,
      reviewTime: config.portfolioReviewTime,
      weeklyReviewTime: config.portfolioWeeklyReviewTime,
      weeklyReviewDay: config.portfolioWeeklyReviewDay,
      timezone: config.portfolioTimezone,
      inFlight: portfolioRunInFlight,
      activeRunId: activePortfolioRunId || "",
      activeRunStartedAt: (db.runs || []).find((run) => run.id === activePortfolioRunId)?.startedAt || "",
      dbFlushPending: portfolioDbFlushPending || Boolean(portfolioDbFlushTimer) || portfolioDbFlushInFlight,
      dbFlushError: portfolioDbLastFlushError
    },
    pushTarget: target
      ? {
          receiveIdType: target.receiveIdType || "chat_id",
          receiveIdMasked: maskSecret(target.receiveId),
          label: target.label || ""
        }
      : null,
    knownPushTargets: (db.pushTargets || []).slice(lightweight ? -3 : -10).reverse().map((target) => ({
      receiveIdType: target.receiveIdType,
      receiveIdMasked: maskSecret(target.receiveId),
      label: target.label,
      firstSeenAt: target.firstSeenAt,
      lastSeenAt: target.lastSeenAt
    })),
    account: summarizeAccount(db.account),
    exposureSummary: buildPortfolioExposureSummary(db.account.positions || []),
    backtestDiagnostics: buildPortfolioBacktestDiagnostics(db),
    capabilityDiagnostics: buildPortfolioCapabilityDiagnostics(db),
    capabilityActionQueue: buildPortfolioCapabilityActionQueue(db),
    managerRankings: buildPortfolioRankingBoard(db),
    rankingActionAudit: buildPortfolioRankingActionAudit(db),
    managerPerformance: buildPortfolioManagerPerformanceStats(db),
    userPortfolios: summarizeUserPortfolios(db),
    positions: db.account.positions.map(summarizePosition),
    watchlist: getActivePortfolioWatchlist(db).slice(0, lightweight ? 12 : 50).map(summarizeWatch),
    activeOrders: (db.orders || []).filter((order) => !["confirmed", "cancelled", "rejected", "settled"].includes(order.status)).map(summarizePortfolioOrder),
    recentRuns: (db.runs || []).slice(-recentRunLimit).reverse().map(summarizeRun),
    recentOrders: (db.orders || []).slice(-recentItemLimit).reverse().map(summarizePortfolioOrder),
    recentTransactions: (db.transactions || []).slice(-recentItemLimit).reverse().map(summarizeTransaction),
    pendingSettlements: (db.settlements || []).filter((item) => item.status === "pending").slice(-20).reverse(),
    recentEquity: (db.dailyEquity || []).slice(-recentItemLimit).reverse().map(summarizeEquity)
  };
}

function buildPortfolioRankingBoard(db = {}) {
  const watchlist = applyPortfolioCatchdownLossMemoryToWatchlist(
    getActivePortfolioWatchlist(db).map(summarizePortfolioWatchItem).filter(Boolean),
    db
  );
  const positions = (db.account?.positions || []).map(summarizePortfolioPosition).filter(Boolean);
  const userPortfolios = summarizeUserPortfolios(db).filter(Boolean);
  const lists = [
    buildPortfolioDecisionSynthesisRanking(watchlist),
    buildPortfolioBuyPreparationRanking(watchlist),
    buildPortfolioLaunchSetupRanking(watchlist),
    buildPortfolioCashRedeploymentRanking(db, watchlist),
    buildPortfolioPositionSizingRanking(db, watchlist),
    buildPortfolioQualityScoreRanking(watchlist),
    buildPortfolioManagerStabilityRanking(watchlist),
    buildPortfolioFitRanking(db, watchlist),
    buildPortfolioThemeAllocationRanking(watchlist),
    buildPortfolioThemeMomentumRanking(watchlist),
    buildPortfolioRotationOpportunityRanking(watchlist),
    buildPortfolioStaleCatchdownRiskRanking(watchlist),
    buildPortfolioChaseRiskRanking(watchlist),
    buildPortfolioDrawdownDefenseRanking(watchlist, positions),
    buildPortfolioDataConfidenceRanking(watchlist, positions),
    buildPortfolioHoldingsOutlookRanking(watchlist),
    buildPortfolioFeeSuitabilityRanking(watchlist),
    buildPortfolioReplacementChoiceRanking(watchlist),
    buildPortfolioOpportunityCostRanking(db, watchlist),
    buildPortfolioSellRiskRanking(positions),
    buildUserHoldingAlertRanking(userPortfolios)
  ];
  const priorityQueue = buildPortfolioRankingPriorityQueue(lists);
  const customerDigest = buildPortfolioRankingCustomerDigest(lists);
  const decisionMatrix = buildPortfolioRankingDecisionMatrix(lists, priorityQueue);
  const consensusRadar = buildPortfolioRankingConsensusRadar(decisionMatrix, priorityQueue);
  const alertCenter = buildPortfolioRankingAlertCenter(lists, priorityQueue, decisionMatrix);
  const customerActionDeck = buildPortfolioRankingCustomerActionDeck({
    customerDigest,
    alertCenter,
    decisionMatrix,
    priorityQueue,
    lists
  });
  const customerDecisionSummary = buildPortfolioRankingCustomerDecisionSummary({
    customerActionDeck,
    alertCenter,
    decisionMatrix,
    priorityQueue
  });
  const customerActionLeaderboard = buildPortfolioRankingCustomerActionLeaderboard({
    customerActionDeck,
    alertCenter,
    decisionMatrix,
    priorityQueue
  });
  return {
    updatedAt: new Date().toISOString(),
    lists,
    priorityQueue,
    alertCenter,
    decisionMatrix,
    consensusRadar,
    customerDigest,
    customerActionDeck,
    customerDecisionSummary,
    customerActionLeaderboard,
    health: buildPortfolioRankingBoardHealth({ watchlist, positions, userPortfolios, lists }),
    summary: `${lists.map((list) => `${list.title}${list.items.length}只`).join("，")}；预警${alertCenter.items.length}项；矩阵${decisionMatrix.items.length}只；共识${consensusRadar.items.length}只；今日优先${priorityQueue.length}项；行动牌${customerActionDeck.cards.filter((card) => card.count).length}类；摘要${customerDecisionSummary.lines.length}条；行动榜${customerActionLeaderboard.lanes.filter((lane) => lane.count).length}类`
  };
}

function buildPortfolioRankingBoardHealth({ watchlist = [], positions = [], userPortfolios = [], lists = [] } = {}) {
  const totalItems = lists.reduce((sum, list) => sum + (list.items?.length || 0), 0);
  if (totalItems > 0) {
    return {
      level: "ok",
      title: "榜单已生成",
      summary: `当前有 ${totalItems} 个可复核对象，经理可以按综合决策、买入、低位启动、现金再部署、仓位方案、基金质量、经理稳定、组合适配、主题配置、主力预热、板块轮动、追涨风险、回撤防线、数据体检、持仓前景、费率适配、替代优选、机会成本、卖出风险和用户持仓提醒分层处理。`,
      actions: ["优先处理排名靠前项", "综合结论/买点/仓位/质量/经理稳定/组合适配/主题配置/主力预热/轮动/追涨/回撤/数据/费率/替代/持仓分开复核", "把用户真实持仓提醒放入每日跟踪"]
    };
  }
  if (!watchlist.length && !positions.length && !userPortfolios.length) {
    return {
      level: "warning",
      title: "缺少榜单输入",
      summary: "当前没有自选池、虚拟持仓和用户持仓数据，榜单只能显示空状态。",
      actions: ["先运行一次盘前观察或今日操作", "从对话截图导入用户持仓", "补充低位启动候选池"]
    };
  }
  return {
    level: "watch",
    title: "暂无触发项",
    summary: "已有基础数据，但暂未出现买入、卖出或用户提醒触发项。",
    actions: ["检查空仓等待诊断", "复核低位启动条件是否过严", "继续沉淀用户持仓成本和盈利点"]
  };
}

function buildPortfolioDecisionSynthesisRanking(watchlist = []) {
  const items = (watchlist || [])
    .filter((item) => item?.code && ["ready", "waiting_pullback", "watch"].includes(item.status))
    .map(buildPortfolioDecisionSynthesisRankingItem)
    .filter(Boolean)
    .sort(compareRankingItems)
    .slice(0, 6);
  return buildPortfolioRankingList({
    id: "decision_synthesis",
    title: "综合决策榜",
    subtitle: "把买点、轮动、追涨风险、费率和持仓前景合成一张客户可读的候选排序。",
    emptyText: "暂无可形成综合结论的候选。",
    nextAction: "下一步补齐走势、题材轮动、前十大持仓和费率证据，再把候选升为可买、观察或回避。",
    items
  });
}

function buildPortfolioDecisionSynthesisRankingItem(item = {}) {
  const evidence = resolvePortfolioDecisionSynthesisEvidence(item);
  if (!evidence.shouldSurface) return null;
  if (evidence.hardCatchdown) return null;
  return buildPortfolioRankingItem({
    code: item.code,
    name: item.name,
    source: "综合决策",
    score: round(evidence.score, 1),
    action: evidence.action,
    reason: evidence.reason,
    facts: evidence.facts,
    decision: {
      highlights: evidence.highlights,
      risks: evidence.risks,
      gaps: evidence.gaps,
      nextStep: evidence.nextStep
    },
    status: evidence.level
  });
}

function resolvePortfolioDecisionSynthesisEvidence(item = {}) {
  const trend = item.lastSnapshot?.trendProfile || {};
  const rotation = resolvePortfolioRotationOpportunityEvidence(item);
  const chase = resolvePortfolioChaseRiskEvidence(item);
  const fee = resolvePortfolioWatchFeeSuitabilityEvidence(item);
  const outlook = resolvePortfolioWatchHoldingsOutlook(item);
  const rotationThemeGap = rotation.missingTheme && rotation.shouldSurface
    ? "缺少当前题材雷达，不能把纯走势低位修复当成板块轮动买点。"
    : "";
  const themeSupportGap = getPortfolioWatchThemeSupportGap(item) || rotationThemeGap;
  const hardCatchdown = Boolean(
    chase.holdingRealtimeCatchdownRisk
    || chase.staleThemeRefreshRisk
    || chase.staleCatchdownRisk
    || chase.staleCatalystRisk
    || chase.themeRetreatRisk
    || chase.unsupportedHoldingThemeRisk
    || themeSupportGap
  );
  const readinessScore = Number(item.readinessScore || 0);
  const setupSignal = trend.pullbackSetup?.signal || "";
  const low120 = Number(trend.lowPositionPct120);
  const scoreParts = [
    Math.min(34, readinessScore * 0.34),
    rotation.strong ? 18 : rotation.shouldSurface && !rotation.highChase ? 10 : 0,
    rotation.leaderPositive && !rotation.highChase ? 12 : 0,
    ["pullback_complete", "launch_setup"].includes(setupSignal) ? 14 : 0,
    Number.isFinite(low120) && low120 <= 55 ? 8 : 0,
    Number(outlook.score || 0) >= 10 ? 10 : Number(outlook.score || 0) >= 5 ? 5 : 0,
    fee.missingCritical ? -14 : fee.highDrag ? -6 : 5,
    chase.shouldSurface ? -Math.min(38, Math.max(16, Number(chase.score || 0) * 0.45)) : 0,
    themeSupportGap ? -24 : 0
  ];
  const score = Math.max(0, Math.min(100, scoreParts.reduce((sum, value) => sum + value, 0)));
  const hasPositiveEvidence = readinessScore >= 45
    || rotation.shouldSurface
    || ["pullback_complete", "launch_setup"].includes(setupSignal)
    || Number(outlook.score || 0) > 0;
  const shouldSurface = hasPositiveEvidence || chase.shouldSurface || fee.shouldSurface;
  const buyable = score >= 70 && !chase.shouldSurface && !fee.missingCritical && !themeSupportGap;
  const starter = score >= 55 && !chase.shouldSurface && !fee.missingCritical && !themeSupportGap;
  const action = chase.shouldSurface
    ? "综合回避"
    : themeSupportGap
      ? "先补题材证据"
    : buyable
      ? "优先买入复核"
      : starter
        ? "小仓试探复核"
        : "继续观察";
  const level = chase.shouldSurface || themeSupportGap ? "warning" : buyable ? "ready" : starter ? "watch" : item.status || "watch";
  const highlights = [
    readinessScore ? `准备度${round(readinessScore, 0)}` : "",
    rotation.leaderPositive && rotation.leaderLabel ? `主力节奏：${rotation.leaderLabel}` : "",
    rotation.newsLogic ? `题材逻辑：${rotation.newsLogic}` : "",
    rotation.shouldSurface && !rotation.highChase ? "板块轮动或低位修复有支撑" : "",
    trend.pullbackSetup?.signalText || "",
    Number(outlook.score || 0) >= 5 ? "前十大持仓有复核价值" : "",
    !fee.missingCritical ? "份额费用可进入复核" : ""
  ].filter(Boolean).slice(0, 3);
  const risks = [
    chase.shouldSurface ? "追涨风险未解除" : "",
    themeSupportGap || "",
    fee.missingCritical ? "费用/份额证据不足" : "",
    fee.highDrag ? "持有期费用拖累偏高" : "",
    outlook.risks?.[0] || ""
  ].filter(Boolean).slice(0, 3);
  const gaps = [
    !["pullback_complete", "launch_setup"].includes(setupSignal) ? "缺回调完成或启动信号" : "",
    themeSupportGap || "",
    rotation.missingTheme ? "缺板块轮动证据" : "",
    fee.missingCritical ? "缺费用/份额关键证据" : "",
    !outlook.hasHoldings ? "缺前十大持仓" : ""
  ].filter(Boolean).slice(0, 3);
  return {
    score,
    shouldSurface,
    hardCatchdown,
    action,
    level,
    reason: buildPortfolioDecisionSynthesisReason({ buyable, starter, chase, fee, rotation, themeSupportGap }),
    facts: [
      readinessScore ? `准备度${round(readinessScore, 0)}` : "",
      rotation.themeName ? `轮动${rotation.themeName}` : "",
      rotation.leaderPositive ? "主力预热" : "",
      chase.shouldSurface ? "追涨拦截" : "",
      fee.shareClass ? `${fee.shareClass}类` : "",
      Number.isFinite(low120) ? `120日位置${round(low120, 1)}%` : ""
    ].filter(Boolean),
    highlights,
    risks,
    gaps,
    nextStep: chase.shouldSurface
      ? "先按追涨风险榜降级观察，等回撤和拥挤度降温后再恢复买入复核。"
      : themeSupportGap
        ? "先补当前题材雷达、新闻催化和主力资金证据；确认前不给买入金额。"
      : buyable || starter
        ? "再和买入准备、费率适配、持仓前景三项交叉确认，通过后只允许小仓或分批。"
        : "继续补齐缺口，不把单一亮点包装成主推荐。"
  };
}

function buildPortfolioDecisionSynthesisReason({ buyable = false, starter = false, chase = {}, fee = {}, rotation = {}, themeSupportGap = "" } = {}) {
  if (chase.shouldSurface) return "综合看追涨风险压过买点证据，本轮不应作为主推荐。";
  if (themeSupportGap) return "走势线索不能脱离当前题材证据；缺少主力、预热或低位轮动支撑时，不把回调包装成买点。";
  if (fee.missingCritical) return "综合证据尚可，但费用/份额证据不足，买入前必须补齐。";
  if (buyable) return "买点、轮动和费用证据相对完整，适合进入优先买入复核。";
  if (rotation.leaderPositive) return "主力进场或新闻预热已经出现，但还要等基金自身买点和费用证据确认。";
  if (starter) return "有低位或轮动线索，但仍需小仓试探和交叉确认。";
  if (rotation.shouldSurface) return "已有轮动或低位线索，但综合证据还不足以直接买入。";
  return "综合证据偏弱，暂时只保留观察，不进入主推荐。";
}

function buildPortfolioBuyPreparationRanking(watchlist = []) {
  const items = watchlist
    .filter((item) => ["ready", "waiting_pullback"].includes(item.status))
    .map((item) => {
      const riskGate = resolvePortfolioPositiveWatchRankingGate(item);
      if (!riskGate.ok) return null;
      const readiness = evaluatePortfolioWatchReadiness(item, item.lastSnapshot || null);
      const readinessScore = Number(readiness.score || item.readinessScore || 0);
      const highReadiness = readinessScore >= 85;
      const mediumReadiness = readinessScore >= 60;
      return buildRankingItemFromWatch(item, {
        score: readinessScore + (item.status === "ready" ? 12 : 0),
        action: highReadiness ? "买入复核" : mediumReadiness ? "触发复核" : "补证据",
        reason: highReadiness
          ? "买入准备度较高，适合进入金额和触发条件复核。"
          : selectPortfolioRankingFirstText(readiness.gaps, item.readinessGaps, item.buyTriggers, item.reason) || "方向可跟踪，但还需要补齐买点证据。",
        gaps: readiness.gaps,
        nextStep: highReadiness
          ? "复核金额、份额类别和15:00前交易规则，再决定小仓或分批。"
          : "等待缺口消失后再升级，避免把备选误当成买入。"
      });
    })
    .filter(Boolean)
    .sort(compareRankingItems)
    .slice(0, 6);
  return buildPortfolioRankingList({
    id: "buy_preparation",
    title: "买入准备榜",
    subtitle: "从自选池里挑出最接近执行的候选，辅助客户决定先看谁。",
    emptyText: "暂无接近买点的候选。",
    nextAction: "下一步刷新自选池，优先找回调完成且5日/10日刚转强的低位候选。",
    items
  });
}

function buildPortfolioLaunchSetupRanking(watchlist = []) {
  const items = watchlist
    .filter((item) => isLowBaseLaunchWatchSeed(item))
    .filter((item) => !["blocked", "removed", "in_position"].includes(item.status))
    .filter((item) => resolvePortfolioPositiveWatchRankingGate(item).ok)
    .map((item) => buildRankingItemFromWatch(item, {
      score: Number(item.readinessScore || 0) + 8 - Number(item.priority || 3),
      action: "启动前夜复核",
      reason: "低位启动前夜候选，只等净值和早期转强证据确认。",
      nextStep: "只盯回调完成后的第一段转强，不用提前重仓。"
    }))
    .sort(compareRankingItems)
    .slice(0, 6);
  return buildPortfolioRankingList({
    id: "launch_setup",
    title: "低位启动榜",
    subtitle: "优先展示回调后准备启动的候选，避免只盯热门追涨。",
    emptyText: "暂无低位启动前夜候选。",
    nextAction: "下一步放宽行业召回范围，再用低位、回撤深度和持仓前景二次筛选。",
    items
  });
}

function buildPortfolioCashRedeploymentRanking(db = {}, watchlist = []) {
  const account = summarizePortfolioAccount(db.account || {});
  const totalAsset = Number(account.totalAsset || 0);
  const cash = Number(account.cash || 0);
  const cashPct = totalAsset > 0 && Number.isFinite(cash) ? cash / totalAsset * 100 : null;
  const positionWeight = Number(account.positionWeightPct || 0);
  const pressureActive = Number.isFinite(cashPct)
    && cashPct >= 55
    && positionWeight <= 45
    && !account.riskBudget?.blockNewBuys;
  const items = pressureActive
    ? (watchlist || [])
      .filter((item) => ["ready", "waiting_pullback", "watch"].includes(item.status))
      .map((item) => buildPortfolioCashRedeploymentRankingItem(item, { cashPct, positionWeight }))
      .filter(Boolean)
      .sort(compareRankingItems)
      .slice(0, 6)
    : [];
  return buildPortfolioRankingList({
    id: "cash_redeployment",
    title: "现金再部署榜",
    subtitle: "当可动用现金偏高、仓位偏低时，把接近买点的候选拉出来复核，防止经理长期只说等待。",
    emptyText: pressureActive ? "现金压力存在，但暂无可进入再部署复核的候选。" : "当前现金或仓位不触发再部署压力。",
    nextAction: pressureActive
      ? "下一步对靠前候选给小仓试探、主动降级或明确复查时间，不能继续泛泛等待。"
      : "若现金升至55%以上且仓位偏低，再用低位、回调完成、费率和追涨拦截筛选候选。",
    items
  });
}

function buildPortfolioCashRedeploymentRankingItem(item = {}, context = {}) {
  const readinessScore = Number(item.readinessScore || 0);
  const trend = item.lastSnapshot?.trendProfile || {};
  const riskGate = resolvePortfolioPositiveWatchRankingGate(item);
  const return20d = finiteMetricNumber(trend.return20dPct);
  const low120 = finiteMetricNumber(trend.lowPositionPct120);
  const themeSupportGap = getPortfolioWatchThemeSupportGap(item);
  const highChase = hasHighChaseTheme(item.lastSnapshot || item)
    || (Number.isFinite(return20d) && return20d > 12 && Number.isFinite(low120) && low120 > 80);
  if (!riskGate.ok || highChase || item.status === "blocked" || themeSupportGap) return null;
  const ready = item.status === "ready" && readinessScore >= 80;
  const starter = item.status === "ready" || readinessScore >= 60;
  if (!starter) return null;
  const score = Math.max(0, Math.min(100,
    readinessScore
    + (ready ? 14 : 6)
    + (Number.isFinite(context.cashPct) ? Math.min(16, Math.max(0, context.cashPct - 50) * 0.7) : 0)
    + (Number.isFinite(low120) && low120 <= 55 ? 6 : 0)
    - (Number.isFinite(return20d) && return20d > 8 ? 8 : 0)
  ));
  return buildRankingItemFromWatch(item, {
    score,
    action: ready ? "现金再部署买入复核" : "0.5%-2.5%试探复核",
    reason: ready
      ? "现金偏高且候选准备度较高，需要复核是否小仓启动，避免继续空泛观望。"
      : "现金偏高但候选仍有缺口，只能进入小仓试探复核或写清下一次触发条件。",
    highlights: [
      Number.isFinite(context.cashPct) ? `可动用现金${formatFallbackPlainPct(context.cashPct)}` : "",
      Number.isFinite(context.positionWeight) ? `当前仓位${formatFallbackPlainPct(context.positionWeight)}` : "",
      item.readinessLabel ? `准备度${readinessScore}/${item.readinessLabel}` : ""
    ].filter(Boolean),
    risks: [
      Number.isFinite(return20d) && return20d > 8 ? "近20日涨幅偏快，试探仓必须更小。" : "",
      ...(item.riskNotes || [])
    ].filter(Boolean),
    gaps: item.readinessGaps || [],
    nextStep: ready
      ? "今日操作必须给 BUY 小仓复核或明确风控拦截理由；若买入，只允许0.5%-2.5%启动仓。"
      : "下一次净值更新后复核缺口是否消失；若缺口消失，只允许0.5%-2.5%小仓试探，不能把它写成无限期等待。"
  });
}

function buildPortfolioPositionSizingRanking(db = {}, watchlist = []) {
  const account = summarizePortfolioAccount(db.account || {});
  const items = (watchlist || [])
    .filter((item) => item?.code && ["ready", "waiting_pullback", "watch"].includes(item.status))
    .map((item) => buildPortfolioPositionSizingRankingItem(item, account))
    .filter(Boolean)
    .sort(compareRankingItems)
    .slice(0, 6);
  return buildPortfolioRankingList({
    id: "position_sizing",
    title: "仓位方案榜",
    subtitle: "把候选基金转成0元观察、0.5%-1.5%试探或最多2.5%启动仓，避免只说可以买却不给边界。",
    emptyText: "暂无可形成仓位方案的候选。",
    nextAction: "下一步按账户现金、当前仓位、买点质量、费率和追涨风险给仓位上限；金额由系统按真实总资产换算。",
    items
  });
}

function buildPortfolioPositionSizingRankingItem(item = {}, account = {}) {
  const readinessScore = Number(item.readinessScore || 0);
  const trend = item.lastSnapshot?.trendProfile || {};
  const chase = resolvePortfolioChaseRiskEvidence(item);
  const fee = resolvePortfolioWatchFeeSuitabilityEvidence(item);
  const themeSupportGap = getPortfolioWatchThemeSupportGap(item);
  const cashPct = Number(account.cashPct ?? (Number(account.totalAsset || 0) > 0 ? Number(account.cash || 0) / Number(account.totalAsset || 1) * 100 : NaN));
  const positionWeight = Number(account.positionWeightPct || 0);
  const blockNewBuys = Boolean(account.riskBudget?.blockNewBuys);
  const highChase = chase.shouldSurface || hasHighChaseTheme(item.lastSnapshot || item);
  const executable = !blockNewBuys && !highChase && !fee.missingCritical && !themeSupportGap && readinessScore >= 55;
  const sizing = resolvePortfolioSizingBand({
    item,
    readinessScore,
    cashPct,
    positionWeight,
    blockNewBuys,
    highChase,
    feeMissing: fee.missingCritical,
    themeSupportGap
  });
  if (!sizing.shouldSurface) return null;
  const score = Math.max(0, Math.min(100,
    readinessScore * 0.5
    + sizing.upperPct * 12
    + (item.status === "ready" ? 10 : 0)
    - (blockNewBuys ? 30 : 0)
    - (highChase ? 26 : 0)
    - (fee.missingCritical ? 18 : 0)
  ));
  return buildPortfolioRankingItem({
    code: item.code,
    name: item.name,
    source: "仓位方案",
    score: round(score, 1),
    action: sizing.action,
    reason: sizing.reason,
    facts: [
      sizing.label,
      Number.isFinite(cashPct) ? `现金${formatFallbackPlainPct(cashPct)}` : "",
      Number.isFinite(positionWeight) ? `当前仓位${formatFallbackPlainPct(positionWeight)}` : "",
      readinessScore ? `准备度${round(readinessScore, 0)}` : ""
    ].filter(Boolean),
    decision: {
      highlights: [
        executable ? `${sizing.label}，先做小仓验证，不做重仓判断。` : "",
        item.status === "ready" ? "自选池状态接近可买。" : "",
        trend.pullbackSetup?.signalText || ""
      ].filter(Boolean),
      risks: [
        blockNewBuys ? "账户回撤预算拦截新增买入。" : "",
        highChase ? "追涨风险未解除，仓位应为0元观察。" : "",
        themeSupportGap || "",
        fee.missingCritical ? "费用/份额关键证据未补齐，不能给买入仓位。" : ""
      ].filter(Boolean),
      gaps: [
        readinessScore < 55 ? "准备度不足，不能给试探仓。" : "",
        !Number.isFinite(cashPct) ? "缺现金比例" : "",
        ...normalizeStringArray(item.readinessGaps).slice(0, 2)
      ].filter(Boolean),
      nextStep: sizing.nextStep
    },
    status: executable ? "ready" : "watch"
  });
}

function resolvePortfolioSizingBand({ item = {}, readinessScore = 0, cashPct = null, positionWeight = 0, blockNewBuys = false, highChase = false, feeMissing = false, themeSupportGap = "" } = {}) {
  if (blockNewBuys || highChase || feeMissing || themeSupportGap || readinessScore < 45) {
    return {
      shouldSurface: Boolean(blockNewBuys || highChase || feeMissing || themeSupportGap || item.status === "ready" || readinessScore >= 45),
      lowerPct: 0,
      upperPct: 0,
      label: "0元观察",
      action: "0元观察",
      reason: blockNewBuys
        ? "账户回撤预算不允许新增买入，本轮只给观察仓位。"
        : highChase
          ? "追涨或高位风险未解除，不能用小仓试探替代风控。"
          : themeSupportGap
            ? "当前题材缺少主力/预热/低位轮动支撑，仓位必须保持0元观察。"
          : feeMissing
            ? "费用/份额关键证据未补齐，买入前仓位必须为0。"
            : "准备度不足，暂时不能给试探仓。",
      nextStep: "先补齐买点、费用、追涨风险和组合适配证据；未通过前仓位保持0元观察。"
    };
  }
  const lowCashCap = Number.isFinite(cashPct) && cashPct < 25;
  const highPositionCap = Number(positionWeight || 0) >= 55;
  const ready = item.status === "ready" && readinessScore >= 80;
  const upperPct = ready && !lowCashCap && !highPositionCap
    ? 2.5
    : readinessScore >= 65 && !highPositionCap
      ? 1.5
      : 1;
  const lowerPct = upperPct >= 2.5 ? 1 : upperPct >= 1.5 ? 0.5 : 0.5;
  const label = `${lowerPct}%-${upperPct}%试探仓`;
  return {
    shouldSurface: true,
    lowerPct,
    upperPct,
    label,
    action: upperPct >= 2.5 ? "2.5%启动仓复核" : "小仓试探复核",
    reason: ready
      ? "买点准备度较高，但仍按启动仓上限处理，先验证不重仓。"
      : "候选接近买点但证据未完全闭环，只允许小仓试探或继续等待。",
    nextStep: `若买入，目标仓位控制在${label}；先和买入准备、组合适配、费率适配交叉确认，确认失败则降为0元观察。`
  };
}

function buildPortfolioQualityScoreRanking(watchlist = []) {
  const items = (watchlist || [])
    .filter((item) => item?.code && !["removed"].includes(item.status))
    .map(buildPortfolioQualityScoreRankingItem)
    .filter(Boolean)
    .sort(compareRankingItems)
    .slice(0, 6);
  return buildPortfolioRankingList({
    id: "quality_score",
    title: "基金质量榜",
    subtitle: "按回撤、夏普、年化收益、规模和费用完整性复核基金底子，避免只因短线买点推荐质量一般的产品。",
    emptyText: "暂无足够质量数据可排序的候选。",
    nextAction: "下一步补齐1年/3年风险收益、最大回撤、夏普、规模和费率证据；质量不过关的基金只能作为观察或替代品。",
    items
  });
}

function buildPortfolioQualityScoreRankingItem(item = {}) {
  const evidence = resolvePortfolioQualityScoreEvidence(item);
  if (!evidence.shouldSurface) return null;
  return buildPortfolioRankingItem({
    code: item.code,
    name: item.name,
    source: "基金质量",
    score: round(evidence.score, 1),
    action: evidence.action,
    reason: evidence.reason,
    facts: evidence.facts,
    decision: {
      highlights: evidence.highlights,
      risks: evidence.risks,
      gaps: evidence.gaps,
      nextStep: evidence.nextStep
    },
    status: evidence.status
  });
}

function resolvePortfolioQualityScoreEvidence(item = {}) {
  const snapshot = item.lastSnapshot || {};
  const risk = selectPortfolioQualityRiskPeriod(snapshot);
  const scaleYi = getPortfolioWatchFundScaleYi(item, snapshot);
  const fee = resolvePortfolioWatchFeeSuitabilityEvidence(item);
  const concentration = getPortfolioWatchTop10Pct(item, snapshot);
  const hasRisk = Boolean(risk?.ok || Number.isFinite(risk?.sharpe) || Number.isFinite(risk?.maxDrawdownPct) || Number.isFinite(risk?.annualizedReturnPct));
  const hasQualityEvidence = hasRisk || Number.isFinite(scaleYi) || Number.isFinite(concentration) || fee.shouldSurface;
  if (!hasQualityEvidence) return { shouldSurface: false };
  const riskGate = resolvePortfolioPositiveWatchRankingGate(item);
  const sharpe = finiteMetricNumber(risk?.sharpe);
  const maxDrawdown = finiteMetricNumber(risk?.maxDrawdownPct);
  const annualizedReturn = finiteMetricNumber(risk?.annualizedReturnPct);
  let score = 50;
  if (Number.isFinite(sharpe)) score += sharpe >= 1 ? 18 : sharpe >= 0.6 ? 10 : sharpe >= 0.2 ? 4 : -10;
  if (Number.isFinite(maxDrawdown)) score += maxDrawdown >= -15 ? 16 : maxDrawdown >= -25 ? 6 : maxDrawdown >= -35 ? -8 : -18;
  if (Number.isFinite(annualizedReturn)) score += annualizedReturn >= 12 ? 12 : annualizedReturn >= 6 ? 6 : annualizedReturn >= 0 ? 0 : -10;
  if (Number.isFinite(scaleYi)) score += scaleYi >= 5 ? 6 : scaleYi >= 1 ? 2 : scaleYi >= 0.5 ? -6 : -16;
  if (Number.isFinite(concentration)) score += concentration <= 45 ? 4 : concentration <= 65 ? 0 : -8;
  if (fee.missingCritical) score -= 8;
  if (fee.highDrag) score -= 5;
  const bounded = Math.max(0, Math.min(100, score));
  const severeDrawdown = Number.isFinite(maxDrawdown) && maxDrawdown <= -30;
  const tinyFund = Number.isFinite(scaleYi) && scaleYi < 0.5;
  const missingRisk = !hasRisk;
  const facts = [
    Number.isFinite(sharpe) ? `夏普${round(sharpe, 2)}` : "",
    Number.isFinite(maxDrawdown) ? `回撤${formatFallbackPlainPct(maxDrawdown)}` : "",
    Number.isFinite(annualizedReturn) ? `年化${formatFallbackPlainPct(annualizedReturn)}` : "",
    Number.isFinite(scaleYi) ? `规模${round(scaleYi, 2)}亿` : "",
    Number.isFinite(concentration) ? `前十大${formatFallbackPlainPct(concentration)}` : ""
  ].filter(Boolean);
  if (!riskGate.ok) {
    return {
      shouldSurface: true,
      score: Math.min(bounded, 49),
      action: riskGate.hardCatchdown ? "质量不抵消接盘风险" : "质量不抵消追涨风险",
      status: "warning",
      reason: riskGate.hardCatchdown
        ? "风险收益质量只能证明基金底子，不代表旧题材回调可以买；主力撤离或旧催化未刷新时先按接盘风险处理。"
        : "风险收益质量只能证明基金底子，不能覆盖当前位置偏热或追涨风险。",
      facts: mergeStringLists(facts, riskGate.facts || []).slice(0, 6),
      highlights: [
        Number.isFinite(sharpe) && sharpe >= 0.8 ? "历史风险调整收益较好，但只能作为以后复核条件。" : "",
        Number.isFinite(maxDrawdown) && maxDrawdown >= -18 ? "历史回撤相对可控，但不能替代当前题材确认。" : ""
      ].filter(Boolean),
      risks: [
        riskGate.reason,
        riskGate.hardCatchdown ? "高夏普/低回撤不等于可以买旧题材反弹。" : "高夏普/低回撤不等于可以追高。"
      ].filter(Boolean),
      gaps: [
        riskGate.hardCatchdown ? "缺主力资金回流" : "缺追涨降温证据",
        riskGate.hardCatchdown ? "缺新鲜新闻/政策/产业催化" : "缺健康回撤或重新确认",
        riskGate.hardCatchdown ? "缺代表持仓止跌和题材重新确认" : ""
      ].filter(Boolean),
      nextStep: riskGate.nextStep || "先降级为观察，风险门禁解除前不得作为主推荐。"
    };
  }
  const action = severeDrawdown || tinyFund
    ? "质量风险复核"
    : bounded >= 74
      ? "质量支撑复核"
      : bounded >= 58
        ? "质量观察"
        : "质量补证据";
  const status = severeDrawdown || tinyFund ? "warning" : bounded >= 74 ? "ready" : "watch";
  return {
    shouldSurface: true,
    score: bounded,
    action,
    status,
    reason: buildPortfolioQualityScoreReason({ bounded, severeDrawdown, tinyFund, missingRisk }),
    facts,
    highlights: [
      Number.isFinite(sharpe) && sharpe >= 0.8 ? "风险调整收益较好，适合进入质量复核。" : "",
      Number.isFinite(maxDrawdown) && maxDrawdown >= -18 ? "历史回撤相对可控。" : "",
      Number.isFinite(scaleYi) && scaleYi >= 1 ? "规模不处于清盘高风险区。" : ""
    ].filter(Boolean),
    risks: [
      severeDrawdown ? "历史最大回撤偏深，不能只看当前买点。" : "",
      tinyFund ? "基金规模过小，存在流动性或清盘风险。" : "",
      fee.highDrag ? "费用拖累偏高，长期持有要谨慎。" : "",
      Number.isFinite(concentration) && concentration > 65 ? "前十大集中度偏高，波动可能被少数持仓放大。" : ""
    ].filter(Boolean),
    gaps: [
      missingRisk ? "缺少1年/3年风险收益指标" : "",
      !Number.isFinite(scaleYi) ? "缺基金规模" : "",
      fee.missingCritical ? "缺费用/份额关键证据" : ""
    ].filter(Boolean),
    nextStep: severeDrawdown || tinyFund
      ? "先降级为观察，补同类替代和风险收益对比；质量风险未解除前不得作为主推荐。"
      : bounded >= 74
        ? "和买入准备、仓位方案、组合适配交叉确认；质量只负责放行底子，不替代买点。"
        : "继续补齐风险收益、规模和费用证据，未补齐前只作为备选观察。"
  };
}

function selectPortfolioQualityRiskPeriod(snapshot = {}) {
  const risk = snapshot.risk || {};
  const periods = [
    risk.threeYear,
    risk.fiveYear,
    risk.oneYear,
    snapshot.riskMetrics?.periods?.["3y"],
    snapshot.riskMetrics?.periods?.["5y"],
    snapshot.riskMetrics?.periods?.["1y"],
    snapshot.actionability?.risk
  ].filter(Boolean);
  return periods.find((period) => period?.ok)
    || periods.find((period) => Number.isFinite(finiteMetricNumber(period?.sharpe)) || Number.isFinite(finiteMetricNumber(period?.maxDrawdownPct)))
    || {};
}

function buildPortfolioQualityScoreReason({ bounded = 0, severeDrawdown = false, tinyFund = false, missingRisk = false } = {}) {
  if (severeDrawdown) return "历史回撤偏深，基金质量不能支撑直接作为主买入。";
  if (tinyFund) return "基金规模过小，买点再好也要先复核流动性和清盘风险。";
  if (missingRisk) return "缺少风险收益证据，不能只凭走势和题材判断基金质量。";
  if (bounded >= 74) return "风险收益、回撤和规模证据相对完整，基金底子可进入买入前质量复核。";
  if (bounded >= 58) return "基金质量中性偏可观察，还需要和同类、费用、持仓前景继续比较。";
  return "质量证据偏弱或缺口较多，暂不适合作为主推荐。";
}

function buildPortfolioManagerStabilityRanking(watchlist = []) {
  const items = (watchlist || [])
    .filter((item) => item?.code && !["removed"].includes(item.status))
    .map(buildPortfolioManagerStabilityRankingItem)
    .filter(Boolean)
    .sort(compareRankingItems)
    .slice(0, 6);
  return buildPortfolioRankingList({
    id: "manager_stability",
    title: "经理稳定榜",
    subtitle: "按基金经理任期、任期收益、产品历史和规模复核产品可信度，避免刚换经理或历史太短的基金被短线买点误推。",
    emptyText: "暂无足够基金经理任期或产品稳定性数据可排序的候选。",
    nextAction: "下一步补齐基金经理任期、任期收益、产品成立时间和规模；经理稳定性不足的基金只能观察或小仓验证。",
    items
  });
}

function buildPortfolioManagerStabilityRankingItem(item = {}) {
  const evidence = resolvePortfolioManagerStabilityEvidence(item);
  if (!evidence.shouldSurface) return null;
  return buildPortfolioRankingItem({
    code: item.code,
    name: item.name,
    source: "经理稳定",
    score: round(evidence.score, 1),
    action: evidence.action,
    reason: evidence.reason,
    facts: evidence.facts,
    decision: {
      highlights: evidence.highlights,
      risks: evidence.risks,
      gaps: evidence.gaps,
      nextStep: evidence.nextStep
    },
    status: evidence.status
  });
}

function resolvePortfolioManagerStabilityEvidence(item = {}) {
  const snapshot = item.lastSnapshot || {};
  const managers = extractPortfolioManagerEvidence(item, snapshot);
  const lead = managers[0] || {};
  const leadTenureYears = managers
    .map((manager) => parsePortfolioManagerTenureYears(manager))
    .filter((value) => Number.isFinite(value))
    .sort((a, b) => b - a)[0];
  const leadReturnPct = finiteMetricNumber(lead.currentFundProfitPct ?? lead.profitPct ?? lead.returnPct);
  const scaleYi = getPortfolioWatchFundScaleYi(item, snapshot);
  const fundAgeYears = resolvePortfolioFundAgeYears(item, snapshot);
  const hasManager = managers.length > 0;
  const hasEvidence = hasManager || Number.isFinite(leadTenureYears) || Number.isFinite(fundAgeYears) || Number.isFinite(scaleYi);
  if (!hasEvidence) return { shouldSurface: false };
  const riskGate = resolvePortfolioPositiveWatchRankingGate(item);

  let score = 50;
  if (Number.isFinite(leadTenureYears)) {
    score += leadTenureYears >= 5 ? 22 : leadTenureYears >= 3 ? 16 : leadTenureYears >= 1 ? 5 : -14;
  } else {
    score -= 8;
  }
  if (Number.isFinite(leadReturnPct)) score += leadReturnPct >= 30 ? 8 : leadReturnPct >= 8 ? 4 : leadReturnPct < 0 ? -6 : 0;
  if (Number.isFinite(fundAgeYears)) score += fundAgeYears >= 5 ? 8 : fundAgeYears >= 3 ? 5 : fundAgeYears >= 1 ? 0 : -8;
  if (Number.isFinite(scaleYi)) score += scaleYi >= 5 ? 5 : scaleYi >= 1 ? 2 : scaleYi >= 0.5 ? -5 : -12;
  if (!hasManager) score -= 10;

  const bounded = Math.max(0, Math.min(100, score));
  const shortTenure = Number.isFinite(leadTenureYears) && leadTenureYears < 1;
  const missingTenure = !Number.isFinite(leadTenureYears);
  const youngFund = Number.isFinite(fundAgeYears) && fundAgeYears < 1;
  const tinyFund = Number.isFinite(scaleYi) && scaleYi < 0.5;
  const riskFlag = shortTenure || youngFund || tinyFund;
  const managerName = lead.name || lead.manager || lead.fundManager || "";
  const facts = [
    managerName ? `经理${managerName}` : "",
    Number.isFinite(leadTenureYears) ? `任期${round(leadTenureYears, 1)}年` : "",
    Number.isFinite(leadReturnPct) ? `任期收益${formatFallbackPlainPct(leadReturnPct)}` : "",
    Number.isFinite(fundAgeYears) ? `产品${round(fundAgeYears, 1)}年` : "",
    Number.isFinite(scaleYi) ? `规模${round(scaleYi, 2)}亿` : ""
  ].filter(Boolean);
  if (!riskGate.ok) {
    return {
      shouldSurface: true,
      score: Math.min(bounded, 49),
      action: riskGate.hardCatchdown ? "稳定性不抵消接盘风险" : "稳定性不抵消追涨风险",
      status: "warning",
      reason: riskGate.hardCatchdown
        ? "基金经理稳定只能证明产品可信度，不能把主力撤离或旧题材反弹改造成买点。"
        : "基金经理稳定只能证明产品可信度，不能覆盖当前位置偏热或追涨风险。",
      facts: mergeStringLists(facts, riskGate.facts || []).slice(0, 6),
      highlights: [
        Number.isFinite(leadTenureYears) && leadTenureYears >= 3 ? "经理任期较长，但只能作为以后复核条件。" : "",
        Number.isFinite(fundAgeYears) && fundAgeYears >= 3 ? "产品历史不短，但当前题材风险优先级更高。" : ""
      ].filter(Boolean),
      risks: [
        riskGate.reason,
        riskGate.hardCatchdown ? "稳定经理不代表旧题材回调可以买。" : "稳定经理不代表可以追高。"
      ].filter(Boolean),
      gaps: [
        riskGate.hardCatchdown ? "缺当前题材雷达重新确认" : "缺追涨降温证据",
        riskGate.hardCatchdown ? "缺主力资金回流和新鲜催化" : "缺健康回撤或重新确认"
      ].filter(Boolean),
      nextStep: riskGate.nextStep || "先降级为观察，风险门禁解除前不得作为主推荐。"
    };
  }
  const action = riskFlag
    ? "经理稳定风险"
    : bounded >= 74
      ? "稳定主理复核"
      : bounded >= 58
        ? "经理稳定观察"
        : "经理资料补证据";
  const status = riskFlag ? "warning" : bounded >= 74 ? "ready" : "watch";
  return {
    shouldSurface: true,
    score: bounded,
    action,
    status,
    reason: buildPortfolioManagerStabilityReason({ bounded, shortTenure, youngFund, tinyFund, missingTenure, managerName }),
    facts,
    highlights: [
      Number.isFinite(leadTenureYears) && leadTenureYears >= 3 ? "基金经理任期较长，历史业绩更有参考价值。" : "",
      Number.isFinite(leadReturnPct) && leadReturnPct > 0 ? "任期内收益为正，可进入稳定性复核。" : "",
      Number.isFinite(fundAgeYears) && fundAgeYears >= 3 ? "产品历史不短，适合与风险收益一起比较。" : ""
    ].filter(Boolean),
    risks: [
      shortTenure ? "当前基金经理任期不足1年，旧业绩不能直接外推。" : "",
      youngFund ? "产品成立时间不足1年，历史风险收益样本太短。" : "",
      tinyFund ? "基金规模过小，稳定性和流动性都需要先复核。" : "",
      Number.isFinite(leadReturnPct) && leadReturnPct < 0 ? "当前经理任期收益为负，需要解释回撤原因。" : ""
    ].filter(Boolean),
    gaps: [
      !hasManager ? "缺基金经理信息" : "",
      missingTenure ? "缺基金经理任期" : "",
      !Number.isFinite(fundAgeYears) ? "缺产品成立时间" : ""
    ].filter(Boolean),
    nextStep: riskFlag
      ? "先降级观察，补经理变动、任期收益和同类替代；稳定性风险未解除前不得作为主推荐。"
      : bounded >= 74
        ? "和基金质量、买入准备、持仓前景交叉确认；经理稳定只放行产品可信度，不替代买点。"
        : "补齐基金经理任期、任期收益和产品历史后再决定是否进入买入准备。"
  };
}

function extractPortfolioManagerEvidence(item = {}, snapshot = {}) {
  const sources = [
    item.managers,
    item.manager ? [{ name: item.manager }] : null,
    snapshot.managers,
    snapshot.manager ? [{ name: snapshot.manager }] : null,
    snapshot.managerInfo?.managers,
    snapshot.currentManagers,
    snapshot.fundManagers
  ];
  const managers = [];
  for (const source of sources) {
    if (!source) continue;
    const list = Array.isArray(source) ? source : [source];
    for (const manager of list) {
      if (!manager) continue;
      if (typeof manager === "string") {
        managers.push({ name: manager });
      } else if (typeof manager === "object") {
        managers.push(manager);
      }
    }
  }
  const seen = new Set();
  return managers
    .map((manager) => ({
      ...manager,
      name: String(manager.name || manager.manager || manager.fundManager || "").trim()
    }))
    .filter((manager) => {
      const key = `${manager.name}|${manager.workTime || manager.tenure || manager.tenureYears || ""}`;
      if (!manager.name && !manager.workTime && !manager.tenure && !manager.tenureYears) return false;
      if (seen.has(key)) return false;
      seen.add(key);
      return true;
    })
    .slice(0, 4);
}

function parsePortfolioManagerTenureYears(manager = {}) {
  const direct = finiteMetricNumber(manager.tenureYears ?? manager.workYears ?? manager.years);
  if (Number.isFinite(direct)) return direct;
  const text = String(manager.workTime || manager.tenure || manager.manageTime || manager.duration || "").trim();
  if (!text) return null;
  const yearMatch = text.match(/(\d+(?:\.\d+)?)\s*年/);
  const monthMatch = text.match(/(\d+(?:\.\d+)?)\s*(?:个月|月)/);
  const dayMatch = text.match(/(\d+(?:\.\d+)?)\s*天/);
  const plain = finiteMetricNumber(text);
  if (Number.isFinite(plain) && !/[年月天]/.test(text)) return plain;
  const years = (yearMatch ? Number(yearMatch[1]) : 0)
    + (monthMatch ? Number(monthMatch[1]) / 12 : 0)
    + (dayMatch ? Number(dayMatch[1]) / 365 : 0);
  return years > 0 ? years : null;
}

function resolvePortfolioFundAgeYears(item = {}, snapshot = {}) {
  const direct = finiteMetricNumber(snapshot.fundAgeYears ?? snapshot.ageYears ?? item.fundAgeYears);
  if (Number.isFinite(direct)) return direct;
  const dateText = [
    snapshot.establishDate,
    snapshot.inceptionDate,
    snapshot.foundDate,
    snapshot.launchDate,
    snapshot.startDate,
    item.establishDate,
    item.inceptionDate
  ].map((value) => String(value || "").trim()).find(Boolean);
  if (!dateText) return null;
  const started = Date.parse(dateText.replace(/\./g, "-").replace(/\//g, "-"));
  if (!Number.isFinite(started)) return null;
  const years = (Date.now() - started) / (365.25 * 24 * 60 * 60 * 1000);
  return years > 0 ? years : null;
}

function buildPortfolioManagerStabilityReason({ bounded = 0, shortTenure = false, youngFund = false, tinyFund = false, missingTenure = false, managerName = "" } = {}) {
  if (shortTenure) return "基金经理任期太短，不能把历史业绩直接当成当前经理能力。";
  if (youngFund) return "产品成立时间太短，历史风险收益样本不足。";
  if (tinyFund) return "基金规模过小，产品稳定性和持续运营风险需要优先复核。";
  if (missingTenure) return "缺少基金经理任期，不能确认当前业绩是否由现任经理贡献。";
  if (bounded >= 74) return `${managerName ? `${managerName}任期` : "基金经理任期"}和产品历史相对稳定，可进入买入前可信度复核。`;
  if (bounded >= 58) return "基金经理和产品稳定性中性偏可观察，还需要补同类和任期收益证据。";
  return "经理稳定性证据偏弱或缺口较多，暂不适合作为主推荐。";
}

function buildPortfolioFitRanking(db = {}, watchlist = []) {
  const context = buildPortfolioFitContext(db);
  const items = (watchlist || [])
    .filter((item) => item?.code && ["ready", "waiting_pullback", "watch"].includes(item.status))
    .map((item) => buildPortfolioFitRankingItem(item, context))
    .filter(Boolean)
    .sort(compareRankingItems)
    .slice(0, 6);
  return buildPortfolioRankingList({
    id: "portfolio_fit",
    title: "组合适配榜",
    subtitle: "从当前持仓出发，看候选基金是补组合短板，还是同题材、同底层重复占用风险预算。",
    emptyText: "暂无可判断组合适配度的候选。",
    nextAction: "下一步把组合补位、同题材重叠和底层持仓重复作为买入前置复核，不再只按单只基金走势推荐。",
    items
  });
}

function buildPortfolioFitContext(db = {}) {
  const positions = db.account?.positions || [];
  const exposureSummary = buildPortfolioExposureSummary(positions);
  const themeClusters = exposureSummary.themeClusters || [];
  const holdingMap = new Map();
  for (const position of positions || []) {
    const fundLabel = `${position.code || ""} ${position.name || ""}`.trim();
    for (const holding of collectPortfolioPositionHoldingItems(position)) {
      const key = normalizePortfolioFitHoldingKey(holding);
      if (!key) continue;
      const current = holdingMap.get(key) || { holding, funds: [] };
      current.funds = mergeStringLists(current.funds, [fundLabel].filter(Boolean)).slice(0, 5);
      holdingMap.set(key, current);
    }
  }
  return {
    positions,
    exposureSummary,
    themeClusters,
    holdingMap,
    topTheme: themeClusters[0] || null
  };
}

function buildPortfolioFitRankingItem(item = {}, context = {}) {
  const riskGate = resolvePortfolioPositiveWatchRankingGate(item);
  if (!riskGate.ok) return null;
  const tags = collectPortfolioWatchFitThemeTags(item);
  const holdings = collectPortfolioWatchHoldingItems(item);
  const relatedClusters = findPortfolioFitRelatedThemeClusters(tags, context.themeClusters || []);
  const topRelated = relatedClusters[0] || null;
  const overlappingHoldings = holdings
    .map((holding) => ({ holding, match: context.holdingMap?.get(normalizePortfolioFitHoldingKey(holding)) }))
    .filter((entry) => entry.match);
  const readinessScore = Number(item.readinessScore || 0);
  const trend = item.lastSnapshot?.trendProfile || {};
  const return20d = finiteMetricNumber(trend.return20dPct);
  const low120 = finiteMetricNumber(trend.lowPositionPct120);
  const highChase = hasHighChaseTheme(item.lastSnapshot || item)
    || (Number.isFinite(return20d) && return20d > 12 && Number.isFinite(low120) && low120 > 80);
  const existingWeight = Number(topRelated?.positionWeightPct || 0);
  const hasThemeEvidence = tags.length > 0;
  const diversifies = hasThemeEvidence && (!topRelated || existingWeight < 8);
  const overlapPenalty = overlappingHoldings.length ? Math.min(24, overlappingHoldings.length * 8) : 0;
  const sameThemePenalty = existingWeight >= 25 ? 24 : existingWeight >= 18 ? 14 : existingWeight >= 8 ? 6 : 0;
  const diversifyBonus = diversifies ? 24 : !topRelated && !context.positions?.length ? 12 : 0;
  const score = Math.max(0, Math.min(100,
    readinessScore * 0.45
    + diversifyBonus
    + (Number.isFinite(low120) && low120 <= 60 ? 8 : 0)
    + (!highChase ? 8 : -18)
    - sameThemePenalty
    - overlapPenalty
  ));
  const shouldSurface = Boolean(hasThemeEvidence || holdings.length || topRelated || overlappingHoldings.length);
  if (!shouldSurface) return null;
  const action = highChase
    ? "适配降温观察"
    : overlappingHoldings.length || existingWeight >= 18
      ? "同线重叠复核"
      : diversifies
        ? "组合补位复核"
        : "适配观察";
  const facts = [
    tags.length ? `候选方向${tags.slice(0, 3).join("/")}` : "",
    topRelated ? `已有${topRelated.theme}${formatFallbackPlainPct(topRelated.positionWeightPct)}` : context.positions?.length ? "组合暂无同线暴露" : "当前接近空仓",
    overlappingHoldings.length ? `底层重叠${formatPortfolioFitHoldingList(overlappingHoldings)}` : "",
    Number.isFinite(low120) ? `120日位置${round(low120, 1)}%` : ""
  ].filter(Boolean);
  return buildPortfolioRankingItem({
    code: item.code,
    name: item.name,
    source: "组合适配",
    score: round(score, 1),
    action,
    reason: buildPortfolioFitReason({ diversifies, topRelated, overlappingHoldings, highChase }),
    facts,
    decision: {
      highlights: [
        diversifies ? "能补当前组合未覆盖方向，适合进入买入前置复核。" : "",
        !context.positions?.length ? "当前组合接近空仓，可作为首仓适配候选复核。" : "",
        Number.isFinite(low120) && low120 <= 60 ? "位置不高，适合和买点榜交叉确认。" : ""
      ].filter(Boolean),
      risks: [
        topRelated && existingWeight >= 18 ? `已有${topRelated.theme}暴露偏高，不能继续同线加仓。` : "",
        overlappingHoldings.length ? `与持仓底层重复：${formatPortfolioFitHoldingList(overlappingHoldings)}。` : "",
        highChase ? "组合适配不能覆盖追涨风险，需等降温。" : ""
      ].filter(Boolean),
      gaps: [
        !tags.length ? "缺候选行业/题材标签" : "",
        !holdings.length ? "缺前十大持仓穿透" : "",
        highChase ? "缺追涨降温证据" : ""
      ].filter(Boolean),
      nextStep: overlappingHoldings.length || existingWeight >= 18
        ? "先和追涨风险、持仓前景、同题材暴露交叉复核；重叠未解除前不得作为主买入。"
        : "和买入准备、低位启动、费率适配交叉确认；若通过，只按0.5%-2.5%小仓补位。"
    },
    status: highChase ? "warning" : diversifies ? "ready" : item.status || "watch"
  });
}

function buildPortfolioFitReason({ diversifies = false, topRelated = null, overlappingHoldings = [], highChase = false } = {}) {
  if (highChase) return "候选可能能补组合方向，但追涨或高位风险未解除，暂时只能降温观察。";
  if (overlappingHoldings.length) return "候选与已有持仓存在底层重复，买入前必须证明不是重复占用同一风险。";
  if (topRelated && Number(topRelated.positionWeightPct || 0) >= 18) return "组合中同题材暴露已经偏高，新增同线基金必须先通过严格复核。";
  if (diversifies) return "候选能补当前组合未覆盖或低暴露方向，适合放入买入前置复核。";
  if (!topRelated) return "当前组合未见明显同线暴露，但候选仍需补齐买点、费用和持仓证据。";
  return "候选与组合已有方向有一定关联，需要确认是补位而不是重复加仓。";
}

function buildPortfolioThemeAllocationRanking(watchlist = []) {
  const items = buildPortfolioThemeAllocationGroups(watchlist)
    .map(buildPortfolioThemeAllocationRankingItem)
    .filter(Boolean)
    .sort(compareRankingItems)
    .slice(0, 6);
  return buildPortfolioRankingList({
    id: "theme_allocation",
    title: "主题配置榜",
    subtitle: "先判断哪个主题/赛道值得配置，再选代表基金，防止同一方向买成一篮子重复仓位。",
    emptyText: "暂无可形成主题配置判断的候选。",
    nextAction: "下一步先选主题，再选代表基金；同一主题只留一个主代表和一只备选，不把同主题多个基金全买。",
    items
  });
}

function buildPortfolioThemeAllocationGroups(watchlist = []) {
  const groups = new Map();
  for (const item of watchlist || []) {
    if (!item?.code || !["ready", "waiting_pullback", "watch"].includes(item.status)) continue;
    if (!resolvePortfolioPositiveWatchRankingGate(item).ok) continue;
    const themes = collectPortfolioThemeAllocationTags(item);
    for (const theme of themes.slice(0, 3)) {
      const key = normalizePortfolioFitThemeLabel(theme);
      if (!key) continue;
      const group = groups.get(key) || { theme: key, candidates: [] };
      if (!group.candidates.some((candidate) => candidate.item.code === item.code)) {
        group.candidates.push({ item, score: scorePortfolioThemeAllocationCandidate(item) });
      }
      groups.set(key, group);
    }
  }
  return [...groups.values()].filter((group) => group.candidates.length);
}

function collectPortfolioThemeAllocationTags(item = {}) {
  const profile = item.lastSnapshot || {};
  const themeSignals = getCandidateThemeSignals({
    ...profile,
    name: item.name || profile.name,
    type: item.type || profile.type,
    matchedThemes: profile.matchedThemes || item.matchedThemes || [],
    seed: {
      ...(profile.seed || {}),
      name: item.name || profile.seed?.name || profile.name,
      matchedThemes: profile.seed?.matchedThemes || profile.matchedThemes || item.matchedThemes || []
    }
  });
  return [...new Set([
    ...themeSignals.flatMap((theme) => [theme.name, theme.id]),
    ...collectPortfolioWatchFitThemeTags(item),
    ...inferHoldingThemeTags(`${item.name || ""} ${profile.name || ""} ${item.type || ""}`)
  ].map(normalizePortfolioFitThemeLabel).filter(Boolean))];
}

function scorePortfolioThemeAllocationCandidate(item = {}) {
  const trend = item.lastSnapshot?.trendProfile || {};
  const readinessScore = Number(item.readinessScore || 0);
  const rotation = resolvePortfolioRotationOpportunityEvidence(item);
  const chase = resolvePortfolioChaseRiskEvidence(item);
  const outlook = resolvePortfolioWatchHoldingsOutlook(item);
  const fee = resolvePortfolioWatchFeeSuitabilityEvidence(item);
  const low120 = finiteMetricNumber(trend.lowPositionPct120);
  const low250 = finiteMetricNumber(trend.lowPositionPct250);
  const setupSignal = trend.pullbackSetup?.signal || "";
  return Math.max(0, Math.min(100,
    readinessScore * 0.28
    + (item.status === "ready" ? 10 : item.status === "waiting_pullback" ? 5 : 0)
    + (rotation.strong ? 22 : rotation.shouldSurface && !rotation.highChase ? 12 : 0)
    + (rotation.leaderPositive && !rotation.highChase ? 12 : 0)
    + (["pullback_complete", "launch_setup"].includes(setupSignal) ? 14 : 0)
    + (Number.isFinite(low120) && low120 <= 55 ? 10 : 0)
    + (Number.isFinite(low250) && low250 <= 65 ? 6 : 0)
    + (outlook.hasHoldings ? Math.max(0, Number(outlook.score || 0)) * 0.75 : -8)
    + (!fee.missingCritical ? 4 : -8)
    - (chase.shouldSurface ? Math.min(34, Math.max(14, Number(chase.score || 0) * 0.42)) : 0)
  ));
}

function buildPortfolioThemeAllocationRankingItem(group = {}) {
  const candidates = (group.candidates || [])
    .map((entry) => ({ ...entry, score: Number(entry.score || 0) }))
    .sort((a, b) => Number(b.score || 0) - Number(a.score || 0)
      || Number(a.item.priority || 3) - Number(b.item.priority || 3)
      || String(a.item.code || "").localeCompare(String(b.item.code || "")));
  const representative = candidates[0]?.item || null;
  if (!representative) return null;
  const candidateScores = candidates.map((entry) => ({
    item: entry.item,
    score: Number(entry.score || 0),
    rotation: resolvePortfolioRotationOpportunityEvidence(entry.item),
    chase: resolvePortfolioChaseRiskEvidence(entry.item),
    outlook: resolvePortfolioWatchHoldingsOutlook(entry.item)
  }));
  const lowEvidenceCount = candidateScores.filter((entry) => hasPortfolioThemeLowEvidence(entry.item, entry.rotation)).length;
  const hotCount = candidateScores.filter((entry) => entry.chase.shouldSurface || entry.rotation.highChase).length;
  const leaderCount = candidateScores.filter((entry) => entry.rotation.leaderPositive).length;
  const holdingsCount = candidateScores.filter((entry) => entry.outlook.hasHoldings).length;
  const representativeScore = Number(candidateScores[0]?.score || 0);
  const score = Math.max(0, Math.min(100,
    representativeScore
    + Math.min(8, Math.max(0, candidates.length - 1) * 3)
    + Math.min(8, lowEvidenceCount * 2)
    + Math.min(10, leaderCount * 4)
    + Math.min(6, holdingsCount * 1.5)
    - Math.min(18, hotCount * 7)
  ));
  const deployable = score >= 64 && hotCount === 0 && (lowEvidenceCount > 0 || leaderCount > 0);
  const action = hotCount > 0
    ? "主题降温观察"
    : deployable
      ? leaderCount > 0
        ? "主力预热配置复核"
        : "主题配置复核"
      : "主题观察";
  const themeName = group.theme || "未命名主题";
  const representativeLabel = `${representative.code || ""} ${representative.name || ""}`.trim();
  const backup = candidates.find((entry) => entry.item.code !== representative.code)?.item || null;
  return buildPortfolioRankingItem({
    code: representative.code,
    name: representative.name,
    source: "主题配置",
    score: round(score, 1),
    action,
    reason: hotCount > 0
      ? `${themeName}主题已有拥挤或追涨风险，先降温观察，不把同主题基金包装成机会。`
      : leaderCount > 0
        ? `${themeName}主题出现主力进场或新闻预热线索，先选主题，再用代表基金做买点、费率和持仓前景复核。`
        : `${themeName}主题有配置线索，先选主题，再用代表基金做买点、费率和持仓前景复核。`,
    facts: [
      `主题${themeName}`,
      `代表基金 ${representativeLabel}`,
      backup ? `备选${backup.code || ""} ${backup.name || ""}`.trim() : "",
      `主力预热${leaderCount}只`,
      `低位证据${lowEvidenceCount}只`,
      `拥挤风险${hotCount}只`
    ].filter(Boolean),
    decision: {
      highlights: [
        `${themeName}进入主题配置榜，候选${candidates.length}只。`,
        leaderCount ? `主力进场/新闻预热线索覆盖${leaderCount}只。` : "",
        lowEvidenceCount ? `低位/回调修复证据覆盖${lowEvidenceCount}只。` : "",
        representativeLabel ? `代表基金：${representativeLabel}。` : ""
      ].filter(Boolean),
      risks: [
        hotCount ? `${hotCount}只候选有拥挤或追涨风险，主题不能直接加仓。` : "",
        candidates.length > 1 ? "同一主题不能多只一起买，避免重复占用风险预算。" : "同一主题后续只补代表基金或备选，不因为主题名字相同就重复买入。",
        holdingsCount < candidates.length ? "部分候选缺前十大持仓/行业前景验证。" : ""
      ].filter(Boolean),
      gaps: [
        !lowEvidenceCount && !leaderCount ? "缺低位或主力预热线索" : "",
        !holdingsCount ? "缺前十大持仓/行业前景验证" : "",
        hotCount ? "缺拥挤度降温证据" : ""
      ].filter(Boolean),
      nextStep: deployable
        ? "先选主题，再选代表基金；只让代表基金进入买入准备复核，备选只观察，不把同主题多个基金全买。"
        : "先补齐低位、拥挤度和前十大持仓证据，再决定代表基金；未通过前只保留主题观察。"
    },
    status: hotCount ? "warning" : deployable ? "ready" : "watch"
  });
}

function hasPortfolioThemeLowEvidence(item = {}, rotation = {}) {
  const trend = item.lastSnapshot?.trendProfile || {};
  const low120 = finiteMetricNumber(trend.lowPositionPct120);
  const low250 = finiteMetricNumber(trend.lowPositionPct250);
  const signal = trend.pullbackSetup?.signal || "";
  return rotation?.strong
    || ["pullback_complete", "launch_setup"].includes(signal)
    || (Number.isFinite(low120) && low120 <= 55)
    || (Number.isFinite(low250) && low250 <= 65)
    || /低位|回调完成|启动前夜|轮动/.test(mergeStringLists(item.setupEvidence, item.buyTriggers, item.reason).join(" "));
}

function buildPortfolioThemeMomentumRanking(watchlist = []) {
  const items = (watchlist || [])
    .filter((item) => item?.code && ["ready", "waiting_pullback", "watch"].includes(item.status))
    .map(buildPortfolioThemeMomentumRankingItem)
    .filter(Boolean)
    .sort(compareRankingItems)
    .slice(0, 6);
  return buildPortfolioRankingList({
    id: "theme_momentum",
    title: "主力预热机会榜",
    subtitle: "把主力进场、题材预热、新闻逻辑和代表基金买点连起来，避免看见机会还只说等待。",
    emptyText: "暂无主力进场或题材预热支撑的候选基金。",
    nextAction: "下一步刷新题材雷达和代表基金数据；若主力/预热成立且基金低位温和转强，只能先做0.5%-1.2%微型试探。",
    items
  });
}

function buildPortfolioThemeMomentumRankingItem(item = {}) {
  const riskGate = resolvePortfolioPositiveWatchRankingGate(item);
  if (!riskGate.ok) return null;
  const profile = item.lastSnapshot || {};
  const theme = selectPortfolioActionableThemeSignal({
    ...profile,
    name: item.name || profile.name,
    matchedThemes: profile.matchedThemes || item.matchedThemes || [],
    seed: {
      ...(profile.seed || {}),
      matchedThemes: profile.seed?.matchedThemes || profile.matchedThemes || item.matchedThemes || []
    }
  });
  if (!theme) return null;
  const trend = profile.trendProfile || {};
  const readinessScore = Number(item.readinessScore || 0);
  const chase = resolvePortfolioChaseRiskEvidence(item);
  const fee = resolvePortfolioWatchFeeSuitabilityEvidence(item);
  const outlook = resolvePortfolioWatchHoldingsOutlook(item);
  const verifiedBuy = hasVerifiedPortfolioBuySetup(profile);
  const starterBuy = hasPortfolioStarterBuySetup(profile);
  const themeMicroStarter = hasPortfolioThemeMicroStarterSetup(profile);
  const structuralGaps = buildPortfolioWatchStructuralReadinessGaps(item, profile);
  const catalystGap = hasThemeLeaderOrPreheatSignal(theme) && !hasTraceableFreshThemeCatalystContext(theme)
    ? "缺可追溯的新闻时事/产业催化来源，不能把主力热度直接当买点。"
    : "";
  const capitalFlowGap = hasThemeLeaderOrPreheatSignal(theme)
    && hasTraceableFreshThemeCatalystContext(theme)
    && !hasPositiveThemeMainCapitalEvidence(theme)
    ? "缺少正向主力资金或主力流入榜确认，不能把新闻预热直接写成微型试探。"
    : "";
  const hardGap = catalystGap || capitalFlowGap || structuralGaps.find(isPortfolioRedeploymentHardGap);
  const buyReady = !chase.shouldSurface && !fee.missingCritical && !hardGap && (verifiedBuy || starterBuy || themeMicroStarter);
  const score = Math.max(0, Math.min(100,
    readinessScore * 0.28
    + scorePortfolioActionableThemeSignal(theme) * 0.5
    + (verifiedBuy ? 18 : starterBuy ? 14 : themeMicroStarter ? 12 : 0)
    + (hasTraceableFreshThemeCatalystContext(theme) ? 8 : hasThemeLeaderOrPreheatSignal(theme) ? -16 : 0)
    + (outlook.hasHoldings ? Math.max(0, Number(outlook.score || 0)) * 0.45 : -6)
    - (chase.shouldSurface ? 24 : 0)
    - (fee.missingCritical ? 14 : 0)
    - (hardGap ? 16 : 0)
  ));
  const action = chase.shouldSurface
    ? "主力热度降温观察"
    : buyReady
      ? themeMicroStarter
        ? "主力预热微型试探"
        : "主力预热买入复核"
      : "主力预热观察";
  const themeName = theme.name || theme.id || "相关题材";
  const catalyst = theme.catalystProfile?.summary || "";
  const newsLogic = theme.newsLogic || theme.primaryCatalyst || "";
  return buildPortfolioRankingItem({
    code: item.code,
    name: item.name,
    source: "主力预热",
    score: round(score, 1),
    action,
    reason: buyReady
      ? `${themeName}有主力进场或题材预热线索，且基金没有明显追涨拦截，可进入小仓动作复核。`
      : capitalFlowGap
        ? `${themeName}有新闻预热线索，但主力资金还没有确认，只能观察补证据，不能先做微型试探。`
      : `${themeName}有主力/预热线索，但基金买点、费用、持仓前景或追涨风险仍需补证据。`,
    facts: [
      `题材${themeName}`,
      formatPortfolioThemeOpportunityLaneTitle(theme),
      catalyst ? `催化${catalyst}` : "",
      newsLogic ? `逻辑${shortenPortfolioCustomerText(newsLogic, 58)}` : "",
      Number.isFinite(Number(trend.lowPositionPct120)) ? `120日位置${round(Number(trend.lowPositionPct120), 1)}%` : ""
    ].filter(Boolean),
    decision: {
      highlights: [
        theme.leaderSignal === "capital_entering" || theme.positionSignal === "main_capital_entering" ? "主力资金开始配合。" : "",
        theme.leaderSignal === "preheat_catalyst" || theme.positionSignal === "preheat_catalyst_watch" ? "题材催化仍处预热阶段。" : "",
        catalyst ? `催化性质：${catalyst}。` : "",
        newsLogic ? `大涨逻辑：${shortenPortfolioCustomerText(newsLogic, 72)}。` : ""
      ].filter(Boolean),
      risks: [
        chase.shouldSurface ? "追涨或拥挤风险未解除。" : "",
        fee.missingCritical ? "费用/份额证据不足。" : "",
        capitalFlowGap || "",
        hardGap || "",
        !outlook.hasHoldings ? "缺前十大持仓承载验证。" : ""
      ].filter(Boolean),
      gaps: [
        !verifiedBuy && !starterBuy && !themeMicroStarter ? "基金自身低位转强还没有完全确认" : "",
        capitalFlowGap ? "缺正向主力资金/主力流入榜确认" : "",
        fee.missingCritical ? "缺费用/份额核验" : "",
        !outlook.hasHoldings ? "缺前十大持仓" : ""
      ].filter(Boolean),
      nextStep: buyReady
        ? themeMicroStarter
          ? "只允许0.5%-1.2%微型试探；下一轮复核主力是否延续、新闻催化是否兑现、基金是否继续温和转强。"
          : "和买入准备、仓位方案、费率适配交叉确认后，只给0.5%-2.5%小仓或分批。"
        : "先列入观察，补齐基金买点、费用和持仓承载；题材热但基金不合格时不得买入。"
    },
    status: chase.shouldSurface ? "warning" : buyReady ? "ready" : "watch"
  });
}

function collectPortfolioWatchFitThemeTags(item = {}) {
  const profile = item.lastSnapshot || {};
  const outlook = profile.holdingsOutlook || profile.actionability?.holdingsOutlook || {};
  const matchedThemes = [
    ...(profile.matchedThemes || []),
    ...(profile.seed?.matchedThemes || []),
    ...(item.matchedThemes || [])
  ];
  const holdings = collectPortfolioWatchHoldingItems(item);
  const text = mergeStringLists(
    [item.name, item.type, item.reason, profile.name, profile.type, profile.seed?.name],
    item.setupEvidence,
    item.buyTriggers,
    item.riskNotes,
    outlook.holdingTags,
    outlook.matchedTags,
    matchedThemes.flatMap((theme) => [theme.name, theme.id]),
    holdings.map((holding) => `${holding.code || ""} ${holding.name || ""} ${holding.text || ""}`)
  ).join(" ");
  return [...new Set([
    ...matchedThemes.flatMap((theme) => [theme.name, theme.id]).filter(Boolean),
    ...normalizeStringArray(outlook.holdingTags),
    ...normalizeStringArray(outlook.matchedTags),
    ...inferHoldingThemeTags(text)
  ].map(normalizePortfolioFitThemeLabel).filter(Boolean))].slice(0, 6);
}

function collectPortfolioWatchHoldingItems(item = {}) {
  const profile = item.lastSnapshot || {};
  const source = Array.isArray(profile.topHoldings) && profile.topHoldings.length
    ? profile.topHoldings
    : profile.holdings?.equityTopHoldings?.length
      ? profile.holdings.equityTopHoldings
      : profile.holdings?.bondTopHoldings?.length
        ? profile.holdings.bondTopHoldings
        : profile.actionability?.holdingsOutlook?.topHoldings || profile.holdingsOutlook?.topHoldings || [];
  return normalizeHoldingItems(source).slice(0, 10);
}

function findPortfolioFitRelatedThemeClusters(tags = [], clusters = []) {
  return (clusters || [])
    .filter((cluster) => tags.some((tag) => areThemeTermsRelated(tag, cluster.theme)))
    .sort((a, b) => Number(b.positionWeightPct || 0) - Number(a.positionWeightPct || 0));
}

function normalizePortfolioFitThemeLabel(value = "") {
  const text = String(value || "").trim();
  if (!text) return "";
  const matched = HOLDING_THEME_GROUPS.find((group) => group.some((term) => text.includes(term)));
  return matched?.[0] || text;
}

function normalizePortfolioFitHoldingKey(holding = {}) {
  const code = String(holding.code || "").trim();
  const name = String(holding.name || "").trim();
  return code || name;
}

function formatPortfolioFitHoldingList(entries = []) {
  return entries
    .slice(0, 3)
    .map((entry) => [entry.holding?.code, entry.holding?.name].filter(Boolean).join(" ") || entry.holding?.text || "")
    .filter(Boolean)
    .join("、");
}

function buildPortfolioRotationOpportunityRanking(watchlist = []) {
  const items = (watchlist || [])
    .filter((item) => item?.code && ["ready", "waiting_pullback", "watch"].includes(item.status))
    .map(buildPortfolioRotationOpportunityRankingItem)
    .filter(Boolean)
    .sort(compareRankingItems)
    .slice(0, 6);
  return buildPortfolioRankingList({
    id: "rotation_opportunity",
    title: "板块轮动榜",
    subtitle: "把题材位置、低位修复和拥挤度放在一起看，减少新闻追涨。",
    emptyText: "暂无低位轮动证据明确的候选。",
    nextAction: "下一步刷新题材雷达和低位候选，优先找轮动评分改善、拥挤度不高、走势刚修复的基金。",
    items
  });
}

function buildPortfolioRotationOpportunityRankingItem(item = {}) {
  const evidence = resolvePortfolioRotationOpportunityEvidence(item);
  const riskGate = resolvePortfolioPositiveWatchRankingGate(item);
  if (!riskGate.ok && !evidence.themeSupportGap) return null;
  if (!evidence.shouldSurface) return null;
  if (evidence.themeRetreatRisk) return null;
  return buildPortfolioRankingItem({
    code: item.code,
    name: item.name,
    source: "板块轮动",
    score: round(evidence.score, 1),
    action: evidence.themeSupportGap || evidence.missingTheme ? "先补题材证据" : evidence.highChase ? "轮动降温观察" : evidence.leaderPositive ? "主力预热复核" : evidence.strong ? "轮动启动复核" : "低位轮动观察",
    reason: buildPortfolioRotationOpportunityReason(evidence),
    facts: buildPortfolioRotationOpportunityFacts(evidence),
    decision: {
      highlights: [
        evidence.themeName ? `${evidence.themeName}：${evidence.themePositionLabel || "轮动线索待确认"}` : "",
        evidence.leaderPositive && evidence.leaderLabel ? `主力节奏：${evidence.leaderLabel}` : "",
        evidence.newsLogic ? `题材逻辑：${evidence.newsLogic}` : "",
        evidence.setupLabel || "",
        evidence.rotationLine || ""
      ].filter(Boolean),
      risks: [
        evidence.highChase ? "板块或基金已经偏热，不能把新闻催化当作追买理由。" : "",
        evidence.themeRetreatRisk ? "题材退潮或主力资金撤离，回调不能当作买点。" : "",
        evidence.crowdingRisk ? "拥挤度偏高，只能等待回调或小额观察。" : "",
        evidence.themeSupportGap ? evidence.themeSupportGap : "",
        evidence.missingTheme ? "缺少题材雷达匹配，轮动判断置信度不足。" : ""
      ].filter(Boolean),
      gaps: [
        evidence.themeSupportGap ? evidence.themeSupportGap : "",
        evidence.missingTheme ? "缺题材雷达" : "",
        evidence.leaderPositive && !evidence.newsLogic ? "缺新闻逻辑复核" : "",
        evidence.needsEarlyTurn ? "缺5日/10日温和转强" : "",
        evidence.needsLowPosition ? "缺120日或250日低位证据" : ""
      ].filter(Boolean),
      nextStep: evidence.themeSupportGap || evidence.missingTheme
        ? "先补当前题材雷达、新闻/资金和代表基金承载；确认前只观察，不给买入金额。"
        : evidence.highChase
        ? evidence.themeRetreatRisk
          ? "降级为回避，等主力资金回流、板块重新转强后再回到轮动榜。"
          : "降级为观察，等拥挤度下降或回撤后再进入买入准备。"
        : evidence.leaderPositive
          ? "把主力预热题材加入买入准备复核；只有基金自身也出现低位或早期转强，才允许0.5%-2.5%试探。"
          : "和买入准备榜、费率适配榜交叉复核；若低位和早期转强同时成立，只能先小仓试探。"
    },
    status: evidence.themeSupportGap || evidence.missingTheme || evidence.highChase ? "watch" : evidence.strong || evidence.leaderPositive ? "ready" : item.status || "watch"
  });
}

function resolvePortfolioRotationOpportunityEvidence(item = {}) {
  const profile = item.lastSnapshot || {};
  const trend = profile.trendProfile || {};
  const candidateContext = {
    ...profile,
    name: item.name || profile.name,
    type: item.type || profile.type,
    matchedThemes: profile.matchedThemes || item.matchedThemes || [],
    marketThemeRefresh: profile.marketThemeRefresh || item.marketThemeRefresh || null,
    holdingThemeRefresh: profile.holdingThemeRefresh || item.holdingThemeRefresh || null,
    seed: {
      ...(profile.seed || {}),
      name: item.name || profile.seed?.name || profile.name,
      matchedThemes: profile.seed?.matchedThemes || profile.matchedThemes || item.matchedThemes || [],
      marketThemeRefresh: profile.seed?.marketThemeRefresh || item.seed?.marketThemeRefresh || null,
      holdingThemeRefresh: profile.seed?.holdingThemeRefresh || item.seed?.holdingThemeRefresh || null
    }
  };
  const themes = getCandidateThemeSignals(candidateContext);
  const theme = themes[0] || {};
  const themeSupportGap = getPortfolioActionableThemeSupportGap(candidateContext);
  const themeRotationScore = scorePortfolioWatchThemeRotation(theme);
  const trendRotationScore = scorePortfolioWatchTrendRotation(trend);
  const text = mergeStringLists(item.setupEvidence, item.buyTriggers, item.reason, item.riskNotes).join(" ");
  const textScore = /低位轮动|板块轮动|轮动/.test(text) ? 12 : /低位|回调完成|启动前夜|刚转强/.test(text) ? 6 : 0;
  const readinessScore = Math.min(18, Number(item.readinessScore || 0) / 5);
  const themeRetreatWarnings = getCandidateThemeRetreatWarnings({ matchedThemes: themes });
  const themeRetreatRisk = themeRetreatWarnings.length > 0;
  const leaderPositive = ["capital_entering", "preheat_catalyst"].includes(theme.leaderSignal)
    || ["main_capital_entering", "preheat_catalyst_watch"].includes(theme.positionSignal)
    || Number(theme.capitalFollowScore) >= 55
    || Number(theme.preheatScore) >= 55;
  const highChase = theme.positionSignal === "high_chase_risk"
    || theme.stage === "crowded"
    || themeRetreatRisk
    || Number(theme.crowdingScore) >= 55
    || Number(trend.return20dPct) > 18
    || Number(trend.lowPositionPct120) > 85;
  const score = Math.max(0, themeRotationScore + trendRotationScore + textScore + readinessScore + (leaderPositive && !highChase ? 12 : 0) - (highChase ? 24 : 0) - (themeSupportGap ? 36 : 0));
  const hasTheme = Boolean(theme.id || theme.name);
  const strong = score >= 55 && !highChase && hasTheme && !themeSupportGap;
  const low120 = Number(trend.lowPositionPct120);
  const low250 = Number(trend.lowPositionPct250);
  const signal = trend.pullbackSetup?.signal || "";
  const shouldSurface = Boolean(
    hasTheme
    || /低位轮动|板块轮动|轮动/.test(text)
    || ["pullback_complete", "launch_setup"].includes(signal)
    || (Number.isFinite(low120) && low120 <= 55)
  );
  return {
    theme,
    themeName: theme.name || theme.id || "",
    themePositionLabel: formatPortfolioRotationThemePosition(theme),
    setupLabel: trend.pullbackSetup?.signalText || formatTrendLabel(trend.trendLabel),
    rotationLine: formatPortfolioRotationScoreLine(theme),
    leaderPositive,
    leaderLabel: formatUserFacingFundLabel(theme.leaderSignal || theme.positionSignal),
    newsLogic: theme.newsLogic || theme.primaryCatalyst || "",
    score,
    strong,
    shouldSurface,
    highChase,
    themeRetreatRisk,
    themeRetreatWarnings,
    crowdingRisk: Number(theme.crowdingScore) >= 40,
    missingTheme: !hasTheme,
    themeSupportGap,
    needsEarlyTurn: !["pullback_complete", "launch_setup"].includes(signal) && !/刚转强|回调完成|启动前夜/.test(text),
    needsLowPosition: !((Number.isFinite(low120) && low120 <= 60) || (Number.isFinite(low250) && low250 <= 65)),
    trend
  };
}

function scorePortfolioWatchThemeRotation(theme = {}) {
  if (!theme?.id && !theme?.name) return 0;
  let score = 18;
  const rotation = Number(theme.rotationScore);
  const lowPosition = Number(theme.lowPositionScore);
  const crowding = Number(theme.crowdingScore);
  const capitalFollow = Number(theme.capitalFollowScore);
  const preheat = Number(theme.preheatScore);
  if (theme.positionSignal === "low_position_rotation") score += 18;
  if (theme.stage === "low_position_rotation") score += 14;
  if (theme.positionSignal === "acceptable_position") score += 8;
  if (theme.positionSignal === "main_capital_entering" || theme.leaderSignal === "capital_entering") score += 18;
  if (theme.positionSignal === "preheat_catalyst_watch" || theme.leaderSignal === "preheat_catalyst") score += 12;
  if (theme.stage === "capital_entering") score += 14;
  if (theme.stage === "preheat_catalyst") score += 10;
  if (Number.isFinite(rotation)) score += Math.min(16, rotation / 4);
  if (Number.isFinite(lowPosition)) score += Math.min(16, lowPosition / 4);
  if (Number.isFinite(capitalFollow)) score += Math.min(16, capitalFollow / 5);
  if (Number.isFinite(preheat)) score += Math.min(12, preheat / 6);
  if (Number.isFinite(crowding)) score -= crowding >= 55 ? 24 : crowding >= 40 ? 10 : 0;
  return score;
}

function scorePortfolioWatchTrendRotation(trend = {}) {
  let score = 0;
  const signal = trend.pullbackSetup?.signal || "";
  const low120 = Number(trend.lowPositionPct120);
  const low250 = Number(trend.lowPositionPct250);
  const r20 = Number(trend.return20dPct);
  const r5 = Number(trend.return5dPct);
  const r10 = Number(trend.return10dPct);
  if (signal === "pullback_complete") score += 18;
  if (signal === "launch_setup") score += 12;
  if (Number.isFinite(low120) && low120 >= 8 && low120 <= 55) score += 14;
  if (Number.isFinite(low250) && low250 <= 65) score += 8;
  if (Number.isFinite(r5) && r5 >= -1 && r5 <= 5 && Number.isFinite(r10) && r10 >= -2 && r10 <= 8) score += 8;
  if (Number.isFinite(r20) && r20 > 14) score -= 12;
  return score;
}

function formatPortfolioRotationThemePosition(theme = {}) {
  const labels = [
    theme.positionSignal ? formatUserFacingFundLabel(theme.positionSignal) : "",
    theme.stage ? formatUserFacingFundLabel(theme.stage) : ""
  ].filter(Boolean);
  return [...new Set(labels)].join(" / ");
}

function formatPortfolioRotationScoreLine(theme = {}) {
  const parts = [
    theme.leaderSignal ? `节奏${formatUserFacingFundLabel(theme.leaderSignal)}` : "",
    Number.isFinite(Number(theme.capitalFollowScore)) ? `主力${round(Number(theme.capitalFollowScore), 0)}` : "",
    Number.isFinite(Number(theme.preheatScore)) ? `预热${round(Number(theme.preheatScore), 0)}` : "",
    Number.isFinite(Number(theme.rotationScore)) ? `轮动${round(Number(theme.rotationScore), 0)}` : "",
    Number.isFinite(Number(theme.lowPositionScore)) ? `低位${round(Number(theme.lowPositionScore), 0)}` : "",
    Number.isFinite(Number(theme.crowdingScore)) ? `拥挤${round(Number(theme.crowdingScore), 0)}` : ""
  ].filter(Boolean);
  return parts.length ? parts.join("，") : "";
}

function buildPortfolioRotationOpportunityReason(evidence = {}) {
  if (evidence.themeRetreatRisk) {
    return "题材出现退潮或主力资金撤离，当前位置不能把回调当买点，先等资金回流。";
  }
  if (evidence.themeSupportGap) {
    return evidence.themeSupportGap;
  }
  if (evidence.highChase) {
    return "板块或基金位置已经偏热，本轮只做降温观察，避免被新闻和短期涨幅牵着追。";
  }
  if (evidence.leaderPositive) {
    return "题材出现主力进场或新闻预热线索，但仍要和基金买点、费用和持仓前景交叉确认，只允许小仓试探。";
  }
  if (evidence.strong) {
    return "板块轮动和低位修复同时出现，适合进入小仓试探前置复核。";
  }
  if (evidence.themeName) {
    return "题材有低位或轮动线索，但还需要和早期转强、费用和持仓前景交叉确认。";
  }
  return "基金走势有低位修复线索，但缺少明确题材雷达，暂时只放轮动观察。";
}

function buildPortfolioRotationOpportunityFacts(evidence = {}) {
  const trend = evidence.trend || {};
  return [
    evidence.themeName ? `题材${evidence.themeName}` : "",
    ...(evidence.themeRetreatWarnings || []).slice(0, 1),
    evidence.leaderLabel ? `节奏${evidence.leaderLabel}` : "",
    evidence.newsLogic ? `逻辑${evidence.newsLogic}` : "",
    evidence.themePositionLabel ? `位置${evidence.themePositionLabel}` : "",
    evidence.rotationLine,
    trend.pullbackSetup?.signalText || "",
    Number.isFinite(Number(trend.lowPositionPct120)) ? `120日位置${round(Number(trend.lowPositionPct120), 1)}%` : "",
    Number.isFinite(Number(trend.return20dPct)) ? `20日${formatFallbackPlainPct(trend.return20dPct)}` : ""
  ].filter(Boolean);
}

function buildPortfolioChaseRiskRanking(watchlist = []) {
  const items = (watchlist || [])
    .filter((item) => item?.code && ["ready", "waiting_pullback", "watch", "blocked"].includes(item.status))
    .map(buildPortfolioChaseRiskRankingItem)
    .filter(Boolean)
    .sort(compareRankingItems)
    .slice(0, 6);
  return buildPortfolioRankingList({
    id: "chase_risk",
    title: "追涨风险榜",
    subtitle: "把短期涨幅偏热、位置偏高和题材拥挤的候选单独拎出来，防止伪装成低位启动。",
    emptyText: "暂无明显追涨风险候选。",
    nextAction: "下一步把偏热候选降级观察，等健康回撤、拥挤度下降或低位证据恢复后再复核。",
    items
  });
}

function buildPortfolioStaleCatchdownRiskRanking(watchlist = []) {
  const items = (watchlist || [])
    .filter((item) => item?.code && ["ready", "waiting_pullback", "watch", "blocked"].includes(item.status))
    .map(buildPortfolioStaleCatchdownRiskRankingItem)
    .filter(Boolean)
    .sort(compareRankingItems)
    .slice(0, 6);
  return buildPortfolioRankingList({
    id: "stale_catchdown_risk",
    title: "接盘风险榜",
    subtitle: "专门拦截主力撤离或底层持仓盘中走弱后的表面回调，防止经理把退潮题材包装成低位启动。",
    emptyText: "暂无主力撤离后的接盘风险候选。",
    nextAction: "下一步只观察资金是否回流、题材是否重新预热、底层持仓是否止跌；没有主力回流或龙头止跌前不得给买入金额。",
    items
  });
}

function buildPortfolioStaleCatchdownRiskRankingItem(item = {}) {
  const evidence = resolvePortfolioChaseRiskEvidence(item);
  if (!evidence.staleCatchdownRisk && !evidence.staleCatalystRisk && !evidence.staleThemeRefreshRisk && !evidence.themeRetreatRisk && !evidence.holdingRealtimeCatchdownRisk && !evidence.unsupportedHoldingThemeRisk && !evidence.lowSetupThemeSupportRisk && !evidence.lossMemoryCatchdownRisk) return null;
  const theme = evidence.theme || {};
  const trend = evidence.trend || {};
  const staleCatalyst = evidence.staleCatalystRisk || theme.catalystProfile?.fresh === false;
  const retreatFacts = [
    evidence.holdingRealtimeWarning || "",
    evidence.holdingThemeSupportGap || "",
    ...(evidence.lossMemoryWarnings || []),
    evidence.lowSetupThemeSupportRisk ? evidence.actionableThemeSupportGap : "",
    ...(evidence.holdingRealtimeFacts || []),
    ...(evidence.staleThemeRefreshWarnings || []),
    ...(evidence.staleCatalystWarnings || []),
    ...(evidence.staleThemeWarnings || []),
    ...(evidence.themeRetreatWarnings || []),
    theme.newsLogic ? `逻辑${shortenPortfolioCustomerText(theme.newsLogic, 72)}` : "",
    Number.isFinite(Number(theme.avgMainNetInflowPct)) ? `主力均值${formatFallbackPlainPct(theme.avgMainNetInflowPct)}` : "",
    trend.pullbackSetup?.signalText ? `基金走势${trend.pullbackSetup.signalText}` : ""
  ].filter(Boolean);
  const score = Math.max(50, Math.min(100,
    Number(evidence.score || 0)
    + (evidence.staleCatchdownRisk ? 24 : 0)
    + (evidence.staleCatalystRisk ? 20 : 0)
    + (evidence.staleThemeRefreshRisk ? 22 : 0)
    + (evidence.themeRetreatRisk ? 18 : 0)
    + (evidence.holdingRealtimeCatchdownRisk ? 28 : 0)
    + (evidence.unsupportedHoldingThemeRisk ? 22 : 0)
    + (evidence.lossMemoryCatchdownRisk ? 26 : 0)
    + (evidence.lowSetupThemeSupportRisk ? 24 : 0)
    + Math.min(18, Number(theme.capitalRetreatScore || 0) / 4)
  ));
  return buildPortfolioRankingItem({
    code: item.code,
    name: item.name,
    source: "主力撤离拦截",
    score: round(score, 1),
    action: evidence.holdingRealtimeCatchdownRisk ? "底层持仓接盘拦截" : evidence.staleThemeRefreshRisk ? "旧雷达接盘拦截" : staleCatalyst ? "旧催化接盘强拦截" : evidence.staleCatchdownRisk ? "退潮接盘强拦截" : evidence.themeRetreatRisk ? "主力撤离回避" : evidence.lossMemoryCatchdownRisk ? "历史接盘冷却" : evidence.lowSetupThemeSupportRisk ? "低位无主力拦截" : "底层题材未确认拦截",
    reason: evidence.holdingRealtimeCatchdownRisk
      ? "前十大持仓盘中明显走弱，基金净值的回调修复可能只是跟跌前半段，不能直接当成启动买点。"
      : evidence.staleThemeRefreshRisk
        ? "题材雷达或持仓题材快照已经过期，旧主力/旧新闻标签不能直接当成今天的低位启动买点。"
      : staleCatalyst
        ? "题材上涨逻辑停留在旧新闻/旧催化上，当前缺少新鲜主力进场证据，基金净值的回调修复不能直接当成启动买点。"
      : evidence.staleCatchdownRisk || evidence.themeRetreatRisk
        ? "题材资金已经退潮或主力撤离，基金净值的回调修复不能直接当成启动买点。"
      : evidence.lossMemoryCatchdownRisk
        ? "历史回测已经证明同主题低位反弹曾造成接盘亏损；当前没有主力资金回流、新鲜催化和代表持仓承载证明前，不能把回调完成当买点。"
      : evidence.lowSetupThemeSupportRisk
        ? "低位不等于启动；基金净值像回调完成，但当前缺少主力资金回流、新鲜新闻催化和题材雷达确认，先按接盘风险处理。"
      : "基金名字看起来宽泛，但前十大持仓已经暴露出明确底层题材；当前题材雷达没有同方向主力或新闻支撑，不能直接当成低位启动。",
    facts: retreatFacts.slice(0, 5),
    decision: {
      highlights: retreatFacts.slice(0, 3),
      risks: [
        evidence.holdingRealtimeCatchdownRisk
          ? "底层龙头没有止跌前，买基金容易接到下一段补跌。"
          : evidence.staleThemeRefreshRisk
            ? "旧雷达快照如果没有重新刷新，容易把已经退潮的题材误判成低位启动。"
          : staleCatalyst
            ? "旧催化如果没有新资金接力，低位反弹很容易变成接盘。"
          : evidence.staleCatchdownRisk || evidence.themeRetreatRisk
            ? "容易买在旧题材反弹尾端，后续若主力不回流，回撤会明显放大。"
          : evidence.lossMemoryCatchdownRisk
            ? "历史同主题接盘已经出现亏损，不能只换一个基金代码继续试错。"
          : evidence.lowSetupThemeSupportRisk
            ? "只有低位和回调形态，没有主力/新闻/题材确认时，买入容易变成接旧题材弱反弹。"
          : "底层题材没有当前主力或新闻支撑，表面低位可能只是旧主线回落后的弱反弹。",
        evidence.themeRisk || "题材退潮或主力资金撤离，先等资金回流。",
        evidence.positionRisk || ""
      ].filter(Boolean),
      gaps: [
        "缺主力资金回流",
        evidence.unsupportedHoldingThemeRisk ? "缺同方向当前题材雷达确认" : "",
        evidence.lossMemoryCatchdownRisk ? "缺历史接盘亏损后的再入场证明" : "",
        evidence.lowSetupThemeSupportRisk ? "低位形态缺主力资金回流确认" : "",
        evidence.staleThemeRefreshRisk ? "缺当前主力资金/新闻催化刷新" : "",
        staleCatalyst ? "缺新鲜新闻/政策/产业预热" : "缺新的新闻/政策/产业预热",
        evidence.holdingRealtimeCatchdownRisk ? "缺底层持仓止跌确认" : "",
        "缺板块重新转强后的代表基金确认"
      ].filter(Boolean),
      nextStep: evidence.holdingRealtimeCatchdownRisk
        ? "先回避，不给买入金额；等前十大持仓止跌、主力回流和基金低位温和转强同时出现后，再回到买入准备榜。"
        : evidence.staleThemeRefreshRisk
          ? "先0元观察；重新刷新主力资金、新闻催化和代表持仓走势，确认仍是当前主线后，才允许回到小仓复核。"
        : staleCatalyst || evidence.staleCatchdownRisk || evidence.themeRetreatRisk
          ? "只保留观察或降级，等主力回流、题材重新预热且基金低位温和转强后，再回到主力预热或买入准备榜。"
        : evidence.lossMemoryCatchdownRisk
          ? "先0元观察；同主题必须重新证明主力资金回流、新鲜新闻催化、代表持仓承载和费率核验齐备，才允许恢复0.5%-1.2%微型试探。"
        : evidence.lowSetupThemeSupportRisk
          ? "先0元观察；只有新鲜催化、主力资金回流、当前题材雷达确认和基金低位温和转强同时出现后，才允许恢复小仓复核。"
        : "先0元观察；等同方向板块出现主力净流入、新闻催化和代表持仓止跌后，再重新评估是否进入小仓复核。"
    },
    status: "warning"
  });
}

function resolvePortfolioPositiveWatchRankingGate(item = {}) {
  const evidence = resolvePortfolioChaseRiskEvidence(item);
  const themeSupportGap = getPortfolioWatchThemeSupportGap(item);
  const hardCatchdown = Boolean(
    evidence.holdingRealtimeCatchdownRisk
    || evidence.staleThemeRefreshRisk
    || evidence.staleCatchdownRisk
    || evidence.staleCatalystRisk
    || evidence.themeRetreatRisk
    || evidence.unsupportedHoldingThemeRisk
    || evidence.lossMemoryCatchdownRisk
    || evidence.lowSetupThemeSupportRisk
    || themeSupportGap
  );
  const chaseOnly = Boolean(evidence.shouldSurface && Number(evidence.score || 0) >= 20);
  if (!hardCatchdown && !chaseOnly) {
    return {
      ok: true,
      reason: "",
      evidence,
      facts: []
    };
  }
  const firstFact = selectPortfolioRankingFirstText(
    themeSupportGap,
    evidence.holdingRealtimeWarning,
    evidence.holdingThemeSupportGap,
    evidence.lossMemoryWarnings,
    evidence.actionableThemeSupportGap,
    evidence.staleThemeRefreshWarnings,
    evidence.staleCatalystWarnings,
    evidence.staleThemeWarnings,
    evidence.themeRetreatWarnings,
    evidence.themeRisk,
    evidence.hotEvidence
  );
  const reason = hardCatchdown
    ? `正向买入门禁拦截：${firstFact || "旧题材、主力撤离或底层持仓走弱风险未解除"}，不能进入买入准备、低位启动或现金再部署。`
    : `正向买入门禁拦截：${firstFact || "追涨风险未解除"}，先去追涨风险榜复核，不能进入买入准备。`;
  return {
    ok: false,
    hardCatchdown,
    chaseOnly,
    reason,
    evidence,
    facts: buildPortfolioChaseRiskFacts(evidence).slice(0, 5),
    nextStep: hardCatchdown
      ? "先放入接盘风险榜或数据补证；等新鲜催化、主力资金回流和代表持仓止跌后，才允许恢复买入复核。"
      : "先等短期涨幅降温、位置回落或健康回撤后，再恢复买入准备复核。"
  };
}

function buildPortfolioChaseRiskRankingItem(item = {}) {
  const evidence = resolvePortfolioChaseRiskEvidence(item);
  if (!evidence.shouldSurface) return null;
  return buildPortfolioRankingItem({
    code: item.code,
    name: item.name,
    source: "追涨拦截",
    score: round(evidence.score, 1),
    action: evidence.score >= 60 ? "追涨强拦截" : "追涨风险复核",
    reason: "短期涨幅、区间位置或题材拥挤度偏高，不符合回调完成后的低位启动。",
    facts: buildPortfolioChaseRiskFacts(evidence),
    decision: {
      highlights: evidence.hotEvidence.slice(0, 3),
      risks: [
        "不能把新闻热度或短期涨幅当成买入理由。",
        evidence.themeRisk || "",
        evidence.positionRisk || ""
      ].filter(Boolean),
      gaps: [
        evidence.needsPullback ? "缺健康回撤" : "",
        evidence.needsLowPosition ? "缺低位证据" : "",
        evidence.needsCooling ? "缺拥挤度降温" : ""
      ].filter(Boolean),
      nextStep: "降级为观察，等短期涨幅回落、区间位置下降或出现健康回撤后，再回到买入准备榜复核。"
    },
    status: "warning"
  });
}

function resolvePortfolioChaseRiskEvidence(item = {}) {
  const profile = item.lastSnapshot || {};
  const trend = profile.trendProfile || {};
  const themes = getCandidateThemeSignals({
    ...profile,
    name: item.name || profile.name,
    type: item.type || profile.type,
    matchedThemes: profile.matchedThemes || item.matchedThemes || [],
    seed: {
      ...(profile.seed || {}),
      name: item.name || profile.seed?.name || profile.name,
      matchedThemes: profile.seed?.matchedThemes || profile.matchedThemes || item.matchedThemes || []
    }
  });
  const theme = themes[0] || {};
  const r20 = Number(trend.return20dPct);
  const r60 = Number(trend.return60dPct);
  const low120 = Number(trend.lowPositionPct120);
  const low250 = Number(trend.lowPositionPct250);
  const crowding = Number(theme.crowdingScore);
  const text = mergeStringLists(item.riskNotes, item.readinessGaps, item.reason, item.setupEvidence).join(" ");
  const themeRetreatWarnings = getCandidateThemeRetreatWarnings({ matchedThemes: themes });
  const staleThemeWarnings = getStaleThemeCatchdownWarnings({ matchedThemes: themes });
  const staleCatalystWarnings = getStaleCatalystThemeWarnings({ matchedThemes: themes });
  const themeRetreatRisk = themeRetreatWarnings.length > 0;
  const staleCatchdownRisk = staleThemeWarnings.length > 0;
  const staleCatalystRisk = staleCatalystWarnings.length > 0;
  const holdingRealtimeProfile = buildPortfolioHoldingRealtimeEvidenceProfile(item, profile);
  const holdingRealtimeCatchdownRisk = Boolean(holdingRealtimeProfile.warning);
  const supportProfile = {
    ...profile,
    name: item.name || profile.name,
    type: item.type || profile.type,
    marketThemeRefresh: profile.marketThemeRefresh || item.marketThemeRefresh,
    holdingThemeRefresh: profile.holdingThemeRefresh || item.holdingThemeRefresh,
    matchedThemes: profile.matchedThemes || item.matchedThemes || [],
    seed: {
      ...(profile.seed || {}),
      name: item.name || profile.seed?.name || profile.name,
      matchedThemes: profile.seed?.matchedThemes || profile.matchedThemes || item.matchedThemes || [],
      marketThemeRefresh: profile.seed?.marketThemeRefresh || item.seed?.marketThemeRefresh,
      holdingThemeRefresh: profile.seed?.holdingThemeRefresh || item.seed?.holdingThemeRefresh
    }
  };
  const holdingThemeSupportGap = getPortfolioHoldingThemeSupportGap(supportProfile);
  const actionableThemeSupportGap = getPortfolioActionableThemeSupportGap(supportProfile);
  const staleThemeRefreshWarnings = getStalePortfolioThemeRefreshWarnings(supportProfile);
  const staleThemeRefreshRisk = staleThemeRefreshWarnings.length > 0;
  const unsupportedHoldingThemeRisk = Boolean(holdingThemeSupportGap);
  const lossMemoryWarnings = getPortfolioCatchdownLossMemoryWarnings(item, profile);
  const lossMemoryCatchdownRisk = Boolean(
    lossMemoryWarnings.length
    && !hasFreshActionableThemeSupport(supportProfile)
    && hasPortfolioLowSetupWithoutMainForceConfirmation(item, trend)
  );
  const lowSetupThemeSupportRisk = Boolean(
    actionableThemeSupportGap
    && themes.length > 0
    && !holdingThemeSupportGap
    && !staleThemeRefreshRisk
    && !staleCatalystRisk
    && !staleCatchdownRisk
    && !themeRetreatRisk
    && !hasThemeLeaderOrPreheatSignal(theme)
    && !hasActionableThemeSupport(supportProfile)
    && hasPortfolioLowSetupWithoutMainForceConfirmation(item, trend)
  );
  const hotEvidence = [
    holdingRealtimeProfile.warning || "",
    holdingThemeSupportGap || "",
    lossMemoryWarnings[0] || "",
    lowSetupThemeSupportRisk ? `低位不等于启动：${actionableThemeSupportGap}` : "",
    staleThemeRefreshWarnings[0] || "",
    staleCatalystWarnings[0] || "",
    staleThemeWarnings[0] || "",
    themeRetreatWarnings[0] || "",
    Number.isFinite(r20) && r20 > 12 ? `近20日涨幅偏热${formatFallbackPlainPct(r20)}` : "",
    Number.isFinite(r60) && r60 > 24 ? `近60日涨幅偏热${formatFallbackPlainPct(r60)}` : "",
    Number.isFinite(low120) && low120 > 80 ? `120日位置偏高${round(low120, 1)}%` : "",
    Number.isFinite(low250) && low250 > 80 ? `250日位置偏高${round(low250, 1)}%` : "",
    Number.isFinite(crowding) && crowding >= 55 ? `题材拥挤度${round(crowding, 0)}` : "",
    /追涨|偏热|高位|拥挤|等待回撤/.test(text) ? selectPortfolioRankingFirstText(item.riskNotes, item.reason, item.setupEvidence) : ""
  ].filter(Boolean);
  const score = [
    Number.isFinite(r20) && r20 > 12 ? Math.min(28, (r20 - 8) * 1.2) : 0,
    Number.isFinite(r60) && r60 > 24 ? Math.min(24, (r60 - 18) * 0.7) : 0,
    Number.isFinite(low120) && low120 > 80 ? 20 : Number.isFinite(low120) && low120 > 65 ? 10 : 0,
    Number.isFinite(low250) && low250 > 80 ? 14 : 0,
    trend.entryBias === "wait_pullback" ? 10 : trend.entryBias === "avoid_now" ? 18 : 0,
    theme.positionSignal === "high_chase_risk" ? 22 : 0,
    theme.stage === "crowded" ? 18 : 0,
    themeRetreatRisk ? 34 : 0,
    staleCatchdownRisk ? 40 : 0,
    staleCatalystRisk ? 30 : 0,
    staleThemeRefreshRisk ? 32 : 0,
    holdingRealtimeCatchdownRisk ? 36 : 0,
    unsupportedHoldingThemeRisk ? 32 : 0,
    lossMemoryCatchdownRisk ? 36 : 0,
    lowSetupThemeSupportRisk ? 34 : 0,
    Number.isFinite(crowding) && crowding >= 55 ? 14 : Number.isFinite(crowding) && crowding >= 40 ? 8 : 0,
    /追涨|偏热|高位|拥挤|等待回撤/.test(text) ? 10 : 0
  ].reduce((sum, value) => sum + value, 0);
  return {
    trend,
    theme,
    themeRetreatRisk,
    staleCatchdownRisk,
    staleCatalystRisk,
    staleThemeRefreshRisk,
    holdingRealtimeCatchdownRisk,
    unsupportedHoldingThemeRisk,
    lossMemoryCatchdownRisk,
    lowSetupThemeSupportRisk,
    holdingRealtimeWarning: holdingRealtimeProfile.warning,
    holdingRealtimeFacts: holdingRealtimeProfile.facts,
    holdingThemeSupportGap,
    lossMemoryWarnings,
    actionableThemeSupportGap,
    themeRetreatWarnings,
    staleThemeWarnings,
    staleCatalystWarnings,
    staleThemeRefreshWarnings,
    score,
    shouldSurface: score >= 20,
    hotEvidence,
    themeRisk: holdingRealtimeCatchdownRisk
      ? "前十大持仓盘中走弱，先等底层持仓止跌。"
      : staleThemeRefreshRisk
      ? "题材雷达快照已经过期，旧主力/旧新闻标签不能当成今天的买点。"
      : unsupportedHoldingThemeRisk
      ? "前十大持仓暴露出明确底层题材，但当前雷达没有同方向主力或新闻支撑。"
      : lossMemoryCatchdownRisk
      ? "历史同主题接盘亏损尚未解除冷却，必须先证明主力资金回流和新鲜催化。"
      : lowSetupThemeSupportRisk
      ? "低位不等于启动；没有主力资金回流、新鲜催化和当前题材确认前，回调先按接盘风险处理。"
      : staleCatchdownRisk
      ? "题材缺少主力进场或预热催化，回调先按接盘风险处理。"
      : staleCatalystRisk
      ? "题材逻辑停留在旧新闻/旧催化，不能当作今天的买点。"
      : themeRetreatRisk
      ? "题材退潮或主力资金撤离，先等资金回流。"
      : theme.name ? `${theme.name}题材偏热或拥挤，需要等降温。` : "",
    positionRisk: Number.isFinite(low120) && low120 > 80 ? "基金处在区间高位，不是低位启动。" : "",
    needsPullback: Number.isFinite(r20) && r20 > 12,
    needsLowPosition: Number.isFinite(low120) && low120 > 65 || Number.isFinite(low250) && low250 > 80,
    needsCooling: holdingRealtimeCatchdownRisk || staleThemeRefreshRisk || unsupportedHoldingThemeRisk || lossMemoryCatchdownRisk || lowSetupThemeSupportRisk || staleCatchdownRisk || staleCatalystRisk || themeRetreatRisk || Number.isFinite(crowding) && crowding >= 40 || theme.positionSignal === "high_chase_risk" || theme.stage === "crowded"
  };
}

function getPortfolioCatchdownLossMemoryWarnings(item = {}, profile = {}) {
  return uniquePortfolioStringArray([
    ...normalizeStringArray(item.catchdownLossMemoryWarnings),
    ...normalizeStringArray(profile.catchdownLossMemoryWarnings),
    ...normalizeStringArray(profile.seed?.catchdownLossMemoryWarnings)
  ]).filter((warning) => /历史接盘亏损冷却|同主题.*接盘|同主题.*亏损/.test(warning));
}

function hasPortfolioLowSetupWithoutMainForceConfirmation(item = {}, trend = {}) {
  const low120 = finiteMetricNumber(trend.lowPositionPct120);
  const low250 = finiteMetricNumber(trend.lowPositionPct250);
  const setupSignal = String(trend.pullbackSetup?.signal || "");
  const readinessScore = finiteMetricNumber(item.readinessScore);
  const text = mergeStringLists(item.reason, item.setupEvidence, item.buyTriggers, item.riskNotes, item.candidateRole).join(" ");
  return ["pullback_complete", "launch_setup"].includes(setupSignal)
    || (Number.isFinite(low120) && low120 <= 55)
    || (Number.isFinite(low250) && low250 <= 65)
    || (Number.isFinite(readinessScore) && readinessScore >= 70)
    || /低位|回调完成|启动前夜|准备启动|刚转强|小仓试探|买入准备/.test(text);
}

function buildPortfolioChaseRiskFacts(evidence = {}) {
  const trend = evidence.trend || {};
  const theme = evidence.theme || {};
  return [
    ...evidence.hotEvidence.slice(0, 3),
    ...(evidence.holdingRealtimeFacts || []).slice(0, 2),
    theme.name ? `题材${theme.name}` : "",
    Number.isFinite(Number(trend.drawdownFromRecentHighPct)) ? `距高点${formatFallbackPlainPct(trend.drawdownFromRecentHighPct)}` : ""
  ].filter(Boolean);
}

function buildPortfolioHoldingRealtimeEvidenceProfile(item = {}, profile = {}) {
  const candidate = {
    ...item,
    ...(profile || {}),
    holdingRealtimePulse: profile?.holdingRealtimePulse || item.holdingRealtimePulse,
    holdings: profile?.holdings || item.holdings,
    actionability: profile?.actionability || item.actionability,
    holdingsOutlook: profile?.holdingsOutlook || item.holdingsOutlook
  };
  const warning = getHoldingRealtimeCatchdownWarning(candidate);
  const pulse = getCandidateHoldingRealtimePulse(candidate);
  if (!warning || !pulse?.ok) return { warning: "", facts: [] };
  const weighted = finiteMetricNumber(pulse.weightedChangePct);
  const covered = finiteMetricNumber(pulse.coveredHoldingPct);
  const negative = Array.isArray(pulse.topNegative)
    ? pulse.topNegative
      .map((entry) => {
        const name = entry?.name || entry?.code || "";
        const change = finiteMetricNumber(entry?.changePct);
        return name ? `${name}${Number.isFinite(change) ? formatFallbackPlainPct(change) : ""}` : "";
      })
      .filter(Boolean)
      .slice(0, 3)
    : [];
  const facts = [
    Number.isFinite(weighted) ? `前十大持仓加权${formatFallbackPlainPct(weighted)}` : "",
    Number.isFinite(covered) ? `覆盖持仓${round(covered, 1)}%` : "",
    negative.length ? `走弱龙头${negative.join("/")}` : "",
    ...normalizeStringArray(pulse.risks).slice(0, 2)
  ].filter(Boolean);
  return { warning, facts };
}

function buildPortfolioDrawdownDefenseRanking(watchlist = [], positions = []) {
  const positionItems = (positions || [])
    .map(buildPortfolioDrawdownDefensePositionItem)
    .filter(Boolean);
  const watchItems = (watchlist || [])
    .filter((item) => item?.code && ["ready", "waiting_pullback", "watch"].includes(item.status))
    .map(buildPortfolioDrawdownDefenseWatchItem)
    .filter(Boolean);
  const items = [...positionItems, ...watchItems]
    .sort(compareRankingItems)
    .slice(0, 8);
  return buildPortfolioRankingList({
    id: "drawdown_defense",
    title: "回撤防线榜",
    subtitle: "先看持仓利润回吐、单仓风险和候选历史最大回撤，防止经理只顾买入不设防线。",
    emptyText: "暂无需要单独拉响的回撤防线。",
    nextAction: "下一步先处理利润回吐、历史最大回撤和单仓风险；买入前必须写清防线，不允许用补仓摊薄替代风控。",
    items
  });
}

function buildPortfolioDrawdownDefensePositionItem(position = {}) {
  if (!position?.code) return null;
  const budget = position.riskBudget || buildPortfolioPositionRiskBudget(position);
  const giveback = finiteMetricNumber(position.profitGivebackPct);
  const weight = finiteMetricNumber(position.weightPct);
  const unrealized = finiteMetricNumber(position.unrealizedPnlPct);
  const peak = finiteMetricNumber(position.peakUnrealizedPnlPct);
  const budgetLevel = String(budget.level || "normal");
  const hasRisk = budgetLevel !== "normal"
    || (Number.isFinite(giveback) && giveback >= 2.5)
    || (Number.isFinite(weight) && weight >= 10)
    || (Number.isFinite(peak) && peak > 0 && Number.isFinite(unrealized) && unrealized < 0);
  if (!hasRisk) return null;
  const severity = budgetLevel === "severe" ? 56 : budgetLevel === "warning" ? 40 : 16;
  const score = Math.max(0, Math.min(100,
    severity
    + (Number.isFinite(giveback) ? Math.min(26, giveback * 3) : 0)
    + (Number.isFinite(weight) ? Math.max(0, weight - 6) * 2 : 0)
    + (Number.isFinite(unrealized) && unrealized < 0 ? 8 : 0)
  ));
  return buildPortfolioRankingItem({
    code: position.code,
    name: position.name,
    source: "持仓回撤防线",
    score: round(score, 1),
    action: budgetLevel === "severe"
      ? "回撤防线优先"
      : budgetLevel === "warning" || (Number.isFinite(giveback) && giveback >= 4)
        ? "利润保护复核"
        : "防线观察",
    reason: budget.triggers?.[0]
      || (Number.isFinite(giveback) && giveback > 0
        ? `已出现浮盈回吐${round(giveback, 2)}个百分点，先保护利润再谈补仓。`
        : "单仓风险进入回撤防线复核。"),
    facts: [
      Number.isFinite(weight) ? `仓位${formatFallbackPlainPct(weight)}` : "",
      Number.isFinite(unrealized) ? `浮盈${formatFallbackPlainPct(unrealized)}` : "",
      Number.isFinite(peak) ? `曾浮盈${formatFallbackPlainPct(peak)}` : "",
      Number.isFinite(giveback) && giveback > 0 ? `回吐${round(giveback, 2)}pct` : "",
      budget.label || ""
    ].filter(Boolean),
    decision: {
      highlights: [budget.label || "持仓进入回撤防线"],
      risks: mergeStringLists(budget.triggers, [
        Number.isFinite(weight) && weight >= 10 ? "单仓仓位偏高，回撤会放大组合波动。" : "",
        Number.isFinite(peak) && peak > 0 && Number.isFinite(unrealized) && unrealized < 0 ? "曾经盈利后转亏，不能用补仓摊薄代替止盈纪律。" : ""
      ]).filter(Boolean).slice(0, 3),
      gaps: position.lastRiskControl ? [position.lastRiskControl] : [],
      nextStep: budgetLevel === "normal"
        ? "先设跟踪防线；若继续回吐或跌破买入理由，降到卖出风险榜复核。"
        : "先复核减仓/赎回边界和到账时间；未解除前暂停同题材新增买入，禁止补仓摊薄。"
    },
    status: budgetLevel === "normal" ? "watch" : budgetLevel
  });
}

function buildPortfolioDrawdownDefenseWatchItem(item = {}) {
  const evidence = resolvePortfolioWatchDrawdownDefenseEvidence(item);
  if (!evidence.shouldSurface) return null;
  return buildPortfolioRankingItem({
    code: item.code,
    name: item.name,
    source: "候选回撤防线",
    score: round(evidence.score, 1),
    action: evidence.severe ? "高回撤降级" : "买前防线复核",
    reason: evidence.reason,
    facts: evidence.facts,
    decision: {
      highlights: evidence.highlights,
      risks: evidence.risks,
      gaps: evidence.gaps,
      nextStep: evidence.severe
        ? "先降级观察或只保留0元备选；除非回撤来源、持仓前景和小仓止损边界全部写清，否则不得进入买入执行。"
        : "买入前必须写清最大试探仓、止损/止盈复核线和复查周期；防线不清则保持观察。"
    },
    status: evidence.severe ? "warning" : "watch"
  });
}

function resolvePortfolioWatchDrawdownDefenseEvidence(item = {}) {
  const snapshot = item.lastSnapshot || {};
  const risk = selectPortfolioQualityRiskPeriod(snapshot);
  const maxDrawdown = finiteMetricNumber(risk.maxDrawdownPct);
  const volatility = finiteMetricNumber(risk.annualizedVolatilityPct ?? risk.volatilityPct);
  const sharpe = finiteMetricNumber(risk.sharpe);
  const trend = snapshot.trendProfile || {};
  const return20d = finiteMetricNumber(trend.return20dPct);
  const drawdownFromHigh = finiteMetricNumber(trend.drawdownFromRecentHighPct);
  const readinessScore = finiteMetricNumber(item.readinessScore);
  const absDrawdown = Number.isFinite(maxDrawdown) ? Math.abs(maxDrawdown) : null;
  const severe = Number.isFinite(absDrawdown) && absDrawdown >= 30
    || Number.isFinite(volatility) && volatility >= 32;
  const shouldSurface = severe
    || (Number.isFinite(absDrawdown) && absDrawdown >= 22)
    || (item.status === "ready" && Number.isFinite(absDrawdown) && absDrawdown >= 18)
    || (Number.isFinite(return20d) && return20d > 10 && Number.isFinite(drawdownFromHigh) && drawdownFromHigh > -3);
  if (!shouldSurface) return { shouldSurface: false };
  const score = Math.max(0, Math.min(100,
    (Number.isFinite(absDrawdown) ? Math.min(48, absDrawdown * 1.35) : 18)
    + (Number.isFinite(volatility) ? Math.min(22, volatility * 0.55) : 0)
    + (Number.isFinite(readinessScore) ? Math.min(16, readinessScore * 0.12) : 0)
    + (Number.isFinite(return20d) && return20d > 10 ? 10 : 0)
    - (Number.isFinite(sharpe) && sharpe >= 1 ? 8 : 0)
  ));
  const facts = [
    Number.isFinite(maxDrawdown) ? `最大回撤${formatFallbackPlainPct(maxDrawdown)}` : "",
    Number.isFinite(volatility) ? `年化波动${formatFallbackPlainPct(volatility)}` : "",
    Number.isFinite(sharpe) ? `夏普${round(sharpe, 2)}` : "",
    Number.isFinite(return20d) ? `20日${formatFallbackPlainPct(return20d)}` : "",
    Number.isFinite(readinessScore) ? `准备度${round(readinessScore, 0)}` : ""
  ].filter(Boolean);
  return {
    shouldSurface,
    severe,
    score,
    facts,
    reason: severe
      ? "候选基金历史回撤或波动偏高，不能只因买点接近就进入执行。"
      : "候选有机会但回撤防线需要先写清，否则容易买完后遇到波动被动止损。",
    highlights: [
      item.status === "ready" ? "候选接近买点，必须同步检查回撤承受力。" : "",
      Number.isFinite(sharpe) && sharpe >= 1 ? "夏普较好，说明回撤风险可继续量化复核。" : ""
    ].filter(Boolean),
    risks: [
      Number.isFinite(maxDrawdown) && maxDrawdown <= -25 ? "历史最大回撤偏深，试探仓必须更小。" : "",
      Number.isFinite(volatility) && volatility >= 28 ? "波动偏高，客户可能难以承受短期回撤。" : "",
      Number.isFinite(return20d) && return20d > 10 ? "近20日涨幅偏热，防线不清容易变成追涨。" : ""
    ].filter(Boolean),
    gaps: [
      !Number.isFinite(maxDrawdown) ? "缺历史最大回撤" : "",
      !Number.isFinite(sharpe) ? "缺夏普/风险收益指标" : "",
      !Number.isFinite(volatility) ? "缺波动率" : ""
    ].filter(Boolean)
  };
}

function buildPortfolioDataConfidenceRanking(watchlist = [], positions = []) {
  const watchItems = (watchlist || [])
    .filter((item) => item?.code && !["removed"].includes(item.status))
    .map(buildPortfolioDataConfidenceWatchItem)
    .filter(Boolean);
  const positionItems = (positions || [])
    .filter((position) => position?.code && Number(position.currentValue || 0) > 0)
    .map(buildPortfolioDataConfidencePositionItem)
    .filter(Boolean);
  const items = [...watchItems, ...positionItems]
    .sort(compareRankingItems)
    .slice(0, 8);
  return buildPortfolioRankingList({
    id: "data_confidence",
    title: "数据体检榜",
    subtitle: "把净值时效、走势、份额费率、前十大持仓和来源完整性放在买卖动作之前体检。",
    emptyText: "暂无明显数据缺口；仍需在执行前刷新净值和费用来源。",
    nextAction: "下一步先补净值、费率、份额类别、前十大持仓和来源；证据未补齐前不得给买入执行金额。",
    items
  });
}

function buildPortfolioDataConfidenceWatchItem(item = {}) {
  const evidence = resolvePortfolioDataConfidenceEvidence(item, { sourceType: "watchlist" });
  if (!evidence.shouldSurface) return null;
  return buildPortfolioRankingItem({
    code: item.code,
    name: item.name,
    source: "数据体检",
    score: round(evidence.score, 1),
    action: evidence.critical ? "数据阻塞" : "补数据复核",
    reason: evidence.reason,
    facts: evidence.facts,
    decision: {
      highlights: evidence.highlights,
      risks: evidence.risks,
      gaps: evidence.gaps,
      nextStep: evidence.critical
        ? "先刷新净值/走势、份额费率、前十大持仓和来源；补齐前只能观察，不能提交买入或加仓动作。"
        : "补齐缺口后再回到买入准备、板块榜和费率榜交叉确认。"
    },
    status: evidence.critical ? "warning" : "watch"
  });
}

function buildPortfolioDataConfidencePositionItem(position = {}) {
  const snapshot = position.fundSnapshot || {};
  const item = {
    code: position.code,
    name: position.name,
    status: "in_position",
    shareClass: position.shareClass,
    lastSnapshot: {
      ...snapshot,
      navDate: snapshot.navDate || position.lastNavDate || "",
      snapshotDate: snapshot.snapshotDate || position.lastNavDate || ""
    },
    reason: position.lastReason || "持仓数据体检"
  };
  const evidence = resolvePortfolioDataConfidenceEvidence(item, { sourceType: "position" });
  if (!evidence.shouldSurface) return null;
  return buildPortfolioRankingItem({
    code: position.code,
    name: position.name,
    source: "持仓数据体检",
    score: round(evidence.score, 1),
    action: evidence.critical ? "持仓数据阻塞" : "持仓补数据",
    reason: evidence.reason,
    facts: evidence.facts,
    decision: {
      highlights: evidence.highlights,
      risks: evidence.risks,
      gaps: evidence.gaps,
      nextStep: evidence.critical
        ? "先刷新持仓净值、走势和前十大持仓；未补齐前不要把加仓、止盈或持有理由说满。"
        : "补齐缺口后再复核持仓前景、回撤防线和卖出风险。"
    },
    status: evidence.critical ? "warning" : "watch"
  });
}

function resolvePortfolioDataConfidenceEvidence(item = {}, options = {}) {
  const snapshot = item.lastSnapshot || {};
  const trend = snapshot.trendProfile || {};
  const navDate = snapshot.navDate || snapshot.snapshotDate || item.navDate || "";
  const navAgeDays = estimateDateAgeDays(navDate);
  const fees = snapshot.fees || {};
  const feeImpact = fees.feeImpact || snapshot.feeImpact || {};
  const missingFeeData = normalizeStringArray(feeImpact.missingFeeData || fees.missingFeeData);
  const missingFeeLabels = missingFeeData.map(formatPortfolioFeeMissingLabel).filter(Boolean);
  const shareClass = String(
    item.shareClass
    || fees.shareClass
    || snapshot.shareClass
    || snapshot.seed?.shareClass
    || inferFundShareClass(item.name || snapshot.name || snapshot.seed?.name || "")
    || ""
  ).trim().toUpperCase();
  const holdings = collectPortfolioWatchHoldingItems(item);
  const themeSupportGap = getPortfolioWatchThemeSupportGap(item, snapshot);
  const sources = normalizeStringArray([
    ...normalizeStringArray(snapshot.sources),
    ...normalizeStringArray(item.dataBasis),
    snapshot.source,
    snapshot.navSource,
    snapshot.valuationSource,
    snapshot.primarySource,
    snapshot.supplementalIntradaySource
  ]);
  const gaps = [
    !navDate ? "缺净值日期" : "",
    Number.isFinite(navAgeDays) && navAgeDays > 5 ? `净值/走势已过期${navAgeDays}天` : "",
    trend.ok === false || (!trend.ok && !snapshot.trendSummary) ? "缺可验证走势" : "",
    !shareClass ? "缺份额类别" : "",
    ...missingFeeLabels.map((label) => `缺${label}`),
    themeSupportGap || "",
    !holdings.length ? "缺前十大持仓" : "",
    !sources.length ? "缺数据来源" : ""
  ].filter(Boolean);
  const critical = gaps.some((gap) => /缺净值日期|过期|缺份额类别|申购费|销售服务费|缺可验证走势|当前主力进场|题材预热|低位轮动支撑/.test(gap))
    || (item.status === "ready" && gaps.length);
  const shouldSurface = Boolean(gaps.length);
  const score = Math.max(0, Math.min(100,
    gaps.length * 14
    + (critical ? 22 : 0)
    + (Number.isFinite(navAgeDays) ? Math.min(20, Math.max(0, navAgeDays - 3) * 2) : 12)
    + (item.status === "ready" ? 10 : 0)
    + (options.sourceType === "position" ? 6 : 0)
  ));
  const facts = [
    navDate ? `净值日期${navDate}` : "净值日期待补",
    Number.isFinite(navAgeDays) ? `距今${navAgeDays}天` : "",
    shareClass ? `${shareClass}类` : "份额待核验",
    missingFeeLabels.length ? `费用缺口${missingFeeLabels.slice(0, 2).join("/")}` : "",
    holdings.length ? `持仓${holdings.length}项` : "持仓缺口",
    sources.length ? `来源${sources.length}个` : "来源缺口"
  ].filter(Boolean);
  return {
    shouldSurface,
    critical,
    score,
    facts,
    reason: critical
      ? "关键数据证据不足或已过期，不能把该基金直接推进买入/加仓执行。"
      : "该基金仍有数据缺口，推荐前需要先补证据，避免客户以为结论已经充分核验。",
    highlights: [
      navDate ? `已有净值日期：${navDate}。` : "",
      sources.length ? `已有${sources.length}个来源线索，可继续追溯。` : ""
    ].filter(Boolean),
    risks: [
      critical ? "关键数据不完整时给买入金额，会让推荐显得不可靠。" : "",
      missingFeeLabels.length ? "费率或份额不完整会影响A/C/D/I选择和盈利模型。" : "",
      themeSupportGap ? "缺当前题材支撑时给买入金额，容易把旧题材回调误判成启动。" : "",
      !holdings.length ? "缺前十大持仓会削弱行业前景判断。" : ""
    ].filter(Boolean),
    gaps: gaps.slice(0, 4)
  };
}

function buildPortfolioHoldingsOutlookRanking(watchlist = []) {
  const items = normalizePortfolioWatchlist(watchlist)
    .filter((item) => item.code && ["ready", "waiting_pullback", "watch"].includes(item.status))
    .map((item) => {
      const outlook = resolvePortfolioWatchHoldingsOutlook(item);
      if (!outlook.hasHoldings) return null;
      const score = Number(item.readinessScore || 0) + Number(outlook.score || 0) * 2;
      const concentration = outlook.concentration || {};
      return buildPortfolioRankingItem({
        code: item.code,
        name: item.name,
        source: "前十大持仓",
        score: round(score, 1),
        action: outlook.score >= 14 ? "持仓支撑复核" : outlook.score >= 7 ? "前景复核" : "持仓风险复核",
        reason: `持仓前景：${outlook.label || "已补齐"}；${outlook.evidence || "前十大持仓已补齐，需要和买点一起复核。"}`,
        facts: [
          Number.isFinite(Number(concentration.top10Pct)) ? `前十大${formatFallbackPlainPct(concentration.top10Pct)}` : "",
          outlook.holdingTags?.length ? `行业${outlook.holdingTags.slice(0, 3).join("/")}` : "",
          outlook.matchedTags?.length ? `匹配${outlook.matchedTags.slice(0, 3).join("/")}` : ""
        ].filter(Boolean),
        decision: {
          highlights: normalizeStringArray(outlook.positives).length
            ? normalizeStringArray(outlook.positives).slice(0, 3)
            : [outlook.evidence || "前十大持仓已补齐"],
          risks: normalizeStringArray(outlook.risks).slice(0, 3),
          gaps: Number(outlook.score || 0) >= 7 ? [] : ["持仓前景还不能单独支撑买入，需要继续补行业和走势证据。"],
          nextStep: "把前十大持仓、行业前景、集中度和当前买点一起复核，通过后才进入主推荐。"
        },
        status: outlook.label || ""
      });
    })
    .filter(Boolean)
    .sort(compareRankingItems)
    .slice(0, 6);
  return buildPortfolioRankingList({
    id: "holdings_outlook",
    title: "持仓前景榜",
    subtitle: "从前十大持仓、行业匹配和集中度看基金是否真的值得买。",
    emptyText: "暂无前十大持仓支撑明确的候选。",
    nextAction: "下一步补齐候选基金前十大持仓和行业前景，避免只凭净值走势推荐。",
    items
  });
}

function resolvePortfolioWatchHoldingsOutlook(item = {}) {
  const profile = item.lastSnapshot || {};
  const embedded = profile.holdingsOutlook || profile.actionability?.holdingsOutlook;
  if (embedded && typeof embedded === "object" && (embedded.hasHoldings || embedded.evidence || embedded.risks?.length)) {
    return {
      ok: embedded.ok !== false,
      hasHoldings: embedded.hasHoldings !== false,
      score: Number.isFinite(Number(embedded.score)) ? Number(embedded.score) : 0,
      label: embedded.label || "",
      evidence: embedded.evidence || "",
      positives: normalizeStringArray(embedded.positives),
      risks: normalizeStringArray(embedded.risks),
      topHoldings: embedded.topHoldings || [],
      holdingTags: normalizeStringArray(embedded.holdingTags),
      matchedTags: normalizeStringArray(embedded.matchedTags),
      concentration: embedded.concentration || {}
    };
  }
  const topHoldings = normalizeStringArray(profile.topHoldings || profile.equityTopHoldings || []);
  return buildHoldingsOutlookProfile({
    ...profile,
    code: item.code || profile.code,
    name: item.name || profile.name,
    seed: {
      ...(profile.seed || {}),
      name: item.name || profile.name,
      keywords: mergeStringLists([item.reason], item.setupEvidence, item.buyTriggers, item.riskNotes)
    },
    topStocks: topHoldings.length ? topHoldings : profile.topStocks,
    holdings: profile.holdings || {
      equityTopHoldings: profile.equityTopHoldings || topHoldings
    }
  });
}

function buildPortfolioFeeSuitabilityRanking(watchlist = []) {
  const items = (watchlist || [])
    .filter((item) => item?.code && !["blocked", "removed"].includes(item.status))
    .map(buildPortfolioFeeSuitabilityRankingItem)
    .filter(Boolean)
    .sort(compareRankingItems)
    .slice(0, 6);
  return buildPortfolioRankingList({
    id: "fee_suitability",
    title: "费率适配榜",
    subtitle: "按 A/C/D/I 份额、每万成本和预计持有期，判断买哪类份额更合适。",
    emptyText: "暂无费用/份额需要优先复核的候选。",
    nextAction: "下一步补齐 A/C/D/I 替代份额、申购费、销售服务费、赎回费和预计持有期，再进入买入执行。",
    items
  });
}

function buildPortfolioFeeSuitabilityRankingItem(item = {}) {
  const evidence = resolvePortfolioWatchFeeSuitabilityEvidence(item);
  if (!evidence.shouldSurface) return null;
  const readinessScore = Number(item.readinessScore || 0);
  const statusScore = item.status === "ready" ? 24 : item.status === "waiting_pullback" ? 14 : item.status === "watch" ? 6 : 0;
  const score = readinessScore
    + statusScore
    + (evidence.missingCritical ? 18 : 0)
    + (evidence.alternativeCount ? 12 : 0)
    + (evidence.highDrag ? 10 : 0)
    + (evidence.specialShare ? 8 : 0);
  return buildPortfolioRankingItem({
    code: item.code,
    name: item.name,
    source: "费用/份额",
    score: round(score, 1),
    action: evidence.missingCritical
      ? "费用补证据"
      : evidence.alternativeCount
        ? "份额对比复核"
        : evidence.highDrag
          ? "长期费率复核"
          : evidence.specialShare
            ? "渠道可买复核"
            : "持有期适配复核",
    reason: buildPortfolioFeeSuitabilityReason(evidence),
    facts: buildPortfolioFeeSuitabilityFacts(evidence),
    decision: {
      highlights: [
        evidence.feeNotes[0] || evidence.feeModel.selectionRule || evidence.feeModel.label || "",
        evidence.feeDecisionRule || "",
        evidence.alternativeCount ? `已有 ${evidence.alternativeCount} 个替代份额，适合做同基金份额比较。` : ""
      ].filter(Boolean),
      risks: [
        evidence.highDrag ? "长期持有可能被持续费用拖累，不能只看短期买点。" : "",
        evidence.specialShare ? "特殊/平台份额需确认普通客户是否可买和起购门槛。" : "",
        evidence.missingLabels.length ? `缺少${evidence.missingLabels.slice(0, 2).join("、")}，买入前证据不足。` : ""
      ].filter(Boolean),
      gaps: [
        evidence.alternativeCount ? "" : "缺少同基金 A/C/D/I 替代份额比较。",
        ...evidence.missingLabels.map((label) => `缺${label}`)
      ].filter(Boolean).slice(0, 3),
      nextStep: evidence.missingCritical
        ? "先补齐份额类别和关键费率，未完成前只能观察，不能提交虚拟申购。"
        : "按预计持有期比较 A/C/D/I、赎回费和可买渠道，再决定小仓试探或继续观察。"
    },
    status: evidence.missingCritical ? "warning" : evidence.highDrag ? "watch" : item.status || "watch"
  });
}

function resolvePortfolioWatchFeeSuitabilityEvidence(item = {}) {
  const profile = item.lastSnapshot || {};
  const fees = profile.fees || {};
  const shareClass = String(
    item.shareClass
    || fees.shareClass
    || profile.shareClass
    || profile.seed?.shareClass
    || inferFundShareClass(item.name || profile.name || profile.seed?.name || "")
    || ""
  ).trim().toUpperCase();
  const feeModel = fees.shareClassFeeModel
    || profile.shareClassFeeModel
    || profile.seed?.shareClassFeeModel
    || inferShareClassFeeModel(shareClass, fees);
  const impact = fees.feeImpact || profile.feeImpact || profile.seed?.feeImpact || {};
  const missing = normalizeStringArray(impact.missingFeeData || fees.missingFeeData);
  const missingLabels = missing.map(formatPortfolioFeeMissingLabel).filter(Boolean);
  const oneYearCost = toNumber(impact.oneYearCostPer10000);
  const twoYearCost = toNumber(impact.twoYearCostPer10000);
  const alternativeShareClasses = normalizePortfolioWatchAlternatives(item.alternativeShareClasses || []);
  const feeNotes = mergeStringLists(
    item.feeNotes,
    fees.feeNotes,
    profile.feeNotes,
    profile.seed?.feeNotes,
    alternativeShareClasses.flatMap((alt) => alt.feeNotes || [])
  );
  const criticalMissingKeys = new Set(["share_class", "subscription_or_sales_service_fee", "sales_service_fee", "subscription_fee"]);
  const missingCritical = !shareClass
    || !feeModel?.label
    || feeModel.type === "unknown"
    || missing.some((key) => criticalMissingKeys.has(key));
  const specialShare = feeModel.type === "special_or_platform_class" || ["D", "I", "Y"].includes(shareClass);
  const highDrag = impact.feeDragLevel === "high"
    || impact.holdingPeriodFit === "short_term_only_high_long_holding_drag"
    || (Number.isFinite(oneYearCost) && oneYearCost >= 80);
  const statusSurface = ["ready", "waiting_pullback", "watch", "in_position"].includes(item.status);
  return {
    shareClass,
    feeModel: feeModel || {},
    impact,
    oneYearCost,
    twoYearCost,
    missingLabels,
    missingCritical,
    specialShare,
    highDrag,
    alternativeCount: alternativeShareClasses.length,
    feeNotes,
    feeDecisionRule: impact.feeDecisionRule || feeModel?.selectionRule || "",
    shouldSurface: Boolean(
      statusSurface
      && (missingCritical
        || specialShare
        || highDrag
        || alternativeShareClasses.length
        || feeNotes.length
        || Number.isFinite(oneYearCost)
        || shareClass)
    )
  };
}

function buildPortfolioFeeSuitabilityReason(evidence = {}) {
  if (evidence.missingCritical) {
    return "买入前缺少可验证费用/份额证据，不能只因为走势达标就下单。";
  }
  if (evidence.alternativeCount) {
    return `存在 ${evidence.alternativeCount} 个同基金替代份额，需要按预计持有期选择更合适的份额。`;
  }
  if (evidence.highDrag) {
    return "该份额可能有较明显费用拖累，长期持有前必须比较低费率替代。";
  }
  if (evidence.specialShare) {
    return "该份额可能属于特殊、机构或平台份额，需要确认普通客户渠道和起购门槛。";
  }
  if (["C", "E"].includes(evidence.shareClass)) {
    return "该份额偏持续销售服务费模型，适合短中期战术观察，长期持有要再比较 A 类或低费替代。";
  }
  if (["A", "B"].includes(evidence.shareClass)) {
    return "该份额偏前端申购费模型，短线试仓要确认收益空间能覆盖申赎摩擦。";
  }
  return "已有费用线索，执行前仍需把份额类别、持有期和赎回规则合并复核。";
}

function buildPortfolioFeeSuitabilityFacts(evidence = {}) {
  return [
    evidence.shareClass ? `${evidence.shareClass}类` : "份额待核验",
    evidence.feeModel?.label || "",
    Number.isFinite(evidence.oneYearCost) ? `每万1年约${round(evidence.oneYearCost, 0)}元` : "",
    Number.isFinite(evidence.twoYearCost) ? `2年约${round(evidence.twoYearCost, 0)}元` : "",
    evidence.alternativeCount ? `替代份额${evidence.alternativeCount}个` : "",
    evidence.missingLabels.length ? `缺${evidence.missingLabels.slice(0, 2).join("/")}` : ""
  ].filter(Boolean);
}

function formatPortfolioFeeMissingLabel(key = "") {
  const labels = {
    share_class: "份额类别",
    fee_page: "费率页",
    subscription_or_sales_service_fee: "申购费或销售服务费",
    sales_service_fee: "销售服务费",
    subscription_fee: "申购费",
    subscription_rules: "申购规则",
    redemption_rules: "赎回规则"
  };
  return labels[String(key || "")] || String(key || "").trim();
}

function buildPortfolioReplacementChoiceRanking(watchlist = []) {
  const items = (watchlist || [])
    .filter((item) => item?.code && !["removed"].includes(item.status))
    .map(buildPortfolioReplacementChoiceRankingItem)
    .filter(Boolean)
    .sort(compareRankingItems)
    .slice(0, 6);
  return buildPortfolioRankingList({
    id: "replacement_choice",
    title: "替代优选榜",
    subtitle: "把同基金 A/C/D/I 份额和同指数/同题材替代品放在一起比较，避免客户买到更贵或重复的产品。",
    emptyText: "暂无替代份额或同类替代需要优先复核的候选。",
    nextAction: "下一步为候选补齐同基金份额、同指数低费替代、规模和费率；买入前只保留一个代表产品，不把替代品当新增推荐名额。",
    items
  });
}

function buildPortfolioReplacementChoiceRankingItem(item = {}) {
  const evidence = resolvePortfolioReplacementChoiceEvidence(item);
  if (!evidence.shouldSurface) return null;
  return buildPortfolioRankingItem({
    code: item.code,
    name: item.name,
    source: "替代优选",
    score: round(evidence.score, 1),
    action: evidence.action,
    reason: evidence.reason,
    facts: evidence.facts,
    decision: {
      highlights: evidence.highlights,
      risks: evidence.risks,
      gaps: evidence.gaps,
      nextStep: evidence.nextStep
    },
    status: evidence.status
  });
}

function resolvePortfolioReplacementChoiceEvidence(item = {}) {
  const fee = resolvePortfolioWatchFeeSuitabilityEvidence(item);
  const shareAlternatives = normalizePortfolioWatchAlternatives(item.alternativeShareClasses || []);
  const exposureAlternatives = normalizePortfolioWatchAlternatives(item.sameExposureAlternatives || []);
  const currentShareClass = fee.shareClass || String(item.shareClass || inferFundShareClass(item.name || "") || "").toUpperCase();
  const shareClasses = collectPortfolioReplacementShareClasses(shareAlternatives);
  const currentOneYearCost = finiteMetricNumber(fee.oneYearCost);
  const alternativeCostValues = [...shareAlternatives, ...exposureAlternatives]
    .map(resolvePortfolioReplacementAlternativeCost)
    .filter((value) => Number.isFinite(value));
  const lowerCostAlternative = Number.isFinite(currentOneYearCost)
    && alternativeCostValues.some((value) => value < currentOneYearCost);
  const missingAlternativeFees = [...shareAlternatives, ...exposureAlternatives]
    .some((alt) => !Number.isFinite(resolvePortfolioReplacementAlternativeCost(alt)) && !normalizeStringArray(alt.feeNotes).length);
  const hasAlternatives = Boolean(shareAlternatives.length || exposureAlternatives.length);
  if (!hasAlternatives) return { shouldSurface: false };

  const readinessScore = Number(item.readinessScore || 0);
  const score = Math.max(0, Math.min(100,
    readinessScore * 0.35
    + shareAlternatives.length * 14
    + exposureAlternatives.length * 10
    + (lowerCostAlternative ? 16 : 0)
    + (fee.highDrag ? 12 : 0)
    + (fee.missingCritical ? 10 : 0)
    - (missingAlternativeFees ? 6 : 0)
  ));
  const action = shareAlternatives.length && exposureAlternatives.length
    ? "份额/同类替代优选"
    : shareAlternatives.length
      ? "A/C份额优选"
      : "同类低费替代";
  const status = fee.missingCritical || missingAlternativeFees ? "warning" : lowerCostAlternative ? "ready" : item.status || "watch";
  const alternativeLabel = formatPortfolioReplacementAlternativeLabel(shareAlternatives, exposureAlternatives);
  return {
    shouldSurface: true,
    score,
    action,
    status,
    reason: buildPortfolioReplacementChoiceReason({ shareAlternatives, exposureAlternatives, lowerCostAlternative, fee }),
    facts: [
      currentShareClass ? `当前${currentShareClass}类` : "当前份额待核验",
      shareClasses.length ? `同基金${shareClasses.join("/")}` : "",
      exposureAlternatives.length ? `同类替代${exposureAlternatives.length}个` : "",
      Number.isFinite(currentOneYearCost) ? `当前每万1年约${round(currentOneYearCost, 0)}元` : "",
      lowerCostAlternative ? "发现可能低费替代" : ""
    ].filter(Boolean),
    highlights: [
      shareAlternatives.length ? `已有同基金${shareClasses.join("/") || "替代"}份额，适合按持有期二选一。` : "",
      exposureAlternatives.length ? `已有同类替代：${alternativeLabel}，需要比较费率、规模和流动性。` : "",
      lowerCostAlternative ? "替代项里存在估算费用更低的选择，买入前应优先复核。" : ""
    ].filter(Boolean),
    risks: [
      fee.highDrag ? "当前份额费用拖累偏高，长期持有可能不划算。" : "",
      exposureAlternatives.length ? "同指数/同题材替代不是新的分散仓位，不能把多个壳当成多个机会。" : "",
      fee.missingCritical ? "当前基金费用/份额关键证据仍不完整。" : "",
      missingAlternativeFees ? "部分替代项缺费率或规模证据，不能直接切换。" : ""
    ].filter(Boolean),
    gaps: [
      shareAlternatives.length ? "" : "缺同基金 A/C/D/I 份额比较",
      exposureAlternatives.length ? "" : "缺同指数或同题材低费替代比较",
      missingAlternativeFees ? "替代项缺完整费率/规模" : ""
    ].filter(Boolean).slice(0, 3),
    nextStep: "买入前必须写清最终选择的代码和份额类别；同基金和同类替代只保留一个代表，不混买A/C，也不把同类替代当新增推荐名额。"
  };
}

function collectPortfolioReplacementShareClasses(alternatives = []) {
  return [...new Set((alternatives || [])
    .map((item) => String(item.shareClass || inferFundShareClass(item.name || "") || "").toUpperCase())
    .filter(Boolean))]
    .slice(0, 5);
}

function resolvePortfolioReplacementAlternativeCost(item = {}) {
  const direct = finiteMetricNumber(
    item.feeImpact?.oneYearCostPer10000
    ?? item.oneYearCostPer10000
    ?? item.oneYearCost
  );
  if (Number.isFinite(direct)) return direct;
  const text = [
    ...normalizeStringArray(item.feeNotes),
    item.reason,
    item.shareClassFeeModel?.selectionRule,
    item.shareClassFeeModel?.label
  ].filter(Boolean).join("；");
  const match = text.match(/(?:每\s*(?:1)?万(?:元)?|1年|一年)[^0-9]{0,12}(\d+(?:\.\d+)?)\s*元/)
    || text.match(/(\d+(?:\.\d+)?)\s*元[^，。；]{0,12}(?:每\s*(?:1)?万|1年|一年)/);
  return match ? finiteMetricNumber(match[1]) : null;
}

function formatPortfolioReplacementAlternativeLabel(shareAlternatives = [], exposureAlternatives = []) {
  const items = [...shareAlternatives, ...exposureAlternatives]
    .map((item) => `${item.code || ""} ${item.name || ""}${item.shareClass ? ` ${item.shareClass}类` : ""}`.trim())
    .filter(Boolean)
    .slice(0, 3);
  return items.join(" / ") || "替代项";
}

function buildPortfolioReplacementChoiceReason({ shareAlternatives = [], exposureAlternatives = [], lowerCostAlternative = false, fee = {} } = {}) {
  if (lowerCostAlternative) return "同基金或同类替代里出现可能更低费率的选择，买入前应先选对产品壳和份额。";
  if (fee.highDrag) return "当前份额费用拖累偏高，需要比较替代份额或同类低费产品后再买。";
  if (shareAlternatives.length && exposureAlternatives.length) return "同时存在同基金份额和同类替代，必须先做优选，不能把替代项拆成多个推荐名额。";
  if (shareAlternatives.length) return "存在同基金不同份额，必须按持有期和费用选择A/C/D/I之一，避免混买。";
  if (exposureAlternatives.length) return "存在同指数或同题材替代，需要比较费率、规模、流动性和渠道后只保留一个代表。";
  return "替代选择证据不足，买入前仍需补齐同类比较。";
}

function buildPortfolioOpportunityCostRanking(db = {}, watchlist = []) {
  const account = db.account || {};
  const totalAsset = Number(account.totalAsset || 0);
  const transactions = getPortfolioDiagnosticTransactions(db);
  const orders = getPortfolioDiagnosticOrders(db);
  const candidates = mergePortfolioBacktestOpportunityCandidates(
    findPortfolioBacktestMissedFollowThroughCandidates({
      watchlist,
      transactions,
      orders,
      totalAsset
    }),
    findPortfolioBacktestMissedThemeMomentumCandidates({
      watchlist,
      transactions,
      orders,
      totalAsset
    })
  );
  const items = candidates.map((candidate) => buildPortfolioRankingItem({
    code: candidate.code,
    name: candidate.name,
    source: candidate.opportunityKind === "theme_momentum" ? "主力预热回测" : "历史回测",
    score: round(
      Number(candidate.readinessScore || 0)
      + Number(candidate.followThroughPct || 0) * 5
      + Math.min(30, Number(candidate.estimatedStarterOpportunity || 0) / 10),
      1
    ),
    action: candidate.opportunityKind === "theme_momentum" ? "主力预热机会成本复核" : "机会成本复核",
    reason: candidate.estimatedStarterOpportunity
      ? candidate.opportunityKind === "theme_momentum"
        ? `主力/预热和新闻逻辑出现后仍被当观察，按1.2%微型试探估算少赚约${round(candidate.estimatedStarterOpportunity, 2)}元。`
        : `等待后继续走强，按2.5%试探仓估算少赚约${round(candidate.estimatedStarterOpportunity, 2)}元。`
      : candidate.opportunityKind === "theme_momentum"
        ? "主力/预热和新闻逻辑出现后仍被当观察，需要复核是否错过微型试探。"
        : "等待后继续走强，需要复核是不是过度保守。",
    facts: [
      candidate.themeEvidence || "",
      candidate.newsLogic ? `新闻逻辑${shortenPortfolioCustomerText(candidate.newsLogic, 58)}` : "",
      candidate.evidence || "",
      Number.isFinite(Number(candidate.followThroughPct)) ? `后续走强${formatFallbackPlainPct(candidate.followThroughPct)}` : "",
      Number.isFinite(Number(candidate.readinessScore)) ? `准备度${round(Number(candidate.readinessScore), 0)}` : ""
    ].filter(Boolean),
    decision: {
      highlights: [
        candidate.opportunityKind === "theme_momentum" ? `${candidate.themeName || "相关题材"}出现主力/预热和新闻逻辑。` : "",
        candidate.evidence || "等待后继续走强"
      ].filter(Boolean),
      risks: ["不能追涨补票，要复核当时买点是否仍有效。"],
      gaps: normalizeStringArray(candidate.readinessGaps).slice(0, 2),
      nextStep: candidate.opportunityKind === "theme_momentum"
        ? "下一次今日操作必须给0.5%-1.2%微型试探、主动降级或明确复查时间。"
        : "下一次今日操作必须给小仓试探、主动降级或明确复查时间。"
    },
    status: "warning"
  })).sort(compareRankingItems).slice(0, 6);
  return buildPortfolioRankingList({
    id: "opportunity_cost",
    title: "机会成本榜",
    subtitle: "找出之前接近买点但没执行、随后继续走强的候选，防止经理只会等待。",
    emptyText: "暂无等待后继续走强的可执行候选。",
    nextAction: "下一步对接近买点但未执行的基金做复盘：小仓试探、主动降级、或写明下一次触发时间。",
    items
  });
}

