function buildThemeRadar({ conceptBoards = [], industryBoards = [], preciousMetals = [], globalMarkets = [], fastNews = [], fundCandidates = {} } = {}) {
  const allFunds = [
    ...(fundCandidates.stockFunds || []),
    ...(fundCandidates.hybridFunds || []),
    ...(fundCandidates.indexFunds || []),
    ...(fundCandidates.qdiiFunds || []),
    ...(fundCandidates.preciousMetalFunds || [])
  ];
  const rules = [
    ...THEME_RADAR_RULES,
    ...buildDynamicThemeRadarRules({ conceptBoards, industryBoards, fastNews, allFunds })
  ];
  const themes = rules.map((rule) => {
    const boards = selectThemeBoardEvidence([...conceptBoards, ...industryBoards], rule.keywords)
      .slice(0, 5)
      .map((board) => ({
        name: board.name || board.boardCode || "",
        boardCode: board.boardCode || "",
        changePct: board.changePct,
        mainNetInflowPct: board.mainNetInflowPct,
        leadStock: board.leadStock || "",
        quoteTime: board.quoteTime || "",
        coverageSources: Array.isArray(board.coverageSources) ? board.coverageSources.slice(0, 4) : [],
        rankSignals: Array.isArray(board.rankSignals) ? board.rankSignals.slice(0, 4) : []
      }));
    const newsKeywords = expandThemeNewsKeywords(rule.newsKeywords || rule.keywords, {
      name: rule.name,
      leadStock: rule.leadStock || ""
    });
    const news = fastNews
      .filter((item) => textMatchesKeywords(`${item.title || ""} ${item.mediaName || ""}`, newsKeywords))
      .slice(0, 5)
      .map((item) => ({
        title: item.title || "",
        showTime: item.showTime || "",
        mediaName: item.mediaName || "",
        url: item.url || ""
      }));
    const funds = allFunds
      .filter((fund) => textMatchesKeywords(`${fund.name || ""} ${fund.type || ""} ${(fund.keywords || []).join(" ")}`, rule.fundKeywords || rule.keywords))
      .slice(0, 6)
      .map((fund) => ({
        code: fund.code || "",
        name: fund.name || "",
        type: fund.type || "",
        oneMonthPct: fund.oneMonthPct,
        oneYearPct: fund.oneYearPct,
        dailyPct: fund.dailyPct,
        shareClass: fund.shareClass || ""
      }));
    const metals = rule.id === "precious_metals"
      ? preciousMetals.slice(0, 6).map((item) => ({
          name: item.name || item.code || "",
          latest: item.latest,
          changePct: item.changePct,
          fiveDayPct: item.fiveDayPct,
          quoteTime: item.quoteTime || ""
        }))
      : [];
    const overseasMarkets = rule.id === "overseas_us" || rule.id === "hongkong"
      ? globalMarkets
          .filter((item) => textMatchesKeywords(`${item.name || ""} ${item.code || ""}`, rule.keywords))
          .slice(0, 6)
          .map((item) => ({
            name: item.name || item.code || "",
            latest: item.latest,
            changePct: item.changePct,
            fiveDayPct: item.fiveDayPct,
            quoteTime: item.quoteTime || ""
          }))
      : [];
    const marketEvidenceCoverageCount = boards.length + news.length + metals.length + overseasMarkets.length;
    const evidenceCoverageCount = marketEvidenceCoverageCount + funds.length;

    const newsCatalystProfile = buildNewsCatalystProfile(news, { ...rule, keywords: newsKeywords });
    const newsMainCapitalScore = scoreNewsMainCapitalConfirmation(newsCatalystProfile, news);
    const boardFlowValues = boards.map((item) => Number(item.mainNetInflowPct)).filter(Number.isFinite);
    const boardChangeValues = boards.map((item) => Number(item.changePct)).filter(Number.isFinite);
    const boardOutflowCount = boardFlowValues.filter((value) => value < 0).length;
    const boardDeclineCount = boardChangeValues.filter((value) => value < 0).length;
    const boardPositiveFlowCount = boardFlowValues.filter((value) => value > 0).length;
    const boardRisingCount = boardChangeValues.filter((value) => value > 0).length;
    const boardModerateRiseCount = boardChangeValues.filter((value) => value >= 0 && value <= 4.5).length;
    const mainInflowRankScore = scoreThemeBoardRankSignals(boards, /主力流入/);
    const mainOutflowRankScore = scoreThemeBoardRankSignals(boards, /主力流出/);
    const avgMainNetInflowPct = boardFlowValues.length ? averageNumeric(boardFlowValues) : null;
    const minMainNetInflowPct = boardFlowValues.length ? Math.min(...boardFlowValues) : null;
    const maxMainNetInflowPct = boardFlowValues.length ? Math.max(...boardFlowValues) : null;
    const maxBoardDropPct = boardChangeValues.length ? Math.min(0, ...boardChangeValues) : 0;
    const avgOutflow = Number.isFinite(avgMainNetInflowPct) ? Math.max(0, -avgMainNetInflowPct) : 0;
    const maxOutflow = Number.isFinite(minMainNetInflowPct) ? Math.max(0, -minMainNetInflowPct) : 0;
    const avgInflow = Number.isFinite(avgMainNetInflowPct) ? Math.max(0, avgMainNetInflowPct) : 0;
    const maxInflow = Number.isFinite(maxMainNetInflowPct) ? Math.max(0, maxMainNetInflowPct) : 0;
    const capitalRetreatScore = clampScore(
      boardOutflowCount * 12
      + boardDeclineCount * 8
      + avgOutflow * 12
      + maxOutflow * 6
      + Math.abs(maxBoardDropPct) * 8
      + mainOutflowRankScore * 0.7
    );
    const freshNewsCount = newsCatalystProfile.fresh === false ? 0 : news.length;
    const catalystScore = clampScore(freshNewsCount * 6 + newsCatalystProfile.score + metals.filter((item) => Number.isFinite(item.changePct)).length * 4 + overseasMarkets.filter((item) => Number.isFinite(item.changePct)).length * 3);
    const newsOnlyPreheatBoost = rule.newsDiscovered && freshNewsCount > 0 && !newsCatalystProfile.risk
      ? Math.min(18, Number(newsCatalystProfile.score || 0) * 0.35 + freshNewsCount * 4)
      : 0;
    const boardScore = clampScore(
      boards.reduce((sum, item) => sum + Math.max(0, Number(item.changePct || 0)) * 4 + Math.max(0, Number(item.mainNetInflowPct || 0)) / 8, 0)
      - capitalRetreatScore * 0.35
    );
    const vehicleScore = clampScore(funds.length * 5);
    const maxBoardChange = Math.max(0, ...boards.map((item) => Number(item.changePct || 0)));
    const fundOneMonthReturns = funds.map((item) => Number(item.oneMonthPct)).filter(Number.isFinite);
    const maxFundOneMonth = Math.max(0, ...fundOneMonthReturns);
    const avgFundOneMonth = averageNumeric(fundOneMonthReturns);
    const metalFiveDay = Math.max(0, ...metals.map((item) => Number(item.fiveDayPct || 0)));
    const overseasFiveDay = Math.max(0, ...overseasMarkets.map((item) => Number(item.fiveDayPct || 0)));
    const overseasDaily = Math.max(0, ...overseasMarkets.map((item) => Number(item.changePct || 0)));
    const crowdingScore = clampScore(Math.max(0, maxBoardChange - 3) * 9 + Math.max(0, maxFundOneMonth - 15) * 1.2 + Math.max(0, metalFiveDay - 4) * 5 + Math.max(0, overseasFiveDay - 5) * 4);
    const lowPositionScore = clampScore(
      Math.max(0, 18 - maxFundOneMonth) * 2.4
      + Math.max(0, 8 - Math.max(0, avgFundOneMonth)) * 1.4
      + Math.max(0, 4 - maxBoardChange) * 4
      + Math.max(0, 5 - metalFiveDay) * 2
      + Math.max(0, 3 - overseasDaily) * 2
    );
    const capitalFollowScore = clampScore(
      boardPositiveFlowCount * 10
      + boardRisingCount * 4
      + avgInflow * 10
      + maxInflow * 5
      + mainInflowRankScore * 1.25
      + (hasStrongMainInflowRankSignal(mainInflowRankScore) ? 12 : 0)
      + newsMainCapitalScore
      + catalystScore * 0.16
      + vehicleScore * 0.14
      + Math.max(0, 5 - maxBoardChange) * 2
      - crowdingScore * 0.28
      - capitalRetreatScore * 0.52
      - Math.max(0, maxBoardChange - 6) * 7
    );
    const preheatScore = clampScore(
      catalystScore * 0.55
      + lowPositionScore * 0.34
      + vehicleScore * 0.22
      + boardModerateRiseCount * 8
      + Math.max(0, 18 - boardScore) * 0.32
      + capitalFollowScore * 0.12
      + mainInflowRankScore * 0.12
      + newsMainCapitalScore * 0.25
      + newsOnlyPreheatBoost
      - crowdingScore * 0.46
      - capitalRetreatScore * 0.42
    );
    const rotationScore = clampScore(
      catalystScore * 0.35
      + vehicleScore * 0.25
      + lowPositionScore * 0.45
      + capitalFollowScore * 0.12
      + preheatScore * 0.1
      + newsOnlyPreheatBoost * 0.18
      + Math.max(0, 28 - boardScore) * 0.25
      - crowdingScore * 0.25
      - capitalRetreatScore * 0.22
    );
    const forwardScore = clampScore(
      catalystScore * 0.32
      + boardScore * 0.28
      + vehicleScore * 0.16
      + rotationScore * 0.16
      + capitalFollowScore * 0.2
      + preheatScore * 0.16
      + newsMainCapitalScore * 0.16
      + newsOnlyPreheatBoost * 0.12
      - crowdingScore * 0.36
      - capitalRetreatScore * 0.32
    );
    const retreatSignal = inferThemeRetreatSignal({ capitalRetreatScore, avgMainNetInflowPct, minMainNetInflowPct, boardOutflowCount, boardDeclineCount, forwardScore, rotationScore });
    const stage = retreatSignal
      ? "theme_fading"
      : inferThemeStage({ catalystScore, boardScore, vehicleScore, crowdingScore, rotationScore, lowPositionScore, capitalFollowScore, preheatScore, avgMainNetInflowPct, maxMainNetInflowPct, mainInflowRankScore });
    const leaderSignal = inferThemeLeaderSignal({ retreatSignal, stage, capitalFollowScore, preheatScore, forwardScore, crowdingScore, avgMainNetInflowPct, maxMainNetInflowPct, mainInflowRankScore });
    const actionBias = retreatSignal
      ? "avoid_until_capital_returns"
      : inferThemeActionBias({ stage, forwardScore, crowdingScore, rotationScore, lowPositionScore, capitalFollowScore, preheatScore });
    const positionSignal = retreatSignal
      ? "capital_outflow_watch"
      : inferThemePositionSignal({ crowdingScore, rotationScore, lowPositionScore, maxFundOneMonth, maxBoardChange, capitalFollowScore, preheatScore, mainInflowRankScore });
    const newsLogic = buildThemeCatalystLogic({
      rule,
      news,
      boards,
      metals,
      overseasMarkets,
      leaderSignal,
      avgMainNetInflowPct,
      maxMainNetInflowPct,
      minMainNetInflowPct,
      newsCatalystProfile
    });

    return {
      id: rule.id,
      name: rule.name,
      keywords: rule.keywords,
      newsKeywords,
      fundKeywords: rule.fundKeywords || rule.keywords,
      dynamic: Boolean(rule.dynamic),
      newsDiscovered: Boolean(rule.newsDiscovered),
      stage,
      forwardScore: round(forwardScore, 1),
      catalystScore: round(catalystScore, 1),
      newsMainCapitalScore: round(newsMainCapitalScore, 1),
      marketConfirmationScore: round(boardScore, 1),
      vehicleScore: round(vehicleScore, 1),
      crowdingScore: round(crowdingScore, 1),
      rotationScore: round(rotationScore, 1),
      lowPositionScore: round(lowPositionScore, 1),
      capitalRetreatScore: round(capitalRetreatScore, 1),
      capitalFollowScore: round(capitalFollowScore, 1),
      preheatScore: round(preheatScore, 1),
      catalystProfile: newsCatalystProfile,
      avgMainNetInflowPct: Number.isFinite(avgMainNetInflowPct) ? round(avgMainNetInflowPct, 2) : null,
      minMainNetInflowPct: Number.isFinite(minMainNetInflowPct) ? round(minMainNetInflowPct, 2) : null,
      maxMainNetInflowPct: Number.isFinite(maxMainNetInflowPct) ? round(maxMainNetInflowPct, 2) : null,
      boardOutflowCount,
      boardDeclineCount,
      boardPositiveFlowCount,
      boardRisingCount,
      marketEvidenceCoverageCount,
      evidenceCoverageCount,
      mainInflowRankScore: round(mainInflowRankScore, 1),
      mainOutflowRankScore: round(mainOutflowRankScore, 1),
      maxBoardDropPct: round(maxBoardDropPct, 2),
      retreatSignal,
      leaderSignal,
      positionSignal,
      actionBias,
      newsLogic,
      primaryCatalyst: news[0]?.title || boards[0]?.name || metals[0]?.name || overseasMarkets[0]?.name || "",
      evidence: { news, boards, metals, globalMarkets: overseasMarkets, funds }
    };
  }).filter((theme) =>
    Number(theme.marketEvidenceCoverageCount || 0) > 0
    && (
      theme.forwardScore >= 8
      || theme.catalystScore >= 12
      || theme.marketConfirmationScore >= 12
      || theme.vehicleScore >= 10
      || theme.capitalRetreatScore >= 50
      || theme.capitalFollowScore >= 38
      || theme.preheatScore >= 42
    )
  );

  return selectThemeRadarThemes(themes, Number(process.env.MARKET_THEME_RADAR_LIMIT || 12));
}

function scoreThemeRadarPriority(theme = {}) {
  return Number(theme.forwardScore || 0)
    + Math.max(0, Number(theme.capitalRetreatScore || 0) - 45) * 1.25
    + Number(theme.capitalFollowScore || 0) * 0.2
    + Number(theme.preheatScore || 0) * 0.16
    + Number(theme.crowdingScore || 0) * 0.12;
}

function selectThemeRadarThemes(themes = [], limit = 12) {
  const max = Math.max(1, Number(limit || 12));
  const sorted = [...(themes || [])].filter(Boolean).sort((a, b) => scoreThemeRadarPriority(b) - scoreThemeRadarPriority(a));
  const selected = [];
  const seen = new Set();
  const addLane = (filter, laneLimit) => {
    let added = 0;
    for (const theme of sorted.filter(filter)) {
      const key = normalizeIntentText(theme.id || theme.name || "");
      if (!key || seen.has(key)) continue;
      selected.push(theme);
      seen.add(key);
      added += 1;
      if (selected.length >= max || added >= laneLimit) break;
    }
  };
  addLane(isThemeRadarMainCapitalOpportunity, 4);
  addLane(isThemeRadarPreheatOpportunity, 4);
  addLane(isThemeRadarLowRotationOpportunity, 3);
  addLane(isThemeRadarRiskLane, 3);
  addLane(() => true, max);
  return selected.slice(0, max);
}

function isThemeRadarMainCapitalOpportunity(theme = {}) {
  return !isThemeRadarRiskLane(theme)
    && hasTraceableFreshThemeCatalystContext(theme)
    && hasPositiveThemeMainCapitalEvidence(theme)
    && (
      theme.leaderSignal === "capital_entering"
      || theme.positionSignal === "main_capital_entering"
      || Number(theme.capitalFollowScore || 0) >= 58
    );
}

function isThemeRadarPreheatOpportunity(theme = {}) {
  return !isThemeRadarRiskLane(theme)
    && !hasConflictingThemeCapitalOutflow(theme)
    && hasTraceableFreshThemeCatalystContext(theme)
    && (
      theme.leaderSignal === "preheat_catalyst"
      || theme.positionSignal === "preheat_catalyst_watch"
      || Number(theme.preheatScore || 0) >= 52
    );
}

function isThemeRadarLowRotationOpportunity(theme = {}) {
  return !isThemeRadarRiskLane(theme) && hasUsableThemeLowRotationSupport(theme, {
    minRotation: 45,
    minLowPosition: 45
  });
}

function isThemeRadarRiskLane(theme = {}) {
  return hasThemeCapitalRetreatRisk(theme)
    || isStaleThemeCatchdownRiskTheme(theme)
    || theme.positionSignal === "high_chase_risk"
    || theme.stage === "crowded"
    || Number(theme.crowdingScore || 0) >= 55;
}

function buildThemeLeaderboards(themeRadar = []) {
  const themes = Array.isArray(themeRadar) ? themeRadar.filter(Boolean) : [];
  const hasRetreatOrCatchdownRisk = (theme) => hasThemeCapitalRetreatRisk(theme) || isStaleThemeCatchdownRiskTheme(theme);
  const notRetreat = (theme) => !hasRetreatOrCatchdownRisk(theme);
  const notCrowded = (theme) => theme.positionSignal !== "high_chase_risk" && theme.stage !== "crowded" && Number(theme.crowdingScore) < 55;
  const makeLane = ({ id, title, subtitle, filter, score, reason }) => ({
    id,
    title,
    subtitle,
    items: themes
      .filter(filter)
      .sort((a, b) => score(b) - score(a))
      .slice(0, 5)
      .map((theme) => compactThemeLeaderboardItem(theme, reason(theme), round(score(theme), 1)))
  });
  return {
    mainCapital: makeLane({
      id: "main_capital",
      title: "主力进场榜",
      subtitle: "资金开始配合、但拥挤度还没失控的方向。",
      filter: (theme) => notRetreat(theme) && notCrowded(theme) && hasTraceableFreshThemeCatalystContext(theme) && hasPositiveThemeMainCapitalEvidence(theme) && (
        theme.leaderSignal === "capital_entering"
        || theme.positionSignal === "main_capital_entering"
        || Number(theme.capitalFollowScore) >= 58
      ),
      score: (theme) => Number(theme.capitalFollowScore || 0) + Number(theme.forwardScore || 0) * 0.35 + Number(theme.catalystProfile?.score || 0) * 0.35,
      reason: (theme) => theme.newsLogic ? "主力资金和题材逻辑同时出现" : "主力资金开始配合，等待新闻逻辑补齐"
    }),
    preheat: makeLane({
      id: "preheat",
      title: "题材预热榜",
      subtitle: "有政策、产业或外盘催化，但还没有明显涨开的方向。",
      filter: (theme) => notRetreat(theme) && notCrowded(theme) && !hasConflictingThemeCapitalOutflow(theme) && hasTraceableFreshThemeCatalystContext(theme) && (
        theme.leaderSignal === "preheat_catalyst"
        || theme.positionSignal === "preheat_catalyst_watch"
        || Number(theme.preheatScore) >= 52
      ),
      score: (theme) => Number(theme.preheatScore || 0) + Number(theme.catalystProfile?.score || 0) * 0.45 + Number(theme.lowPositionScore || 0) * 0.22,
      reason: (theme) => theme.catalystProfile?.summary ? `催化清晰：${theme.catalystProfile.summary}` : "预热线索出现，等待催化确认"
    }),
    lowRotation: makeLane({
      id: "low_rotation",
      title: "低位轮动榜",
      subtitle: "位置较低、轮动评分改善，适合进入小仓试探复核的方向。",
      filter: (theme) => notRetreat(theme) && notCrowded(theme) && hasUsableThemeLowRotationSupport(theme, {
        minRotation: 45,
        minLowPosition: 45
      }),
      score: (theme) => Number(theme.rotationScore || 0) + Number(theme.lowPositionScore || 0) * 0.75 + Number(theme.capitalFollowScore || 0) * 0.18,
      reason: () => "低位和轮动证据同时改善"
    }),
    retreat: makeLane({
      id: "retreat",
      title: "退潮回避榜",
      subtitle: "主力流出或板块转弱，回调不能当买点。",
      filter: (theme) => hasRetreatOrCatchdownRisk(theme),
      score: (theme) => Number(theme.capitalRetreatScore || 0) + Math.max(0, -Number(theme.avgMainNetInflowPct || 0)) * 10 + (isStaleThemeCatchdownRiskTheme(theme) ? 18 : 0),
      reason: (theme) => isStaleThemeCatchdownRiskTheme(theme)
        ? "缺少新催化且资金边际转弱，回调按接盘风险处理"
        : "主力撤离或题材退潮，先等资金回流"
    }),
    chaseRisk: makeLane({
      id: "chase_risk",
      title: "追涨风险榜",
      subtitle: "涨幅、拥挤度或位置已经偏热，不能被新闻牵着追。",
      filter: (theme) => theme.positionSignal === "high_chase_risk" || theme.stage === "crowded" || Number(theme.crowdingScore) >= 55,
      score: (theme) => Number(theme.crowdingScore || 0) + Math.max(0, Number(theme.marketConfirmationScore || 0) - 35) * 0.5,
      reason: () => "热度偏高，优先等回撤或降温"
    })
  };
}

function buildThemeMainForcePlaybook(themeRadar = [], leaderboards = null) {
  const radar = Array.isArray(themeRadar) ? themeRadar.filter(Boolean) : [];
  const boards = leaderboards || buildThemeLeaderboards(radar);
  const radarByKey = buildThemeRadarLookup(radar);
  const laneSpecs = [
    {
      id: "follow_main_capital",
      sourceKey: "mainCapital",
      title: "主力进场快跟",
      subtitle: "资金刚开始配合、新闻逻辑说得清，优先召回代表基金。",
      action: "立即找代表基金，小仓复核",
      tone: "buy"
    },
    {
      id: "preheat_watch",
      sourceKey: "preheat",
      title: "预热题材雷达",
      subtitle: "政策、订单、产业或外盘催化先出现，等资金和基金买点确认。",
      action: "先入观察，资金确认后微型试探",
      tone: "watch"
    },
    {
      id: "low_rotation",
      sourceKey: "lowRotation",
      title: "低位轮动备选",
      subtitle: "位置不高、轮动改善，适合找启动前夜的承载基金。",
      action: "找低位启动前夜",
      tone: "rotation"
    },
    {
      id: "avoid_catchdown",
      sourceKey: "retreat",
      title: "退潮接盘回避",
      subtitle: "主力撤离或旧催化退潮，回调不能当买点。",
      action: "先回避，等资金回流",
      tone: "sell"
    },
    {
      id: "avoid_chase",
      sourceKey: "chaseRisk",
      title: "追涨风险回避",
      subtitle: "已经涨开或拥挤，先等降温和健康回踩。",
      action: "不追，等回踩",
      tone: "chase"
    }
  ];
  const lanes = laneSpecs.map((spec) => {
    const items = (boards?.[spec.sourceKey]?.items || [])
      .map((item) => buildThemeMainForcePlaybookItem(item, findThemeRadarByLeaderboardItem(item, radarByKey), spec))
      .filter(Boolean)
      .slice(0, 4);
    return {
      id: spec.id,
      sourceKey: spec.sourceKey,
      title: spec.title,
      subtitle: spec.subtitle,
      action: spec.action,
      tone: spec.tone,
      items
    };
  });
  const opportunityCount = lanes
    .filter((lane) => ["follow_main_capital", "preheat_watch", "low_rotation"].includes(lane.id))
    .reduce((sum, lane) => sum + lane.items.length, 0);
  const riskCount = lanes
    .filter((lane) => ["avoid_catchdown", "avoid_chase"].includes(lane.id))
    .reduce((sum, lane) => sum + lane.items.length, 0);
  return {
    title: "主力题材作战图",
    summary: formatThemeMainForcePlaybookSummary({ opportunityCount, riskCount }),
    opportunityCount,
    riskCount,
    lanes,
    discipline: [
      "先看主力进场、预热催化和新闻时效，再找承载基金。",
      "代表基金必须用前十大持仓、指数名称或底层龙头证明承载题材。",
      "退潮和追涨方向即使回调，也先按0元观察处理。"
    ],
    source: "theme_main_force_playbook"
  };
}

function buildThemeRadarLookup(themeRadar = []) {
  const map = new Map();
  for (const theme of themeRadar || []) {
    for (const key of [theme?.id, theme?.name, ...(theme?.themeKeywords || []), ...(theme?.fundKeywords || [])]) {
      const normalized = normalizeIntentText(key);
      if (normalized && !map.has(normalized)) map.set(normalized, theme);
    }
  }
  return map;
}

function findThemeRadarByLeaderboardItem(item = {}, radarByKey = new Map()) {
  const keys = [item.id, item.name]
    .map((value) => normalizeIntentText(value))
    .filter(Boolean);
  for (const key of keys) {
    if (radarByKey.has(key)) return radarByKey.get(key);
  }
  for (const key of keys) {
    for (const [themeKey, theme] of radarByKey.entries()) {
      if (themeKey.includes(key) || key.includes(themeKey)) return theme;
    }
  }
  return null;
}

function buildThemeMainForcePlaybookItem(item = {}, theme = null, spec = {}) {
  const sourceTheme = theme || {};
  const name = item.name || sourceTheme.name || sourceTheme.id || "";
  if (!name) return null;
  const whyMove = item.whyMove || buildThemeLeaderboardWhyMove(sourceTheme) || item.newsLogic || item.reason || "";
  const catalyst = item.catalyst || sourceTheme.catalystProfile?.summary || "";
  const newsLogic = item.newsLogic || sourceTheme.newsLogic || item.primaryCatalyst || sourceTheme.primaryCatalyst || "";
  const capitalProof = formatThemeMainForceCapitalProof(sourceTheme);
  const carrierSearchKeywords = collectThemeOpportunitySearchKeywords(sourceTheme, {
    extra: [name, whyMove, newsLogic, catalyst, item.primaryCatalyst]
  }).slice(0, 12);
  const carrierAnchors = collectThemeOpportunityAnchorKeywords(sourceTheme, {
    extra: [name, item.primaryCatalyst]
  }).slice(0, 8);
  return {
    id: item.id || sourceTheme.id || "",
    name,
    laneKey: spec.sourceKey || "",
    laneTitle: spec.title || "",
    action: spec.action || item.action || "",
    score: finiteMetricNumber(item.score),
    whyMove: normalizePortfolioUserFacingText(whyMove),
    newsLogic: normalizePortfolioUserFacingText(newsLogic),
    catalyst,
    catalystFreshness: item.catalystFreshness || sourceTheme.catalystProfile?.freshnessLabel || "",
    capitalProof,
    carrierRule: "代表基金必须核验前十大持仓、指数名称或底层龙头是否承载该题材。",
    carrierSearchKeywords,
    carrierAnchors,
    nextStep: item.nextStep || buildThemeLeaderboardNextStep(sourceTheme),
    invalidation: item.invalidation || buildThemeLeaderboardInvalidation(sourceTheme),
    evidence: mergeStringLists(item.evidence, [
      capitalProof,
      catalyst ? `催化：${catalyst}` : "",
      sourceTheme.catalystProfile?.latestNewsTime ? `新闻时间：${sourceTheme.catalystProfile.latestNewsTime}` : ""
    ]).slice(0, 5),
    sourceType: item.sourceType || (sourceTheme.newsDiscovered ? "新闻自动发现" : sourceTheme.dynamic ? "动态题材雷达" : "题材雷达")
  };
}

function formatThemeMainForceCapitalProof(theme = {}) {
  const avgFlow = finiteMetricNumber(theme.avgMainNetInflowPct);
  const maxFlow = finiteMetricNumber(theme.maxMainNetInflowPct);
  const minFlow = finiteMetricNumber(theme.minMainNetInflowPct);
  if (Number.isFinite(avgFlow)) {
    if (avgFlow > 0.2) {
      return `主力资金均值净流入${formatFallbackPlainPct(avgFlow)}`;
    }
    if (avgFlow < -0.2) {
      return `主力资金均值净流出${formatFallbackPlainPct(Math.abs(avgFlow))}`;
    }
    return "主力资金均值接近平衡，仍需确认是否真正流入";
  }
  if (Number.isFinite(maxFlow) && maxFlow >= 1.5 && (!Number.isFinite(minFlow) || minFlow > -2)) {
    return `最强相关板块净流入${formatFallbackPlainPct(maxFlow)}`;
  }
  if (Number.isFinite(maxFlow) && maxFlow > 0.2) {
    return `最强相关板块小幅流入${formatFallbackPlainPct(maxFlow)}，尚未达到主力确认`;
  }
  if (Number.isFinite(minFlow) && minFlow <= -0.5) return `最弱相关板块净流出${formatFallbackPlainPct(Math.abs(minFlow))}`;
  if (Number.isFinite(minFlow) && minFlow < -0.2) return `最弱相关板块小幅流出${formatFallbackPlainPct(Math.abs(minFlow))}，继续观察`;
  if (hasStrongMainInflowRankSignal(theme.mainInflowRankScore)) return "进入主力流入榜";
  if (hasNewsMainCapitalEvidence(theme)) return "新闻提示资金抢筹";
  return "主力资金仍需复核";
}

function formatThemeMainForcePlaybookSummary({ opportunityCount = 0, riskCount = 0 } = {}) {
  if (opportunityCount && riskCount) {
    return `本轮先跟随${opportunityCount}条主力/预热/低位轮动线索，同时回避${riskCount}条退潮或追涨风险。`;
  }
  if (opportunityCount) return `本轮发现${opportunityCount}条可继续找代表基金的主力/预热/低位轮动线索。`;
  if (riskCount) return `本轮机会不足，先处理${riskCount}条退潮或追涨风险，避免把回调当买点。`;
  return "本轮暂未形成可执行题材线索，具体基金只能待复核。";
}

function collectThemeMainForcePlaybookOpportunityItems(marketSnapshot = null) {
  const playbook = marketSnapshot?.themeMainForcePlaybook
    || buildThemeMainForcePlaybook(marketSnapshot?.themeRadar || [], marketSnapshot?.themeLeaderboards || null);
  return (playbook?.lanes || [])
    .filter((lane) => ["follow_main_capital", "preheat_watch", "low_rotation"].includes(lane.id))
    .flatMap((lane) => (lane.items || []).map((item) => ({
      ...item,
      laneKey: item.laneKey || lane.sourceKey,
      title: lane.title,
      reason: item.whyMove || item.newsLogic || "",
      whyMove: item.whyMove || item.newsLogic || "",
      playbookAction: lane.action
    })));
}

function getMarketThemeMainForcePlaybook(marketSnapshot = null, themeRadar = []) {
  if (marketSnapshot?.themeMainForcePlaybook) return marketSnapshot.themeMainForcePlaybook;
  const radar = Array.isArray(themeRadar)
    ? themeRadar
    : Array.isArray(marketSnapshot?.themeRadar)
      ? marketSnapshot.themeRadar
      : [];
  if (!radar.length && !marketSnapshot?.themeLeaderboards) return null;
  return buildThemeMainForcePlaybook(radar, marketSnapshot?.themeLeaderboards || null);
}

function collectThemeMainForcePlaybookRiskItems(playbook = null) {
  return (playbook?.lanes || [])
    .filter((lane) => ["avoid_catchdown", "avoid_chase"].includes(lane.id))
    .flatMap((lane) => (lane.items || []).map((item) => ({
      ...item,
      laneId: lane.id,
      laneTitle: lane.title || item.laneTitle || "",
      laneAction: lane.action || item.action || ""
    })));
}

function collectThemeMainForcePlaybookOpportunityLaneItems(playbook = null) {
  return (playbook?.lanes || [])
    .filter((lane) => ["follow_main_capital", "preheat_watch", "low_rotation"].includes(lane.id))
    .flatMap((lane) => (lane.items || []).map((item) => ({
      ...item,
      laneId: lane.id,
      laneTitle: lane.title || item.laneTitle || "",
      laneAction: lane.action || item.action || ""
    })));
}

function attachThemeMainForcePlaybookOpportunity(candidate = {}, marketSnapshot = null, options = {}) {
  if (!candidate || typeof candidate !== "object") return candidate;
  const playbook = options.playbook || getMarketThemeMainForcePlaybook(marketSnapshot);
  const matches = matchCandidateThemeMainForceOpportunityItems(candidate, playbook);
  if (!matches.length) return candidate;
  const matchedThemes = mergeCandidateMatchedThemes(
    candidate.matchedThemes,
    candidate.seed?.matchedThemes,
    matches.map((match) => buildMatchedThemeSignalFromPlaybookOpportunityMatch(match, marketSnapshot))
  );
  const supportSignals = matches.map(formatThemeMainForcePlaybookOpportunitySupportSignal).filter(Boolean).slice(0, 3);
  const dataBasis = matches.flatMap((match) => {
    const item = match.item || {};
    return [
      `作战图机会：${item.name || item.id || "相关题材"} ${item.laneTitle || match.laneTitle || ""}`.trim(),
      item.capitalProof || "",
      item.catalyst ? `催化：${item.catalyst}` : "",
      normalizeStringArray(match.matchedTerms).length ? `命中承载锚点：${normalizeStringArray(match.matchedTerms).slice(0, 4).join("/")}` : ""
    ];
  }).filter(Boolean).slice(0, 6);
  const newsLogic = matches
    .map((match) => match.item?.whyMove || match.item?.newsLogic || match.item?.catalyst || "")
    .filter(Boolean)
    .map((text) => shortenPortfolioCustomerText(text, 96))
    .slice(0, 2)
    .join("；");
  const marketThemeRefresh = {
    ...(candidate.marketThemeRefresh && typeof candidate.marketThemeRefresh === "object" ? candidate.marketThemeRefresh : {}),
    source: candidate.marketThemeRefresh?.source || "theme_main_force_playbook_opportunity",
    refreshedAt: candidate.marketThemeRefresh?.refreshedAt || marketSnapshot?.fetchedAt || new Date().toISOString(),
    noCurrentThemeMatch: false,
    matchedThemeNames: matchedThemes.map((theme) => theme.name || theme.id).filter(Boolean).slice(0, 3),
    supportLabel: supportSignals[0] || candidate.marketThemeRefresh?.supportLabel || "",
    supportSignals: mergeStringLists(candidate.marketThemeRefresh?.supportSignals, supportSignals).slice(0, 3),
    newsLogic: [candidate.marketThemeRefresh?.newsLogic, newsLogic].filter(Boolean).join("；"),
    dataBasis: mergeStringLists(candidate.marketThemeRefresh?.dataBasis, dataBasis).slice(0, 8),
    playbookOpportunityMatches: matches.map(compactThemeMainForcePlaybookOpportunityMatch).filter(Boolean).slice(0, 3)
  };
  const next = {
    ...candidate,
    matchedThemes,
    playbookOpportunityMatches: marketThemeRefresh.playbookOpportunityMatches,
    marketThemeRefresh
  };
  if (candidate.seed && typeof candidate.seed === "object") {
    next.seed = {
      ...candidate.seed,
      matchedThemes,
      playbookOpportunityMatches: marketThemeRefresh.playbookOpportunityMatches,
      marketThemeRefresh: {
        ...(candidate.seed.marketThemeRefresh && typeof candidate.seed.marketThemeRefresh === "object" ? candidate.seed.marketThemeRefresh : {}),
        source: candidate.seed.marketThemeRefresh?.source || marketThemeRefresh.source,
        refreshedAt: candidate.seed.marketThemeRefresh?.refreshedAt || marketThemeRefresh.refreshedAt,
        noCurrentThemeMatch: false,
        matchedThemeNames: marketThemeRefresh.matchedThemeNames,
        supportLabel: marketThemeRefresh.supportLabel,
        supportSignals: marketThemeRefresh.supportSignals,
        newsLogic: marketThemeRefresh.newsLogic,
        dataBasis: marketThemeRefresh.dataBasis,
        playbookOpportunityMatches: marketThemeRefresh.playbookOpportunityMatches
      }
    };
  }
  return next;
}

function matchCandidateThemeMainForceOpportunityItems(candidate = {}, playbook = null) {
  if (!candidate || typeof candidate !== "object") return [];
  const opportunityItems = collectThemeMainForcePlaybookOpportunityLaneItems(playbook);
  if (!opportunityItems.length) return [];
  const candidateText = buildCandidateThemeMatchText(candidate);
  const normalizedCandidateText = normalizeIntentText(candidateText);
  const candidateTerms = collectCandidatePlaybookRiskTerms(candidate, candidateText);
  const holdings = collectCandidateHoldings(candidate, "equity");
  const matches = [];
  const seen = new Set();

  for (const item of opportunityItems) {
    const anchors = collectThemeMainForcePlaybookRiskAnchors(item);
    const terms = collectThemeMainForcePlaybookRiskTerms(item);
    const holdingMatches = holdings
      .filter((holding) => holdingMatchesThemeAnchors(holding, anchors))
      .map((holding) => holding.name || holding.code || holding.text)
      .filter(Boolean)
      .slice(0, 4);
    const directMatches = terms
      .filter((term) => {
        const value = normalizeIntentText(term);
        return value.length >= 2 && normalizedCandidateText.includes(value);
      })
      .slice(0, 4);
    const relatedMatches = terms
      .filter((term) => candidateTerms.some((candidateTerm) => areThemeTermsRelated(candidateTerm, term)))
      .slice(0, 4);
    const matchedTerms = mergeStringLists(holdingMatches, directMatches, relatedMatches).slice(0, 5);
    if (!matchedTerms.length) continue;
    const key = `${item.laneId}|${item.id || item.name}|${matchedTerms.join("/")}`;
    if (seen.has(key)) continue;
    seen.add(key);
    matches.push({
      item,
      laneId: item.laneId,
      laneTitle: item.laneTitle,
      holdingMatches,
      directMatches,
      relatedMatches,
      matchedTerms
    });
  }
  return matches.slice(0, 4);
}

function buildMatchedThemeSignalFromPlaybookOpportunityMatch(match = {}, marketSnapshot = null) {
  const item = match.item || {};
  const laneId = match.laneId || item.laneId || "";
  const laneMap = {
    follow_main_capital: {
      stage: "capital_entering",
      positionSignal: "main_capital_entering",
      leaderSignal: "capital_entering",
      actionBias: "follow_main_small",
      capitalFollowScore: 72,
      preheatScore: 58,
      rotationScore: 50,
      lowPositionScore: 54
    },
    preheat_watch: {
      stage: "preheat_catalyst",
      positionSignal: "preheat_catalyst_watch",
      leaderSignal: "preheat_catalyst",
      actionBias: "preheat_watch",
      capitalFollowScore: 56,
      preheatScore: 72,
      rotationScore: 50,
      lowPositionScore: 54
    },
    low_rotation: {
      stage: "low_position_rotation",
      positionSignal: "low_position_rotation",
      leaderSignal: "",
      actionBias: "low_rotation_probe",
      capitalFollowScore: 52,
      preheatScore: 50,
      rotationScore: 68,
      lowPositionScore: 68
    }
  };
  const spec = laneMap[laneId] || laneMap.preheat_watch;
  const latestNewsTime = extractThemeMainForcePlaybookNewsTime(item) || marketSnapshot?.fetchedAt || "";
  const catalystSummary = item.catalyst || item.catalystFreshness || shortenPortfolioCustomerText(item.whyMove || item.newsLogic || "主力题材作战图当前线索", 48);
  return compactMatchedThemeSignal({
    id: item.id || `playbook_${normalizeIntentText(item.name || laneId).replace(/\s+/g, "_")}`,
    name: item.name || item.id || "作战图机会",
    stage: spec.stage,
    positionSignal: spec.positionSignal,
    actionBias: spec.actionBias,
    leaderSignal: spec.leaderSignal,
    forwardScore: 62,
    crowdingScore: 18,
    rotationScore: spec.rotationScore,
    lowPositionScore: spec.lowPositionScore,
    capitalRetreatScore: 0,
    capitalFollowScore: spec.capitalFollowScore,
    preheatScore: spec.preheatScore,
    mainInflowRankScore: 18,
    avgMainNetInflowPct: /净流出|撤离/.test(item.capitalProof || "") ? 0 : 1.2,
    catalystProfile: {
      score: 34,
      tags: ["主力作战图", item.laneTitle || match.laneTitle || ""].filter(Boolean),
      summary: catalystSummary,
      risk: false,
      fresh: true,
      freshnessLabel: item.catalystFreshness || "作战图当前线索",
      latestNewsTime
    },
    primaryCatalyst: item.catalyst || item.whyMove || item.newsLogic || "",
    newsLogic: [
      "主力作战图机会",
      item.laneTitle || match.laneTitle || "",
      item.whyMove || item.newsLogic || item.catalyst || "",
      item.capitalProof || ""
    ].filter(Boolean).join("："),
    boardNames: normalizeStringArray(item.carrierSearchKeywords).slice(0, 4),
    leaderStocks: normalizeStringArray(item.carrierAnchors).slice(0, 4),
    themeKeywords: normalizeStringArray(item.carrierSearchKeywords).slice(0, 8)
  });
}

function formatThemeMainForcePlaybookOpportunitySupportSignal(match = {}) {
  const item = match.item || {};
  const name = item.name || item.id || "相关题材";
  const laneTitle = item.laneTitle || match.laneTitle || "主力作战图机会";
  const anchors = normalizeStringArray(match.matchedTerms).slice(0, 3).join("/");
  return [
    `${name}${laneTitle}`,
    item.capitalProof || "",
    anchors ? `承载锚点=${anchors}` : ""
  ].filter(Boolean).join("，");
}

function compactThemeMainForcePlaybookOpportunityMatch(match = {}) {
  const item = match.item || {};
  if (!item.name && !item.id) return null;
  return {
    laneId: match.laneId || "",
    laneTitle: item.laneTitle || match.laneTitle || "",
    name: item.name || item.id || "",
    capitalProof: item.capitalProof || "",
    matchedTerms: normalizeStringArray(match.matchedTerms).slice(0, 5),
    nextStep: item.nextStep || "",
    invalidation: item.invalidation || ""
  };
}

function extractThemeMainForcePlaybookNewsTime(item = {}) {
  const text = [
    item.catalystFreshness,
    item.whyMove,
    item.newsLogic,
    item.primaryCatalyst,
    normalizeStringArray(item.evidence).join(" ")
  ].filter(Boolean).join(" ");
  const explicit = text.match(/新闻时间[:：]\s*([0-9]{4}-[0-9]{2}-[0-9]{2}(?:[ T][0-9:.-]+Z?)?|[0-9]{1,2}:[0-9]{2})/);
  if (explicit) return explicit[1];
  const intraday = text.match(/([0-9]{1,2}:[0-9]{2})/);
  return intraday ? intraday[1] : "";
}

function attachThemeMainForcePlaybookRisk(candidate = {}, marketSnapshot = null, options = {}) {
  if (!candidate || typeof candidate !== "object") return candidate;
  const playbook = options.playbook || getMarketThemeMainForcePlaybook(marketSnapshot);
  const matches = matchCandidateThemeMainForceRiskItems(candidate, playbook);
  const warnings = mergeStringLists(
    getThemeMainForcePlaybookRiskWarnings(candidate),
    matches.map(formatThemeMainForcePlaybookRiskWarning)
  ).slice(0, 3);
  if (!warnings.length) return candidate;
  const compactMatches = matches.map(compactThemeMainForcePlaybookRiskMatch).filter(Boolean).slice(0, 3);
  const marketThemeRefresh = {
    ...(candidate.marketThemeRefresh && typeof candidate.marketThemeRefresh === "object" ? candidate.marketThemeRefresh : {}),
    source: candidate.marketThemeRefresh?.source || "theme_main_force_playbook_risk",
    refreshedAt: candidate.marketThemeRefresh?.refreshedAt || marketSnapshot?.fetchedAt || new Date().toISOString(),
    playbookRiskWarnings: warnings,
    playbookRiskMatches: compactMatches
  };
  const next = {
    ...candidate,
    playbookRiskWarnings: warnings,
    playbookRiskMatches: compactMatches,
    marketThemeRefresh
  };
  if (candidate.seed && typeof candidate.seed === "object") {
    next.seed = {
      ...candidate.seed,
      playbookRiskWarnings: warnings,
      playbookRiskMatches: compactMatches,
      marketThemeRefresh: {
        ...(candidate.seed.marketThemeRefresh && typeof candidate.seed.marketThemeRefresh === "object" ? candidate.seed.marketThemeRefresh : {}),
        playbookRiskWarnings: warnings,
        playbookRiskMatches: compactMatches
      }
    };
  }
  return next;
}

function matchCandidateThemeMainForceRiskItems(candidate = {}, playbook = null) {
  if (!candidate || typeof candidate !== "object") return [];
  const riskItems = collectThemeMainForcePlaybookRiskItems(playbook);
  if (!riskItems.length) return [];
  const candidateText = buildCandidateThemeMatchText(candidate);
  const normalizedCandidateText = normalizeIntentText(candidateText);
  const candidateTerms = collectCandidatePlaybookRiskTerms(candidate, candidateText);
  const holdings = collectCandidateHoldings(candidate, "equity");
  const matches = [];
  const seen = new Set();

  for (const item of riskItems) {
    const anchors = collectThemeMainForcePlaybookRiskAnchors(item);
    const terms = collectThemeMainForcePlaybookRiskTerms(item);
    const holdingMatches = holdings
      .filter((holding) => holdingMatchesThemeAnchors(holding, anchors))
      .map((holding) => holding.name || holding.code || holding.text)
      .filter(Boolean)
      .slice(0, 4);
    const directMatches = terms
      .filter((term) => {
        const value = normalizeIntentText(term);
        return value.length >= 2 && normalizedCandidateText.includes(value);
      })
      .slice(0, 4);
    const relatedMatches = terms
      .filter((term) => candidateTerms.some((candidateTerm) => areThemeTermsRelated(candidateTerm, term)))
      .slice(0, 4);
    const matchedTerms = mergeStringLists(holdingMatches, directMatches, relatedMatches).slice(0, 5);
    if (!matchedTerms.length) continue;
    const key = `${item.laneId}|${item.id || item.name}|${matchedTerms.join("/")}`;
    if (seen.has(key)) continue;
    seen.add(key);
    matches.push({
      item,
      laneId: item.laneId,
      laneTitle: item.laneTitle,
      holdingMatches,
      directMatches,
      relatedMatches,
      matchedTerms
    });
  }
  return matches.slice(0, 4);
}

function collectThemeMainForcePlaybookRiskAnchors(item = {}) {
  return mergeStringLists(
    normalizeStringArray(item.carrierAnchors),
    normalizeStringArray(item.carrierSearchKeywords),
    item.name,
    item.id
  )
    .flatMap((value) => String(value || "").split(/[，,、/；;+\s]+/))
    .map((value) => value.trim())
    .filter(isThemeMainForcePlaybookRiskTermUseful)
    .slice(0, 24);
}

function collectThemeMainForcePlaybookRiskTerms(item = {}) {
  return mergeStringLists(
    item.name,
    item.id,
    normalizeStringArray(item.carrierSearchKeywords),
    normalizeStringArray(item.carrierAnchors)
  )
    .flatMap((value) => String(value || "").split(/[，,、/；;+\s]+/))
    .map((value) => value.trim())
    .filter(isThemeMainForcePlaybookRiskTermUseful)
    .slice(0, 24);
}

function collectCandidatePlaybookRiskTerms(candidate = {}, candidateText = "") {
  const holdings = collectCandidateHoldings(candidate, "equity");
  const rawTerms = mergeStringLists(
    candidate.name,
    candidate.type,
    candidate.category,
    candidate.focusTheme,
    candidate.themeName,
    candidate.sector,
    candidate.industry,
    candidate.seed?.name,
    candidate.seed?.type,
    candidate.seed?.category,
    candidate.seed?.focusTheme,
    candidate.seed?.themeName,
    candidate.seed?.sector,
    candidate.seed?.industry,
    normalizeStringArray(candidate.keywords),
    normalizeStringArray(candidate.themeKeywords),
    normalizeStringArray(candidate.fundKeywords),
    normalizeStringArray(candidate.seed?.keywords),
    normalizeStringArray(candidate.seed?.themeKeywords),
    normalizeStringArray(candidate.seed?.fundKeywords),
    getPortfolioThemeSupportRequirement(candidate),
    inferHoldingThemeTags(candidateText),
    holdings.flatMap((holding) => [
      holding.name,
      holding.code,
      inferHoldingThemeTags(`${holding.code || ""} ${holding.name || ""} ${holding.text || ""}`)
    ])
  );
  return rawTerms
    .flatMap((value) => String(value || "").split(/[，,、/；;+\s]+/))
    .map((value) => value.trim())
    .filter(isCandidateThemeMainForceRiskTermUseful)
    .slice(0, 36);
}

function isThemeMainForcePlaybookRiskTermUseful(value = "") {
  const text = String(value || "").trim();
  if (text.length < 2 || text.length > 24) return false;
  if (/^(基金|代表基金|主题|板块|概念|行业|方向|逻辑|催化|新闻|预热|主力|资金|低位|轮动|回调|风险|回避|机会|测试|当前|相关题材)$/.test(text)) return false;
  if (/^(news|dynamic|theme|main|preheat|low|capital)[_-]/i.test(text)) return false;
  if (/^\d+(?:\.\d+)?%?$/.test(text)) return false;
  return true;
}

function isCandidateThemeMainForceRiskTermUseful(value = "") {
  if (!isThemeMainForcePlaybookRiskTermUseful(value)) return false;
  const text = String(value || "").trim();
  if (/^(科技|成长|创新|优选|精选|策略|量化|股票|混合|指数|联接|ETF|QDII)$/i.test(text)) return false;
  if (/科技/.test(text) && !/(人工智能|\bAI\b|算力|CPO|光模块|通信|云计算|信创|数字经济|大数据|软件|互联网|网络安全|半导体|芯片)/i.test(text)) return false;
  return isSpecificThemeTerm(text)
    || inferHoldingThemeTags(text).length > 0
    || Boolean(getPortfolioSectorThemeLabel(text));
}

function getThemeMainForcePlaybookRiskWarnings(candidate = {}) {
  if (!candidate || typeof candidate !== "object") return [];
  return mergeStringLists(
    normalizeStringArray(candidate.playbookRiskWarnings),
    normalizeStringArray(candidate.seed?.playbookRiskWarnings),
    normalizeStringArray(candidate.marketThemeRefresh?.playbookRiskWarnings),
    normalizeStringArray(candidate.seed?.marketThemeRefresh?.playbookRiskWarnings)
  ).slice(0, 3);
}

function formatThemeMainForcePlaybookRiskWarning(match = {}) {
  const item = match.item || {};
  const name = item.name || item.id || "相关题材";
  const laneTitle = item.laneTitle || match.laneTitle || (match.laneId === "avoid_chase" ? "追涨风险回避" : "退潮接盘回避");
  const proof = item.capitalProof || normalizeStringArray(item.evidence)[0] || "";
  const logic = item.whyMove || item.newsLogic || item.catalyst || "";
  const matched = normalizeStringArray(match.matchedTerms).slice(0, 4).join("/");
  const boundary = match.laneId === "avoid_chase"
    ? "不能把上涨热度当今天的买点，等降温和健康回踩后再复核。"
    : "回调先按接盘风险处理，等主力资金回流和新鲜催化重新出现后再复核。";
  return [
    `作战图风险：${name}已进入${laneTitle}`,
    proof ? `主力证据=${shortenPortfolioCustomerText(proof, 56)}` : "",
    matched ? `命中承载锚点=${matched}` : "",
    logic ? `逻辑=${shortenPortfolioCustomerText(logic, 72)}` : "",
    boundary
  ].filter(Boolean).join("；");
}

function compactThemeMainForcePlaybookRiskMatch(match = {}) {
  const item = match.item || {};
  if (!item.name && !item.id) return null;
  return {
    laneId: match.laneId || "",
    laneTitle: item.laneTitle || match.laneTitle || "",
    name: item.name || item.id || "",
    capitalProof: item.capitalProof || "",
    matchedTerms: normalizeStringArray(match.matchedTerms).slice(0, 5),
    nextStep: item.nextStep || "",
    invalidation: item.invalidation || ""
  };
}

async function fetchMarketFastNews() {
  const [eastmoney, sina, cls] = await Promise.all([
    fetchEastmoneyFastNews().catch((error) => ({ ok: false, label: "东方财富7x24快讯", error: error.message, items: [] })),
    fetchSinaFastNews().catch((error) => ({ ok: false, label: "新浪财经7x24快讯", error: error.message, items: [] })),
    fetchClsTelegraphNews().catch((error) => ({ ok: false, label: "财联社电报", error: error.message, items: [] }))
  ]);
  const sources = [eastmoney, sina, cls];
  const items = mergeFastNewsItems(eastmoney.items || [], sina.items || [], cls.items || [])
    .slice(0, Number(process.env.MARKET_FAST_NEWS_LIMIT || 30));
  const errors = sources
    .filter((source) => source && source.ok === false && source.error)
    .map((source) => `${source.label || "快讯源"}：${source.error}`);
  return {
    ok: items.length > 0 && sources.some((source) => source?.ok !== false),
    label: "实时财经新闻（东方财富+新浪+财联社）",
    items,
    sourceKinds: [...new Set(items.map((item) => item.sourceKind).filter(Boolean))],
    error: errors.join("；")
  };
}

async function fetchSinaFastNews() {
  const limit = Number(process.env.MARKET_FAST_NEWS_LIMIT || 30);
  const callback = `jsonp_sina_news_${Date.now()}_${Math.floor(Math.random() * 1000)}`;
  const url = new URL("https://zhibo.sina.com.cn/api/zhibo/feed");
  url.searchParams.set("callback", callback);
  url.searchParams.set("page", "1");
  url.searchParams.set("page_size", String(limit));
  url.searchParams.set("zhibo_id", "152");
  url.searchParams.set("tag_id", "0");
  url.searchParams.set("dire", "f");
  url.searchParams.set("dpc", "1");
  url.searchParams.set("_", String(Date.now()));
  const text = await fetchText(url.href, "https://finance.sina.com.cn/7x24/");
  const items = parseSinaFastNewsJsonp(text).slice(0, limit);
  updateStats({ counters: { sinaFastNewsFetches: 1 } });
  return {
    ok: items.length > 0,
    label: "新浪财经7x24快讯",
    items,
    sourceKinds: ["sina_finance_7x24_news"],
    error: items.length ? "" : "新浪财经快讯返回为空"
  };
}

function mergeFastNewsItems(...groups) {
  const seen = new Set();
  return groups.flat().filter((item) => {
    const title = normalizeIntentText(item?.title || "");
    if (!title || seen.has(title)) return false;
    seen.add(title);
    return true;
  });
}

async function fetchClsTelegraphNews() {
  const limit = Number(process.env.MARKET_FAST_NEWS_LIMIT || 30);
  const text = await fetchText("https://m.cls.cn/telegraph", "https://www.cls.cn/telegraph");
  const items = parseClsTelegraphHtml(text).slice(0, limit);
  updateStats({ counters: { clsTelegraphNewsFetches: 1 } });
  return {
    ok: items.length > 0,
    label: "财联社电报",
    items,
    sourceKinds: ["cls_telegraph_news"],
    error: items.length ? "" : "财联社电报返回为空"
  };
}

function parseClsTelegraphHtml(text = "") {
  const source = String(text || "");
  const items = [];
  const addItem = (title, showTime = "", url = "") => {
    const cleaned = decodeHtmlEntitiesBasic(String(title || ""))
      .replace(/<[^>]+>/g, " ")
      .replace(/\s+/g, " ")
      .trim();
    if (!cleaned || cleaned.length < 6 || /^财联社(?:电报|快讯)?$/.test(cleaned)) return;
    if (items.some((item) => normalizeIntentText(item.title) === normalizeIntentText(cleaned))) return;
    items.push({
      title: cleaned.slice(0, 180),
      showTime: String(showTime || "").trim(),
      mediaName: "财联社",
      url: String(url || "").trim(),
      sourceKind: "cls_telegraph_news"
    });
  };

  for (const match of source.matchAll(/"(?:title|brief|content)"\s*:\s*"([^"]{6,240})"[\s\S]{0,220}?"(?:ctime_text|show_time|time|created_at)"\s*:\s*"([^"]*)"/g)) {
    addItem(match[1], match[2]);
  }
  const plain = decodeHtmlEntitiesBasic(source)
    .replace(/<script[\s\S]*?<\/script>/gi, "\n")
    .replace(/<style[\s\S]*?<\/style>/gi, "\n")
    .replace(/<[^>]+>/g, "\n")
    .replace(/\r/g, "\n");
  for (const match of plain.matchAll(/(?:^|\n)\s*(\d{1,2}:\d{2})(?:\s*[【〖]([^】〗]{4,120})[】〗])?\s*([^\n]{8,220})/g)) {
    const headline = [match[2], match[3]].filter(Boolean).join(" ");
    addItem(headline, match[1]);
  }
  return items.slice(0, Number(process.env.MARKET_FAST_NEWS_LIMIT || 30));
}

function decodeHtmlEntitiesBasic(value = "") {
  return String(value || "")
    .replace(/\\u([0-9a-fA-F]{4})/g, (_, hex) => String.fromCharCode(parseInt(hex, 16)))
    .replace(/\\"/g, "\"")
    .replace(/&nbsp;/g, " ")
    .replace(/&amp;/g, "&")
    .replace(/&quot;/g, "\"")
    .replace(/&#39;/g, "'")
    .replace(/&lt;/g, "<")
    .replace(/&gt;/g, ">");
}

function compactThemeLeaderboardItem(theme = {}, reason = "", score = 0) {
  return {
    id: theme.id || "",
    name: theme.name || theme.id || "",
    score,
    reason,
    leader: formatUserFacingFundLabel(theme.leaderSignal || theme.positionSignal || ""),
    action: formatUserFacingFundLabel(theme.actionBias || ""),
    sourceType: theme.newsDiscovered ? "新闻自动发现" : theme.dynamic ? "动态题材雷达" : "预置题材雷达",
    catalyst: theme.catalystProfile?.summary || "",
    catalystFreshness: theme.catalystProfile?.freshnessLabel || "",
    newsLogic: theme.newsLogic || theme.primaryCatalyst || "",
    whyMove: buildThemeLeaderboardWhyMove(theme),
    primaryCatalyst: theme.primaryCatalyst || "",
    nextStep: buildThemeLeaderboardNextStep(theme),
    invalidation: buildThemeLeaderboardInvalidation(theme),
    evidence: buildThemeLeaderboardEvidenceChips(theme)
  };
}

function buildThemeLeaderboardWhyMove(theme = {}) {
  const logic = shortenPortfolioCustomerText(theme.newsLogic || theme.primaryCatalyst || "", 120);
  if (logic) return `为什么动：${logic}`;
  const catalyst = theme.catalystProfile?.summary || "";
  const flow = finiteMetricNumber(theme.avgMainNetInflowPct);
  const board = theme.evidence?.boards?.[0] || {};
  if (hasThemeCapitalRetreatRisk(theme)) {
    return "为什么回避：主力资金转弱或题材退潮，表面回调不能直接当买点。";
  }
  if (catalyst && Number.isFinite(flow)) {
    return `为什么动：${catalyst}，主力资金${flow >= 0 ? "净流入" : "净流出"}${formatFallbackPlainPct(Math.abs(flow))}。`;
  }
  if (catalyst) return `为什么动：${catalyst}。`;
  if (board.name) return `为什么动：${board.name}板块出现异动，仍需补新闻和资金证据。`;
  return "为什么动：等待新闻、资金和板块证据补齐。";
}

function buildThemeLeaderboardNextStep(theme = {}) {
  if (hasThemeCapitalRetreatRisk(theme)) return "不碰同题材回调，等资金重新回流和板块止跌后再复核。";
  if (theme.positionSignal === "high_chase_risk" || theme.stage === "crowded" || Number(theme.crowdingScore) >= 55) {
    return "先等降温和回踩，不把新闻热度当追涨理由。";
  }
  if (theme.leaderSignal === "capital_entering" || theme.positionSignal === "main_capital_entering") {
    return "找承载题材的代表基金，只有低位温和转强且费率/持仓过关时才做微型试探。";
  }
  if (theme.leaderSignal === "preheat_catalyst" || theme.positionSignal === "preheat_catalyst_watch") {
    if (hasPositiveThemeMainCapitalEvidence(theme)) {
      return "预热已有资金确认，立即找代表基金；只有低位温和转强、持仓承载和费率过关时才做0.5%-1.2%微型试探。";
    }
    return "先召回代表基金加入观察池，等新闻催化兑现、主力流入延续、基金走势转强后再进入试探。";
  }
  if (theme.positionSignal === "low_position_rotation" || theme.stage === "low_position_rotation") {
    return "从代表基金里筛低位启动前夜，补齐前十大持仓和费用后再小仓。";
  }
  return "继续观察题材与代表基金是否形成同向证据。";
}

function buildThemeLeaderboardInvalidation(theme = {}) {
  if (hasThemeCapitalRetreatRisk(theme)) return "失效条件：资金重新净流入、跌幅收敛且新闻逻辑重新转强。";
  if (theme.positionSignal === "high_chase_risk" || theme.stage === "crowded" || Number(theme.crowdingScore) >= 55) {
    return "失效条件：涨幅降温、拥挤度下降且代表基金出现健康回踩。";
  }
  if (theme.leaderSignal === "capital_entering" || theme.positionSignal === "main_capital_entering") {
    return "失效条件：主力净流入转弱、龙头回落或新闻催化被证伪。";
  }
  if (theme.leaderSignal === "preheat_catalyst" || theme.positionSignal === "preheat_catalyst_watch") {
    return "失效条件：催化落空、资金没有继续跟进或代表基金先涨成追高。";
  }
  if (theme.positionSignal === "low_position_rotation" || theme.stage === "low_position_rotation") {
    return "失效条件：低位轮动失败、板块继续破位或基金买点迟迟不转强。";
  }
  return "失效条件：题材证据断裂或代表基金走势变弱。";
}

function buildThemeLeaderboardEvidenceChips(theme = {}) {
  const chips = [];
  const flow = Number(theme.avgMainNetInflowPct);
  const maxFlow = Number(theme.maxMainNetInflowPct);
  const retreat = Number(theme.capitalRetreatScore);
  const board = theme.evidence?.boards?.[0] || {};
  const news = theme.evidence?.news?.[0] || {};
  if (theme.newsDiscovered) chips.push("新闻自动发现");
  if (news.mediaName || news.showTime || news.title) {
    const sourceLine = [
      news.mediaName || "",
      news.showTime || news.time || "",
      news.title ? shortenPortfolioCustomerText(news.title, 24) : ""
    ].filter(Boolean).join(" ");
    chips.push(`新闻：${sourceLine}`);
  }
  if (Number.isFinite(flow)) {
    chips.push(flow >= 0 ? `主力净流入${formatFallbackPlainPct(flow)}` : `主力净流出${formatFallbackPlainPct(Math.abs(flow))}`);
  } else if (Number.isFinite(maxFlow) && maxFlow > 0) {
    chips.push(`最强板块净流入${formatFallbackPlainPct(maxFlow)}`);
  } else if (hasNewsMainCapitalEvidence(theme)) {
    chips.push("新闻提示资金抢筹");
  }
  if (theme.catalystProfile?.summary) chips.push(`催化：${theme.catalystProfile.summary}`);
  if (theme.catalystProfile?.freshnessLabel && theme.catalystProfile.fresh !== undefined) chips.push(theme.catalystProfile.freshnessLabel);
  if (board.name) chips.push(`板块：${board.name}${formatSignedNumber(board.changePct)}%`);
  if (theme.primaryCatalyst && !theme.catalystProfile?.summary) chips.push(shortenPortfolioCustomerText(theme.primaryCatalyst, 28));
  if (Number.isFinite(retreat) && retreat >= 45) chips.push("退潮风险高");
  return chips.filter(Boolean).slice(0, 4);
}

