function isGenericPullbackSetupRequest(text) {
  return isPullbackSetupRequest(text) && !inferFocusedFundSearchKeywords(text).length;
}

function scoreResearchDigestForPullbackSetup(digest = {}) {
  if (!digest?.ok) return -100;
  const trend = digest.trendProfile || {};
  const actionability = digest.actionability || {};
  const seedThisYear = getCandidateSeedThisYearPct(digest);
  let score = Number(actionability.score || 0) * 0.35;
  const setupScore = Number(trend.pullbackSetup?.score || 0);
  const lowPosition = finiteMetricNumber(trend.lowPositionPct120);
  const earlyTurn = isEarlyTurnSetupTrend(trend);
  if (Number.isFinite(setupScore)) score += setupScore * 0.75;
  if (trend.pullbackSetup?.signal === "pullback_complete") score += 28;
  if (trend.pullbackSetup?.signal === "launch_setup") score += 16;
  if (earlyTurn) score += 12;
  if (!earlyTurn) score -= 14;
  if (Number.isFinite(lowPosition) && lowPosition >= 12 && lowPosition <= 55) score += 10;
  if (Number.isFinite(lowPosition) && lowPosition > 60 && lowPosition <= 85) score -= 10;
  if (Number.isFinite(lowPosition) && lowPosition > 85) score -= 12;
  const longPosition = finiteMetricNumber(trend.lowPositionPct250);
  if (Number.isFinite(longPosition) && longPosition >= 0 && longPosition <= 65) score += 6;
  if (Number.isFinite(longPosition) && longPosition > 75 && longPosition <= 85) score -= 8;
  if (Number.isFinite(longPosition) && longPosition > 85) score -= 18;
  if (!hasPullbackLowPositionEvidence(trend)) score -= 18;
  if (trend.trendLabel === "extended_uptrend" || trend.entryBias === "wait_pullback") score -= 34;
  if (Number(trend.return5dPct) > 5 || Number(trend.return10dPct) > 9) score -= 12;
  if (Number(trend.return20dPct) > 10) score -= 18;
  if (Number(trend.return60dPct) > 24) score -= 16;
  if (Number(trend.drawdownFromRecentHighPct) > -2 && Number(trend.return20dPct) > 6) score -= 14;
  if (!isPullbackTrendFreshEnough(digest)) score -= 30;
  const themeOpportunityGap = getPullbackThemeOpportunityBackingGap(digest);
  if (themeOpportunityGap) {
    score -= 44;
  } else if (requiresPullbackThemeOpportunityBacking(digest) && hasPullbackThemeOpportunityBacking(digest)) {
    score += 16;
  }
  const playbookRiskWarnings = getThemeMainForcePlaybookRiskWarnings(digest);
  if (playbookRiskWarnings.length) score -= 70;
  const actionableThemeSupportGap = getPortfolioActionableThemeSupportGap(digest);
  if (hasHoldingRealtimeCatchdownRisk(digest)) score -= 34;
  if (Number.isFinite(seedThisYear)) {
    if (seedThisYear >= -35 && seedThisYear <= 12) score += 6;
    if (seedThisYear <= 5 && Number(trend.return20dPct) > 0 && Number(trend.return20dPct) <= 8) score += 6;
    if (seedThisYear > 30) score -= Math.min(30, (seedThisYear - 30) * 0.9 + 10);
  }
  if (hasPullbackLongPositionChaseRisk(digest)) score -= 18;
  if (hasThemeRetreatRisk(digest)) score -= 42;
  if (hasStaleThemeCatchdownRisk(digest)) score -= 60;
  if (getTextualCatchdownWarnings(digest).length) score -= 60;
  if (getUnrefreshedMarketThemeWarnings(digest).length) score -= 54;
  if (actionableThemeSupportGap) score -= 54;
  if (getCandidateThemeSignals(digest).length && !hasFreshActionableThemeSupport(digest)) score -= 24;
  score += scorePullbackThemeRotation(digest);
  score += scoreHoldingsOutlookForCandidate(digest);
  return score;
}

function isEarlyTurnSetupTrend(trend = {}) {
  const r5 = Number(trend.return5dPct);
  const r10 = Number(trend.return10dPct);
  const r20 = Number(trend.return20dPct);
  return Number.isFinite(r5)
    && Number.isFinite(r10)
    && r5 > 0
    && r5 <= 4.5
    && r10 > 0
    && r10 <= 7
    && (!Number.isFinite(r20) || (r20 >= -4 && r20 <= 6));
}

async function fetchFundResearchDigest(code, seed = {}) {
  const [valuation, profileText, navHistory, holdings, feePageText] = await Promise.all([
    fetchFundValuation(code).catch((error) => ({ ok: false, error: error.message })),
    fetchFundPingzhongData(code).catch(() => ""),
    fetchFundRecentNavHistory(code).catch((error) => ({ ok: false, error: error.message, points: [] })),
    fetchFundHoldings(code).catch((error) => ({ ok: false, error: error.message, equityTopHoldings: [], bondTopHoldings: [] })),
    fetchFundFeePage(code).catch(() => "")
  ]);
  const profile = profileText ? parseFundPingzhongData(profileText) : {};
  const name = profile.name || valuation.name || seed.name || "";
  const valuationSourceAgreement = buildFundValuationSourceAgreement(valuation);
  const feeProfile = buildFundFeeProfile({
    code,
    name,
    sourceRate: profile.sourceRate || seed.sourceRatePct || "",
    rate: profile.rate || seed.currentRatePct || "",
    minPurchase: profile.minPurchase || seed.minPurchase || ""
  }, feePageText);
  const trendProfile = navHistory.ok ? computeTrendProfile(navHistory.points) : { ok: false, note: navHistory.error || "近一年净值下钻失败。" };
  const latest = navHistory.points?.[navHistory.points.length - 1] || null;
  const oneYearRisk = navHistory.ok && latest
    ? computePeriodRiskMetrics(navHistory.points, latest, 1, Number(process.env.RISK_FREE_RATE_PCT || 2))
    : { ok: false, note: "近一年风险指标不足。" };
  const holdingsSummary = buildHoldingsDigest(holdings, profile.topStocks);
  const holdingRealtimePulse = await fetchFundHoldingRealtimePulse(holdingsSummary).catch((error) => ({
    ok: false,
    label: "前十大持仓实时脉冲抓取失败",
    error: error.message,
    items: [],
    sources: []
  }));
  const digest = {
    ok: true,
    code,
    name,
    seed: {
      type: seed.type || "",
      keywords: seed.keywords || [],
      oneWeekPct: seed.oneWeekPct ?? "",
      oneMonthPct: seed.oneMonthPct ?? "",
      threeMonthPct: seed.threeMonthPct ?? "",
      sixMonthPct: seed.sixMonthPct ?? "",
      oneYearPct: seed.oneYearPct ?? "",
      thisYearPct: seed.thisYearPct ?? "",
      productKey: seed.productKey || "",
      exposureKey: seed.exposureKey || "",
      themeOpportunityRequirement: seed.themeOpportunityRequirement || "",
      matchedThemes: (seed.matchedThemes || []).slice(0, 3),
      alternativeShareClasses: (seed.alternativeShareClasses || []).slice(0, 6),
      sameExposureAlternatives: (seed.sameExposureAlternatives || []).slice(0, 6)
    },
    themeOpportunityRequirement: seed.themeOpportunityRequirement || "",
    nav: {
      unitNav: valuation.dwjz || seed.unitNav || "",
      estimatedNav: valuation.gsz || "",
      estimatedChangePct: valuation.gszzl || "",
      navDate: valuation.jzrq || seed.navDate || "",
      estimateTime: valuation.gztime || ""
    },
    intradayTrend: valuation.intradayTrend || null,
    intradayTrendLabel: valuation.intradayTrend?.label || valuation.intradayTrendLabel || "",
    valuationSourceAgreement,
    valuationSourceKind: valuation.sourceKind || "",
    supplementalIntradaySourceKind: valuation.supplementalIntradaySourceKind || "",
    returns: {
      oneMonthPct: profile.syl_1y || seed.oneMonthPct || "",
      threeMonthPct: profile.syl_3y || seed.threeMonthPct || "",
      sixMonthPct: profile.syl_6y || seed.sixMonthPct || "",
      oneYearPct: profile.syl_1n || seed.oneYearPct || ""
    },
    trendProfile,
    risk: { oneYear: pickRiskPeriod(oneYearRisk) },
    fees: {
      shareClass: feeProfile.shareClass,
      shareClassFeeModel: feeProfile.shareClassFeeModel,
      currentRatePct: feeProfile.currentRatePct,
      salesServiceFeePct: feeProfile.salesServiceFeePct,
      minPurchase: feeProfile.minPurchase,
      estimatedSubscriptionFeePer10000: feeProfile.estimatedSubscriptionFeePer10000,
      estimatedSalesServiceFeePer10000PerYear: feeProfile.estimatedSalesServiceFeePer10000PerYear,
      feeImpact: feeProfile.feeImpact,
      holdingPeriodFit: feeProfile.holdingPeriodFit,
      feeDecisionRule: feeProfile.feeDecisionRule,
      missingFeeData: feeProfile.missingFeeData,
      feeRules: feeProfile.feeRules
    },
    moneyMarket: profile.moneyMarket || null,
    scale: profile.scale,
    managers: (profile.managers || []).slice(0, 2),
    holdings: holdingsSummary,
    holdingRealtimePulse,
    sources: [
      `https://fund.eastmoney.com/${code}.html`,
      `https://fund.eastmoney.com/f10/F10DataApi.aspx?type=lsjz&code=${code}`,
      `https://fundf10.eastmoney.com/jjfl_${code}.html`,
      ...(holdingRealtimePulse.sources || [])
    ]
  };
  digest.actionability = buildFundActionabilitySignals(digest);
  return digest;
}

async function fetchFundRecentNavHistory(code) {
  const endDate = new Date();
  const startDate = new Date(endDate);
  startDate.setMonth(startDate.getMonth() - Number(process.env.FUND_DEEP_DIVE_NAV_MONTHS || 18));
  try {
    const firstPage = await fetchFundNavHistoryPage(code, 1, startDate, endDate);
    const points = [...firstPage.points];
    const totalPages = Math.min(firstPage.pages || 1, Number(process.env.FUND_DEEP_DIVE_NAV_MAX_PAGES || 10));

    for (let page = 2; page <= totalPages; page += 1) {
      const pageData = await fetchFundNavHistoryPage(code, page, startDate, endDate);
      points.push(...pageData.points);
    }

    const deduped = [...new Map(points.map((point) => [point.date, point])).values()].sort((a, b) =>
      a.date.localeCompare(b.date)
    );
    if (deduped.length < 20) {
      throw new Error(`F10 NAV history returned ${deduped.length} points`);
    }
    updateStats({
      counters: { deepDiveNavHistoryFetches: 1, deepDiveNavHistoryPoints: deduped.length },
      last: { lastDeepDiveNavHistoryFetchAt: new Date().toISOString() }
    });

    return {
      ok: deduped.length >= 20,
      code,
      startDate: formatDate(startDate),
      endDate: formatDate(endDate),
      sourceKind: "eastmoney_f10_nav_history",
      points: deduped
    };
  } catch (error) {
    const fallback = await fetchFundPingzhongNavHistory(code, startDate, endDate).catch((fallbackError) => ({
      ok: false,
      code,
      startDate: formatDate(startDate),
      endDate: formatDate(endDate),
      sourceKind: "eastmoney_pingzhongdata_nav_history_fallback",
      error: fallbackError.message,
      points: []
    }));
    updateStats({
      counters: {
        deepDiveNavHistoryFetches: 1,
        deepDiveNavHistoryFallbacks: fallback.ok ? 1 : 0,
        deepDiveNavHistoryPoints: fallback.points?.length || 0
      },
      last: { lastDeepDiveNavHistoryFetchAt: new Date().toISOString() }
    });

    if (fallback.ok) {
      return {
        ...fallback,
        primaryError: error.message
      };
    }
    return {
      ...fallback,
      error: `${error.message}; pingzhongdata fallback: ${fallback.error || "no points"}`
    };
  }
}

function buildHoldingsDigest(holdings = {}, fallbackTopStocks = []) {
  const equitySource = holdings.equityTopHoldings?.length ? holdings.equityTopHoldings : fallbackTopStocks;
  const equity = normalizeHoldingItems(equitySource).slice(0, 10).map(formatNormalizedHoldingItem);
  const bond = normalizeHoldingItems(holdings.bondTopHoldings || []).slice(0, 10).map(formatNormalizedHoldingItem);
  return {
    ok: Boolean(holdings.ok || equity.length || bond.length || fallbackTopStocks.length),
    equityDisclosureDate: holdings.equityDisclosureDate || "",
    bondDisclosureDate: holdings.bondDisclosureDate || "",
    equityTopHoldings: equity.length ? equity : fallbackTopStocks.slice(0, 10),
    bondTopHoldings: bond,
    note: holdings.ok ? "已下钻前十大持仓摘要。" : "持仓下钻不足，使用可见候选信息。"
  };
}

async function fetchFundHoldingRealtimePulse(holdings = {}) {
  if (String(process.env.FUND_HOLDING_REALTIME_ENABLED ?? "true") === "false") {
    return { ok: false, label: "前十大持仓实时脉冲未启用", items: [], sources: [] };
  }
  const normalized = normalizeHoldingItems(holdings.equityTopHoldings || [])
    .map((item) => ({
      ...item,
      secid: inferEastmoneySecidFromHolding(item),
      tencentQuoteCode: inferTencentQuoteCodeFromHolding(item)
    }))
    .filter((item) => item.secid)
    .slice(0, finiteNumberOr(process.env.FUND_HOLDING_REALTIME_LIMIT, 8));
  if (!normalized.length) {
    return { ok: false, label: "前十大持仓实时脉冲不可用", note: "前十大持仓缺少可映射的市场代码。", items: [], sources: [] };
  }
  const quotes = await fetchEastmoneyRealtimeQuotes(normalized.map((item) => item.secid));
  let quoteItems = quotes.items || [];
  let sourceLabel = quotes.label;
  const coveredKeys = new Set(quoteItems.flatMap((item) => [item.secid, item.code].filter(Boolean).map((key) => String(key).toUpperCase())));
  const missingTencentCodes = normalized
    .filter((item) =>
      item.tencentQuoteCode
      && !coveredKeys.has(String(item.secid || "").toUpperCase())
      && !coveredKeys.has(String(item.code || "").toUpperCase())
    )
    .map((item) => item.tencentQuoteCode);
  if (missingTencentCodes.length) {
    const supplemental = await fetchTencentRealtimeQuotes(missingTencentCodes).catch(() => null);
    if (supplemental?.items?.length) {
      quoteItems = [...quoteItems, ...supplemental.items];
      sourceLabel = quoteItems.length > (quotes.items || []).length
        ? `${quotes.label || "东方财富实时行情"} + 腾讯实时行情`
        : sourceLabel;
    }
  }
  return buildFundHoldingRealtimePulseFromQuotes(normalized, quoteItems, {
    sourceLabel,
    fetchedAt: quotes.fetchedAt || new Date().toISOString()
  });
}

async function fetchEastmoneyRealtimeQuotes(secids = []) {
  const uniqueSecids = [...new Set((secids || []).map((item) => String(item || "").trim()).filter(Boolean))]
    .slice(0, finiteNumberOr(process.env.EASTMONEY_REALTIME_QUOTE_LIMIT, 60));
  if (!uniqueSecids.length) {
    return { ok: false, label: "东方财富实时行情", error: "没有可抓取的市场代码", items: [] };
  }
  const url = new URL("https://push2.eastmoney.com/api/qt/ulist.np/get");
  const params = {
    fltt: "2",
    secids: uniqueSecids.join(","),
    fields: "f12,f13,f14,f2,f3,f4,f15,f16,f17,f18,f22,f24,f25,f124,f152"
  };
  for (const [key, value] of Object.entries(params)) {
    url.searchParams.set(key, value);
  }
  const fetchedAt = new Date().toISOString();
  const json = JSON.parse(await fetchText(url.href, "https://quote.eastmoney.com/"));
  const diff = Array.isArray(json?.data?.diff) ? json.data.diff : [];
  updateStats({ counters: { holdingRealtimeQuoteFetches: 1, holdingRealtimeQuoteCodes: uniqueSecids.length } });
  return {
    ok: diff.length > 0,
    label: "东方财富前十大持仓实时行情",
    fetchedAt,
    items: diff.map(normalizeEastmoneyRealtimeQuote).filter((item) => item.code && item.name)
  };
}

function normalizeEastmoneyRealtimeQuote(item = {}) {
  const secid = item.f13 && item.f12 ? `${item.f13}.${item.f12}` : "";
  return {
    code: item.f12 || "",
    secid,
    name: item.f14 || "",
    latest: toNumber(item.f2),
    change: toNumber(item.f4),
    changePct: toNumber(item.f3),
    open: toNumber(item.f17),
    high: toNumber(item.f15),
    low: toNumber(item.f16),
    previousClose: toNumber(item.f18),
    amplitudePct: toNumber(item.f22),
    fiveDayPct: toNumber(item.f24),
    yearToDatePct: toNumber(item.f25),
    quoteTime: formatEpochSeconds(item.f124),
    source: secid ? `https://quote.eastmoney.com/unify/r/${secid}` : "https://push2.eastmoney.com/api/qt/ulist.np/get"
  };
}

async function fetchTencentRealtimeQuotes(quoteCodes = []) {
  const uniqueCodes = [...new Set((quoteCodes || []).map((item) => String(item || "").trim().toLowerCase()).filter(Boolean))]
    .slice(0, finiteNumberOr(process.env.TENCENT_REALTIME_QUOTE_LIMIT, 60));
  if (!uniqueCodes.length) {
    return { ok: false, label: "腾讯实时行情", error: "没有可抓取的市场代码", items: [] };
  }
  const source = `https://qt.gtimg.cn/q=${uniqueCodes.join(",")}`;
  const fetchedAt = new Date().toISOString();
  const text = await fetchText(source, "https://gu.qq.com/");
  const items = parseTencentRealtimeQuotes(text);
  updateStats({ counters: { holdingTencentRealtimeQuoteFetches: 1, holdingTencentRealtimeQuoteCodes: uniqueCodes.length } });
  return {
    ok: items.length > 0,
    label: "腾讯前十大持仓实时行情",
    fetchedAt,
    items
  };
}

function parseTencentRealtimeQuotes(text = "") {
  const body = String(text || "");
  const items = [];
  const pattern = /v_([a-z]{2}\d{5,6})="([^"]*)";/gi;
  for (const match of body.matchAll(pattern)) {
    const quoteCode = String(match[1] || "").toLowerCase();
    const parts = String(match[2] || "").split("~");
    const code = parts[2] || quoteCode.replace(/^(?:sh|sz|hk)/, "");
    const secid = inferEastmoneySecidFromTencentQuoteCode(quoteCode);
    const latest = toNumber(parts[3]);
    const previousClose = toNumber(parts[4]);
    const change = toNumber(parts[31]);
    const changePct = toNumber(parts[32]);
    if (!code || !Number.isFinite(latest)) continue;
    items.push({
      code,
      secid,
      name: parts[1] || "",
      latest,
      change,
      changePct,
      open: toNumber(parts[5]),
      high: toNumber(parts[33]),
      low: toNumber(parts[34]),
      previousClose,
      quoteTime: normalizeTencentQuoteTime(parts[30] || ""),
      source: `https://qt.gtimg.cn/q=${quoteCode}`,
      sourceKind: "tencent_realtime_quote"
    });
  }
  return items;
}

function inferEastmoneySecidFromHolding(holding = {}) {
  const raw = [
    holding.secid,
    holding.code,
    holding.name,
    holding.text
  ].map((item) => String(item || "").trim()).filter(Boolean).join(" ");
  const hkMatch = raw.match(/\b(?:HK)?(\d{5})(?:\.HK)?\b/i);
  if (hkMatch) return `116.${hkMatch[1]}`;
  const secidMatch = raw.match(/(?:^|\s)(\d{1,3}\.[A-Z0-9]{1,8})(?=\s|$)/i);
  if (secidMatch) return secidMatch[1].toUpperCase();
  const cnMatch = raw.match(/\b(\d{6})\b/);
  if (!cnMatch) return "";
  const code = cnMatch[1];
  return code.startsWith("6") ? `1.${code}` : `0.${code}`;
}

function inferTencentQuoteCodeFromHolding(holding = {}) {
  const raw = [
    holding.tencentQuoteCode,
    holding.quoteCode,
    holding.secid,
    holding.code,
    holding.name,
    holding.text
  ].map((item) => String(item || "").trim()).filter(Boolean).join(" ");
  const explicit = raw.match(/\b((?:sh|sz)\d{6}|hk\d{5})\b/i);
  if (explicit) return explicit[1].toLowerCase();
  const secid = raw.match(/(?:^|\s)(\d{1,3})\.([A-Z0-9]{1,8})(?=\s|$)/i);
  if (secid) return inferTencentQuoteCodeFromEastmoneySecid(`${secid[1]}.${secid[2]}`);
  const hkMatch = raw.match(/\b(?:HK)?(\d{5})(?:\.HK)?\b/i);
  if (hkMatch) return `hk${hkMatch[1]}`;
  const cnMatch = raw.match(/\b(\d{6})\b/);
  if (!cnMatch) return "";
  const code = cnMatch[1];
  return `${code.startsWith("6") ? "sh" : "sz"}${code}`;
}

function inferTencentQuoteCodeFromEastmoneySecid(secid = "") {
  const match = String(secid || "").trim().match(/^(\d{1,3})\.([A-Z0-9]{1,8})$/i);
  if (!match) return "";
  const market = match[1];
  const code = match[2].toUpperCase();
  if (market === "1") return `sh${code}`;
  if (market === "0") return `sz${code}`;
  if (market === "116") return `hk${code.padStart(5, "0")}`;
  return "";
}

function inferEastmoneySecidFromTencentQuoteCode(quoteCode = "") {
  const match = String(quoteCode || "").trim().match(/^(sh|sz|hk)(\d{5,6})$/i);
  if (!match) return "";
  const prefix = match[1].toLowerCase();
  const code = match[2];
  if (prefix === "sh") return `1.${code}`;
  if (prefix === "sz") return `0.${code}`;
  if (prefix === "hk") return `116.${code.padStart(5, "0")}`;
  return "";
}

function normalizeTencentQuoteTime(value = "") {
  const text = String(value || "").trim();
  const compact = text.match(/^(\d{4})(\d{2})(\d{2})(\d{2})(\d{2})(\d{2})$/);
  if (compact) return `${compact[1]}-${compact[2]}-${compact[3]} ${compact[4]}:${compact[5]}`;
  const slashed = text.match(/^(\d{4})\/(\d{2})\/(\d{2})\s+(\d{2}):(\d{2})/);
  if (slashed) return `${slashed[1]}-${slashed[2]}-${slashed[3]} ${slashed[4]}:${slashed[5]}`;
  return text;
}

function buildFundHoldingRealtimePulseFromQuotes(holdings = [], quotes = [], options = {}) {
  const normalizedHoldings = normalizeHoldingItems(holdings)
    .map((item) => ({ ...item, secid: inferEastmoneySecidFromHolding(item) }))
    .filter((item) => item.secid);
  const quoteByKey = new Map();
  for (const quote of quotes || []) {
    if (!quote) continue;
    const normalized = normalizeEastmoneyRealtimeQuoteLike(quote);
    if (normalized.secid) quoteByKey.set(normalized.secid.toUpperCase(), normalized);
    if (normalized.code) quoteByKey.set(normalized.code.toUpperCase(), normalized);
  }
  const items = normalizedHoldings.map((holding) => {
    const quote = quoteByKey.get(String(holding.secid || "").toUpperCase())
      || quoteByKey.get(String(holding.code || "").toUpperCase());
    if (!quote) return null;
    return {
      code: holding.code || quote.code || "",
      secid: holding.secid || quote.secid || "",
      name: holding.name || quote.name || "",
      pct: Number.isFinite(holding.pct) ? round(holding.pct, 2) : null,
      changePct: finiteMetricNumber(quote.changePct),
      latest: finiteMetricNumber(quote.latest),
      quoteTime: quote.quoteTime || "",
      source: quote.source || ""
    };
  }).filter(Boolean);
  const weightedItems = items.filter((item) => Number.isFinite(item.pct) && Number.isFinite(item.changePct));
  const weightedPct = weightedItems.reduce((sum, item) => sum + Number(item.pct || 0), 0);
  const weightedChangePct = weightedPct > 0
    ? weightedItems.reduce((sum, item) => sum + Number(item.pct || 0) * Number(item.changePct || 0), 0) / weightedPct
    : averageNumeric(items.map((item) => item.changePct).filter(Number.isFinite));
  const positiveCount = items.filter((item) => Number(item.changePct) > 0).length;
  const negativeCount = items.filter((item) => Number(item.changePct) < 0).length;
  const label = formatFundHoldingRealtimePulseLabel(weightedChangePct);
  const risks = [];
  const positives = [];
  if (Number.isFinite(weightedChangePct) && weightedChangePct <= -0.8) risks.push("底层持仓盘中走弱，买入需要等止跌确认。");
  if (Number.isFinite(weightedChangePct) && weightedChangePct >= 1.2) risks.push("底层持仓盘中冲高，避免把实时强势当成追涨理由。");
  if (Number.isFinite(weightedChangePct) && weightedChangePct > 0 && weightedChangePct < 1.2) positives.push("底层持仓温和转强，支持观察是否进入启动确认。");
  if (weightedPct > 0 && weightedPct < 15) risks.push(`实时覆盖前十大约${formatFallbackPlainPct(weightedPct)}，只能作为辅助证据。`);
  return {
    ok: items.length > 0,
    label,
    weightedChangePct: Number.isFinite(weightedChangePct) ? round(weightedChangePct, 2) : null,
    coveredHoldingPct: Number.isFinite(weightedPct) && weightedPct > 0 ? round(weightedPct, 2) : null,
    quoteCount: items.length,
    positiveCount,
    negativeCount,
    quoteTime: items.map((item) => item.quoteTime).find(Boolean) || "",
    sourceLabel: options.sourceLabel || "东方财富前十大持仓实时行情",
    fetchedAt: options.fetchedAt || "",
    topPositive: [...items].filter((item) => Number.isFinite(item.changePct)).sort((a, b) => Number(b.changePct) - Number(a.changePct)).slice(0, 2),
    topNegative: [...items].filter((item) => Number.isFinite(item.changePct)).sort((a, b) => Number(a.changePct) - Number(b.changePct)).slice(0, 2),
    positives: positives.slice(0, 3),
    risks: risks.slice(0, 3),
    items: items.slice(0, 8),
    sources: [...new Set(items.map((item) => item.source).filter(Boolean))].slice(0, 6)
  };
}

function normalizeEastmoneyRealtimeQuoteLike(quote = {}) {
  if (quote.f12 || quote.f13 || quote.f14) return normalizeEastmoneyRealtimeQuote(quote);
  const secid = String(quote.secid || "").trim();
  return {
    code: String(quote.code || (secid.includes(".") ? secid.split(".").slice(1).join(".") : "") || "").trim(),
    secid,
    name: String(quote.name || "").trim(),
    latest: finiteMetricNumber(quote.latest),
    change: finiteMetricNumber(quote.change),
    changePct: finiteMetricNumber(quote.changePct),
    quoteTime: quote.quoteTime || "",
    source: quote.source || (secid ? `https://quote.eastmoney.com/unify/r/${secid}` : "")
  };
}

function formatFundHoldingRealtimePulseLabel(value) {
  if (!Number.isFinite(value)) return "底层持仓实时脉冲待确认";
  if (value >= 1.2) return "底层持仓盘中明显走强";
  if (value >= 0.3) return "底层持仓盘中偏强";
  if (value <= -1.2) return "底层持仓盘中明显走弱";
  if (value <= -0.3) return "底层持仓盘中偏弱";
  return "底层持仓盘中平稳";
}

function compactFundHoldingRealtimePulse(pulse = null) {
  if (!pulse || typeof pulse !== "object" || !pulse.ok) return null;
  return {
    label: pulse.label || "",
    weightedChangePct: finiteMetricNumber(pulse.weightedChangePct),
    coveredHoldingPct: finiteMetricNumber(pulse.coveredHoldingPct),
    quoteCount: Number(pulse.quoteCount || 0),
    positiveCount: Number(pulse.positiveCount || 0),
    negativeCount: Number(pulse.negativeCount || 0),
    quoteTime: pulse.quoteTime || "",
    topPositive: (pulse.topPositive || []).slice(0, 2).map(compactHoldingRealtimePulseItem),
    topNegative: (pulse.topNegative || []).slice(0, 2).map(compactHoldingRealtimePulseItem),
    risks: normalizeStringArray(pulse.risks).slice(0, 3),
    positives: normalizeStringArray(pulse.positives).slice(0, 3)
  };
}

function compactHoldingRealtimePulseItem(item = {}) {
  return {
    code: item.code || "",
    name: item.name || "",
    pct: finiteMetricNumber(item.pct),
    changePct: finiteMetricNumber(item.changePct)
  };
}

