function getRuntimeStats() {
  const stats = normalizeStats(shouldPersistRuntimeStats()
    ? safeReadJson(STATS_PATH)
    : runtimeStatsMemoryCache || {});
  return {
    ...stats,
    diagnostics: buildRuntimeDiagnostics(stats),
    release: getRuntimeRelease()
  };
}

function updateStats(patch = {}) {
  const stats = getRuntimeStats();
  for (const [key, value] of Object.entries(patch.counters || {})) {
    stats.counters[key] = Number(stats.counters[key] || 0) + Number(value || 0);
  }
  stats.last = { ...stats.last, ...(patch.last || {}) };
  stats.updatedAt = new Date().toISOString();
  if (shouldPersistRuntimeStats()) {
    ensureDir(path.dirname(STATS_PATH));
    fs.writeFileSync(STATS_PATH, `${JSON.stringify(stats, null, 2)}\n`, "utf8");
  } else {
    runtimeStatsMemoryCache = stripRuntimeStatsComputedFields(stats);
  }
  return stats;
}

function shouldPersistRuntimeStats() {
  return process.env.FUNDAGENT_SKIP_SERVER_START !== "1"
    || parseBoolean(process.env.FUNDAGENT_PERSIST_TEST_STATS, false);
}

function stripRuntimeStatsComputedFields(stats = {}) {
  const { diagnostics, release, ...raw } = stats || {};
  return raw;
}

function normalizeStats(value) {
  const defaults = getDefaultStats();
  return {
    ...defaults,
    ...value,
    counters: { ...defaults.counters, ...(value?.counters || {}) },
    last: { ...defaults.last, ...(value?.last || {}) }
  };
}

function buildRuntimeDiagnostics(stats = {}) {
  const counters = stats.counters || {};
  const last = stats.last || {};
  const items = [
    buildStatsIntegrityDiagnostic(stats),
    buildCounterRateDiagnostic({
      label: "模型调用失败",
      failures: counters.modelFailures,
      total: counters.modelCalls,
      warningRate: 0.03,
      criticalRate: 0.08,
      note: "影响回答稳定性，连续失败时优先检查模型服务、上下文长度和网络。"
    }),
    buildCounterRateDiagnostic({
      label: "市场快照失败",
      failures: counters.marketSnapshotFailures,
      total: counters.marketSnapshotCalls,
      warningRate: 0.12,
      criticalRate: 0.25,
      note: "影响题材、贵金属和候选池判断，失败率高时推荐结论需要降级。"
    }),
    buildCounterRateDiagnostic({
      label: "持仓补全失败",
      failures: counters.fundHoldingsFailures,
      total: counters.fundHoldingsFetches,
      warningRate: 0.06,
      criticalRate: 0.14,
      note: "影响前十大持仓和行业前景判断，失败率高时不能把持仓前景说满。"
    }),
    buildCounterRateDiagnostic({
      label: "图表生成失败",
      failures: counters.fundReportTrendImageFailures,
      total: Number(counters.fundReportTrendImageFailures || 0) + Number(counters.fundReportTrendImagesUploaded || 0),
      warningRate: 0.08,
      criticalRate: 0.2,
      note: "影响配图解释和买点证据展示，失败率高时客户会觉得图文割裂。"
    }),
    buildCounterRateDiagnostic({
      label: "组合任务失败",
      failures: counters.portfolioErrors,
      total: counters.portfolioRuns,
      warningRate: 0.04,
      criticalRate: 0.12,
      note: "影响每日复盘、估值和风控连续性，失败后应优先复核最近任务。"
    }),
    buildCounterRateDiagnostic({
      label: "回答质检失败",
      failures: counters.fundAnswerQualityFailures,
      total: Number(counters.fundAnswerQualityFailures || 0) + Number(counters.fundAnswerQualityPasses || 0),
      warningRate: 0.08,
      criticalRate: 0.18,
      note: "说明回答可能缺少动作、证据、费用或中文化，需要关注质检 issue。"
    }),
    buildFundAnswerQualityIssueDiagnostic(last),
    buildModelConfigCommentDiagnostic(last),
    buildContextWindowDiagnostic(last)
  ].filter(Boolean);
  const severityRank = { ok: 0, info: 1, warning: 2, critical: 3 };
  const level = items.reduce((current, item) =>
    severityRank[item.severity] > severityRank[current] ? item.severity : current
  , "ok");
  return {
    level,
    summary: formatRuntimeDiagnosticSummary(level, items),
    items
  };
}

function buildCounterRateDiagnostic({ label, failures, total, warningRate, criticalRate, note }) {
  const failed = Number(failures || 0);
  const count = Number(total || 0);
  if (!Number.isFinite(count) || count <= 0 || !Number.isFinite(failed) || failed <= 0) return null;
  const rate = failed / count;
  const severity = rate >= criticalRate ? "critical" : rate >= warningRate ? "warning" : "info";
  if (severity === "info" && failed < 3) return null;
  return {
    severity,
    label,
    value: `${failed}/${count} (${round(rate * 100, 1)}%)`,
    note
  };
}

function buildStatsIntegrityDiagnostic(stats = {}) {
  const counters = stats.counters || {};
  const customerActivity = [
    counters.messageEvents,
    counters.conversations,
    counters.routedMessages,
    counters.answersSent,
    counters.repliesSent,
    counters.portfolioRuns,
    counters.portfolioTransactions,
    counters.portfolioStatusRequests
  ].reduce((sum, value) => sum + Number(value || 0), 0);
  const syntheticSignals = [
    counters.fundAnswerQualityFailures,
    counters.fundAnswerQualityPasses,
    counters.fundAnswerQualityDeterministicFallbacks,
    counters.fundAnswerQualityLocalizationFixes,
    counters.modelCalls,
    counters.modelFailures,
    counters.intentRouterFailures,
    counters.errors
  ].reduce((sum, value) => sum + Number(value || 0), 0);
  if (customerActivity > 0 || syntheticSignals < 10) return null;
  return {
    severity: "warning",
    label: "统计样本疑似测试噪音",
    value: `客户活动 ${customerActivity} / 诊断信号 ${syntheticSignals}`,
    note: "当前统计几乎没有真实消息、回复或组合任务，却有大量质检/模型失败；评估经理能力时先看线上真实 stats 或重置本地测试统计。"
  };
}

function buildFundAnswerQualityIssueDiagnostic(last = {}) {
  const issues = parseFundAnswerQualityIssues(last.lastFundAnswerQualityIssues);
  if (!issues.length) return null;
  const categories = summarizeFundAnswerQualityIssueCategories(issues);
  if (!categories.length) return null;
  const severe = issues.some((issue) => /watch_candidate|recommendation_not_from|recommends_without|stale_data|stale_theme|missing_no_qualified|missing_pullback_main_candidate_code/.test(issue));
  return {
    severity: severe ? "critical" : "warning",
    label: "最近质检问题",
    value: `${issues.length} 个 issue`,
    note: categories.slice(0, 3).join("；")
  };
}

function parseFundAnswerQualityIssues(value) {
  return String(value || "")
    .split(/[,，\s]+/)
    .map((item) => item.trim())
    .filter(Boolean);
}

function summarizeFundAnswerQualityIssueCategories(issues = []) {
  const text = issues.join(",");
  const categories = [];
  const add = (pattern, note) => {
    if (pattern.test(text)) categories.push(note);
  };
  add(/watch_candidate_promoted_to_recommendation|recommendation_not_from_pullback_main_candidates|recommends_without_qualified_pullback_candidate|missing_no_qualified_pullback_message|missing_pullback_main_candidate_code/, "回调/低位启动请求存在硬凑或错推风险：没有合格主候选时必须明确先不买");
  add(/watch_candidate_given_buy_execution|watch_candidate_given_buy_signal/, "观察池候选被写成可买：备选只能给等待条件和0元观察");
  add(/stale_data_candidate_given_buy_execution|stale_data_candidate_given_buy_signal/, "过期净值/走势仍给买入：必须重新下钻复核后再谈金额");
  add(/stale_theme_candidate_given_buy_execution|stale_theme_candidate_given_buy_signal/, "题材退潮、主力撤离或旧题材未被当前雷达确认仍给买入：必须改成0元观察，等资金回流或当前题材雷达重新确认再复核");
  add(/missing_pullback_timing_evidence/, "主推荐缺少回调、低位、5日/10日转强或近20/60日不过热证据");
  add(/missing_pullback_share_class_fee/, "主推荐缺少A/C份额和费用依据，无法支撑执行金额");
  add(/missing_pullback_three_tier_execution/, "缺少激进/均衡/保守三档执行方案");
  add(/missing_market_data_quality_disclosure/, "公开数据源不完整但没有主动降级说明");
  add(/insufficient_chart_linked_candidates/, "图文覆盖不足：有候选却没有补足买入参考和备选观察配图");
  add(/missing_requested_result_sort_policy|requested_result_sort_order_mismatch/, "回答没有按用户指定优先级排序：高夏普、低回撤、主力题材或费用等偏好必须进入排序口径并真实改变结果顺序");
  add(/missing_result_first_ranking_summary|opening_metric_dump_before_result|result_ranking_metric_dump/, "回答开头仍不够像客户榜单：必须先给直接结论、排序口径和结果榜，再展开少量关键证据");
  add(/internal_signal_leak|raw_english_section_leak|stiff_confidence_label/, "表达仍有内部字段、英文栏目或生硬把握度，需要中文自然化");
  add(/generic_cliche_answer|risk_dump_without_decision_boundary|missing_actionable_decision/, "回答偏套话或只堆风险，缺少动作边界");
  return [...new Set(categories)];
}

function buildModelConfigCommentDiagnostic(last = {}) {
  const message = String(last.lastError || "");
  if (!/(unknown provider|model|模型).{0,120}#|#.{0,80}(模型|model|provider)/i.test(message)) return null;
  return {
    severity: "critical",
    label: "模型名称疑似带注释",
    value: "最近一次模型错误",
    note: "模型名里像是混入了 # 后面的注释文字；系统会清洗新配置，但已保存的配置需要重新打开保存或重启后复核。"
  };
}

function buildContextWindowDiagnostic(last = {}) {
  const message = String(last.lastError || "");
  if (!isModelContextWindowError({ message })) return null;
  return {
    severity: "critical",
    label: "模型上下文超限",
    value: "最近一次模型错误",
    note: "模型输入仍可能过长，需要继续压缩历史账本、图表序列或候选池。"
  };
}

function formatRuntimeDiagnosticSummary(level, items = []) {
  if (!items.length || level === "ok") return "运行状态暂无明显异常。";
  const criticalCount = items.filter((item) => item.severity === "critical").length;
  const warningCount = items.filter((item) => item.severity === "warning").length;
  if (criticalCount) return `发现 ${criticalCount} 个严重运行风险，需要优先处理。`;
  if (warningCount) return `发现 ${warningCount} 个运行预警，建议复核数据源和模型链路。`;
  return "存在轻微信号，继续观察即可。";
}

function getRuntimeRelease() {
  return { ...APP_RELEASE };
}

async function getDeploymentFreshness(options = {}) {
  const release = getRuntimeRelease();
  const repository = normalizeGitHubRepository(options.repository || DEFAULT_DEPLOYMENT_REPOSITORY);
  const branch = String(options.branch || process.env.FUNDAGENT_MAIN_BRANCH || release.branch || "main")
    .replace(/^origin\//, "")
    .trim() || "main";
  const now = Date.now();
  const cacheValid = !options.force
    && deploymentFreshnessCache.value
    && deploymentFreshnessCache.repository === repository
    && deploymentFreshnessCache.branch === branch
    && now - deploymentFreshnessCache.fetchedAtMs < DEPLOYMENT_CHECK_CACHE_MS;
  if (cacheValid) return deploymentFreshnessCache.value;
  if (!options.force && deploymentFreshnessCache.promise) return deploymentFreshnessCache.promise;

  deploymentFreshnessCache.promise = fetchDeploymentFreshnessSnapshot({ release, repository, branch })
    .then((value) => {
      deploymentFreshnessCache = {
        fetchedAtMs: Date.now(),
        value,
        promise: null,
        repository,
        branch
      };
      return value;
    })
    .catch((error) => {
      const value = buildDeploymentFreshnessUnknown({
        release,
        repository,
        branch,
        reason: `无法连接 GitHub 主分支：${error.message}`
      });
      deploymentFreshnessCache = {
        fetchedAtMs: Date.now(),
        value,
        promise: null,
        repository,
        branch
      };
      return value;
    });
  return deploymentFreshnessCache.promise;
}

async function fetchDeploymentFreshnessSnapshot({ release = {}, repository = "", branch = "main" } = {}) {
  if (!repository) {
    return buildDeploymentFreshnessUnknown({
      release,
      repository,
      branch,
      reason: "未配置 GitHub 仓库，无法比较部署版本。"
    });
  }
  const runtimeCommit = normalizeGitCommit(release.commit || release.shortCommit || "");
  const apiUrl = `https://api.github.com/repos/${repository}/commits/${encodeURIComponent(branch)}`;
  const headers = {
    accept: "application/vnd.github+json",
    "user-agent": "FundAgent deployment freshness"
  };
  const token = String(process.env.FUNDAGENT_GITHUB_TOKEN || process.env.GITHUB_TOKEN || "").trim();
  if (token) headers.authorization = `Bearer ${token}`;
  const response = await fetchWithTimeout(apiUrl, { headers }, Number(process.env.DEPLOYMENT_CHECK_TIMEOUT_MS || 8000));
  const text = await response.text();
  if (!response.ok) {
    throw new Error(`GitHub HTTP ${response.status}: ${text.slice(0, 180)}`);
  }
  const json = text ? JSON.parse(text) : {};
  const latestCommit = normalizeGitCommit(json.sha || "");
  const latestShortCommit = latestCommit ? latestCommit.slice(0, 7) : "";
  const latestUrl = json.html_url || `https://github.com/${repository}/commit/${latestCommit}`;
  const latestDate = json.commit?.committer?.date || json.commit?.author?.date || "";
  if (!runtimeCommit || !latestCommit) {
    return buildDeploymentFreshnessUnknown({
      release,
      repository,
      branch,
      latestCommit,
      latestShortCommit,
      latestUrl,
      latestDate,
      reason: runtimeCommit ? "无法读取 GitHub 最新提交。" : "当前服务缺少运行提交指纹。"
    });
  }
  const current = isSameGitCommit(runtimeCommit, latestCommit);
  return {
    status: current ? "current" : "stale",
    label: current ? "已是最新" : "部署落后",
    severity: current ? "ok" : "warning",
    message: current
      ? `当前服务已运行 ${branch} 最新提交 ${latestShortCommit}。`
      : `当前服务运行 ${runtimeCommit.slice(0, 7)}，${branch} 最新为 ${latestShortCommit}。`,
    updateHint: current ? "无需更新。" : "服务器需要拉取最新镜像或重新构建后重启服务。",
    repository,
    branch,
    checkedAt: new Date().toISOString(),
    runtime: {
      commit: runtimeCommit,
      shortCommit: runtimeCommit ? runtimeCommit.slice(0, 7) : "",
      source: release.source || "",
      builtAt: release.builtAt || "",
      startedAt: release.startedAt || ""
    },
    latest: {
      commit: latestCommit,
      shortCommit: latestShortCommit,
      url: latestUrl,
      date: latestDate
    }
  };
}

function buildDeploymentFreshnessUnknown({ release = {}, repository = "", branch = "", latestCommit = "", latestShortCommit = "", latestUrl = "", latestDate = "", reason = "" } = {}) {
  const runtimeCommit = normalizeGitCommit(release.commit || release.shortCommit || "");
  return {
    status: "unknown",
    label: "无法确认",
    severity: "warning",
    message: reason || "暂时无法确认部署是否最新。",
    updateHint: "可在服务器运行部署检查或稍后刷新。",
    repository,
    branch,
    checkedAt: new Date().toISOString(),
    runtime: {
      commit: runtimeCommit,
      shortCommit: runtimeCommit ? runtimeCommit.slice(0, 7) : "",
      source: release.source || "",
      builtAt: release.builtAt || "",
      startedAt: release.startedAt || ""
    },
    latest: {
      commit: latestCommit,
      shortCommit: latestShortCommit || (latestCommit ? latestCommit.slice(0, 7) : ""),
      url: latestUrl,
      date: latestDate
    }
  };
}

function normalizeGitHubRepository(value = "") {
  return String(value || "")
    .trim()
    .replace(/^https?:\/\/github\.com\//i, "")
    .replace(/^git@github\.com:/i, "")
    .replace(/\.git$/i, "")
    .replace(/^\/+|\/+$/g, "");
}

function isSameGitCommit(left = "", right = "") {
  const a = normalizeGitCommit(left).toLowerCase();
  const b = normalizeGitCommit(right).toLowerCase();
  if (!a || !b) return false;
  return a === b || a.startsWith(b) || b.startsWith(a);
}

function resolveAppRelease() {
  const pkg = safeReadJson(path.join(ROOT, "package.json"));
  const envCommit = firstNonEmptyEnv([
    "FUNDAGENT_COMMIT",
    "GIT_COMMIT",
    "COMMIT_SHA",
    "VERCEL_GIT_COMMIT_SHA",
    "RENDER_GIT_COMMIT",
    "HEROKU_SLUG_COMMIT"
  ]);
  const envBranch = firstNonEmptyEnv([
    "FUNDAGENT_BRANCH",
    "GIT_BRANCH",
    "BRANCH_NAME",
    "VERCEL_GIT_COMMIT_REF",
    "RENDER_GIT_BRANCH"
  ]);
  const buildFile = readBuildReleaseMetadata();
  const git = readGitReleaseMetadata();
  const commit = normalizeGitCommit(envCommit || buildFile.commit || git.commit || "");
  const branch = String(envBranch || buildFile.branch || git.branch || "").replace(/^origin\//, "");
  return {
    name: pkg.name || "feishu-fund-assistant",
    version: pkg.version || "0.0.0",
    commit,
    shortCommit: commit ? commit.slice(0, 7) : "",
    branch,
    source: envCommit ? "env" : buildFile.source || git.source || "",
    builtAt: buildFile.builtAt || "",
    startedAt: STARTED_AT.toISOString()
  };
}

function firstNonEmptyEnv(keys = []) {
  for (const key of keys) {
    const value = String(process.env[key] || "").trim();
    if (value) return value;
  }
  return "";
}

function normalizeGitCommit(value) {
  const match = String(value || "").trim().match(/[a-f0-9]{7,40}/i);
  return match ? match[0] : "";
}

function readBuildReleaseMetadata() {
  const release = safeReadJson(path.join(ROOT, ".fundagent-release.json"));
  const commit = normalizeGitCommit(release.commit || release.shortCommit || "");
  const branch = String(release.branch || "").replace(/^origin\//, "").trim();
  return commit || branch || release.builtAt
    ? {
        commit,
        branch,
        source: "build-file",
        builtAt: String(release.builtAt || "").trim()
      }
    : {};
}

function readGitReleaseMetadata() {
  const gitDir = resolveGitDir(path.join(ROOT, ".git"));
  if (!gitDir) return {};
  const head = safeReadText(path.join(gitDir, "HEAD")).trim();
  if (!head) return {};
  if (!head.startsWith("ref:")) {
    const commit = normalizeGitCommit(head);
    return commit ? { commit, branch: "", source: "git-head" } : {};
  }
  const ref = head.replace(/^ref:\s*/, "").trim();
  const commit = normalizeGitCommit(safeReadText(path.join(gitDir, ref))) || normalizeGitCommit(readPackedGitRef(gitDir, ref));
  const branch = ref.replace(/^refs\/heads\//, "");
  return {
    commit,
    branch,
    source: commit ? "git-ref" : "git-head"
  };
}

function resolveGitDir(gitPath) {
  try {
    if (!fs.existsSync(gitPath)) return "";
    const stat = fs.statSync(gitPath);
    if (stat.isDirectory()) return gitPath;
    const text = fs.readFileSync(gitPath, "utf8").trim();
    const match = text.match(/^gitdir:\s*(.+)$/i);
    if (!match) return "";
    const target = match[1].trim();
    return path.resolve(path.dirname(gitPath), target);
  } catch {
    return "";
  }
}

function readPackedGitRef(gitDir, ref) {
  const lines = safeReadText(path.join(gitDir, "packed-refs")).split(/\r?\n/);
  const line = lines.find((item) => item.trim().endsWith(` ${ref}`));
  return line ? line.split(/\s+/)[0] : "";
}

function recordError(error, extraCounters = {}) {
  updateStats({
    counters: { errors: 1, ...extraCounters },
    last: {
      lastErrorAt: new Date().toISOString(),
      lastError: error?.message || String(error)
    }
  });
}

function validateModelConfig(config) {
  if (config && typeof config === "object") {
    config.modelName = normalizeModelName(config.modelName);
  }
  if (!config.modelBaseUrl || !config.modelName || !config.modelApiKey) {
    throw new Error("模型配置不完整，请在管理界面填写 Base URL、模型名和 API Key。");
  }
}

function validateFeishuConfig(config) {
  if (!config.feishuBaseUrl || !config.feishuAppId || !config.feishuAppSecret) {
    throw new Error("飞书配置不完整，请在管理界面填写 App ID 和 App Secret。");
  }
}

function loadCodexDefaults() {
  const codexHome = process.env.CODEX_HOME || path.join(os.homedir(), ".codex");
  const configPath = process.env.CODEX_CONFIG_PATH || path.join(codexHome, "config.toml");
  const authPath = process.env.CODEX_AUTH_PATH || path.join(codexHome, "auth.json");
  const parsedConfig = parseCodexToml(safeReadText(configPath));
  const providerName = parsedConfig.root.model_provider || Object.keys(parsedConfig.modelProviders)[0] || "";
  const provider = parsedConfig.modelProviders[providerName] || {};
  const auth = safeReadJson(authPath);

  return {
    modelName: parsedConfig.root.model || "",
    modelBaseUrl: provider.base_url || "",
    modelWireApi: provider.wire_api || "",
    modelReasoningEffort: parsedConfig.root.model_reasoning_effort || "",
    modelApiKey: auth.OPENAI_API_KEY || ""
  };
}

function parseCodexToml(text) {
  const root = {};
  const modelProviders = {};
  let section = "";

  for (const rawLine of text.split(/\r?\n/)) {
    const line = rawLine.trim();
    if (!line || line.startsWith("#")) continue;

    const sectionMatch = line.match(/^\[([^\]]+)\]$/);
    if (sectionMatch) {
      section = sectionMatch[1].trim();
      continue;
    }

    const keyValue = line.match(/^([A-Za-z0-9_.-]+)\s*=\s*(.+)$/);
    if (!keyValue) continue;

    const key = keyValue[1];
    const value = parseTomlValue(keyValue[2]);
    const providerMatch = section.match(/^model_providers\.("?)([^"]+)\1$/);
    if (providerMatch) {
      const providerName = providerMatch[2];
      modelProviders[providerName] ||= {};
      modelProviders[providerName][key] = value;
    } else if (!section) {
      root[key] = value;
    }
  }

  return { root, modelProviders };
}

function parseTomlValue(value) {
  const trimmed = value.trim();
  if (trimmed.startsWith('"') && trimmed.endsWith('"')) return trimmed.slice(1, -1);
  if (trimmed === "true") return true;
  if (trimmed === "false") return false;
  const numeric = Number(trimmed);
  return Number.isNaN(numeric) ? trimmed : numeric;
}

function listSkills(includeContent) {
  if (!fs.existsSync(SKILLS_DIR)) {
    return [];
  }

  return fs
    .readdirSync(SKILLS_DIR, { withFileTypes: true })
    .filter((entry) => entry.isFile() && entry.name.toLowerCase().endsWith(".md"))
    .map((entry) => {
      const filePath = path.join(SKILLS_DIR, entry.name);
      const content = safeReadText(filePath);
      const stat = fs.statSync(filePath);
      const meta = parseSkillMeta(content, entry.name);
      return {
        id: path.basename(entry.name, ".md"),
        name: meta.name,
        description: meta.description,
        path: path.relative(ROOT, filePath).replace(/\\/g, "/"),
        updatedAt: stat.mtime.toISOString(),
        bytes: stat.size,
        content: includeContent ? content : undefined
      };
    });
}

function parseSkillMeta(content, fileName) {
  const frontMatter = content.match(/^---\n([\s\S]*?)\n---/);
  const frontMatterValues = {};
  if (frontMatter) {
    for (const line of frontMatter[1].split(/\r?\n/)) {
      const match = line.match(/^([A-Za-z0-9_-]+):\s*(.+)$/);
      if (match) {
        frontMatterValues[match[1]] = match[2].trim();
      }
    }
  }

  const title = content.match(/^#\s+(.+)$/m)?.[1]?.trim();
  const paragraph = content
    .replace(/^---[\s\S]*?---/, "")
    .split(/\r?\n\r?\n/)
    .map((part) => part.trim())
    .find((part) => part && !part.startsWith("#") && !part.startsWith("|"));

  return {
    name: frontMatterValues.name || title || path.basename(fileName, ".md"),
    description: frontMatterValues.description || paragraph || "No description"
  };
}

function decodeFeishuPayload(rawBody, config) {
  const bodyText = rawBody.toString("utf8");
  const parsed = JSON.parse(bodyText || "{}");
  if (!parsed.encrypt) {
    return parsed;
  }
  if (!config.feishuEncryptKey) {
    throw new Error("收到加密事件，但未配置 Encrypt Key。");
  }
  return JSON.parse(decryptFeishuPayload(parsed.encrypt, config.feishuEncryptKey));
}

function decryptFeishuPayload(encryptedText, encryptKey) {
  const key = crypto.createHash("sha256").update(encryptKey).digest();
  const encrypted = Buffer.from(encryptedText, "base64");
  const iv = encrypted.subarray(0, 16);
  const ciphertext = encrypted.subarray(16);
  const decipher = crypto.createDecipheriv("aes-256-cbc", key, iv);
  const decrypted = Buffer.concat([decipher.update(ciphertext), decipher.final()]);
  return decrypted.toString("utf8");
}

function maybeVerifyFeishuSignature(headers, rawBody, encryptKey) {
  const timestamp = headerValue(headers, "x-lark-request-timestamp");
  const nonce = headerValue(headers, "x-lark-request-nonce");
  const signature = headerValue(headers, "x-lark-signature");
  if (!timestamp && !nonce && !signature) {
    return;
  }
  if (!timestamp || !nonce || !signature) {
    throw new Error("缺少飞书签名请求头。");
  }

  const expected = crypto
    .createHash("sha256")
    .update(`${timestamp}${nonce}${encryptKey}${rawBody.toString("utf8")}`)
    .digest("hex");

  if (!timingSafeEqualHex(expected, signature)) {
    throw new Error("飞书事件签名校验失败。");
  }
}

function verifyFeishuToken(payload, config) {
  if (!config.feishuVerificationToken) {
    return;
  }
  const token = payload?.header?.token || payload?.token || payload?.event?.token || "";
  if (token && token !== config.feishuVerificationToken) {
    throw new Error("飞书 Verification Token 校验失败。");
  }
}

function isMessageReceiveEvent(payload) {
  const eventType = payload?.header?.event_type || payload?.event?.type || payload?.type;
  return eventType === "im.message.receive_v1";
}

function getChallenge(payload) {
  const eventType = payload?.header?.event_type || payload?.event?.type || payload?.type;
  if (eventType !== "url_verification") {
    return "";
  }
  return payload?.challenge || payload?.event?.challenge || "";
}

function extractImageKeys(value, output = []) {
  if (!value || typeof value !== "object") {
    return output;
  }
  if (typeof value.image_key === "string") {
    output.push(value.image_key);
  }
  if (typeof value.file_key === "string") {
    output.push(value.file_key);
  }
  for (const child of Object.values(value)) {
    if (Array.isArray(child)) {
      for (const item of child) {
        extractImageKeys(item, output);
      }
    } else if (child && typeof child === "object") {
      extractImageKeys(child, output);
    }
  }
  return [...new Set(output)];
}

function extractUserText(messageType, content) {
  if (!content || typeof content !== "object") {
    return "";
  }
  if (messageType === "text" && typeof content.text === "string") {
    return cleanFeishuUserText(content.text, content);
  }
  if (typeof content.text === "string") {
    return cleanFeishuUserText(content.text, content);
  }
  if (content.title || content.content) {
    const pieces = [];
    collectText(content, pieces);
    return cleanFeishuUserText(pieces.join("\n"), content);
  }
  return "";
}

function collectText(value, pieces, key = "") {
  if (!value) return;
  if (["image_key", "file_key"].includes(key)) return;
  if (typeof value === "string") {
    const trimmed = value.trim();
    if (trimmed) pieces.push(trimmed);
    return;
  }
  if (Array.isArray(value)) {
    for (const item of value) collectText(item, pieces, key);
    return;
  }
  if (typeof value === "object") {
    if (typeof value.text === "string" && value.text.trim()) pieces.push(value.text.trim());
    for (const [childKey, child] of Object.entries(value)) {
      if (child !== value.text) collectText(child, pieces, childKey);
    }
  }
}

function cleanFeishuUserText(text, content = {}) {
  let cleaned = String(text || "");
  const mentions = Array.isArray(content?.mentions) ? content.mentions : [];

  for (const mention of mentions) {
    for (const value of [mention?.key, mention?.name].filter(Boolean)) {
      cleaned = cleaned.replace(new RegExp(escapeRegExp(String(value)), "g"), " ");
      cleaned = cleaned.replace(new RegExp(`@\\s*${escapeRegExp(String(value))}`, "g"), " ");
    }
  }

  cleaned = cleaned
    .replace(/<at\b[^>]*>[\s\S]*?<\/at>/gi, " ")
    .replace(/@\s*(基金助手|基金经理)/g, " ")
    .replace(/@\s*FundAgent/gi, " ")
    .replace(/@\s*Fund\s*Agent/gi, " ")
    .replace(/\s+/g, " ")
    .trim();

  return cleaned;
}

function isHeldFundSellTimingAsk(text) {
  const normalized = normalizeIntentText(text);
  if (!normalized) return false;
  const hasHeldPositionContext = hasAny(normalized, [
    "已经买",
    "已买",
    "买了",
    "我买",
    "持有",
    "已持有",
    "我的持仓",
    "仓位",
    "成本",
    "浮盈",
    "浮亏",
    "已入",
    "入场"
  ]);
  const hasImageOrSpecificContext = hasAny(normalized, [
    "图中",
    "图片",
    "截图",
    "这只",
    "这支",
    "这个",
    "这个基金",
    "该基金",
    "这几个",
    "这些"
  ]);
  const asksSellTiming = hasAny(normalized, [
    "多久卖",
    "多久可以卖",
    "多久能卖",
    "什么时候卖",
    "什么时候减仓",
    "何时卖",
    "哪天卖",
    "卖点",
    "止盈",
    "止损",
    "退出",
    "出场",
    "减仓",
    "清仓",
    "卖出",
    "要不要卖",
    "怎么卖",
    "拿多久",
    "持有多久",
    "还能拿",
    "卖出计划"
  ]);
  return asksSellTiming && (hasHeldPositionContext || hasImageOrSpecificContext);
}

function isUserPortfolioImportRequest(text) {
  const normalized = normalizeIntentText(text);
  if (!normalized) return false;
  const hasUser = /(用户|客户|账户|账号|user|admin)/i.test(normalized);
  const hasPosition = /(持仓|持有|已买|买了|基金列表|自选.*持有|实际组合)/.test(normalized);
  const hasCreate = /(建立|创建|新建|记录|保存|导入|同步|更新|录入|添加)/.test(normalized);
  return hasPosition && (hasCreate || hasUser) && !/(虚拟组合|经理自己|经理的持仓)/.test(normalized);
}

function extractUserPortfolioId(text) {
  const raw = String(text || "");
  const patterns = [
    /用户[“"']?([A-Za-z0-9_\-\u4e00-\u9fa5]{1,32})[”"']?/i,
    /客户[“"']?([A-Za-z0-9_\-\u4e00-\u9fa5]{1,32})[”"']?/i,
    /账户[“"']?([A-Za-z0-9_\-\u4e00-\u9fa5]{1,32})[”"']?/i,
    /账号[“"']?([A-Za-z0-9_\-\u4e00-\u9fa5]{1,32})[”"']?/i,
    /\buser[:：\s]+([A-Za-z0-9_\-]{1,32})\b/i
  ];
  for (const pattern of patterns) {
    const match = raw.match(pattern);
    if (match?.[1]) return sanitizeUserPortfolioId(match[1]);
  }
  if (/admin/i.test(raw)) return "admin";
  return "";
}

function extractUserPortfolioDisplayName(text) {
  return extractUserPortfolioId(text);
}

function sanitizeUserPortfolioId(value) {
  return String(value || "")
    .replace(/[^\w\-\u4e00-\u9fa5]/g, "")
    .slice(0, 32);
}

async function classifyMessageIntent({ imageKeys = [], userText = "", messageType = "" }) {
  const text = normalizeIntentText(userText);
  const fundCodes = extractFundCodes(text);
  const hasFundWord = hasAny(text, ["基金", "etf", "lof", "qdii", "指数", "主动", "混合", "股票型", "债基", "债券", "纯债", "短债", "货币"]);
  const asksRecommendation =
    hasAny(text, ["推荐", "筛选", "筛一下", "帮我筛", "找一个", "找一只", "找几个", "几个基金", "哪些基金", "买什么", "投什么", "配什么", "配置", "候选", "清单", "名单", "标的", "机会", "有没有", "有无", "回调完成", "准备启动", "准备向上", "准备走强", "低位启动", "低位修复", "不要追涨"]) ||
    (hasAny(text, ["最近", "最新", "当前", "现在", "市场", "行情", "题材", "热点", "板块", "赛道", "机会"]) &&
      hasAny(text, ["基金", "etf", "配置", "推荐", "候选", "清单"]));
  const asksCompare = hasAny(text, ["对比", "比较", "哪个好", "哪个更好", "哪只好", "哪只更好", "哪一个好", "选哪", "挑一个", "二选一", "三选一", "排名", "pk"]);
  const asksSpecificAction = hasAny(text, [
    "这只基金",
    "这个基金",
    "该基金",
    "基金代码",
    "值得买吗",
    "适合买吗",
    "还能买吗",
    "能买吗",
    "能不能买",
    "买不买",
    "要不要买",
    "要不要卖",
    "持有",
    "卖出",
    "买入",
    "加仓",
    "减仓",
    "定投",
    "仓位",
    "评分",
    "评价",
    "怎么样",
    "分析一下"
  ]);

  if (imageKeys.length) {
    if (isUserPortfolioImportRequest(text)) {
      return {
        workflow: "user_portfolio_import",
        mode: "screenshot_user_holdings_import",
        reason: "message_contains_image_user_portfolio_import_request",
        fundCodes,
        userPortfolioId: extractUserPortfolioId(text),
        skillIds: ["fund-vision", "fund-data-enrichment", "fund-trend-analysis", "fund-risk-analysis", "fund-actionability-evaluation", "fund-answer-quality"],
        messageType
      };
    }
    if (isHeldFundSellTimingAsk(text)) {
      return {
        workflow: "fund_screening",
        mode: "screenshot_held_position_sell_plan",
        reason: "message_contains_image_and_sell_timing_request",
        fundCodes,
        skillIds: [
          "fund-vision",
          ...getFundAnalysisSkillIds(["fund-market-timing", "fund-portfolio-execution", "fund-synthesis"])
        ],
        messageType
      };
    }
    return {
      workflow: "fund_screening",
      mode: "screenshot_or_mixed",
      reason: "message_contains_image",
      fundCodes,
      skillIds: ["fund-vision", ...getFundAnalysisSkillIds(["fund-comparison", "fund-synthesis"])],
      messageType
    };
  }

  if (!text) {
    return {
      workflow: "conversation",
      mode: "empty_text",
      reason: "no_text_after_parsing",
      fundCodes,
      skillIds: [],
      messageType
    };
  }

  if (isUserPortfolioImportRequest(text)) {
    return {
      workflow: "user_portfolio_import",
      mode: "awaiting_user_holdings_screenshot",
      reason: "text_requests_user_portfolio_import",
      fundCodes,
      userPortfolioId: extractUserPortfolioId(text),
      skillIds: ["fund-vision", "fund-data-enrichment", "fund-answer-quality"],
      messageType
    };
  }

  if (looksLikePortfolioStatusQuestion(text)) {
    return {
      workflow: "portfolio_status",
      mode: "virtual_portfolio_status",
      reason: "hard_rule_virtual_manager_account_query",
      fundCodes,
      skillIds: [],
      messageType
    };
  }

  if (fundCodes.length) {
    const specificPullbackSetup = isPullbackSetupRequest(text);
    if (isHeldFundSellTimingAsk(text)) {
      return {
        workflow: "fund_screening",
        mode: "held_position_sell_plan",
        reason: "text_contains_held_position_sell_timing_request",
        fundCodes,
        skillIds: getFundAnalysisSkillIds(["fund-market-timing", "fund-portfolio-execution", "fund-synthesis"]),
        messageType
      };
    }
    return {
      workflow: "fund_screening",
      mode: specificPullbackSetup
        ? "specific_pullback_setup_assessment"
        : fundCodes.length > 1 ? "comparison_or_specific_fund" : "specific_fund_or_fund_name",
      reason: specificPullbackSetup ? "text_contains_fund_code_pullback_setup_request" : "text_contains_fund_code",
      fundCodes,
      skillIds: getFundAnalysisSkillIds(specificPullbackSetup ? ["fund-market-timing", "fund-synthesis"] : ["fund-comparison", "fund-synthesis"]),
      messageType
    };
  }

  if (isPullbackSetupRequest(text) && (hasFundWord || asksRecommendation || isPullbackSetupDiscoveryAsk(text))) {
    return {
      workflow: "fund_recommendation",
      mode: "pullback_setup_discovery",
      reason: "hard_rule_pullback_setup_request",
      fundCodes,
      skillIds: getFundRecommendationSkillIds(),
      messageType
    };
  }

  if (!fundCodes.length && asksRecommendation) {
    return {
      workflow: "fund_recommendation",
      mode: "market_theme_discovery",
      reason: "hard_rule_text_requests_recommendations_without_specific_fund",
      fundCodes,
      skillIds: getFundRecommendationSkillIds(),
      messageType
    };
  }

  if (hasFundWord && isHeldFundSellTimingAsk(text)) {
    return {
      workflow: "fund_screening",
      mode: "held_position_sell_plan",
      reason: "hard_rule_held_position_sell_timing_request",
      fundCodes,
      skillIds: getFundAnalysisSkillIds(["fund-market-timing", "fund-portfolio-execution", "fund-synthesis"]),
      messageType
    };
  }

  if (hasFundWord && (asksSpecificAction || asksCompare)) {
    return {
      workflow: "fund_screening",
      mode: asksCompare ? "comparison_or_specific_fund" : "specific_fund_or_fund_name",
      reason: "hard_rule_text_mentions_specific_fund_action",
      fundCodes,
      skillIds: getFundAnalysisSkillIds(asksCompare ? ["fund-comparison", "fund-synthesis"] : ["fund-synthesis"]),
      messageType
    };
  }

  if (looksLikeConversation(text)) {
    return {
      workflow: "conversation",
      mode: "plain_conversation",
      reason: "hard_rule_plain_conversation",
      fundCodes,
      skillIds: [],
      messageType
    };
  }

  if (shouldFetchMarketSnapshotForQuestion(text) && isActionSeekingFundQuestion(text)) {
    return {
      workflow: "fund_qa",
      mode: "market_question",
      reason: "hard_rule_market_action_question",
      fundCodes,
      skillIds: getFundQaSkillIds(),
      messageType
    };
  }

  const modelIntent = await classifyTextIntentWithModel({ userText, messageType }).catch((error) => {
    console.error("[intent-router-error]", error);
    recordError(error, { intentRouterFailures: 1 });
    return null;
  });
  if (modelIntent?.workflow) {
    return normalizeIntentResult(modelIntent, { fundCodes, messageType, source: "model_router" });
  }

  if (!fundCodes.length && asksRecommendation) {
    return {
      workflow: "fund_recommendation",
      mode: "market_theme_discovery",
      reason: "fallback_text_requests_recommendations_without_specific_fund",
      fundCodes,
      skillIds: getFundRecommendationSkillIds(),
      messageType
    };
  }

  if (fundCodes.length || (hasFundWord && (asksSpecificAction || asksCompare))) {
    return {
      workflow: "fund_screening",
      mode: asksCompare || fundCodes.length > 1 ? "comparison_or_specific_fund" : "specific_fund_or_fund_name",
      reason: "fallback_text_mentions_specific_fund_action",
      fundCodes,
      skillIds: getFundAnalysisSkillIds(asksCompare ? ["fund-comparison", "fund-synthesis"] : ["fund-synthesis"]),
      messageType
    };
  }

  return {
    workflow: looksLikeConversation(text) ? "conversation" : "fund_qa",
    mode: shouldFetchMarketSnapshotForQuestion(text) ? "market_question" : "general_fund_question",
    reason: "fallback_no_image_no_specific_fund_recommendation",
    fundCodes,
    skillIds: looksLikeConversation(text) ? [] : getFundQaSkillIds(),
    messageType
  };
}

async function classifyTextIntentWithModel({ userText, messageType }) {
  const skills = listSkills(false).map((skill) => ({
    id: skill.id,
    name: skill.name,
    description: skill.description
  }));
  const systemText = [
    "你是基金经理的意图路由器。只返回 JSON，不要解释。",
    "你的任务是先理解用户想做什么，再选择工作流和需要加载的 skill。",
    "不要因为机器人名称叫基金经理，就把自我介绍、寒暄、能力询问、普通聊天强行归类到基金工作流。",
    "可选 workflow：",
    "- conversation：自我介绍、能做什么、寒暄、帮助、普通非基金对话。",
    "- portfolio_status：用户询问机器人/虚拟基金经理自己的仓位、持仓、自选基金池、候选池、今日操作、买卖、现金、盈亏、账户或虚拟组合。",
    "- fund_recommendation：用户让你推荐几个基金、按最近题材/市场/热点找基金、给配置清单。",
    "- fund_screening：用户提供具体基金名称/代码、问某只基金能买吗/要不要卖/评分/对比。",
    "- fund_qa：基金知识、市场题材解释、投资方法问题，但没有要求给候选基金清单。",
    "- user_portfolio_import：用户要求为某个用户/客户建立、导入、保存真实持仓截图。",
    "如果要加载技能，只能从 availableSkills 里选择 id。"
  ].join("\n");
  const userPrompt = [
    `messageType: ${messageType || "unknown"}`,
    `userText: ${userText || ""}`,
    "",
    "availableSkills:",
    JSON.stringify(skills, null, 2),
    "",
    "返回 JSON：",
    '{"workflow":"conversation|portfolio_status|fund_recommendation|fund_screening|fund_qa|user_portfolio_import","mode":"short label","reason":"brief reason","skillIds":["fund-recommendation"],"confidence":0.0}'
  ].join("\n");

  const raw = await callModel({ systemText, userPrompt, images: [], maxTokens: 500 });
  updateStats({
    counters: { intentRouterCalls: 1 },
    last: { lastIntentRouterAt: new Date().toISOString() }
  });
  return parseJsonFromModel(raw);
}

function normalizeIntentResult(intent, defaults = {}) {
  const validWorkflows = new Set(["conversation", "portfolio_status", "fund_recommendation", "fund_screening", "fund_qa", "user_portfolio_import"]);
  const workflow = validWorkflows.has(String(intent.workflow || "")) ? String(intent.workflow) : "fund_qa";
  const availableSkillIds = new Set(allowedSkillIdsForWorkflow(workflow).filter((id) =>
    listSkills(false).some((skill) => skill.id === id)
  ));
  let skillIds = Array.isArray(intent.skillIds)
    ? intent.skillIds.map(String).filter((id) => availableSkillIds.has(id))
    : [];
  if (!skillIds.length) {
    skillIds = defaultSkillIdsForWorkflow(workflow).filter((id) => availableSkillIds.has(id));
  }

  return {
    workflow,
    mode: String(intent.mode || defaults.mode || workflow),
    reason: String(intent.reason || defaults.reason || defaults.source || "model_router"),
    fundCodes: mergeFundCodes(defaults.fundCodes || [], intent.fundCodes || []),
    skillIds: workflow === "conversation" ? [] : skillIds,
    confidence: Number.isFinite(Number(intent.confidence)) ? Number(intent.confidence) : null,
    source: defaults.source || "router",
    messageType: defaults.messageType || ""
  };
}

function defaultSkillIdsForWorkflow(workflow) {
  if (workflow === "portfolio_status") return getPortfolioDecisionSkillIds();
  if (workflow === "fund_recommendation") return getFundRecommendationSkillIds();
  if (workflow === "fund_screening") return getFundAnalysisSkillIds(["fund-synthesis"]);
  if (workflow === "fund_qa") return getFundQaSkillIds();
  if (workflow === "user_portfolio_import") return ["fund-vision", "fund-data-enrichment", "fund-answer-quality"];
  return [];
}

function allowedSkillIdsForWorkflow(workflow) {
  const byWorkflow = {
    conversation: [],
    portfolio_status: uniqueSkillIds([
      ...getPortfolioDecisionSkillIds(),
      ...getPortfolioPremarketSkillIds(),
      ...getPortfolioReviewSkillIds(),
      ...getPortfolioWeeklySkillIds()
    ]),
    fund_recommendation: [...getFundRecommendationSkillIds(), "fund-data-enrichment"],
    fund_screening: [
      "fund-vision",
      ...getFundAnalysisSkillIds(["fund-comparison", "fund-synthesis"]),
      "fund-portfolio-execution",
      "fund-screening"
    ],
    fund_qa: ["fund-data-enrichment", ...getFundQaSkillIds()],
    user_portfolio_import: ["fund-vision", "fund-data-enrichment", "fund-trend-analysis", "fund-risk-analysis", "fund-actionability-evaluation", "fund-answer-quality"]
  };
  return byWorkflow[workflow] || [];
}

function recordWorkflowIntent(intent) {
  const counters = { routedMessages: 1 };
  if (intent.workflow === "conversation") counters.conversationRequests = 1;
  if (intent.workflow === "fund_screening") counters.screeningRequests = 1;
  if (intent.workflow === "fund_recommendation") counters.fundRecommendationRequests = 1;
  if (intent.workflow === "fund_qa") counters.fundQaRequests = 1;
  if (intent.workflow === "portfolio_status") counters.portfolioStatusRequests = 1;
  if (intent.workflow === "user_portfolio_import") counters.userPortfolioImportRequests = 1;
  updateStats({
    counters,
    last: {
      lastWorkflow: intent.workflow,
      lastWorkflowMode: intent.mode,
      lastWorkflowReason: intent.reason
    }
  });
}

function shouldFetchMarketSnapshotForQuestion(text) {
  const normalized = normalizeIntentText(text);
  return hasAny(normalized, [
    "最近",
    "最新",
    "当前",
    "现在",
    "市场",
    "行情",
    "题材",
    "热点",
    "板块",
    "赛道",
    "机会",
    "黄金",
    "金价",
    "贵金属",
    "白银",
    "沪金",
    "沪银",
    "comex",
    "美元指数",
    "避险"
  ]);
}

function detectComparisonNeed({ userText = "", extracted = {}, enrichments = [] }) {
  const text = normalizeIntentText(userText);
  const explicitCompare = hasAny(text, ["对比", "比较", "哪个更好", "哪只更好", "选哪", "挑一个", "二选一", "三选一", "排名", "pk"]);
  const codeCount = mergeFundCodes(
    extractFundCodes(text),
    extracted?.fundCodes || [],
    Array.isArray(enrichments) ? enrichments.map((item) => item?.code) : []
  ).length;
  const extractedFundCount = Array.isArray(extracted?.funds) ? extracted.funds.length : 0;
  return explicitCompare || codeCount > 1 || extractedFundCount > 1;
}

function looksLikeConversation(text) {
  const normalized = normalizeIntentText(text);
  return hasAny(normalized, [
    "你是谁",
    "自我介绍",
    "介绍一下你",
    "你能做什么",
    "有什么功能",
    "怎么使用",
    "帮助",
    "help",
    "你好",
    "hello",
    "hi",
    "谢谢",
    "thanks"
  ]);
}

